#[cfg(feature = "unicorn")]
impl NativeGuestExecutionGuard {
    fn enter() -> Result<Self> {
        NATIVE_ENTRY_ACTIVE.with(|active| {
            if active.replace(true) {
                Err(Error::Backend(
                    "nested native guest execution is unsupported".to_owned(),
                ))
            } else {
                Ok(Self)
            }
        })
    }
}

#[cfg(feature = "unicorn")]
impl Drop for NativeGuestExecutionGuard {
    fn drop(&mut self) {
        NATIVE_ENTRY_ACTIVE.with(|active| active.set(false));
    }
}

/// A CPU payload may be cloned for diagnostics or checkpoint preparation, but
/// copying the native wrapper must never copy its directory execution right.
/// Legacy unbound fixtures keep their old clone behavior until the remaining
/// public routes are migrated behind the machine-owned directory.
#[cfg(feature = "unicorn")]
#[derive(Debug)]
enum CpuExecutionBinding {
    LegacyUnbound,
    Directory {
        key: CpuCustodyKey,
        birth: crate::ce::object::ProcessBirthKey,
        verifier: CpuLeafVerifier,
    },
    PoisonedClone,
}

#[cfg(feature = "unicorn")]
impl Clone for CpuExecutionBinding {
    fn clone(&self) -> Self {
        match self {
            Self::LegacyUnbound => Self::LegacyUnbound,
            Self::Directory { .. } | Self::PoisonedClone => Self::PoisonedClone,
        }
    }
}

#[cfg(feature = "unicorn")]
impl CpuExecutionBinding {
    fn bind(
        &mut self,
        key: CpuCustodyKey,
        birth: crate::ce::object::ProcessBirthKey,
        verifier: CpuLeafVerifier,
    ) -> std::result::Result<(), CpuCustodyError> {
        if key.machine_lineage() != verifier.machine_lineage() {
            return Err(CpuCustodyError::WrongMachine);
        }
        if !matches!(&*self, Self::LegacyUnbound) {
            return Err(CpuCustodyError::CpuAlreadyBound);
        }
        *self = Self::Directory {
            key,
            birth,
            verifier,
        };
        Ok(())
    }

    /// This is checked on the original payload, not on a cloneable handle.
    /// In particular, A's long-lived mutable payload loan cannot execute
    /// while a separately issued B permit is the directory's current leaf.
    fn verify_native_entry(
        &self,
        kernel: &CeKernel,
        thread_id: u32,
        thread_birth: Option<crate::ce::object::ThreadBirthKey>,
    ) -> Result<()> {
        match self {
            Self::LegacyUnbound => {
                if kernel.cpu_machine_lineage().is_some() || kernel.requires_cpu_machine_relineage()
                {
                    return Err(Error::Backend(
                        "unbound CPU cannot execute in a CPU-directory machine".to_owned(),
                    ));
                }
                Ok(())
            }
            Self::PoisonedClone => Err(Error::Backend(
                "cloned CPU custody payload cannot execute".to_owned(),
            )),
            Self::Directory {
                key,
                birth,
                verifier,
            } => {
                kernel
                    .require_cpu_machine_lineage(key.machine_lineage())
                    .map_err(|error| Error::Backend(error.to_string()))?;
                if kernel.current_process_birth_key() != Some(*birth) {
                    return Err(Error::Backend(
                        "CPU custody payload differs from selected process birth".to_owned(),
                    ));
                }
                let permit = verifier.current_permit().ok_or_else(|| {
                    Error::Backend("CPU custody payload has no active execution leaf".to_owned())
                })?;
                verifier
                    .validate(permit, *key, *birth, permit.thread_birth(), permit.frame())
                    .map_err(|error| Error::Backend(error.to_string()))?;
                if permit.thread_birth().thread_id() != thread_id
                    || thread_birth != Some(permit.thread_birth())
                    || kernel.handles.thread_birth_key_by_id(thread_id)
                        != Some(permit.thread_birth())
                    || kernel.handles.live_thread_creation_owner_by_id(thread_id) != Some(*birth)
                {
                    return Err(Error::Backend(
                        "CPU custody execution leaf differs from the exact live thread birth"
                            .to_owned(),
                    ));
                }
                Ok(())
            }
        }
    }
}

#[cfg(feature = "unicorn")]
#[derive(Clone, Copy, Default)]
struct NativeStopEvidence {
    native_error: bool,
    capture_error: bool,
    hook_control_error: bool,
    count_stop_requested: bool,
    requested_pc_stop: bool,
    native_deadline_expired: bool,
    hook_stop_reason: Option<NativeHookStopReason>,
}

/// One guest self-exit observed at an import or decoded kernel-call stop.
/// This remains CPU-local until the native owner is closed and the framebuffer
/// exit preflight passes.
#[cfg(feature = "unicorn")]
#[derive(Debug, Clone, Copy)]
struct StoppedPseudoSelfExit {
    caller: crate::ce::object::ThreadBirthKey,
    owner: crate::ce::object::ProcessBirthKey,
    exit_code: u32,
    stop_pc: u32,
}

/// A native code hook observed the actual JALR instruction and source GPR in
/// this run attempt. Static RA-relative code bytes are only candidates, never
/// authority to retire a child whose CPU later stops at PC zero.
#[cfg(feature = "unicorn")]
#[derive(Debug)]
struct DecodedExitCallWitness {
    call_pc: u32,
    sp: u32,
    source_register: u32,
    target: u32,
    caller: crate::ce::object::ThreadBirthKey,
    owner: crate::ce::object::ProcessBirthKey,
    direct_load_verified: bool,
}

#[cfg(feature = "unicorn")]
impl NativeStopEvidence {
    fn outcome(self) -> NativeSliceOutcome {
        if self.native_error {
            NativeSliceOutcome::NativeError
        } else if self.capture_error || self.hook_control_error {
            NativeSliceOutcome::BackendError
        } else if self.count_stop_requested {
            if self.requested_pc_stop
                || self.native_deadline_expired
                || self.hook_stop_reason.is_some()
            {
                NativeSliceOutcome::UnknownNormalStop
            } else {
                NativeSliceOutcome::CountLimit
            }
        } else if self.requested_pc_stop {
            NativeSliceOutcome::RequestedPcStop
        } else if self.native_deadline_expired {
            NativeSliceOutcome::NativeDeadline
        } else if let Some(reason) = self.hook_stop_reason {
            NativeSliceOutcome::HookStop(reason)
        } else {
            NativeSliceOutcome::UnknownNormalStop
        }
    }
}

#[cfg(feature = "unicorn")]
fn should_repair_native_deadline_jr_import_thunk(
    native_result_ok: bool,
    requested_pc_stop: bool,
    outcome: NativeSliceOutcome,
    typed_hook_stop_reason: Option<NativeHookStopReason>,
) -> bool {
    native_result_ok
        && !requested_pc_stop
        && outcome == NativeSliceOutcome::NativeDeadline
        && typed_hook_stop_reason.is_none()
}

