/// The native CPU's currently executing thread and the birth that supplied
/// its registers. An unverified switch must not inherit the previous birth,
/// even when the numeric TID happens to be unchanged.
#[cfg(feature = "unicorn")]
struct NativeCurrentThread {
    state: std::cell::Cell<(u32, Option<crate::ce::object::ThreadBirthKey>)>,
    /// Run-owned terminal latch, shared with the native attempt result path.
    /// Tests constructed outside an attempt receive their own inspectable
    /// latch; a canonical frame failure never depends on private-VM mapping.
    terminal_error: std::rc::Rc<std::cell::RefCell<Option<Error>>>,
}

#[cfg(feature = "unicorn")]
impl NativeCurrentThread {
    fn new(thread_id: u32, birth: Option<crate::ce::object::ThreadBirthKey>) -> Self {
        Self::with_terminal_error(
            thread_id,
            birth,
            std::rc::Rc::new(std::cell::RefCell::new(None)),
        )
    }

    fn with_terminal_error(
        thread_id: u32,
        birth: Option<crate::ce::object::ThreadBirthKey>,
        terminal_error: std::rc::Rc<std::cell::RefCell<Option<Error>>>,
    ) -> Self {
        Self {
            state: std::cell::Cell::new((
                thread_id,
                birth.filter(|birth| birth.thread_id() == thread_id),
            )),
            terminal_error,
        }
    }

    fn fail_backend(&self, thread_id: u32, reason: impl Into<String>) {
        let reason = reason.into();
        tracing::error!(target: "ce.scheduler", thread_id, reason, "native frame failed");
        let mut failure = self.terminal_error.borrow_mut();
        if failure.is_none() {
            *failure = Some(Error::Backend(reason));
        }
        drop(failure);
        self.set_unverified(thread_id);
    }

    fn fail_exit_authority_recovery(&self, thread_id: u32, reason: &'static str) {
        tracing::error!(target: "ce.scheduler", thread_id, reason, "native exit authority requires recovery");
        let mut failure = self.terminal_error.borrow_mut();
        if failure.is_none() {
            *failure = Some(Error::HostExitAuthorityRecoveryRequired { reason });
        }
        drop(failure);
        self.set_unverified(thread_id);
    }

    fn get(&self) -> (u32, Option<crate::ce::object::ThreadBirthKey>) {
        self.state.get()
    }

    fn set_unverified(&self, thread_id: u32) {
        self.state.set((thread_id, None));
    }

    fn set_verified(&self, birth: crate::ce::object::ThreadBirthKey) {
        self.state.set((birth.thread_id(), Some(birth)));
    }
}

#[cfg(feature = "unicorn")]
fn verified_native_register_birth(
    kernel: &CeKernel,
    current_thread: &NativeCurrentThread,
    thread_id: u32,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let (captured_thread_id, captured_birth) = current_thread.get();
    captured_birth.filter(|birth| {
        captured_thread_id == thread_id
            && birth.thread_id() == thread_id
            && kernel.handles.thread_birth_key_by_id(thread_id) == Some(*birth)
            && kernel.handles.thread_execution_live_by_id(thread_id)
    })
}

#[cfg(feature = "unicorn")]
fn native_sent_has_sender_birth(
    sent: &crate::ce::gwe::SentMessage,
    thread: crate::ce::object::ThreadBirthKey,
    process: crate::ce::object::ProcessBirthKey,
) -> bool {
    sent.sender_owner == (crate::ce::gwe::SentMessageSenderOwner::Birth { thread, process })
        && sent.sender_thread_id() == Some(thread.thread_id())
        && sent.sender_process_id() == Some(process.process_id())
}

#[cfg(feature = "unicorn")]
fn native_gwe_queue_import_requires_verified_birth(
    module_kind: crate::emulator::imports::ImportModuleKind,
    ordinal: Option<u32>,
) -> bool {
    module_kind == crate::emulator::imports::ImportModuleKind::Coredll
        && matches!(
            ordinal,
            Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_W)
                | Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_WNO_WAIT)
                | Some(crate::ce::coredll_ordinals::ORD_PEEK_MESSAGE_W)
                | Some(crate::ce::coredll_ordinals::ORD_POST_MESSAGE_W)
                | Some(crate::ce::coredll_ordinals::ORD_POST_THREAD_MESSAGE_W)
                | Some(crate::ce::coredll_ordinals::ORD_POST_QUIT_MESSAGE)
                | Some(crate::ce::coredll_ordinals::ORD_MSG_WAIT_FOR_MULTIPLE_OBJECTS_EX)
                | Some(crate::ce::coredll_ordinals::ORD_GET_QUEUE_STATUS)
                | Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_QUEUE_READY_TIME_STAMP)
        )
}

