#[cfg(feature = "unicorn")]
fn native_process_exit_import_caller_matches_owner(
    kernel: &CeKernel,
    caller_birth: Option<crate::ce::object::ThreadBirthKey>,
    native_owner_birth: Option<crate::ce::object::ProcessBirthKey>,
) -> bool {
    caller_birth
        .zip(native_owner_birth)
        .is_some_and(|(birth, owner)| {
            kernel.checked_guest_process_caller_for_birth(birth) == Some(owner)
        })
}

#[cfg(feature = "unicorn")]
fn native_import_requires_verified_thread_birth(
    module_kind: crate::emulator::imports::ImportModuleKind,
    ordinal: Option<u32>,
    first_arg: u32,
) -> bool {
    native_gwe_queue_import_requires_verified_birth(module_kind, ordinal)
        || native_window_creation_import_requires_verified_birth(module_kind, ordinal)
        || native_send_import_requires_verified_birth(module_kind, ordinal)
        || native_no_wait_effect_import_requires_verified_birth(module_kind, ordinal)
        || native_process_exit_import_requires_verified_birth(module_kind, ordinal)
        || native_notification_event_import_requires_verified_birth(module_kind, ordinal)
        || (module_kind == crate::emulator::imports::ImportModuleKind::Coredll
            && first_arg == 0
            && matches!(
                ordinal,
                Some(crate::ce::coredll_ordinals::ORD_SET_TIMER)
                    | Some(crate::ce::coredll_ordinals::ORD_KILL_TIMER)
            ))
}

#[cfg(feature = "unicorn")]
fn stop_native_opaque_wait_error<D>(
    uc: &mut unicorn_engine::Unicorn<'_, D>,
    current_thread: &NativeCurrentThread,
    terminal_error: &std::cell::RefCell<Option<Error>>,
    thread_id: u32,
    reason: impl Into<String>,
) {
    let reason = reason.into();
    tracing::error!(target: "ce.scheduler", thread_id, reason, "native opaque wait rejected");
    let mut failure = terminal_error.borrow_mut();
    if failure.is_none() {
        *failure = Some(Error::Backend(reason));
    }
    drop(failure);
    current_thread.set_unverified(thread_id);
    let _ = uc.emu_stop();
}

#[cfg(feature = "unicorn")]
#[allow(clippy::too_many_arguments)]
fn try_publish_native_opaque_wait<D>(
    kernel: &mut CeKernel,
    uc: &mut unicorn_engine::Unicorn<'_, D>,
    current_thread: &NativeCurrentThread,
    terminal_error: &std::cell::RefCell<Option<Error>>,
    owner_birth: crate::ce::object::ThreadBirthKey,
    thread_handle: u32,
    wait_handles: Vec<u32>,
    kind: crate::ce::scheduler::SchedulerBlockedWaitKind,
    wait_started_ms: u32,
    timeout_ms: u32,
) -> Option<u64> {
    match kernel.try_register_opaque_waiter_for_birth(
        owner_birth,
        thread_handle,
        wait_handles,
        kind,
        wait_started_ms,
        timeout_ms,
    ) {
        Ok(wait_id) => Some(wait_id),
        Err(err) => {
            stop_native_opaque_wait_error(
                uc,
                current_thread,
                terminal_error,
                owner_birth.thread_id(),
                format!("opaque wait publication rejected for {owner_birth:?}: {err:?}"),
            );
            None
        }
    }
}

#[cfg(feature = "unicorn")]
fn try_publish_native_finite_sleep<D>(
    kernel: &mut CeKernel,
    uc: &mut unicorn_engine::Unicorn<'_, D>,
    current_thread: &NativeCurrentThread,
    terminal_error: &std::cell::RefCell<Option<Error>>,
    owner_birth: crate::ce::object::ThreadBirthKey,
    thread_handle: u32,
    wait_started_ms: u32,
    timeout_ms: u32,
) -> Option<crate::ce::object::TaskFrameRef> {
    match kernel.try_publish_finite_sleep_wait_for_birth(
        owner_birth,
        thread_handle,
        wait_started_ms,
        timeout_ms,
    ) {
        Ok(frame) => Some(frame),
        Err(error) => {
            stop_native_opaque_wait_error(
                uc,
                current_thread,
                terminal_error,
                owner_birth.thread_id(),
                format!("finite Sleep frame publication rejected: {error:?}"),
            );
            None
        }
    }
}

#[cfg(feature = "unicorn")]
fn retire_exact_opaque_send(
    kernel: &mut CeKernel,
    send_id: u64,
    active_receiver_thread_id: Option<u32>,
) {
    let completed_active = active_receiver_thread_id.is_some_and(|receiver_thread_id| {
        kernel.gwe.active_sent_message_id(receiver_thread_id) == Some(send_id)
            && kernel
                .gwe
                .complete_active_sent_message(receiver_thread_id, 0)
                == Some(send_id)
    });
    if !completed_active {
        let _ = kernel.gwe.timeout_sent_message(send_id);
    }
    let _ = kernel.take_completed_send_message_result(send_id);
}

#[cfg(feature = "unicorn")]
fn verified_native_guest_thread_exit_birth(
    kernel: &CeKernel,
    current_thread: &NativeCurrentThread,
    worker_thread_id: u32,
    pending_birth: Option<crate::ce::object::ThreadBirthKey>,
    running_handle: Option<u32>,
    native_owner_birth: Option<crate::ce::object::ProcessBirthKey>,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let birth = verified_native_register_birth(kernel, current_thread, worker_thread_id)?;
    if pending_birth.is_some_and(|expected| expected != birth)
        || kernel.handles.thread_creation_owner_by_id(worker_thread_id) != native_owner_birth
        || native_owner_birth.is_none()
    {
        return None;
    }
    // Closing the public CreateThread handle does not stop its worker. A live
    // handle must still name this exact birth; a closed handle is harmless
    // because the native register stamp and canonical live birth agree.
    if running_handle.is_some_and(|handle| {
        !CeKernel::is_current_thread_pseudo_handle(handle)
            && kernel.handles.get(handle).is_ok()
            && kernel.handles.thread_birth_key_for_handle(handle) != Some(birth)
    }) {
        return None;
    }
    Some(birth)
}

#[cfg(feature = "unicorn")]
fn verified_get_message_wait_birth(
    kernel: &CeKernel,
    wait_id: u64,
    thread_id: u32,
    thread_handle: u32,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let wait = kernel.blocked_waiter(wait_id)?;
    if wait.id != wait_id
        || wait.thread_id != thread_id
        || wait.thread_handle != thread_handle
        || !matches!(
            &wait.kind,
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage { .. }
        )
    {
        return None;
    }
    wait.owner_birth.filter(|birth| {
        birth.thread_id() == thread_id
            && kernel.handles.thread_birth_key_by_id(thread_id) == Some(*birth)
            && kernel.handles.thread_execution_live_by_id(thread_id)
    })
}

#[cfg(feature = "unicorn")]
fn verified_sleep_wait_birth(
    kernel: &CeKernel,
    wait_id: u64,
    thread_id: u32,
    thread_handle: u32,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let wait = kernel.blocked_waiter(wait_id)?;
    let frame = wait.frame_ref?;
    if wait.id != wait_id
        || wait.thread_id != thread_id
        || wait.thread_handle != thread_handle
        || !matches!(
            wait.kind,
            crate::ce::scheduler::SchedulerBlockedWaitKind::Sleep
        )
        || !wait.wait_handles.is_empty()
        || !kernel.is_blocked_finite_sleep_frame(frame)
    {
        return None;
    }
    wait.owner_birth.filter(|birth| {
        birth.thread_id() == thread_id
            && frame.key().owner_birth() == *birth
            && frame.wait_id() == wait_id
            && kernel.handles.thread_birth_key_by_id(thread_id) == Some(*birth)
            && kernel.handles.thread_execution_live_by_id(thread_id)
    })
}

#[cfg(feature = "unicorn")]
#[allow(clippy::too_many_arguments)]
fn verified_registered_native_wait_birth(
    kernel: &CeKernel,
    wait_id: u64,
    thread_id: u32,
    thread_handle: u32,
    wait_handles: &[u32],
    kind: BlockedWaitKind,
    wait_started_ms: u32,
    timeout_ms: u32,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let wait = kernel.blocked_waiter(wait_id)?;
    if wait.id != wait_id
        || wait.thread_id != thread_id
        || wait.thread_handle != thread_handle
        || wait.wait_handles.as_slice() != wait_handles
        || wait.kind != scheduler_blocked_wait_kind(kind)
        || wait.wait_started_ms != wait_started_ms
        || wait.timeout_ms != timeout_ms
    {
        return None;
    }
    wait.owner_birth.filter(|birth| {
        birth.thread_id() == thread_id
            && kernel.handles.thread_birth_key_by_id(thread_id) == Some(*birth)
            && kernel.handles.thread_execution_live_by_id(thread_id)
    })
}

#[cfg(feature = "unicorn")]
fn select_staged_context_thread_birth(
    kernel: &CeKernel,
    saved: &SavedCpuContext,
    executed_thread_id: u32,
    worker_exit_birth: Option<crate::ce::object::ThreadBirthKey>,
    captured_native_thread: (u32, Option<crate::ce::object::ThreadBirthKey>),
    rejection_count: &mut u64,
) -> Option<crate::ce::object::ThreadBirthKey> {
    let selected = captured_native_thread.1.filter(|birth| {
        captured_native_thread.0 == executed_thread_id
            && birth.thread_id() == executed_thread_id
            && worker_exit_birth.is_none_or(|exit_birth| exit_birth == *birth)
            && match kernel.handles.thread_birth_key_by_id(executed_thread_id) {
                Some(live_birth) => live_birth == *birth,
                // The owner may already have retired at its exit stub. No
                // replacement incarnation may receive these registers.
                None => saved.pc == THREAD_EXIT_STUB_ADDR,
            }
    });
    if selected.is_none() {
        *rejection_count = (*rejection_count).saturating_add(1);
    }
    selected
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct UnicornImportCountKey {
    module: String,
    ordinal: Option<u32>,
    name: Option<String>,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct UnicornImportStats {
    count: u64,
    max_a0: u32,
    max_a1: u32,
    max_a2: u32,
    max_a3: u32,
}

impl UnicornImportStats {
    fn record(&mut self, a0: u32, a1: u32, a2: u32, a3: u32) {
        self.count = self.count.saturating_add(1);
        self.max_a0 = self.max_a0.max(a0);
        self.max_a1 = self.max_a1.max(a1);
        self.max_a2 = self.max_a2.max(a2);
        self.max_a3 = self.max_a3.max(a3);
    }
}

#[cfg(feature = "unicorn")]
fn unicorn_window_snapshot(window: crate::ce::gwe::Window) -> UnicornWindowSnapshot {
    UnicornWindowSnapshot {
        hwnd: window.hwnd,
        thread_id: window.thread_id,
        process_id: window.process_id,
        class_name: window.class_name,
        title: window.title,
        visible: window.visible,
        being_destroyed: window.being_destroyed,
        destroyed: window.destroyed,
        parent: window.parent,
        owner: window.owner,
        style: window.style,
        ex_style: window.ex_style,
        update_pending: window.update_pending,
        erase_pending: window.erase_pending,
        pending_move: window.pending_move,
        pending_size: window.pending_size,
        rect: window.rect,
        client_rect: window.client_rect,
        update_rect: window
            .update_rects
            .iter()
            .copied()
            .reduce(crate::ce::gwe::Rect::union)
            .unwrap_or_default(),
        wndproc: window.wndproc,
    }
}

