#[cfg(feature = "unicorn")]
fn pop_pending_guest_thread_return_for_thread(
    pending_returns: &std::rc::Rc<std::cell::RefCell<Vec<PendingGuestThreadReturn>>>,
    kernel: &CeKernel,
    thread_id: u32,
) -> Option<PendingGuestThreadReturn> {
    let mut pending_returns = pending_returns.borrow_mut();
    let index = pending_returns
        .iter()
        .rposition(|pending| pending.worker_thread_id == thread_id)?;
    if pending_guest_thread_return_stale_reason(kernel, pending_returns.as_slice(), thread_id)
        .is_some()
    {
        return None;
    }
    Some(pending_returns.remove(index))
}

#[cfg(feature = "unicorn")]
fn verified_native_exit_pending_return(
    pending_returns: &std::rc::Rc<std::cell::RefCell<Vec<PendingGuestThreadReturn>>>,
    kernel: &CeKernel,
    current_thread: &NativeCurrentThread,
    thread_id: u32,
    native_owner_birth: Option<crate::ce::object::ProcessBirthKey>,
) -> std::result::Result<Option<PendingGuestThreadReturn>, String> {
    let pending_returns = pending_returns.borrow();
    if !pending_returns
        .iter()
        .any(|pending| pending.worker_thread_id == thread_id)
    {
        return Ok(None);
    }
    let birth = verified_native_guest_thread_exit_birth(
        kernel,
        current_thread,
        thread_id,
        None,
        None,
        native_owner_birth,
    )
    .ok_or_else(|| format!("unverified native worker birth for TID {thread_id}"))?;
    let Some(pending) = pending_returns
        .iter()
        .rfind(|pending| pending.worker_thread_id == thread_id && pending.worker_birth == birth)
    else {
        // A retired birth's pending return does not own these live registers.
        // The live worker may still have a separate running-thread fallback.
        return Ok(None);
    };
    if let Some(reason) =
        pending_guest_thread_return_stale_reason(kernel, std::slice::from_ref(pending), thread_id)
    {
        return Err(reason);
    }
    Ok(Some(pending.clone()))
}

#[cfg(feature = "unicorn")]
fn pop_pending_guest_thread_return_for_birth(
    pending_returns: &std::rc::Rc<std::cell::RefCell<Vec<PendingGuestThreadReturn>>>,
    birth: crate::ce::object::ThreadBirthKey,
) -> Option<PendingGuestThreadReturn> {
    let mut pending_returns = pending_returns.borrow_mut();
    let index = pending_returns
        .iter()
        .rposition(|pending| pending.worker_birth == birth)?;
    Some(pending_returns.remove(index))
}

#[cfg(feature = "unicorn")]
fn pending_guest_thread_return_stale_reason(
    kernel: &CeKernel,
    pending_returns: &[PendingGuestThreadReturn],
    thread_id: u32,
) -> Option<String> {
    for pending in pending_returns
        .iter()
        .filter(|pending| pending.worker_thread_id == thread_id)
    {
        let live_worker_birth = kernel.handles.thread_birth_key_by_id(thread_id);
        let live_creator_birth = kernel
            .handles
            .thread_birth_key_by_id(pending.creator_thread_id);
        if live_worker_birth == Some(pending.worker_birth)
            && kernel.handles.thread_execution_live_by_id(thread_id)
            && live_creator_birth == Some(pending.creator_birth)
            && kernel
                .handles
                .thread_execution_live_by_id(pending.creator_thread_id)
        {
            continue;
        }
        return Some(format!(
            "stale native CreateThread continuation: worker TID {thread_id}, expected worker {:?}, live worker {:?}, expected creator {:?}, live creator {:?}",
            pending.worker_birth, live_worker_birth, pending.creator_birth, live_creator_birth,
        ));
    }
    None
}

#[cfg(feature = "unicorn")]
fn stop_stale_pending_guest_thread_return<D>(
    kernel: &CeKernel,
    uc: &mut unicorn_engine::Unicorn<'_, D>,
    pending_returns: &std::rc::Rc<std::cell::RefCell<Vec<PendingGuestThreadReturn>>>,
    thread_id: u32,
) -> bool {
    let reason = pending_guest_thread_return_stale_reason(
        kernel,
        pending_returns.borrow().as_slice(),
        thread_id,
    );
    let Some(reason) = reason else {
        return false;
    };
    tracing::warn!(target: "ce.scheduler", thread_id, reason = reason.as_str(), "refused stale native CreateThread continuation");
    let _ = uc.emu_stop();
    true
}

#[cfg(feature = "unicorn")]
fn guest_thread_wait_owner_id(kernel: &CeKernel, thread_id: u32, thread_handle: u32) -> u32 {
    kernel.guest_thread_id(thread_handle).unwrap_or(thread_id)
}

#[cfg(feature = "unicorn")]
fn running_guest_thread_for_wait(
    kernel: &CeKernel,
    thread_id: u32,
    running_thread: &std::rc::Rc<std::cell::RefCell<Option<(u32, u32)>>>,
) -> Option<(u32, u32)> {
    running_thread.borrow().and_then(|(id, handle)| {
        (id == thread_id).then(|| {
            (
                guest_thread_wait_owner_id(kernel, thread_id, handle),
                handle,
            )
        })
    })
}

#[cfg(feature = "unicorn")]
fn pop_pending_wndproc_return_for_call_sp(
    pending_returns: &std::rc::Rc<std::cell::RefCell<Vec<PendingWndProcReturn>>>,
    call_sp: u32,
) -> Option<PendingWndProcReturn> {
    let mut pending_returns = pending_returns.borrow_mut();
    if pending_returns
        .last()
        .is_some_and(|pending| pending.return_sp.wrapping_sub(WNDPROC_CALL_FRAME_BYTES) == call_sp)
    {
        return pending_returns.pop();
    }
    let index = pending_returns
        .iter()
        .rposition(|pending| pending.return_sp.wrapping_sub(WNDPROC_CALL_FRAME_BYTES) == call_sp)?;
    Some(pending_returns.remove(index))
}

#[cfg(feature = "unicorn")]
fn snapshot_has_orphaned_cross_process_send_yield(
    snapshot: &mut Option<UnicornDebugSnapshot>,
    kernel: &CeKernel,
) -> bool {
    let Some(snapshot) = snapshot.as_mut() else {
        return false;
    };
    let Some(yielded) = snapshot.cross_process_send_yield.as_ref() else {
        return false;
    };
    if kernel.gwe.sent_message(yielded.send_id).is_some() {
        return false;
    }
    snapshot.cross_process_send_yield = None;
    true
}

