    pub fn has_ready_parked_send_unblock(&self, kernel: &CeKernel) -> bool {
        #[cfg(feature = "unicorn")]
        {
            return self
                .parked_child_processes
                .iter()
                .filter(|process| !self.parked_process_matches_current_active(process, kernel))
                .any(|process| {
                    process.blocked_send_id.is_some_and(|send_id| {
                        Self::parked_send_result_ready(process, kernel, send_id)
                    })
                });
        }
        #[cfg(not(feature = "unicorn"))]
        self.parked_child_processes
            .iter()
            .filter(|process| !self.parked_process_matches_current_active(process, kernel))
            .filter_map(|process| process.blocked_send_id)
            .any(|send_id| kernel.sent_message_result_ready(send_id))
    }

    #[cfg(feature = "unicorn")]
    pub fn has_runnable_parked_process(&self, kernel: &CeKernel) -> bool {
        self.parked_child_processes
            .iter()
            .filter(|process| !self.parked_process_matches_current_active(process, kernel))
            .any(|process| Self::parked_process_can_run(process, kernel))
    }

    #[cfg(feature = "unicorn")]
    pub fn has_live_pump_priority_parked_process(&self, kernel: &CeKernel) -> bool {
        self.parked_child_processes
            .iter()
            .filter(|process| !self.parked_process_matches_current_active(process, kernel))
            .any(|process| Self::parked_process_has_live_pump_priority_work(process, kernel))
    }

    #[cfg(feature = "unicorn")]
    fn rotate_after_run_slice_handoff(&mut self, kernel: &mut CeKernel, live_pump: bool) {
        let outgoing_process_id = kernel.current_process_id();
        self.rotate_after_run_slice_handoff_inner(kernel, live_pump);
        if kernel.current_process_id() != outgoing_process_id {
            // Record that the slice-end handoff already chose the next
            // process so follow-up main-loop priority rotations do not
            // immediately reverse the round-robin decision.
            self.slice_end_rotation_pending = true;
        }
    }

    #[cfg(feature = "unicorn")]
    pub fn slice_end_rotation_pending(&self) -> bool {
        self.slice_end_rotation_pending
    }

    pub fn last_native_slice_outcome(&self) -> NativeSliceOutcome {
        self.last_native_slice_outcome
    }

    #[cfg(feature = "unicorn")]
    fn rotate_after_run_slice_handoff_inner(&mut self, kernel: &mut CeKernel, live_pump: bool) {
        tracing::debug!(
            target: "ce.quantum",
            active_process_id = kernel.current_process_id(),
            live_pump,
            running = self.running_guest_thread.is_some(),
            visible_receiver = self.active_process_has_visible_receiver_work(kernel),
            queued_receiver = self.active_process_has_visible_queued_receiver_work(kernel),
            service_boundary = self.last_native_slice_outcome.is_service_boundary(),
            blocked_state = self.has_active_blocked_state(kernel),
            runnable_parked = self.has_runnable_parked_process(kernel),
            "handoff gates"
        );
        if self.complete_active_send_wait_with_unavailable_receiver(kernel) {
            return;
        }
        let active_send_receiver_threads = self.active_blocked_send_receiver_threads(kernel);
        if !active_send_receiver_threads.is_empty()
            && self.rotate_to_ready_parked_threads(kernel, &active_send_receiver_threads)
        {
            return;
        }
        if self.has_active_blocked_state(kernel)
            && self.has_ready_parked_wait_unblock(kernel)
            && self.rotate_to_ready_parked_wait(kernel)
        {
            return;
        }
        let active_has_visible_receiver = self.active_process_has_visible_receiver_work(kernel);
        let active_has_visible_queued_receiver =
            self.active_process_has_visible_queued_receiver_work(kernel);
        let active_has_receiver = self.active_process_has_receiver_work(kernel);
        let active_has_visible_windows = self.active_process_has_visible_windows(kernel);
        if live_pump
            && !active_has_visible_queued_receiver
            && self.has_ready_parked_wait_unblock(kernel)
            && self.rotate_to_ready_parked_wait(kernel)
        {
            return;
        }
        if self.running_guest_thread.is_none()
            && !active_has_receiver
            && !active_has_visible_queued_receiver
            && (!live_pump
                || Self::live_pump_active_should_yield_to_visible_parked_process(
                    &self.parked_child_processes,
                    kernel,
                    self.current_thread_id,
                ))
            && self.rotate_to_visible_window_parked_process(kernel)
        {
            return;
        }
        if self.running_guest_thread.is_none()
            && !active_has_visible_queued_receiver
            && (!live_pump || !active_has_visible_windows)
            && self.has_runnable_parked_process(kernel)
            && self.rotate_to_next_parked_process(kernel)
        {
            return;
        }
        if live_pump
            && !self.active_process_has_resumable_context()
            && self.rotate_to_any_runnable_parked_process(kernel)
        {
            return;
        }
        if live_pump
            && !active_has_visible_windows
            && self.rotate_to_visible_window_parked_process(kernel)
        {
            return;
        }
        if live_pump
            && !active_has_visible_queued_receiver
            && self.rotate_to_live_pump_resumable_parked_process(kernel)
        {
            return;
        }
        if live_pump
            && active_has_visible_receiver
            && !active_has_visible_queued_receiver
            && self.rotate_to_live_pump_runnable_parked_process(kernel)
        {
            return;
        }
        if live_pump
            && active_has_visible_receiver
            && !active_has_visible_queued_receiver
            && !active_has_visible_windows
            && self.rotate_to_live_pump_cpu_runnable_parked_process(kernel)
        {
            return;
        }
        if self.has_active_blocked_state(kernel)
            && !active_has_visible_receiver
            && self.has_runnable_parked_process(kernel)
        {
            let _ = self.rotate_to_next_parked_process(kernel);
            return;
        }
        // A successful native service boundary permits another runnable
        // process to run. This does not claim a CE task quantum expired: an
        // instruction count, hook yield, or unknown normal stop can reach it.
        if live_pump && self.last_native_slice_outcome.is_service_boundary() {
            let rotated = self.rotate_to_any_runnable_parked_process(kernel);
            tracing::debug!(
                target: "ce.quantum",
                rotated,
                incoming_process_id = kernel.current_process_id(),
                "quantum handoff rotation"
            );
        }
    }

    #[cfg(feature = "unicorn")]
    pub fn complete_orphaned_parked_send_wait(&mut self, kernel: &mut CeKernel) -> bool {
        Self::complete_orphaned_send_wait_in_parked_processes(
            &mut self.parked_child_processes,
            kernel,
        )
    }

    #[cfg(feature = "unicorn")]
    fn active_blocked_send_receiver_threads(&self, kernel: &CeKernel) -> Vec<u32> {
        let mut receiver_threads = Vec::new();
        let mut push_receiver = |thread_id: u32| {
            if thread_id != 0 && !receiver_threads.contains(&thread_id) {
                receiver_threads.push(thread_id);
            }
        };

        for blocked in &self.blocked_wait_threads {
            if let BlockedWaitKind::SendMessage {
                send_id,
                receiver_thread_id,
                ..
            } = blocked.kind
                && kernel.gwe.sent_message(send_id).is_some()
                && verified_native_send_wait_birth(kernel, blocked).is_some()
                && !kernel.sent_message_result_ready(send_id)
            {
                push_receiver(receiver_thread_id);
            }
        }

        let active_thread_ids = self.tracked_thread_ids();
        for wait in kernel.blocked_waiters() {
            if !active_thread_ids.contains(&wait.thread_id) {
                continue;
            }
            if let crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id } =
                wait.kind
                && let Some(sent) = kernel.gwe.sent_message(send_id)
                && verified_scheduler_send_wait_owner(kernel, wait)
                && !kernel.sent_message_result_ready(send_id)
            {
                push_receiver(sent.receiver_thread_id);
            }
        }

        let active_process_id = kernel.current_process_id();
        let active_process_birth = kernel.current_process_birth_key();
        for snapshot in [
            self.last_debug.as_ref(),
            self.last_wall_clock_debug.as_ref(),
        ]
        .into_iter()
        .flatten()
        {
            let Some(yielded) = snapshot.cross_process_send_yield.as_ref() else {
                continue;
            };
            if yielded.sender_process_id == active_process_id
                && active_thread_ids.contains(&yielded.sender_thread_id)
                && active_process_birth.is_some_and(|process| {
                    kernel
                        .live_thread_birth_key_by_id(yielded.sender_thread_id)
                        .is_some_and(|thread| {
                            kernel
                                .gwe
                                .sent_message(yielded.send_id)
                                .is_some_and(|sent| {
                                    native_sent_has_sender_birth(sent, thread, process)
                                        && sent.receiver_thread_id == yielded.target_thread_id
                                        && sent.message.hwnd == yielded.hwnd
                                        && sent.message.msg == yielded.msg
                                })
                        })
                })
                && !kernel.sent_message_result_ready(yielded.send_id)
            {
                push_receiver(yielded.target_thread_id);
            }
        }

        receiver_threads
    }

    #[cfg(feature = "unicorn")]
    fn complete_active_send_wait_with_unavailable_receiver(
        &mut self,
        kernel: &mut CeKernel,
    ) -> bool {
        let Some((send_id, receiver_thread_id)) = self.active_blocked_send_wait(kernel) else {
            return false;
        };
        if let Some(candidate) = self.blocked_wait_threads.iter().find(|blocked| {
            matches!(blocked.kind, BlockedWaitKind::SendMessage { send_id: id, .. } if id == send_id)
        }) {
            if verified_native_send_wait_birth(kernel, candidate).is_none() {
                return Self::complete_blocked_send_for_parked_cpu(self, kernel, send_id, 0);
            }
        } else if !kernel.blocked_waiters().any(|wait| {
            matches!(wait.kind, crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id: id } if id == send_id)
                && verified_scheduler_send_wait_owner(kernel, wait)
        }) {
            return false;
        }
        if self.thread_has_runnable_context(receiver_thread_id, kernel) {
            return false;
        }
        if kernel
            .terminate_sent_messages_to_receiver(receiver_thread_id)
            .is_empty()
        {
            return false;
        }
        Self::complete_ready_blocked_send_for_parked_cpu(self, kernel, send_id)
    }

    #[cfg(feature = "unicorn")]
    fn active_blocked_send_wait(&self, kernel: &CeKernel) -> Option<(u64, u32)> {
        for blocked in &self.blocked_wait_threads {
            if let BlockedWaitKind::SendMessage {
                send_id,
                receiver_thread_id,
                ..
            } = blocked.kind
                && kernel.gwe.sent_message(send_id).is_some()
                && !kernel.sent_message_result_ready(send_id)
            {
                return Some((send_id, receiver_thread_id));
            }
        }

        let active_thread_ids = self.tracked_thread_ids();
        kernel.blocked_waiters().find_map(|wait| {
            if !active_thread_ids.contains(&wait.thread_id) {
                return None;
            }
            if let crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id } =
                wait.kind
                && let Some(sent) = kernel.gwe.sent_message(send_id)
                && !kernel.sent_message_result_ready(send_id)
            {
                return Some((send_id, sent.receiver_thread_id));
            }
            None
        })
    }

    #[cfg(feature = "unicorn")]
    fn thread_has_runnable_context(&self, thread_id: u32, kernel: &CeKernel) -> bool {
        if self.tracked_thread_ids().contains(&thread_id) {
            return true;
        }
        self.parked_child_processes.iter().any(|process| {
            !self.parked_process_matches_current_active(process, kernel)
                && process.cpu.tracked_thread_ids().contains(&thread_id)
        })
    }

    #[cfg(feature = "unicorn")]
    pub fn complete_orphaned_active_send_wait(&mut self, kernel: &mut CeKernel) -> bool {
        let Some(send_id) = self.blocked_wait_threads.iter().find_map(|blocked| {
            if let BlockedWaitKind::SendMessage { send_id, .. } = blocked.kind
                && kernel.gwe.sent_message(send_id).is_none()
            {
                Some(send_id)
            } else {
                None
            }
        }) else {
            return false;
        };
        Self::complete_blocked_send_for_parked_cpu(self, kernel, send_id, 0)
    }

    #[cfg(feature = "unicorn")]
    pub fn clear_orphaned_send_depths(&mut self, kernel: &mut CeKernel) -> bool {
        let mut protected_threads = self
            .pending_wndproc_returns
            .iter()
            .filter_map(|pending| pending.send_thread_id)
            .collect::<Vec<_>>();
        protected_threads.extend(self.orphaned_wndproc_returns.iter().filter_map(|record| {
            matches!(record.source, "SendMessageW" | "SendMessageTimeout")
                .then_some(record.send_thread_id)
                .flatten()
        }));
        protected_threads.sort_unstable();
        protected_threads.dedup();
        let cleared = kernel
            .gwe
            .clear_orphaned_send_depths_excluding(&protected_threads);
        if cleared.is_empty() {
            return false;
        }
        tracing::debug!(
            target: "ce.gwe",
            ?cleared,
            ?protected_threads,
            "cleared orphaned send-message depth"
        );
        true
    }

    #[cfg(feature = "unicorn")]
    pub fn clear_orphaned_direct_send_callouts(&mut self, kernel: &CeKernel) -> bool {
        let context_pcs = [
            self.saved_context.as_ref().map(|saved| saved.pc),
            self.last_debug.as_ref().map(|snapshot| snapshot.pc),
        ];
        let context_frames = [
            self.saved_context
                .as_ref()
                .map(|saved| (saved.pc, saved.regs.regs[31], saved.regs.regs[29])),
            self.last_debug
                .as_ref()
                .map(|snapshot| (snapshot.pc, snapshot.ra, snapshot.sp)),
        ];
        Self::clear_orphaned_direct_send_callouts_for_context(
            &mut self.pending_wndproc_returns,
            kernel,
            &self.mapped_blobs,
            context_pcs,
            context_frames,
            Some(&mut self.orphaned_wndproc_returns),
        )
    }

    #[cfg(feature = "unicorn")]
    pub fn clear_escaped_visible_message_callouts(&mut self, kernel: &mut CeKernel) -> bool {
        // A freshly pushed callout inherits its return pc from the very stop
        // snapshot the candidates below still describe. Until a run slice has
        // completed after the newest push, that snapshot is pre-callout
        // evidence and must not be treated as an escaped return.
        if self.run_slice_generation == self.visible_callout_push_generation
            && self.pending_wndproc_returns.iter().any(|pending| {
                pending.source == "OrphanedVisibleMessage" && pending.resume_import.is_some()
            })
        {
            return false;
        }
        let candidates = [
            self.saved_context
                .as_ref()
                .map(|saved| (saved.pc, import_trap_pc(saved.pc))),
            self.last_debug.as_ref().map(|snapshot| {
                let stopped_on_import_trap = snapshot.trap_address == Some(snapshot.pc)
                    || snapshot.trap_module_kind.is_some()
                    || snapshot.trap_ordinal.is_some();
                (snapshot.pc, stopped_on_import_trap)
            }),
        ];
        let Some(index) =
            self.pending_wndproc_returns
                .iter()
                .enumerate()
                .rev()
                .find_map(|(index, pending)| {
                    let escaped_visible_message = pending.source == "OrphanedVisibleMessage"
                        && pending.resume_import.is_some()
                        && pending.return_pc != 0
                        && candidates.iter().copied().flatten().any(
                            |(pc, stopped_on_import_trap)| {
                                pc == pending.return_pc && !stopped_on_import_trap
                            },
                        );
                    escaped_visible_message.then_some(index)
                })
        else {
            return false;
        };
        if !self.pending_wndproc_returns[index]
            .resume_import
            .as_ref()
            .is_some_and(|resume| resume_import_has_live_birth(kernel, resume))
        {
            return false;
        }
        let callout = self.pending_wndproc_returns.remove(index);
        let Some(resume) = callout.resume_import.clone() else {
            return false;
        };
        let _ = finish_guest_paint_after_wndproc_return(kernel, &callout);
        self.saved_context = Some(SavedCpuContext {
            pc: resume.import_pc,
            regs: resume.regs,
        });
        self.saved_context_thread_birth = Some(resume.thread_birth);
        self.current_thread_id = resume.thread_id;
        self.running_guest_thread = resume.running_thread;
        tracing::warn!(
            target: "ce.gwe",
            hwnd = format_args!("0x{:08x}", callout.hwnd),
            msg = format_args!("0x{:08x}", callout.msg),
            wndproc = format_args!("0x{:08x}", callout.wndproc),
            import_pc = format_args!("0x{:08x}", resume.import_pc),
            thread_id = resume.thread_id,
            running_thread = ?resume.running_thread,
            "completed escaped visible-message WNDPROC callout"
        );
        true
    }

    #[cfg(feature = "unicorn")]
    fn clear_escaped_visible_message_callouts_for_context(
        pending_wndproc_returns: &mut Vec<PendingWndProcReturn>,
        context_pcs: [Option<u32>; 2],
        mut orphaned_wndproc_returns: Option<&mut Vec<UnicornWndProcReturn>>,
    ) -> bool {
        let before = pending_wndproc_returns.len();
        let mut removed_callouts = Vec::new();
        pending_wndproc_returns.retain(|pending| {
            let escaped_visible_message = pending.source == "OrphanedVisibleMessage"
                && pending.resume_import.is_none()
                && pending.return_pc != 0
                && context_pcs
                    .iter()
                    .copied()
                    .flatten()
                    .any(|pc| pc == pending.return_pc);
            if escaped_visible_message {
                removed_callouts.push(pending.clone());
            }
            !escaped_visible_message
        });
        let removed = before.saturating_sub(pending_wndproc_returns.len());
        if removed == 0 {
            return false;
        }
        if let Some(returns) = orphaned_wndproc_returns.as_deref_mut() {
            archive_removed_wndproc_callouts(returns, &removed_callouts);
        }
        tracing::warn!(
            target: "ce.gwe",
            removed,
            removed_callouts = ?removed_callouts,
            saved_pc = ?context_pcs[0],
            last_pc = ?context_pcs[1],
            "cleared escaped visible-message WNDPROC callouts"
        );
        true
    }

    #[cfg(feature = "unicorn")]
    fn clear_orphaned_direct_send_callouts_for_context(
        pending_wndproc_returns: &mut Vec<PendingWndProcReturn>,
        kernel: &CeKernel,
        mapped_blobs: &[MappedBlob],
        context_pcs: [Option<u32>; 2],
        context_frames: [Option<(u32, u32, u32)>; 2],
        mut orphaned_wndproc_returns: Option<&mut Vec<UnicornWndProcReturn>>,
    ) -> bool {
        let before = pending_wndproc_returns.len();
        // A later same-thread callback is an actual descendant activation.
        // Anchor liveness to its own frame, not the total depth below an outer
        // SendMessage frame: nested callbacks can exceed the outer grace even
        // while the innermost frame remains within the existing bound.
        let live_nested_frames = pending_wndproc_returns
            .iter()
            .enumerate()
            .filter_map(|(index, nested)| {
                let call_sp = nested.return_sp.checked_sub(WNDPROC_CALL_FRAME_BYTES)?;
                let thread_id = nested
                    .send_restore
                    .as_ref()
                    .map(|restore| restore.receiver_thread_id)
                    .or(nested.send_thread_id)
                    .or_else(|| {
                        kernel
                            .gwe
                            .window_thread_process_id(nested.hwnd)
                            .map(|(thread, _)| thread)
                    })?;
                let live = context_frames.iter().copied().flatten().any(|(_, ra, sp)| {
                    ra != 0 && sp <= call_sp && call_sp - sp <= WNDPROC_NESTED_STACK_GRACE_BYTES
                });
                live.then_some((index, thread_id, nested.return_sp))
            })
            .collect::<Vec<_>>();
        let mut removed_callouts = Vec::new();
        let mut pending_index = 0;
        pending_wndproc_returns.retain(|pending| {
            let index = pending_index;
            pending_index += 1;
            let Some(thread_id) = pending.send_thread_id else {
                return true;
            };
            let direct_send = pending.send_restore.is_none()
                && pending.send_timeout_result_ptr.is_none()
                && matches!(pending.source, "SendMessageW" | "SendMessageTimeout");
            if !direct_send || kernel.gwe.active_sent_message_id(thread_id).is_some() {
                return true;
            }
            let pending_call_sp = pending.return_sp.wrapping_sub(WNDPROC_CALL_FRAME_BYTES);
            if pending_call_sp < pending.return_sp
                && live_nested_frames
                    .iter()
                    .any(|&(nested_index, nested_thread, return_sp)| {
                        nested_index > index
                            && nested_thread == thread_id
                            && return_sp <= pending_call_sp
                    })
            {
                return true;
            }
            let send_message_without_restore =
                pending.source == "SendMessageW" && pending.send_restore.is_none();
            let keep = context_frames
                .iter()
                .copied()
                .flatten()
                .any(|(pc, ra, sp)| {
                    let nested_stack_candidate = ra != 0
                        && sp <= pending_call_sp
                        && pending_call_sp < pending.return_sp
                        && pending_call_sp.wrapping_sub(sp) <= WNDPROC_NESTED_STACK_GRACE_BYTES;
                    pc == pending.return_pc
                        || pc == WNDPROC_RETURN_STUB_ADDR
                        || (ra == WNDPROC_RETURN_STUB_ADDR && sp == pending_call_sp)
                        || (nested_stack_candidate
                            && (send_message_without_restore || {
                                let pending_module =
                                    mapped_blob_module_index_for_pc(mapped_blobs, pending.wndproc);
                                let same_wndproc_module =
                                    pending_module.is_none_or(|module_index| {
                                        let mut frame_modules =
                                            [pc, ra].into_iter().filter_map(|addr| {
                                                mapped_blob_module_index_for_pc(mapped_blobs, addr)
                                            });
                                        let mut saw_mapped_frame = false;
                                        let same = frame_modules.any(|frame_index| {
                                            saw_mapped_frame = true;
                                            frame_index == module_index
                                                || mapped_blobs.get(frame_index).is_some_and(
                                                    |blob| blob.name.starts_with("image:"),
                                                )
                                        });
                                        same || !saw_mapped_frame
                                    });
                                same_wndproc_module
                            }))
                });
            if !keep {
                removed_callouts.push(pending.clone());
            }
            keep
        });
        let removed = before.saturating_sub(pending_wndproc_returns.len());
        if removed == 0 {
            return false;
        }
        if let Some(returns) = orphaned_wndproc_returns.as_deref_mut() {
            archive_removed_wndproc_callouts(returns, &removed_callouts);
        }
        tracing::warn!(
            target: "ce.gwe",
            removed,
            removed_callouts = ?removed_callouts,
            saved_pc = ?context_pcs[0],
            last_pc = ?context_pcs[1],
            saved_frame = ?context_frames[0],
            last_frame = ?context_frames[1],
            "cleared orphaned direct SendMessage WNDPROC callouts"
        );
        true
    }

    #[cfg(feature = "unicorn")]
    fn complete_orphaned_send_wait_in_parked_processes(
        parked_child_processes: &mut VecDeque<ParkedProcess>,
        kernel: &mut CeKernel,
    ) -> bool {
        let Some((index, send_id)) =
            parked_child_processes
                .iter()
                .enumerate()
                .find_map(|(index, process)| {
                    process
                        .blocked_send_id
                        .filter(|send_id| {
                            kernel.gwe.sent_message(*send_id).is_none()
                                || process.cpu.blocked_wait_threads.iter().any(|blocked| {
                                    matches!(blocked.kind, BlockedWaitKind::SendMessage { send_id: id, .. } if id == *send_id)
                                        && verified_native_send_wait_birth(kernel, blocked).is_none()
                                })
                        })
                        .or_else(|| {
                            process.cpu.blocked_wait_threads.iter().find_map(|blocked| {
                                if let BlockedWaitKind::SendMessage { send_id, .. } = blocked.kind
                                    && (kernel.gwe.sent_message(send_id).is_none()
                                        || verified_native_send_wait_birth(kernel, blocked).is_none())
                                {
                                    Some(send_id)
                                } else {
                                    None
                                }
                            })
                        })
                        .or_else(|| {
                            kernel.blocked_waiters().find_map(|wait| {
                                if wait.thread_id == process.thread_id
                                && let crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage {
                                    send_id,
                                } = wait.kind
                                && kernel.gwe.sent_message(send_id).is_none()
                            {
                                Some(send_id)
                            } else {
                                None
                            }
                            })
                        })
                        .map(|send_id| (index, send_id))
                })
        else {
            return false;
        };
        let parked = &mut parked_child_processes[index];
        let wait_present = parked.cpu.blocked_wait_threads.iter().any(|blocked| {
            matches!(blocked.kind, BlockedWaitKind::SendMessage { send_id: id, .. } if id == send_id)
        });
        if !wait_present {
            let stale_wait_ids = kernel
                .blocked_waiters()
                .filter_map(|wait| {
                    (wait.thread_id == parked.thread_id
                        && matches!(
                            wait.kind,
                            crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage {
                                send_id: id
                            } if id == send_id
                        ))
                    .then_some(wait.id)
                })
                .collect::<Vec<_>>();
            for wait_id in stale_wait_ids {
                let _ = kernel.remove_blocked_waiter(wait_id);
            }
            parked.blocked_send_id = None;
            return true;
        }
        if Self::complete_blocked_send_for_parked_cpu(parked.cpu.as_mut(), kernel, send_id, 0) {
            parked.blocked_send_id = None;
            return true;
        }
        false
    }

