    #[cfg(feature = "unicorn")]
    pub fn rotate_to_ready_parked_wait_with_framebuffer(
        &mut self,
        kernel: &mut CeKernel,
        framebuffer: Option<&mut dyn Framebuffer>,
    ) -> bool {
        if self.active_has_unrun_staged_visible_callout() {
            return false;
        }
        let Some(index) = self.parked_child_processes.iter().position(|process| {
            !self.parked_process_matches_current_active(process, kernel)
                && Self::parked_process_has_priority_ready_work(process, kernel)
        }) else {
            return false;
        };
        let Some(parked) = self.parked_child_processes.remove(index) else {
            return false;
        };
        self.switch_to_parked_process(kernel, parked, true, framebuffer);
        true
    }

