    #[test]
    fn blocked_wait_outputs_reject_sealed_bytes_before_consuming_results() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        let output_ptr = 0x2000_2000u32;
        uc.mem_map(u64::from(output_ptr), 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();
        uc.mem_write(u64::from(output_ptr), &0xfeed_faceu32.to_le_bytes())
            .unwrap();
        uc.mem_protect(u64::from(output_ptr), 0x1000, unicorn_engine::Prot::READ)
            .unwrap();

        let mut blocked = blocked_wait(0, 0);
        blocked.kind = BlockedWaitKind::SendMessage {
            send_id: 1,
            receiver_thread_id: 2,
            result_ptr: Some(output_ptr),
            previous_running_thread: None,
        };
        let send_guard = super::SealedHostWriteGuard {
            ranges: std::rc::Rc::new(vec![(u64::from(output_ptr), u64::from(output_ptr) + 4)]),
            violation: std::rc::Rc::new(std::cell::RefCell::new(None)),
        };
        assert_eq!(
            super::complete_blocked_send_message(&blocked, &mut kernel, &mut uc, &send_guard),
            0
        );
        assert!(send_guard.poison_error().is_some());
        assert_eq!(
            uc.mem_read_as_vec(u64::from(output_ptr), 4).unwrap(),
            0xfeed_faceu32.to_le_bytes().to_vec()
        );

        blocked.kind = BlockedWaitKind::SerialCommEvent {
            handle: 0,
            event_ptr: output_ptr,
            owner_birth: Some(owner),
        };
        let mapped = std::cell::RefCell::new(super::KernelMemoryMappings::new(&[]));
        let pins = super::NativeMappingPins::default();
        let guards = std::cell::RefCell::new(std::collections::BTreeMap::new());
        let terminal_error = std::cell::RefCell::new(None);
        let comm_guard = super::SealedHostWriteGuard {
            ranges: std::rc::Rc::new(vec![(u64::from(output_ptr), u64::from(output_ptr) + 4)]),
            violation: std::rc::Rc::new(std::cell::RefCell::new(None)),
        };
        assert_eq!(
            complete_blocked_serial_comm_event(
                &blocked,
                &mut kernel,
                &mut uc,
                &comm_guard,
                Some(super::UnicornPrivateVmMapping {
                    mapped: &mapped,
                    owner,
                    native_pins: &pins,
                    active_guards: &guards,
                    terminal_error: &terminal_error,
                }),
            ),
            0
        );
        assert!(comm_guard.poison_error().is_some());
        assert_eq!(
            uc.mem_read_as_vec(u64::from(output_ptr), 4).unwrap(),
            0xfeed_faceu32.to_le_bytes().to_vec()
        );
    }

    #[test]
    fn current_wait_comm_event_without_peer_parks_and_stops_instead_of_falling_through() {
        const EV_RXCHAR: u32 = 0x0001;
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let com = kernel
            .create_file_w("COM7:", GENERIC_READ | GENERIC_WRITE, CREATE_ALWAYS)
            .unwrap();
        kernel.set_comm_mask(com, EV_RXCHAR).unwrap();
        assert!(!kernel.serial_comm_event_ready(com));

        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        let event_ptr = 0x3000_2000;
        uc.mem_map(event_ptr.into(), 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();
        let thread_id = 8;
        let (thread_handle, thread_birth) = registered_native_test_thread(&mut kernel, thread_id);
        let return_pc = 0x0040_8000u32;
        uc.reg_write(unicorn_engine::RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::S1, 0x2468_1357)
            .unwrap();

        let blocked_waits = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let stale_event = kernel.create_event_w(None, true, false);
        let stale_wait_id = kernel.register_blocked_waiter(
            thread_id,
            thread_handle,
            vec![stale_event],
            crate::ce::scheduler::SchedulerBlockedWaitKind::Kernel,
            0,
            INFINITE,
        );
        blocked_waits.borrow_mut().push(BlockedWaitThread {
            frame_ref: None,
            wait_id: stale_wait_id,
            thread_id,
            thread_handle,
            wait_handles: vec![stale_event],
            kind: BlockedWaitKind::Kernel,
            wait_started_ms: 0,
            timeout_ms: INFINITE,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0,
        });
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let current_thread_id = std::rc::Rc::new(super::NativeCurrentThread::new(
            thread_id,
            Some(thread_birth),
        ));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let running_thread =
            std::rc::Rc::new(std::cell::RefCell::new(Some((thread_id, thread_handle))));

        assert!(super::try_block_wait_comm_event(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_WAIT_COMM_EVENT),
            &[com, event_ptr],
            thread_id,
            &blocked_waits,
            &pending_returns,
            &current_thread_id,
            &suspended_thread,
            &running_thread,
            &std::cell::RefCell::new(None),
        ));

        assert_eq!(*running_thread.borrow(), None);
        assert_eq!(current_thread_id.get(), (thread_id, Some(thread_birth)));
        assert!(kernel.blocked_waiter(stale_wait_id).is_none());
        let blocked_waits = blocked_waits.borrow();
        assert_eq!(blocked_waits.len(), 1);
        let blocked = &blocked_waits[0];
        assert_eq!(blocked.thread_id, thread_id);
        assert_eq!(blocked.thread_handle, thread_handle);
        assert!(blocked.wait_handles.is_empty());
        assert!(matches!(
            blocked.kind,
            BlockedWaitKind::SerialCommEvent {
                handle,
                event_ptr: actual_event_ptr,
                ..
            } if handle == com && actual_event_ptr == event_ptr
        ));
        assert!(kernel.blocked_waiter(blocked.wait_id).is_some());
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::S1).unwrap() as u32,
            0x2468_1357
        );
    }

    #[test]
    fn wait_comm_event_yields_to_ready_blocked_waiter() {
        const EV_RXCHAR: u32 = 0x0001;
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let com = kernel
            .create_file_w("COM7:", GENERIC_READ | GENERIC_WRITE, CREATE_ALWAYS)
            .unwrap();
        kernel.set_comm_mask(com, EV_RXCHAR).unwrap();
        assert!(!kernel.serial_comm_event_ready(com));

        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        let event_ptr = 0x3000_2000;
        uc.mem_map(event_ptr.into(), 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();
        let active_thread_id = 8;
        let active_thread_handle = registered_test_thread(&mut kernel, active_thread_id);
        let active_return_pc = 0x0040_8000u32;
        uc.reg_write(
            unicorn_engine::RegisterMIPS::RA,
            u64::from(active_return_pc),
        )
        .unwrap();

        let worker_thread_id = 9;
        let worker_thread_handle = registered_test_thread(&mut kernel, worker_thread_id);
        let worker_return_pc = 0x0040_9000;
        let worker_event = kernel.create_event_w(None, true, true);
        let wait_started_ms = kernel.timers.tick_count();
        let worker_wait_id = kernel.register_blocked_waiter(
            worker_thread_id,
            worker_thread_handle,
            vec![worker_event],
            crate::ce::scheduler::SchedulerBlockedWaitKind::Kernel,
            wait_started_ms,
            INFINITE,
        );
        let mut worker_regs = super::MipsGuestContext::zero();
        worker_regs.regs[16] = 0x9090_0001;
        let blocked_waits = std::rc::Rc::new(std::cell::RefCell::new(vec![BlockedWaitThread {
            frame_ref: None,
            wait_id: worker_wait_id,
            thread_id: worker_thread_id,
            thread_handle: worker_thread_handle,
            wait_handles: vec![worker_event],
            kind: BlockedWaitKind::Kernel,
            wait_started_ms,
            timeout_ms: INFINITE,
            regs: worker_regs,
            return_pc: worker_return_pc,
        }]));
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let current_thread_id = std::rc::Rc::new(super::NativeCurrentThread::new(
            active_thread_id,
            kernel.handles.thread_birth_key_by_id(active_thread_id),
        ));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(Some((
            active_thread_id,
            active_thread_handle,
        ))));

        assert!(super::try_block_wait_comm_event(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_WAIT_COMM_EVENT),
            &[com, event_ptr],
            active_thread_id,
            &blocked_waits,
            &pending_returns,
            &current_thread_id,
            &suspended_thread,
            &running_thread,
            &std::cell::RefCell::new(None),
        ));

        assert!(kernel.blocked_waiter(worker_wait_id).is_none());
        assert_eq!(current_thread_id.get().0, worker_thread_id);
        assert_eq!(
            *running_thread.borrow(),
            Some((worker_thread_id, worker_thread_handle))
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::S0).unwrap() as u32,
            0x9090_0001
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::V0).unwrap() as u32,
            WAIT_OBJECT_0
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::PC).unwrap() as u32,
            worker_return_pc
        );
        let remaining = blocked_waits.borrow();
        assert_eq!(remaining.len(), 1);
        assert_eq!(remaining[0].thread_id, active_thread_id);
        assert!(matches!(
            remaining[0].kind,
            BlockedWaitKind::SerialCommEvent { handle, .. } if handle == com
        ));
        assert_eq!(remaining[0].return_pc, active_return_pc);
    }

    #[test]
    fn finite_serial_read_timeout_without_peer_completes_current_thread() {
        use unicorn_engine::RegisterMIPS;

        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.mem_map(0x2000_0000, 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();
        let thread_id = 6;
        let (thread_handle, thread_birth) = registered_native_test_thread(&mut kernel, thread_id);
        let return_pc = 0x0040_6000;
        let buffer = 0x2000_0100;
        let transferred_ptr = 0x2000_0200;
        let handle = kernel
            .create_file_w("COM7:", GENERIC_READ | GENERIC_WRITE, CREATE_ALWAYS)
            .unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x1234_5678).unwrap();
        uc.mem_write(u64::from(transferred_ptr), &0xffff_ffff_u32.to_le_bytes())
            .unwrap();

        let blocked_waits = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let current_thread_id = std::rc::Rc::new(super::NativeCurrentThread::new(
            thread_id,
            Some(thread_birth),
        ));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let running_thread =
            std::rc::Rc::new(std::cell::RefCell::new(Some((thread_id, thread_handle))));
        let mapped = std::cell::RefCell::new(super::KernelMemoryMappings::new(&[]));
        let pins = super::NativeMappingPins::default();
        let guards = std::cell::RefCell::new(std::collections::BTreeMap::new());
        let terminal_error = std::cell::RefCell::new(None);

        // Bracket both tick readings with host timestamps so host scheduling
        // jitter does not require an arbitrary upper bound on total duration.
        let host_started_before_tick = std::time::Instant::now();
        let tick_before = kernel.timers.tick_count();
        let host_started_after_tick = std::time::Instant::now();

        assert!(block_serial_read_file(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            Some(super::UnicornPrivateVmMapping {
                mapped: &mapped,
                owner,
                native_pins: &pins,
                active_guards: &guards,
                terminal_error: &terminal_error,
            }),
            &[],
            thread_id,
            &blocked_waits,
            &pending_returns,
            &current_thread_id,
            &suspended_thread,
            &running_thread,
            handle,
            buffer,
            16,
            transferred_ptr,
            50,
            &std::cell::RefCell::new(None),
        ));

        let host_finished_before_tick = std::time::Instant::now();
        let guest_elapsed_ms = u64::from(kernel.timers.tick_count().wrapping_sub(tick_before));
        let host_finished_after_tick = std::time::Instant::now();
        let host_elapsed_min_ms = host_finished_before_tick
            .duration_since(host_started_after_tick)
            .as_millis() as u64;
        let host_elapsed_max_ms = host_finished_after_tick
            .duration_since(host_started_before_tick)
            .as_millis() as u64;
        assert!(
            guest_elapsed_ms.saturating_add(2) >= host_elapsed_min_ms
                && guest_elapsed_ms <= host_elapsed_max_ms.saturating_add(2),
            "guest tick advanced {guest_elapsed_ms} ms for host interval \
             {host_elapsed_min_ms}..={host_elapsed_max_ms} ms"
        );

        assert!(blocked_waits.borrow().is_empty());
        assert!(kernel.blocked_waiters().next().is_none());
        assert_eq!(current_thread_id.get(), (thread_id, Some(thread_birth)));
        assert_eq!(*running_thread.borrow(), Some((thread_id, thread_handle)));
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x1234_5678);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 1);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, return_pc);
        let mut transferred = [0; 4];
        uc.mem_read(u64::from(transferred_ptr), &mut transferred)
            .unwrap();
        assert_eq!(u32::from_le_bytes(transferred), 0);
        assert!(terminal_error.borrow().is_none());
    }

