    #[test]
    fn current_sleep_yields_to_ready_blocked_get_message() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.mem_map(0x3000_0000, 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();

        let main_thread_id = super::MAIN_GUEST_THREAD_ID;
        let main_thread_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let active_thread_id = 9;
        let active_thread_handle = registered_test_thread(&mut kernel, active_thread_id);
        let worker_thread_id = 6;
        let worker_thread_handle = registered_test_thread(&mut kernel, worker_thread_id);
        let main_return_pc = 0x2222_2000_u32;
        let active_return_pc = 0x1111_2000_u32;
        let getmsg_wait_id = kernel.register_blocked_waiter(
            main_thread_id,
            main_thread_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            },
            kernel.timers.tick_count(),
            crate::ce::timer::INFINITE,
        );
        let worker_wait_started_ms = kernel.timers.tick_count();
        let worker_wait_id = kernel.register_blocked_waiter(
            worker_thread_id,
            worker_thread_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::Sleep,
            worker_wait_started_ms,
            101,
        );
        let blocked_waits = std::rc::Rc::new(std::cell::RefCell::new(vec![BlockedWaitThread {
            frame_ref: None,
            wait_id: worker_wait_id,
            thread_id: worker_thread_id,
            thread_handle: worker_thread_handle,
            wait_handles: Vec::new(),
            kind: BlockedWaitKind::Sleep,
            wait_started_ms: worker_wait_started_ms,
            timeout_ms: 101,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0x2222_6000,
        }]));
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let last_imports = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let import_milestones = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let current_thread_id = std::rc::Rc::new(super::NativeCurrentThread::new(
            active_thread_id,
            kernel.handles.thread_birth_key_by_id(active_thread_id),
        ));
        let blocked_get_message =
            std::rc::Rc::new(std::cell::RefCell::new(Some(super::BlockedGuestThread {
                wait_id: getmsg_wait_id,
                thread_id: main_thread_id,
                thread_birth: kernel
                    .live_thread_birth_key_by_id(main_thread_id)
                    .expect("boot GetMessage birth"),
                thread_handle: main_thread_handle,
                regs: super::MipsGuestContext::zero(),
                import_pc: 0,
                return_pc: main_return_pc,
                msg_ptr: 0x3000_0100,
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            })));
        let displaced_blocked_get_messages = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let self_suspended_threads =
            std::rc::Rc::new(std::cell::RefCell::new(std::collections::BTreeMap::new()));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(Some((
            active_thread_id,
            active_thread_handle,
        ))));
        uc.reg_write(
            unicorn_engine::RegisterMIPS::RA,
            u64::from(active_return_pc),
        )
        .unwrap();
        assert!(kernel.post_thread_message_w(
            main_thread_id,
            crate::ce::gwe::WM_USER + 0x24,
            0x25,
            0x26
        ));

        assert!(super::try_block_sleep(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SLEEP),
            &[334],
            active_thread_id,
            &last_imports,
            &import_milestones,
            &blocked_waits,
            &pending_returns,
            &current_thread_id,
            &blocked_get_message,
            &displaced_blocked_get_messages,
            &suspended_thread,
            &std::rc::Rc::new(std::cell::RefCell::new(std::collections::VecDeque::new())),
            &self_suspended_threads,
            &running_thread,
            &std::rc::Rc::new(std::cell::RefCell::new(Vec::new())),
            std::time::Instant::now(),
            Some(std::time::Duration::from_secs(1)),
            false,
            &std::cell::RefCell::new(None),
        ));

        assert_eq!(current_thread_id.get().0, main_thread_id);
        assert_eq!(
            *running_thread.borrow(),
            Some((main_thread_id, main_thread_handle))
        );
        assert!(blocked_get_message.borrow().is_none());
        assert!(suspended_thread.borrow().is_none());
        assert!(kernel.blocked_waiter(getmsg_wait_id).is_none());
        assert!(kernel.blocked_waiter(worker_wait_id).is_some());
        let remaining = blocked_waits.borrow();
        assert_eq!(remaining.len(), 2);
        assert!(remaining.iter().any(|blocked| {
            blocked.thread_id == worker_thread_id && matches!(blocked.kind, BlockedWaitKind::Sleep)
        }));
        assert!(remaining.iter().any(|blocked| {
            blocked.thread_id == active_thread_id && matches!(blocked.kind, BlockedWaitKind::Sleep)
        }));
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::V0).unwrap() as u32,
            1
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::PC).unwrap() as u32,
            main_return_pc
        );
    }

    #[test]
    fn blocked_current_get_message_dispatches_pending_send_when_no_thread_running() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.mem_map(0x3000_0000, 0x1000, unicorn_engine::Prot::ALL)
            .unwrap();

        let main_thread_id = super::MAIN_GUEST_THREAD_ID;
        let main_thread_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let sender_thread_id = 9;
        let import_pc = 0x7fff_2990_u32;
        let wndproc = 0x0001_3570_u32;
        let msg_ptr = 0x3000_0100_u32;
        let hwnd = kernel.create_window_ex_w(main_thread_id, "SYNC_TARGET", "", None, 0, 0, 0);
        assert!(
            kernel
                .gwe
                .set_window_long(hwnd, crate::ce::gwe::GWL_WNDPROC, wndproc)
                .is_some()
        );
        let send_msg = crate::ce::gwe::WM_USER + 0x77;
        let send_id = kernel
            .begin_cross_thread_send_message_w(sender_thread_id, hwnd, send_msg, 1, 2, None)
            .expect("queued cross-thread send");
        let getmsg_wait_id = kernel.register_blocked_waiter(
            main_thread_id,
            main_thread_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            },
            kernel.timers.tick_count(),
            crate::ce::timer::INFINITE,
        );
        let blocked_get_message =
            std::rc::Rc::new(std::cell::RefCell::new(Some(super::BlockedGuestThread {
                wait_id: getmsg_wait_id,
                thread_id: main_thread_id,
                thread_birth: kernel
                    .live_thread_birth_key_by_id(main_thread_id)
                    .expect("boot GetMessage birth"),
                thread_handle: main_thread_handle,
                regs: super::MipsGuestContext::zero(),
                import_pc,
                return_pc: 0x2222_7000,
                msg_ptr,
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            })));
        let current_thread_id =
            std::rc::Rc::new(super::NativeCurrentThread::new(main_thread_id, None));
        let displaced_blocked_get_messages = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let pending_wndproc_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));

        assert!(super::try_resume_blocked_get_message_after_current_blocked(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            main_thread_id,
            &current_thread_id,
            &blocked_get_message,
            &displaced_blocked_get_messages,
            &suspended_thread,
            &running_thread,
            &pending_wndproc_returns,
        ));

        assert_eq!(current_thread_id.get().0, main_thread_id);
        assert_eq!(
            *running_thread.borrow(),
            Some((main_thread_id, main_thread_handle))
        );
        assert!(blocked_get_message.borrow().is_none());
        assert!(suspended_thread.borrow().is_none());
        assert!(kernel.blocked_waiter(getmsg_wait_id).is_none());
        assert_eq!(
            kernel.gwe.active_sent_message_id(main_thread_id),
            Some(send_id)
        );
        assert!(kernel.gwe.in_send_message(main_thread_id));
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::A0).unwrap() as u32,
            hwnd
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::A1).unwrap() as u32,
            send_msg
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::A2).unwrap() as u32,
            1
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::A3).unwrap() as u32,
            2
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::PC).unwrap() as u32,
            wndproc
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::RA).unwrap() as u32,
            super::WNDPROC_RETURN_STUB_ADDR
        );
        let pending = pending_wndproc_returns.borrow();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].source, "GetMessageW/SentMessage");
        assert_eq!(pending[0].send_thread_id, Some(main_thread_id));
        assert_eq!(
            pending[0]
                .resume_import
                .as_ref()
                .map(|resume| resume.import_pc),
            Some(import_pc)
        );
    }

    #[test]
    fn escaped_get_message_sent_callout_completes_active_send() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();

        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("receiver birth");
        let sender_thread = 17;
        let import_pc = 0x7fff_2990_u32;
        let wndproc = 0x0001_2570_u32;
        let return_sp = 0x7ffd_f160_u32;
        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "EscapedSendTarget", "", None, 0, 0, 0);
        assert!(
            kernel
                .gwe
                .set_window_long(hwnd, crate::ce::gwe::GWL_WNDPROC, wndproc)
                .is_some()
        );
        let send_id = kernel
            .begin_cross_thread_send_message_w(
                sender_thread,
                hwnd,
                crate::ce::gwe::WM_USER + 1,
                0x0e,
                0,
                None,
            )
            .expect("queued cross-thread send");
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, send_id)
        );
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(send_id)
        );

        let mut resume_regs = super::MipsGuestContext::zero();
        resume_regs.regs[4] = 0x3000_1000;
        resume_regs.regs[5] = 0;
        resume_regs.regs[6] = 0;
        resume_regs.regs[7] = 0;
        let pending_returns =
            std::rc::Rc::new(std::cell::RefCell::new(vec![super::PendingWndProcReturn {
                source: "GetMessageW/SentMessage",
                hwnd,
                msg: crate::ce::gwe::WM_USER + 1,
                wparam: 0x0e,
                lparam: 0,
                typed_payload_owner: None,
                wndproc,
                return_pc: import_pc,
                return_sp,
                caller_regs: None,
                class_name: Some("EscapedSendTarget".to_owned()),
                api_result: None,
                dialog_result_hwnd: None,
                finalize_destroy: false,
                destroy_root_hwnd: None,
                remaining_destroy_callouts: Vec::new(),
                send_thread_id: Some(receiver_thread),
                send_timeout_result_ptr: None,
                send_restore: None,
                continuation: None,
                resume_import: Some(super::ResumeImportAfterWndProc {
                    thread_id: receiver_thread,
                    thread_birth: kernel
                        .live_thread_birth_key_by_id(receiver_thread)
                        .expect("receiver birth"),
                    sent_message_id: Some(send_id),
                    running_thread: Some((
                        receiver_thread,
                        crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
                    )),
                    regs: resume_regs.clone(),
                    import_pc,
                }),
                clear_focus_after_return: None,
            }]));
        uc.reg_write(unicorn_engine::RegisterMIPS::V0, 0x1122_3344)
            .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::PC, u64::from(import_pc))
            .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::SP, u64::from(return_sp))
            .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::RA,
            u64::from(super::WNDPROC_RETURN_STUB_ADDR),
        )
        .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::A0,
            u64::from(resume_regs.regs[4]),
        )
        .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::A1,
            u64::from(resume_regs.regs[5]),
        )
        .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::A2,
            u64::from(resume_regs.regs[6]),
        )
        .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::A3,
            u64::from(resume_regs.regs[7]),
        )
        .unwrap();

        assert!(super::complete_escaped_get_message_sent_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_W),
            import_pc,
            receiver_thread,
            Some(receiver_birth),
            &super::NativeCurrentThread::new(receiver_thread, Some(receiver_birth)),
            &pending_returns,
        ));

        assert!(pending_returns.borrow().is_empty());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(!kernel.gwe.in_send_message(receiver_thread));
        assert_eq!(
            kernel.take_completed_send_message_result(send_id),
            Some(0x1122_3344)
        );
        assert_eq!(
            uc.reg_read(unicorn_engine::RegisterMIPS::PC).unwrap() as u32,
            import_pc
        );
    }

    #[test]
    fn recorded_sent_callout_finishes_consumed_early_reply_by_exact_birth() {
        let mut kernel = crate::ce::kernel::CeKernel::boot(RuntimeConfig::load_default().unwrap());
        let (receiver_handle, receiver_thread) = kernel.create_guest_thread(0x0040_1000, 0, false);
        let receiver_birth = kernel
            .handles
            .thread_birth_key_for_handle(receiver_handle)
            .expect("receiver birth");
        let (_, sender_thread) = kernel.create_guest_thread(0x0040_2000, 0, false);
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "EARLY_REPLY_NATIVE",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned receiver HWND");
        let send_id = kernel
            .begin_cross_thread_send_message_w(
                sender_thread,
                hwnd,
                crate::ce::gwe::WM_USER + 1,
                0,
                0,
                None,
            )
            .expect("queued send");
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver_birth(receiver_birth, send_id)
        );
        assert!(kernel.reply_message(receiver_thread, 0x55aa));
        assert_eq!(
            kernel.take_completed_send_message_result(send_id),
            Some(0x55aa)
        );
        assert!(kernel.gwe.sent_message(send_id).is_none());
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(send_id)
        );

        let callout = super::PendingWndProcReturn {
            source: "GetMessageW/SentMessage",
            hwnd,
            msg: crate::ce::gwe::WM_USER + 1,
            wparam: 0,
            lparam: 0,
            typed_payload_owner: None,
            wndproc: 0x0040_5000,
            return_pc: 0x7fff_2990,
            return_sp: 0x7ffd_f160,
            caller_regs: None,
            class_name: None,
            api_result: None,
            dialog_result_hwnd: None,
            finalize_destroy: false,
            destroy_root_hwnd: None,
            remaining_destroy_callouts: Vec::new(),
            send_thread_id: Some(receiver_thread),
            send_timeout_result_ptr: None,
            send_restore: None,
            continuation: None,
            resume_import: Some(super::ResumeImportAfterWndProc {
                thread_id: receiver_thread,
                thread_birth: receiver_birth,
                sent_message_id: Some(send_id),
                running_thread: Some((receiver_thread, receiver_handle)),
                regs: super::MipsGuestContext::zero(),
                import_pc: 0x7fff_2990,
            }),
            clear_focus_after_return: None,
        };
        let completed_before = kernel.gwe.stats().send_transaction_completed_count;
        assert_eq!(
            super::complete_recorded_sent_callout(&mut kernel, &callout, 0x7788),
            Ok(Some(send_id))
        );
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert_eq!(
            kernel.gwe.stats().send_transaction_completed_count,
            completed_before
        );
        assert_eq!(kernel.take_completed_send_message_result(send_id), None);
    }

    #[test]
    fn peek_sent_host_dispatch_restore_failure_is_terminal() {
        let mut kernel = crate::ce::kernel::CeKernel::boot(RuntimeConfig::load_default().unwrap());
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("receiver birth");
        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "PeekHostDispatchTarget", "", None, 0, 0, 0);
        assert_eq!(
            kernel.gwe.window(hwnd).map(|window| window.wndproc),
            Some(crate::ce::gwe::DEFAULT_WNDPROC),
        );
        let send_id = kernel
            .begin_cross_thread_send_message_w(17, hwnd, crate::ce::gwe::WM_USER + 1, 0, 0, None)
            .expect("queued sent message");
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        let import_pc = 0x7fff_2990;
        uc.reg_write(unicorn_engine::RegisterMIPS::PC, u64::from(import_pc))
            .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::SP, 0x3000_1000)
            .unwrap();
        let current_thread_id = std::rc::Rc::new(super::NativeCurrentThread::new(
            receiver_thread,
            Some(receiver_birth),
        ));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(Some((
            receiver_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ))));
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));

        // The sent message may be host-dispatched, but failed KData restoration
        // must stop the native attempt rather than return a false Peek result.
        // Deliberately do not map KData in this minimal Unicorn instance.
        assert!(super::try_enter_get_message_sent_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_PEEK_MESSAGE_W),
            &[
                0x3000_2000,
                0,
                0,
                0,
                crate::ce::gwe::PeekFlags::REMOVE.bits()
            ],
            import_pc,
            receiver_thread,
            &current_thread_id,
            &running_thread,
            &pending_returns,
        ));
        assert!(matches!(
            current_thread_id.terminal_error.borrow().as_ref(),
            Some(crate::Error::Backend(message)) if message.contains("KData")
        ));
        assert_eq!(current_thread_id.get(), (receiver_thread, None));
        assert!(pending_returns.borrow().is_empty());
        assert!(kernel.gwe.sent_message_result_ready(send_id));
    }

    #[test]
    fn escaped_get_message_does_not_complete_reused_thread_birth() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let receiver_thread = 17;
        let old_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, receiver_thread, 0x0040_3000, 0, false)
            .expect("old receiver");
        let old_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("old receiver birth");
        assert!(kernel.mark_guest_thread_exited_by_id(receiver_thread, 0));
        kernel.close_handle(old_handle).expect("close old receiver");
        let _new_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, receiver_thread, 0x0040_4000, 0, false)
            .expect("replacement receiver");
        let new_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("replacement receiver birth");
        assert_ne!(old_birth, new_birth);

        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "ReusedSendTarget", "", None, 0, 0, 0);
        let send_id = kernel
            .begin_cross_thread_send_message_w(
                super::MAIN_GUEST_THREAD_ID,
                hwnd,
                crate::ce::gwe::WM_USER + 1,
                0,
                0,
                None,
            )
            .expect("queued send to replacement");
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, send_id)
        );
        let import_pc = 0x7fff_2990;
        let return_sp = 0x7ffd_f160;
        let pending_returns =
            std::rc::Rc::new(std::cell::RefCell::new(vec![super::PendingWndProcReturn {
                source: "GetMessageW/SentMessage",
                hwnd,
                msg: crate::ce::gwe::WM_USER + 1,
                wparam: 0,
                lparam: 0,
                typed_payload_owner: None,
                wndproc: 0x0040_5000,
                return_pc: import_pc,
                return_sp,
                caller_regs: None,
                class_name: Some("ReusedSendTarget".to_owned()),
                api_result: None,
                dialog_result_hwnd: None,
                finalize_destroy: false,
                destroy_root_hwnd: None,
                remaining_destroy_callouts: Vec::new(),
                send_thread_id: Some(receiver_thread),
                send_timeout_result_ptr: None,
                send_restore: None,
                continuation: None,
                resume_import: Some(super::ResumeImportAfterWndProc {
                    thread_id: receiver_thread,
                    thread_birth: old_birth,
                    sent_message_id: Some(send_id),
                    running_thread: Some((receiver_thread, old_handle)),
                    regs: super::MipsGuestContext::zero(),
                    import_pc,
                }),
                clear_focus_after_return: None,
            }]));
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::PC, u64::from(import_pc))
            .unwrap();
        uc.reg_write(unicorn_engine::RegisterMIPS::SP, u64::from(return_sp))
            .unwrap();
        uc.reg_write(
            unicorn_engine::RegisterMIPS::RA,
            u64::from(super::WNDPROC_RETURN_STUB_ADDR),
        )
        .unwrap();

        assert!(!super::complete_escaped_get_message_sent_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_W),
            import_pc,
            receiver_thread,
            Some(new_birth),
            &super::NativeCurrentThread::new(receiver_thread, Some(new_birth)),
            &pending_returns,
        ));
        assert_eq!(pending_returns.borrow().len(), 1);
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(send_id)
        );
        assert!(kernel.gwe.in_send_message(receiver_thread));
        assert_eq!(kernel.take_completed_send_message_result(send_id), None);
    }

