    #[test]
    fn timeslice_pending_survives_unsafe_sample_until_safe_pc() {
        let pending = std::cell::Cell::new(true);
        assert!(!super::scheduler_timeslice_consume_if_safe(&pending, false));
        assert!(pending.get());
        assert!(super::scheduler_timeslice_consume_if_safe(&pending, true));
        assert!(!pending.get());
        assert!(!super::scheduler_timeslice_consume_if_safe(&pending, true));
    }

    #[test]
    fn timeslice_identifies_mips_delay_slot_instructions() {
        assert!(super::is_mips_control_transfer_instruction(0x0800_1000)); // j
        assert!(super::is_mips_control_transfer_instruction(0x0c00_1000)); // jal
        assert!(super::is_mips_control_transfer_instruction(0x03e0_0008)); // jr ra
        assert!(super::is_mips_control_transfer_instruction(0x00e0_f809)); // jalr ra,a3
        assert!(super::is_mips_control_transfer_instruction(0x04c0_004c)); // bltz a2
        assert!(super::is_mips_control_transfer_instruction(0x50a0_0003)); // beql a1,zero
        assert!(super::is_mips_control_transfer_instruction(0x4501_0002)); // bc1t
        assert!(!super::is_mips_control_transfer_instruction(0x8ca5_0008)); // lw a1,8(a1)
        assert!(!super::is_mips_control_transfer_instruction(0x0000_0000)); // nop
    }

    #[test]
    fn pending_guest_thread_return_is_owned_by_worker_thread() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let creator_birth = kernel
            .handles
            .thread_birth_key_by_id(1)
            .expect("creator birth");
        let worker_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, 6, 0x0040_3000, 0, false)
            .expect("worker birth");
        let worker_birth = kernel
            .handles
            .thread_birth_key_by_id(6)
            .expect("worker birth");
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(vec![
            super::PendingGuestThreadReturn {
                creator_thread_id: 1,
                creator_birth,
                worker_thread_id: 6,
                worker_birth,
                thread_handle: worker_handle,
                return_pc: 0x1111_0000,
                creator_regs: super::MipsGuestContext::zero(),
            },
        ]));

        assert!(
            super::pop_pending_guest_thread_return_for_thread(&pending_returns, &kernel, 7)
                .is_none()
        );
        assert_eq!(pending_returns.borrow().len(), 1);

        let callout =
            super::pop_pending_guest_thread_return_for_thread(&pending_returns, &kernel, 6)
                .unwrap();
        assert_eq!(callout.worker_thread_id, 6);
        assert!(pending_returns.borrow().is_empty());
    }

    #[test]
    fn pending_guest_thread_return_can_complete_below_newer_worker() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let creator_one_birth = kernel
            .handles
            .thread_birth_key_by_id(1)
            .expect("main birth");
        let _creator_three_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, 3, 0x0040_3000, 0, false)
            .expect("second creator birth");
        let creator_three_birth = kernel
            .handles
            .thread_birth_key_by_id(3)
            .expect("creator birth");
        let worker_six_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, 6, 0x0040_6000, 0, false)
            .expect("first worker birth");
        let worker_six_birth = kernel
            .handles
            .thread_birth_key_by_id(6)
            .expect("first worker birth");
        let worker_eight_handle = kernel
            .handles
            .try_create_thread_in_birth(owner, 8, 0x0040_8000, 0, false)
            .expect("second worker birth");
        let worker_eight_birth = kernel
            .handles
            .thread_birth_key_by_id(8)
            .expect("second worker birth");
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(vec![
            super::PendingGuestThreadReturn {
                creator_thread_id: 1,
                creator_birth: creator_one_birth,
                worker_thread_id: 6,
                worker_birth: worker_six_birth,
                thread_handle: worker_six_handle,
                return_pc: 0x1111_0000,
                creator_regs: super::MipsGuestContext::zero(),
            },
            super::PendingGuestThreadReturn {
                creator_thread_id: 3,
                creator_birth: creator_three_birth,
                worker_thread_id: 8,
                worker_birth: worker_eight_birth,
                thread_handle: worker_eight_handle,
                return_pc: 0x3333_0000,
                creator_regs: super::MipsGuestContext::zero(),
            },
        ]));

        let callout =
            super::pop_pending_guest_thread_return_for_thread(&pending_returns, &kernel, 6)
                .unwrap();
        assert_eq!(callout.worker_thread_id, 6);
        let remaining = pending_returns.borrow();
        assert_eq!(remaining.len(), 1);
        assert_eq!(remaining[0].worker_thread_id, 8);
    }

    #[test]
    fn stale_pending_guest_thread_return_does_not_resume_reused_tid() -> crate::error::Result<()> {
        use unicorn_engine::RegisterMIPS;

        let config = RuntimeConfig::load_default()?;
        let mut kernel = crate::ce::kernel::CeKernel::boot(config);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_1000).unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x7fff_0000).unwrap();
        let boot_birth = kernel
            .handles
            .thread_birth_key_by_id(1)
            .expect("boot thread birth");
        let current_thread_id =
            std::rc::Rc::new(super::NativeCurrentThread::new(1_u32, Some(boot_birth)));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let stack_slots =
            std::rc::Rc::new(std::cell::RefCell::new(std::collections::BTreeMap::new()));
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));

        assert!(super::try_enter_create_thread_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_CREATE_THREAD),
            &[0, 0, 0x0040_3000, 0, 0, 0],
            1,
            0x8000_0000,
            &current_thread_id,
            &running_thread,
            &stack_slots,
            &pending_returns,
        ));
        let (worker_tid, old_handle) = (*running_thread.borrow()).expect("entered worker A");
        let old_birth = kernel
            .handles
            .thread_birth_key_by_id(worker_tid)
            .expect("worker A birth");
        assert_eq!(pending_returns.borrow().len(), 1);

        assert!(kernel.mark_guest_thread_exited_by_id(worker_tid, 0x11));
        kernel.close_handle(old_handle)?;
        assert!(!kernel.handles.contains_thread_birth(old_birth));
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, worker_tid, 0x0040_4000, 0, false)?;
        let new_birth = kernel
            .handles
            .thread_birth_key_by_id(worker_tid)
            .expect("worker B birth");
        assert_ne!(old_birth, new_birth);

        // The old native return is still pending, while this TID and stack
        // slot now belong to B. A's delayed completion has no authority to
        // retire B or load A's saved creator registers into B's CPU context.
        stack_slots.borrow_mut().insert(worker_tid, 7);
        uc.reg_write(RegisterMIPS::PC, 0x0040_4000).unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x7ffe_2000).unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7676_8989).unwrap();
        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x22],
            &pending_returns,
            &current_thread_id,
            Some(owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert!(kernel.handles.contains_thread_birth(new_birth));
        assert!(kernel.handles.thread_execution_live_by_id(worker_tid));
        assert_eq!(
            kernel.guest_thread_exit_code(new_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(stack_slots.borrow().get(&worker_tid), Some(&7));
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_4000);
        assert_eq!(uc.reg_read(RegisterMIPS::SP).unwrap() as u32, 0x7ffe_2000);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7676_8989);
        Ok(())
    }

    #[test]
    fn native_exit_selects_only_verified_birth_when_pending_returns_share_tid()
    -> crate::error::Result<()> {
        use unicorn_engine::RegisterMIPS;

        let mut kernel = crate::ce::kernel::CeKernel::boot(RuntimeConfig::load_default()?);
        let owner = kernel.current_process_birth_key().expect("boot owner");
        let creator_birth = kernel.handles.thread_birth_key_by_id(1).expect("creator");
        let old_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_3000, 0, false)?;
        let old_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker A");
        assert!(kernel.mark_guest_thread_exited_by_birth(old_birth, 0x11));
        kernel.close_handle(old_handle)?;
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_4000, 0, false)?;
        let new_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker B");
        assert_ne!(old_birth, new_birth);

        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(vec![
            super::PendingGuestThreadReturn {
                creator_thread_id: 1,
                creator_birth,
                worker_thread_id: 6,
                worker_birth: old_birth,
                thread_handle: old_handle,
                return_pc: 0x0040_1110,
                creator_regs: super::MipsGuestContext::zero(),
            },
            super::PendingGuestThreadReturn {
                creator_thread_id: 1,
                creator_birth,
                worker_thread_id: 6,
                worker_birth: new_birth,
                thread_handle: new_handle,
                return_pc: 0x0040_2220,
                creator_regs: {
                    let mut regs = super::MipsGuestContext::zero();
                    regs.regs[16] = 0xfeed_b002;
                    regs
                },
            },
        ]));
        let current_thread_id =
            std::rc::Rc::new(super::NativeCurrentThread::new(6, Some(old_birth)));
        let suspended_thread = std::rc::Rc::new(std::cell::RefCell::new(None));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(Some((6, new_handle))));
        let stack_slots =
            std::rc::Rc::new(std::cell::RefCell::new(std::collections::BTreeMap::from([
                (6, 7),
            ])));
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x0040_4000).unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x7ffe_2000).unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7676_8989).unwrap();

        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x22],
            &pending_returns,
            &current_thread_id,
            Some(owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert_eq!(pending_returns.borrow().len(), 2);
        assert_eq!(*running_thread.borrow(), Some((6, new_handle)));
        assert_eq!(stack_slots.borrow().get(&6), Some(&7));
        assert_eq!(
            kernel.guest_thread_exit_code(new_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_4000);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7676_8989);

        current_thread_id.set_verified(new_birth);
        let foreign_handle = kernel.handles.create_process(99);
        let foreign_owner = kernel.handles.process_birth_key(99).expect("foreign owner");
        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x23],
            &pending_returns,
            &current_thread_id,
            Some(foreign_owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert_eq!(pending_returns.borrow().len(), 2);
        assert_eq!(*running_thread.borrow(), Some((6, new_handle)));
        assert_eq!(stack_slots.borrow().get(&6), Some(&7));
        assert_eq!(
            kernel.guest_thread_exit_code(new_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        kernel.close_handle(foreign_handle)?;

        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x24],
            &pending_returns,
            &current_thread_id,
            Some(owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert_eq!(kernel.guest_thread_exit_code(new_handle), Some(0x24));
        assert_eq!(pending_returns.borrow().len(), 1);
        assert_eq!(pending_returns.borrow()[0].worker_birth, old_birth);
        assert!(stack_slots.borrow().is_empty());
        assert!(running_thread.borrow().is_none());
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_2220);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0xfeed_b002);
        Ok(())
    }

    #[test]
    fn native_exit_fallback_rejects_stale_birth_but_accepts_closed_worker_handle()
    -> crate::error::Result<()> {
        use unicorn_engine::RegisterMIPS;

        let mut kernel = crate::ce::kernel::CeKernel::boot(RuntimeConfig::load_default()?);
        let owner = kernel.current_process_birth_key().expect("boot owner");
        let creator_birth = kernel.handles.thread_birth_key_by_id(1).expect("creator");
        let old_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_3000, 0, false)?;
        let old_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker A");
        assert!(kernel.mark_guest_thread_exited_by_birth(old_birth, 0x11));
        kernel.close_handle(old_handle)?;
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_4000, 0, false)?;
        let new_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker B");
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let current_thread_id =
            std::rc::Rc::new(super::NativeCurrentThread::new(6, Some(old_birth)));
        let suspended_thread =
            std::rc::Rc::new(std::cell::RefCell::new(Some(super::SuspendedGuestThread {
                thread_id: 1,
                thread_birth: Some(creator_birth),
                thread_handle: None,
                regs: {
                    let mut regs = super::MipsGuestContext::zero();
                    regs.regs[16] = 0xfeed_c001;
                    regs
                },
                pc: 0x0040_1000,
            })));
        let running_thread = std::rc::Rc::new(std::cell::RefCell::new(Some((6, new_handle))));
        let stack_slots =
            std::rc::Rc::new(std::cell::RefCell::new(std::collections::BTreeMap::from([
                (6, 8),
            ])));
        let mut uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x0040_4000).unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x7ffe_2000).unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7676_8989).unwrap();

        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x22],
            &pending_returns,
            &current_thread_id,
            Some(owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert_eq!(*running_thread.borrow(), Some((6, new_handle)));
        assert!(suspended_thread.borrow().is_some());
        assert_eq!(stack_slots.borrow().get(&6), Some(&8));
        assert_eq!(
            kernel.guest_thread_exit_code(new_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_4000);
        assert_eq!(uc.reg_read(RegisterMIPS::SP).unwrap() as u32, 0x7ffe_2000);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7676_8989);

        current_thread_id.set_verified(new_birth);
        kernel.close_handle(new_handle)?;
        assert_eq!(kernel.handles.thread_birth_key_for_handle(new_handle), None);
        assert_eq!(kernel.handles.thread_birth_key_by_id(6), Some(new_birth));
        assert!(super::try_exit_guest_thread_callout(
            &mut kernel,
            &mut uc,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_EXIT_THREAD),
            &[0x23],
            &pending_returns,
            &current_thread_id,
            Some(owner),
            &suspended_thread,
            &running_thread,
            &stack_slots,
        ));
        assert!(running_thread.borrow().is_none());
        assert!(suspended_thread.borrow().is_none());
        assert!(stack_slots.borrow().is_empty());
        assert_eq!(kernel.handles.thread_birth_key_by_id(6), None);
        assert_eq!(current_thread_id.get(), (1, Some(creator_birth)));
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_1000);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0xfeed_c001);
        Ok(())
    }

    #[test]
    fn native_return_stub_no_exit_candidate_requires_live_owner_register_birth()
    -> crate::error::Result<()> {
        let mut kernel = crate::ce::kernel::CeKernel::boot(RuntimeConfig::load_default()?);
        let owner = kernel.current_process_birth_key().expect("boot owner");
        let root_birth = kernel
            .handles
            .thread_birth_key_by_id(1)
            .expect("root birth");
        let root_native = super::NativeCurrentThread::new(1, Some(root_birth));
        assert_eq!(
            super::verified_native_guest_thread_exit_birth(
                &kernel,
                &root_native,
                1,
                None,
                None,
                Some(owner),
            ),
            Some(root_birth)
        );

        let old_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_3000, 0, false)?;
        let old_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker A");
        assert!(kernel.mark_guest_thread_exited_by_birth(old_birth, 0x11));
        kernel.close_handle(old_handle)?;
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, 6, 0x0040_4000, 0, false)?;
        let new_birth = kernel.handles.thread_birth_key_by_id(6).expect("worker B");
        let stale_native = super::NativeCurrentThread::new(6, Some(old_birth));
        assert_eq!(
            super::verified_native_guest_thread_exit_birth(
                &kernel,
                &stale_native,
                6,
                None,
                None,
                Some(owner),
            ),
            None
        );
        let live_native = super::NativeCurrentThread::new(6, Some(new_birth));
        assert_eq!(
            super::verified_native_guest_thread_exit_birth(
                &kernel,
                &live_native,
                6,
                None,
                None,
                Some(owner),
            ),
            Some(new_birth)
        );
        kernel.close_handle(new_handle)?;
        Ok(())
    }

    #[test]
    fn pending_wndproc_return_can_complete_by_call_stack_below_newer_frame() {
        let make_pending = |hwnd, return_sp| super::PendingWndProcReturn {
            source: "DispatchMessageW",
            hwnd,
            msg: crate::ce::gwe::WM_PAINT,
            wparam: 0,
            lparam: 0,
            typed_payload_owner: None,
            wndproc: 0x6004_f0f4,
            return_pc: 0x1234_0000,
            return_sp,
            caller_regs: None,
            class_name: None,
            api_result: None,
            dialog_result_hwnd: None,
            finalize_destroy: false,
            destroy_root_hwnd: None,
            remaining_destroy_callouts: Vec::new(),
            send_thread_id: None,
            send_timeout_result_ptr: None,
            send_restore: None,
            continuation: None,
            resume_import: None,
            clear_focus_after_return: None,
        };
        let pending_returns = std::rc::Rc::new(std::cell::RefCell::new(vec![
            make_pending(0x0002_0004, 0x7ffd_f160),
            make_pending(0x0002_0008, 0x7ffd_f260),
        ]));

        let callout = super::pop_pending_wndproc_return_for_call_sp(
            &pending_returns,
            0x7ffd_f160 - super::WNDPROC_CALL_FRAME_BYTES,
        )
        .unwrap();
        assert_eq!(callout.hwnd, 0x0002_0004);
        let remaining = pending_returns.borrow();
        assert_eq!(remaining.len(), 1);
        assert_eq!(remaining[0].hwnd, 0x0002_0008);
    }

