    #[test]
    fn parked_process_return_stubs_are_not_resumable_work() -> Result<()> {
        let config = crate::config::RuntimeConfig::load_default()?;
        let kernel = CeKernel::boot(config);

        for pc in [THREAD_EXIT_STUB_ADDR, GUEST_THREAD_RETURN_STUB_ADDR] {
            let mut cpu = UnicornMips::new()?;
            cpu.set_initial_thread_id(5);
            cpu.saved_context = Some(SavedCpuContext {
                pc,
                regs: MipsGuestContext::zero(),
            });
            cpu.last_debug = Some(UnicornDebugSnapshot {
                pc,
                ra: pc,
                sp: 0x7ffc_0000,
                thread_exit_reached: pc == THREAD_EXIT_STUB_ADDR,
                ..Default::default()
            });
            let parked = ParkedProcess {
                application: Some("\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned()),
                process_handle: None,
                thread_handle: None,
                process_state: crate::ce::kernel::CurrentProcessState {
                    process_id: 67,
                    exit_code: crate::ce::kernel::STILL_ACTIVE,
                    signaled: false,
                },
                thread_id: 5,
                cpu: Box::new(cpu),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned(),
                module_host_path: std::path::PathBuf::from(
                    r"D:\INAVI_Emulator\INAVI\INavi\happyway_win.exe",
                ),
                command_line: String::new(),
                current_directory: None,
            };

            assert!(!UnicornMips::parked_process_can_run(&parked, &kernel));
            assert!(!UnicornMips::parked_process_has_live_pump_priority_work(
                &parked, &kernel
            ));
        }

        Ok(())
    }

    #[test]
    fn parked_modal_message_box_does_not_report_thread_exit() -> Result<()> {
        let config = crate::config::RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let launch = kernel.queue_process_launch(None, None);
        let thread_id = launch.thread_id;
        let primary = launch.primary_thread_birth.expect("child primary birth");
        let mut memory = ModalTestMemory::default();
        let text_ptr = 0x2000;
        let caption_ptr = 0x2100;
        memory.write_wide_z(text_ptr, "Route search failed");
        memory.write_wide_z(caption_ptr, "iNavi");

        let mut cpu = UnicornMips::new()?;
        cpu.set_initial_thread_id(thread_id);
        cpu.current_thread_id = thread_id;
        cpu.owned_process_launch = Some(launch.clone());
        let mut regs = MipsGuestContext::zero();
        regs.regs[2] = 0x1234;
        cpu.saved_context = Some(SavedCpuContext {
            pc: THREAD_EXIT_STUB_ADDR,
            regs,
        });
        cpu.saved_context_thread_birth = Some(primary);
        cpu.last_debug = Some(UnicornDebugSnapshot {
            pc: THREAD_EXIT_STUB_ADDR,
            ra: THREAD_EXIT_STUB_ADDR,
            v0: 0x1234,
            thread_exit_reached: true,
            ..Default::default()
        });
        let mut parked = parked_process_for_cpu(thread_id, cpu);
        parked.process_state.process_id = launch.process_id;

        assert_eq!(
            UnicornMips::parked_process_thread_exit_code(&parked, &kernel),
            Some(0x1234)
        );

        let modal_state = crate::ce::coredll::message_box_w_prepare(
            &mut kernel,
            &memory,
            None,
            None,
            thread_id,
            &[0, text_ptr, caption_ptr, 0],
        )
        .map_err(|result| Error::Backend(format!("prepare MessageBoxW returned {result}")))?;
        parked.cpu.blocked_modal_message_box = Some(BlockedModalMessageBox {
            wait_id: 1,
            thread_id,
            thread_handle: 0x200,
            regs: MipsGuestContext::zero(),
            return_pc: 0x0040_1000,
            modal_state,
        });

        assert_eq!(
            UnicornMips::parked_process_thread_exit_code(&parked, &kernel),
            None
        );
        assert!(UnicornMips::active_matching_parked_process_should_remain(
            &parked
        ));

        Ok(())
    }

