    #[test]
    fn requested_active_exit_preserves_foreign_cpu_under_same_birth_duplicate() -> Result<()> {
        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let exiting = kernel.queue_process_launch(Some("\\Test\\exiting.exe".to_owned()), None);
        let foreign = kernel.queue_process_launch(Some("\\Test\\survivor.exe".to_owned()), None);
        let exiting_birth = exiting.process_birth.expect("exiting birth");
        let foreign_birth = foreign.process_birth.expect("foreign birth");
        assert_ne!(exiting_birth, foreign_birth);
        let _ = kernel.take_pending_process_launches();
        kernel.set_current_process_id(foreign.process_id);
        let (foreign_parked, wait_id) =
            parked_blocked_foreign_exit_survivor(&mut kernel, &foreign, 0x0060_3450, 0x7ffa_2000)?;
        let foreign_cpu_before = foreign_parked.cpu.as_ref() as *const UnicornMips;

        let mut duplicate_cpu = UnicornMips::new()?;
        duplicate_cpu.owned_process_launch = Some(exiting.clone());
        duplicate_cpu.set_initial_thread_id(exiting.thread_id);
        duplicate_cpu.current_thread_id = exiting.thread_id;
        duplicate_cpu
            .parked_child_processes
            .push_back(foreign_parked);
        let mut duplicate_parked = parked_process_for_cpu(exiting.thread_id, duplicate_cpu);
        duplicate_parked.process_state.process_id = exiting.process_id;
        duplicate_parked.process_handle = Some(exiting.process_handle);
        duplicate_parked.thread_handle = Some(exiting.thread_handle);

        let mut active = UnicornMips::new()?;
        active.owned_process_launch = Some(exiting.clone());
        active.set_initial_thread_id(exiting.thread_id);
        active.current_thread_id = exiting.thread_id;
        active.parked_child_processes.push_back(duplicate_parked);
        kernel.set_current_process_id(exiting.process_id);
        assert!(kernel.terminate_process(exiting.process_handle, 0x6e));
        assert!(
            active
                .complete_requested_active_child_termination(&mut kernel, None)
                .expect("live exact foreign CPU must survive requested exit")
        );
        assert!(active.active_process_execution_completed());
        assert!(
            !kernel
                .handles
                .process_execution_live_by_birth(exiting_birth)
        );
        assert_eq!(kernel.process_exit_code(exiting.process_handle), Some(0x6e));
        assert_eq!(
            kernel
                .recent_process_ops()
                .iter()
                .filter(|record| {
                    record.op == "CreateProcessTerminationCompleted"
                        && record.process_id == Some(exiting.process_id)
                })
                .count(),
            1
        );
        assert_eq!(active.parked_child_processes.len(), 1);
        assert_parked_foreign_exit_survivor(
            &active.parked_child_processes[0],
            &foreign,
            foreign_cpu_before,
            wait_id,
            0x0060_3450,
            0x7ffa_2000,
        );
        assert!(
            kernel
                .handles
                .process_execution_live_by_birth(foreign_birth)
        );
        assert!(kernel.blocked_waiter(wait_id).is_some());
        Ok(())
    }

    #[test]
    fn stopped_boot_exit_refuses_exact_birth_parked_popup_before_kernel_effects() -> Result<()> {
        use crate::ce::scheduler::SchedulerBlockedWaitKind;

        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let boot_birth = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let primary = kernel
            .handles
            .thread_birth_key_by_id(MAIN_GUEST_THREAD_ID)
            .expect("boot primary thread birth");
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                primary,
                "BOOT_POPUP_OWNER",
                "",
                None,
                None,
                0,
                crate::ce::gwe::WS_VISIBLE,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 100, 100),
            )
            .expect("boot-owned popup owner window");
        let menu = kernel.resources.create_popup_menu();
        assert!(kernel.resources.append_menu_item(
            menu,
            crate::ce::resource::MenuItem::from_insert_flags(0, 0x42, Some("Choice".to_owned()),),
        ));
        let mut source = VirtualFramebuffer::default_primary()?;
        let modal_state = crate::ce::coredll::track_popup_menu_ex_prepare(
            &mut kernel,
            &ModalTestMemory::default(),
            Some(&mut source),
            MAIN_GUEST_THREAD_ID,
            &[menu, 0, 100, 100, hwnd, 0],
        )
        .map_err(|result| Error::Backend(format!("prepare TrackPopupMenuEx returned {result}")))?;
        let wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                primary,
                crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
                Vec::new(),
                SchedulerBlockedWaitKind::PopupMenuModal {
                    mouse_message_max: modal_state.mouse_message_max,
                },
                kernel.timers.tick_count(),
                crate::ce::timer::INFINITE,
            )
            .expect("exact boot popup wait");
        let mut parked_cpu = UnicornMips::new()?;
        parked_cpu.set_initial_thread_id(MAIN_GUEST_THREAD_ID);
        parked_cpu.current_thread_id = MAIN_GUEST_THREAD_ID;
        parked_cpu.saved_context_thread_birth = Some(primary);
        parked_cpu.blocked_popup_menu_modal = Some(BlockedPopupMenuModal {
            wait_id,
            thread_id: MAIN_GUEST_THREAD_ID,
            thread_handle: crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
            regs: MipsGuestContext::zero(),
            return_pc: 0x0040_1000,
            modal_state,
        });
        let mut parked = parked_process_for_cpu(MAIN_GUEST_THREAD_ID, parked_cpu);
        parked.process_state.process_id = boot_birth.process_id();
        let mut active = UnicornMips::new()?;
        active.set_initial_thread_id(MAIN_GUEST_THREAD_ID);
        active.current_thread_id = MAIN_GUEST_THREAD_ID;
        active.saved_context = Some(SavedCpuContext {
            pc: THREAD_EXIT_STUB_ADDR,
            regs: MipsGuestContext::zero(),
        });
        active.saved_context_thread_birth = Some(primary);
        active.last_debug = Some(UnicornDebugSnapshot {
            pc: THREAD_EXIT_STUB_ADDR,
            v0: 0x76,
            thread_exit_reached: true,
            ..Default::default()
        });
        active.parked_child_processes.push_back(parked);

        let mut destination = VirtualFramebuffer::new(
            VirtualFramebuffer::DEFAULT_WIDTH,
            VirtualFramebuffer::DEFAULT_HEIGHT,
            crate::ce::framebuffer::PixelFormat::Bgra8888,
        )?;
        let pixels_before = destination.pixels().to_vec();
        let dirty_before = destination.dirty_rects().to_vec();
        let process_before = kernel.current_process_state();
        let trace_before = kernel.recent_process_ops().len();
        let error = active
            .try_complete_active_process_thread_exit(&mut kernel, Some(&mut destination))
            .expect_err("exact-birth parked boot popup requires pre-exit recovery");
        assert!(matches!(
            error,
            Error::HostExitRecoveryRequired { process_id, incarnation, .. }
                if process_id == boot_birth.process_id()
                    && incarnation == boot_birth.incarnation()
        ));
        assert_eq!(kernel.current_process_state(), process_before);
        assert!(kernel.handles.process_execution_live_by_birth(boot_birth));
        assert_eq!(active.parked_child_processes.len(), 1);
        assert!(
            active.parked_child_processes[0]
                .cpu
                .blocked_popup_menu_modal
                .is_some()
        );
        assert_eq!(
            active.saved_context.as_ref().map(|saved| saved.pc),
            Some(THREAD_EXIT_STUB_ADDR)
        );
        assert!(kernel.blocked_waiter(wait_id).is_some());
        assert!(kernel.gwe.is_window(hwnd));
        assert_eq!(destination.pixels(), pixels_before);
        assert_eq!(destination.dirty_rects(), dirty_before.as_slice());
        assert_eq!(kernel.recent_process_ops().len(), trace_before);
        Ok(())
    }

    #[test]
    fn parked_modal_ready_probe_requires_published_wait_after_button_result() -> Result<()> {
        use crate::ce::gwe::Point;
        use crate::ce::scheduler::SchedulerBlockedWaitKind;

        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let thread_id = MAIN_GUEST_THREAD_ID;
        let birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("boot modal thread birth");
        let thread_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let mut memory = ModalTestMemory::default();
        let text_ptr = 0x2000;
        let caption_ptr = 0x2100;
        memory.write_wide_z(text_ptr, "Continue");
        memory.write_wide_z(caption_ptr, "Modal");
        let modal_state = crate::ce::coredll::message_box_w_prepare(
            &mut kernel,
            &memory,
            None,
            None,
            thread_id,
            &[0, text_ptr, caption_ptr, 0],
        )
        .map_err(|result| Error::Backend(format!("prepare MessageBoxW returned {result}")))?;
        let dialog = modal_state.dialog_hwnd();
        let button = kernel
            .gwe
            .get_dlg_item(dialog, 1)
            .expect("MessageBox OK button");
        let wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                birth,
                thread_handle,
                Vec::new(),
                SchedulerBlockedWaitKind::ModalMessageBox {
                    dialog_hwnd: dialog,
                },
                kernel.timers.tick_count(),
                crate::ce::timer::INFINITE,
            )
            .expect("birth-owned modal wait");
        let mut cpu = UnicornMips::new()?;
        cpu.set_initial_thread_id(thread_id);
        cpu.current_thread_id = thread_id;
        cpu.blocked_modal_message_box = Some(BlockedModalMessageBox {
            wait_id,
            thread_id,
            thread_handle,
            regs: MipsGuestContext::zero(),
            return_pc: 0x0040_1000,
            modal_state,
        });
        let parked = parked_process_for_cpu(thread_id, cpu);

        kernel.remote.set_framebuffer_size(800, 480);
        let rect = kernel.gwe.get_window_rect(button).expect("button rect");
        let point = Point {
            x: rect.left + rect.width() / 2,
            y: rect.top + rect.height() / 2,
        };
        assert_eq!(
            kernel.gwe.window_from_point_for_thread(thread_id, point),
            Some(button)
        );
        kernel
            .remote
            .enqueue_touch("tap", point.x, point.y)
            .expect("button tap");
        assert_eq!(
            kernel.drain_remote_input_to_thread_window(thread_id, Some(dialog)),
            2
        );
        assert!(kernel.has_modal_dialog_result(thread_id, dialog));
        assert_eq!(
            UnicornMips::parked_process_ready_wait_id(&parked, &kernel),
            Some(wait_id)
        );

        // The result is still queued, but a detached modal payload cannot
        // nominate an absent wait as a runnable parked-process continuation.
        assert!(kernel.remove_blocked_waiter(wait_id).is_some());
        assert!(kernel.has_modal_dialog_result(thread_id, dialog));
        assert_eq!(
            UnicornMips::parked_process_ready_wait_id(&parked, &kernel),
            None
        );
        Ok(())
    }

    #[test]
    fn non_requeued_terminal_child_handoff_marks_process_exited() -> Result<()> {
        let config = crate::config::RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let mut scheduler = UnicornMips::new()?;

        let launch = kernel.queue_process_launch(
            Some("\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned()),
            Some("iNavi|SDMMC Disk\\mapdata".to_owned()),
        );
        scheduler.owned_process_launch = Some(launch.clone());
        scheduler.set_initial_thread_id(launch.thread_id);
        scheduler.current_thread_id = launch.thread_id;
        scheduler.saved_context = Some(SavedCpuContext {
            pc: GUEST_THREAD_RETURN_STUB_ADDR,
            regs: MipsGuestContext::zero(),
        });
        scheduler.saved_context_thread_birth = launch.primary_thread_birth;
        scheduler.last_debug = Some(UnicornDebugSnapshot {
            pc: GUEST_THREAD_RETURN_STUB_ADDR,
            ra: GUEST_THREAD_RETURN_STUB_ADDR,
            v0: 0x42,
            ..Default::default()
        });
        kernel.set_current_process_state(crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        });
        kernel.set_process_module_base(0x0040_0000);
        kernel.set_process_module_path("\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned());
        kernel.set_process_module_host_path(std::path::PathBuf::from(
            r"D:\INAVI_Emulator\INAVI\INavi\happyway_win.exe",
        ));
        let child_hwnd =
            kernel.create_window_ex_w(launch.thread_id, "hidden_child", "", None, 0, 0, 0);
        assert!(kernel.gwe.window(child_hwnd).is_some_and(|w| !w.destroyed));

        let parent_thread = 1;
        let mut parent_cpu = UnicornMips::new()?;
        parent_cpu.set_initial_thread_id(parent_thread);
        parent_cpu.current_thread_id = parent_thread;
        parent_cpu.saved_context = Some(SavedCpuContext {
            pc: 0x0010_2000,
            regs: MipsGuestContext::zero(),
        });
        let stale_child_cpu = scheduler.clone();
        parent_cpu.parked_child_processes.push_back(ParkedProcess {
            application: launch.application.clone(),
            process_handle: Some(launch.process_handle),
            thread_handle: Some(launch.thread_handle),
            process_state: crate::ce::kernel::CurrentProcessState {
                process_id: launch.process_id,
                exit_code: crate::ce::kernel::STILL_ACTIVE,
                signaled: false,
            },
            thread_id: launch.thread_id,
            cpu: Box::new(stale_child_cpu),
            blocked_send_id: None,
            module_base: 0x0040_0000,
            module_path: "\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned(),
            module_host_path: std::path::PathBuf::from(
                r"D:\INAVI_Emulator\INAVI\INavi\happyway_win.exe",
            ),
            command_line: launch.command_line.clone().unwrap_or_default(),
            current_directory: None,
        });
        scheduler.parked_child_processes.push_back(ParkedProcess {
            application: Some("\\SDMMC Disk\\INavi\\iNavi.exe".to_owned()),
            process_handle: None,
            thread_handle: None,
            process_state: crate::ce::kernel::CurrentProcessState {
                process_id: 1,
                exit_code: crate::ce::kernel::STILL_ACTIVE,
                signaled: false,
            },
            thread_id: parent_thread,
            cpu: Box::new(parent_cpu),
            blocked_send_id: None,
            module_base: 0x0010_0000,
            module_path: "\\SDMMC Disk\\INavi\\iNavi.exe".to_owned(),
            module_host_path: std::path::PathBuf::from(r"D:\INAVI_Emulator\INAVI\INavi\iNavi.exe"),
            command_line: String::new(),
            current_directory: None,
        });

        assert!(scheduler.switch_to_next_parked_child_process(&mut kernel));

        assert_eq!(kernel.current_process_id(), 1);
        assert_eq!(scheduler.current_thread_id, parent_thread);
        assert!(kernel.gwe.window(child_hwnd).is_none_or(|w| w.destroyed));
        assert!(kernel.recent_process_ops().iter().any(|record| {
            record.op == "CreateProcessExited"
                && record.process_id == Some(launch.process_id)
                && record.thread_id == Some(launch.thread_id)
                && record.result == Some(0x42)
        }));

        Ok(())
    }

