#[cfg(feature = "unicorn")]
fn annotate_call_import_targets(calls: &mut [UnicornLastCall], traps: &ImportTrapTable) {
    for call in calls {
        let Some(trap) = traps.trap_at(call.target) else {
            continue;
        };
        call.target_module_kind = Some(trap.module_kind);
        call.target_module_name = Some(trap.module_name.clone());
        call.target_name = trap.name.clone();
        call.target_ordinal = trap.ordinal;
    }
}

fn import_count_snapshot(
    counts: &std::collections::BTreeMap<UnicornImportCountKey, UnicornImportStats>,
) -> Vec<UnicornImportCount> {
    const IMPORT_COUNT_SNAPSHOT_LIMIT: usize = 256;

    let mut counts = counts
        .iter()
        .map(|(key, stats)| UnicornImportCount {
            module: key.module.clone(),
            ordinal: key.ordinal,
            name: key.name.clone(),
            count: stats.count,
            max_a0: stats.max_a0,
            max_a1: stats.max_a1,
            max_a2: stats.max_a2,
            max_a3: stats.max_a3,
        })
        .collect::<Vec<_>>();
    counts.sort_by(|lhs, rhs| {
        rhs.count
            .cmp(&lhs.count)
            .then_with(|| lhs.module.cmp(&rhs.module))
            .then_with(|| lhs.ordinal.cmp(&rhs.ordinal))
            .then_with(|| lhs.name.cmp(&rhs.name))
    });
    counts.truncate(IMPORT_COUNT_SNAPSHOT_LIMIT);
    counts
}

#[cfg(feature = "unicorn")]
fn read_unicorn_stack_words<D>(
    uc: &unicorn_engine::Unicorn<'_, D>,
    sp: u32,
    byte_len: u32,
) -> Vec<(u32, Option<u32>)> {
    let mut words = Vec::new();
    let mut offset = 0;
    while offset < byte_len {
        words.push((
            offset,
            sp.checked_add(offset)
                .and_then(|addr| read_unicorn_u32(uc, addr)),
        ));
        offset = offset.saturating_add(4);
    }
    words
}

/// Host memory writes bypass Unicorn's guest page protection; explicitly check
/// writable persistent RAM before an allocator can initialize/publish a pointer.
#[cfg(feature = "unicorn")]
fn validate_heap_destination<D>(
    uc: &unicorn_engine::Unicorn<'_, D>,
    blobs: Option<&[MappedBlob]>,
    addr: u32,
    len: u32,
    allow_missing: bool,
) -> Result<()> {
    let end = addr
        .checked_add(len)
        .ok_or_else(|| Error::InvalidArgument("heap destination overflow".to_owned()))?;
    let regions = uc
        .mem_regions()
        .map_err(|err| Error::Backend(format!("inspect heap destination: {err:?}")))?;
    let mut cursor = u64::from(addr);
    while cursor < u64::from(end) {
        let Some(region) = regions
            .iter()
            .find(|region| cursor >= region.begin && cursor <= region.end)
        else {
            if !allow_missing {
                return Err(Error::InvalidArgument(
                    "heap destination is unmapped".to_owned(),
                ));
            }
            cursor = regions
                .iter()
                .filter(|region| region.begin > cursor)
                .map(|region| region.begin)
                .min()
                .unwrap_or(u64::from(end))
                .min(u64::from(end));
            continue;
        };
        let needed = (unicorn_engine::Prot::READ | unicorn_engine::Prot::WRITE).0 as u32;
        if region.perms & needed != needed {
            return Err(Error::InvalidArgument(
                "heap destination is not writable RAM".to_owned(),
            ));
        }
        let mut next = u64::from(end).min(region.end + 1);
        if let Some(blobs) = blobs {
            let Some(blob) = blobs.iter().find(|blob| {
                blob.name.starts_with("ram:")
                    && cursor >= u64::from(blob.base)
                    && cursor < u64::from(blob.base) + blob.bytes.len() as u64
            }) else {
                return Err(Error::InvalidArgument(
                    "heap destination has no persistent RAM backing".to_owned(),
                ));
            };
            next = next.min(u64::from(blob.base) + blob.bytes.len() as u64);
        }
        cursor = next;
    }
    Ok(())
}

#[cfg(feature = "unicorn")]
struct UnicornGuestMemory<'a, 'uc, D> {
    uc: &'a mut unicorn_engine::Unicorn<'uc, D>,
    heap_mapping: Option<UnicornHeapMapping<'a>>,
    private_vm_mapping: Option<UnicornPrivateVmMapping<'a>>,
    private_vm_applied_generation: Option<u64>,
    sealed_host_write_guard: SealedHostWriteGuard,
    #[cfg(test)]
    fail_next_private_unmap_for_test: bool,
}

#[cfg(feature = "unicorn")]
#[derive(Clone, Copy)]
struct UnicornHeapMapping<'a> {
    mapped: &'a RefCell<KernelMemoryMappings>,
    mapped_blobs: *mut Vec<MappedBlob>,
}

#[cfg(feature = "unicorn")]
#[derive(Clone, Copy)]
struct UnicornPrivateVmMapping<'a> {
    mapped: &'a RefCell<KernelMemoryMappings>,
    owner: crate::ce::object::ProcessBirthKey,
    native_pins: &'a NativeMappingPins,
    active_guards: &'a ActivePrivatePageGuards,
    terminal_error: &'a RefCell<Option<Error>>,
}

#[cfg(feature = "unicorn")]
impl<'a, 'uc, D> UnicornGuestMemory<'a, 'uc, D> {
    fn new(uc: &'a mut unicorn_engine::Unicorn<'uc, D>) -> Self {
        Self {
            uc,
            heap_mapping: None,
            private_vm_mapping: None,
            private_vm_applied_generation: None,
            sealed_host_write_guard: SealedHostWriteGuard::default(),
            #[cfg(test)]
            fail_next_private_unmap_for_test: false,
        }
    }

    unsafe fn with_heap_mapping(
        uc: &'a mut unicorn_engine::Unicorn<'uc, D>,
        mapped: &'a RefCell<KernelMemoryMappings>,
        mapped_blobs: *mut Vec<MappedBlob>,
    ) -> Self {
        Self {
            uc,
            heap_mapping: Some(UnicornHeapMapping {
                mapped,
                mapped_blobs,
            }),
            private_vm_mapping: None,
            private_vm_applied_generation: None,
            sealed_host_write_guard: SealedHostWriteGuard::default(),
            #[cfg(test)]
            fail_next_private_unmap_for_test: false,
        }
    }

    fn with_private_vm_mapping(mut self, mapping: UnicornPrivateVmMapping<'a>) -> Self {
        self.private_vm_mapping = Some(mapping);
        self
    }

    fn with_optional_private_vm_mapping(
        mut self,
        mapping: Option<UnicornPrivateVmMapping<'a>>,
    ) -> Self {
        self.private_vm_mapping = mapping;
        self
    }

    fn with_sealed_host_write_guard(mut self, guard: &SealedHostWriteGuard) -> Self {
        self.sealed_host_write_guard = guard.clone();
        self
    }

    fn reconcile_private_vm_mapping(&mut self, kernel: &CeKernel) -> Result<()> {
        let mapping = self.private_vm_mapping.ok_or_else(|| {
            Error::Unsupported("private VM has no captured native mapping context".to_owned())
        })?;
        let heap = self.heap_mapping.ok_or_else(|| {
            Error::Unsupported("private VM has no native blob mapping context".to_owned())
        })?;
        if !std::ptr::eq(mapping.mapped, heap.mapped) {
            return Err(Error::Backend(
                "private VM and heap mapping ledgers differ".to_owned(),
            ));
        }
        let mut mapped = mapping.mapped.borrow_mut();
        if mapped.heap_generation != kernel.memory.heap_generation()
            || mapped.virtual_generation != kernel.memory.virtual_generation()
        {
            // The first import begins with an unsynchronized ledger. Reconcile
            // all pre-existing mappings before the detached private token has
            // any native side effect; afterward the token is the only change.
            // SAFETY: this pointer belongs to the live, sequential import
            // adapter, as in ensure_heap_mapped below.
            let blobs = unsafe { &mut *heap.mapped_blobs };
            map_kernel_memory_allocations_for_owner(
                self.uc,
                kernel,
                &mut mapped,
                blobs,
                Some(mapping.owner),
                Some(mapping.native_pins),
                Some(mapping.active_guards),
            )?;
        }
        Ok(())
    }

    fn validate_private_host_access(&self, addr: u32, len: usize, required: u32) -> Result<()> {
        if len == 0 {
            return Ok(());
        }
        let end = u64::from(addr)
            .checked_add(u64::try_from(len).map_err(|_| {
                Error::InvalidArgument("guest access length overflows address space".to_owned())
            })?)
            .filter(|end| *end <= u64::from(u32::MAX) + 1)
            .ok_or_else(|| Error::InvalidArgument("guest access range wraps VA".to_owned()))?;
        let Some(mapping) = self.private_vm_mapping else {
            return Ok(());
        };
        let first_page = addr & !0xfff;
        let last_page = ((end - 1) as u32) & !0xfff;
        let mapped = mapping.mapped.borrow();
        let mut page = first_page;
        loop {
            let recorded = mapped.private_pages.get(&page);
            if overlaps_fixed_system_slab(&mapped, page, 0x1000) && recorded.is_none() {
                return Err(Error::InvalidArgument(format!(
                    "host access to untouched fixed system slab page 0x{page:08x}"
                )));
            }
            if recorded.is_some_and(|record| {
                record.identity.owner() != mapping.owner || record.perms & required != required
            }) {
                return Err(Error::InvalidArgument(format!(
                    "guest access at private page 0x{page:08x} violates native protection"
                )));
            }
            if page == last_page {
                break;
            }
            page = page.checked_add(0x1000).ok_or_else(|| {
                Error::InvalidArgument("host private access page wraps VA".to_owned())
            })?;
        }
        Ok(())
    }
}

#[cfg(feature = "unicorn")]
impl<D> CoredllGuestMemory for UnicornGuestMemory<'_, '_, D> {
    fn native_shared_view_owner(&self) -> Option<crate::ce::object::ProcessBirthKey> {
        self.private_vm_mapping.map(|mapping| mapping.owner)
    }

    fn prepare_host_write(&mut self, kernel: &mut CeKernel, addr: u32, len: u32) -> Result<()> {
        if len == 0 {
            return Ok(());
        }
        let Some(mapping) = self.private_vm_mapping else {
            // Compatibility adapters without a native owner cannot publish a
            // fixed stack page. Their ordinary write still checks the guest VA.
            return Ok(());
        };
        let end = addr
            .checked_add(len)
            .ok_or_else(|| Error::InvalidArgument("host output range wraps guest VA".to_owned()))?;
        self.sealed_host_write_guard
            .check_write(u64::from(addr), len as usize)?;
        if kernel.current_process_birth_key() != Some(mapping.owner)
            || kernel.handles.process_birth_key(mapping.owner.process_id()) != Some(mapping.owner)
        {
            return Err(Error::Backend(
                "host output owner differs from selected process birth".to_owned(),
            ));
        }
        let first = addr & !0xfff;
        let last = (end - 1) & !0xfff;
        let mut existing = Vec::new();
        let mut missing_stack = Vec::new();
        let mut page = first;
        loop {
            let (is_system_slab, recorded, slab_owner) = {
                let mapped = mapping.mapped.borrow();
                (
                    overlaps_fixed_system_slab(&mapped, page, 0x1000),
                    mapped.private_pages.get(&page).copied(),
                    mapped.system_slab_owner,
                )
            };
            let native_perms = native_page_perms(self.uc, page)?;
            if is_system_slab {
                if slab_owner != Some(mapping.owner) {
                    return Err(Error::Backend(
                        "host output fixed slab has another native owner".to_owned(),
                    ));
                }
                let allocation = kernel
                    .memory
                    .virtual_allocations_visible_to(mapping.owner)
                    .find(|allocation| {
                        page >= allocation.base
                            && allocation
                                .base
                                .checked_add(allocation.size)
                                .is_some_and(|end| page < end)
                    })
                    .ok_or_else(|| {
                        Error::Backend(format!(
                            "host output fixed page 0x{page:08x} has no owner reservation"
                        ))
                    })?;
                if allocation.backing != VirtualAllocationBacking::StablePrivateSlab
                    || !matches!(
                        allocation.source,
                        VirtualAllocationSource::ProcessHeapArena
                            | VirtualAllocationSource::ThreadStack
                    )
                {
                    return Err(Error::Backend(format!(
                        "host output fixed page 0x{page:08x} has another byte authority"
                    )));
                }
                if self.heap_mapping.is_some_and(|heap| {
                    // SAFETY: sequential import dispatch owns this vector.
                    unsafe { &*heap.mapped_blobs }.iter().any(|blob| {
                        let blob_start = u64::from(blob.base);
                        let blob_end = blob_start + blob.bytes.len() as u64;
                        u64::from(page) < blob_end && blob_start < u64::from(page) + 0x1000
                    })
                }) {
                    return Err(Error::Backend(format!(
                        "host output fixed page 0x{page:08x} overlaps a byte blob"
                    )));
                }
                match kernel.memory.private_page_pin(mapping.owner, page) {
                    Some(pin) => {
                        if let Some(record) = recorded {
                            let needed = unicorn_engine::Prot::WRITE.0 as u32;
                            if record.identity != pin.identity()
                                || record.host_address != pin.native_ptr() as usize
                                || record.perms & needed != needed
                                || native_perms != Some(record.perms)
                            {
                                return Err(Error::Backend(format!(
                                    "host output fixed page 0x{page:08x} differs from native ledger"
                                )));
                            }
                        } else if native_perms.is_some() {
                            return Err(Error::Backend(format!(
                                "host output fixed page 0x{page:08x} has an unowned native map"
                            )));
                        }
                        existing.push(pin);
                    }
                    None if allocation.source == VirtualAllocationSource::ThreadStack => {
                        if recorded.is_some() || native_perms.is_some() {
                            return Err(Error::Backend(format!(
                                "untouched stack page 0x{page:08x} already has native bytes"
                            )));
                        }
                        missing_stack.push(page);
                    }
                    None => {
                        return Err(Error::InvalidArgument(format!(
                            "host output heap page 0x{page:08x} was not committed by HeapAlloc"
                        )));
                    }
                }
            } else {
                let needed = unicorn_engine::Prot::WRITE.0 as u32;
                if native_perms.is_none_or(|perms| perms & needed != needed)
                    || recorded.is_some_and(|record| record.identity.owner() != mapping.owner)
                {
                    return Err(Error::InvalidArgument(format!(
                        "host output page 0x{page:08x} is not writable guest memory"
                    )));
                }
            }
            if page == last {
                break;
            }
            page = page.checked_add(0x1000).ok_or_else(|| {
                Error::InvalidArgument("host output page wraps guest VA".to_owned())
            })?;
        }
        let prepared = if let (Some(&first), Some(&last)) =
            (missing_stack.first(), missing_stack.last())
        {
            let span_len = last
                .checked_add(0x1000)
                .and_then(|end| end.checked_sub(first))
                .ok_or_else(|| Error::InvalidArgument("host stack span wraps VA".to_owned()))?;
            let token = kernel
                .memory
                .prepare_fixed_private_span(mapping.owner, first, span_len)
                .ok_or_else(|| {
                    Error::Backend(format!(
                        "host output stack span 0x{first:08x}+0x{span_len:x} exceeds guest RAM budget or reservation"
                    ))
                })?;
            if token.new_page_pins().len() != missing_stack.len()
                || !token
                    .new_page_pins()
                    .iter()
                    .zip(&missing_stack)
                    .all(|(pin, page)| pin.identity().page_base() == *page)
            {
                return Err(Error::Backend(
                    "host stack batch proposal differs from preflighted pages".to_owned(),
                ));
            }
            Some(token)
        } else {
            None
        };
        let map_result = {
            let mut mapped = mapping.mapped.borrow_mut();
            existing.into_iter().try_for_each(|pin| {
                map_private_slab_page(
                    self.uc,
                    kernel,
                    &mut mapped,
                    mapping.owner,
                    pin,
                    mapping.native_pins,
                    Some(mapping.active_guards),
                )
            })?;
            if let Some(prepared) = prepared.as_ref() {
                map_prepared_private_slab_pages(
                    self.uc,
                    &mut mapped,
                    prepared,
                    mapping.native_pins,
                    mapping.active_guards,
                )?;
            }
            Ok::<(), Error>(())
        };
        if let Err(err) = map_result {
            self.note_private_vm_transaction_failure(Error::Backend(format!(
                "host output stack native map failed: {err}"
            )));
            return Err(err);
        }
        if let Some(prepared) = prepared {
            let expected = prepared.result_ptr();
            if kernel.memory.commit_prepared_private_vm(prepared) != Some(expected) {
                let err = Error::Backend(format!(
                    "host output stack page 0x{expected:08x} changed before publication"
                ));
                self.note_private_vm_transaction_failure(Error::Backend(format!("{err}")));
                return Err(err);
            }
        }
        self.validate_private_host_access(addr, len as usize, unicorn_engine::Prot::WRITE.0 as u32)
    }

    fn ensure_heap_mapped_with_kernel(
        &mut self,
        kernel: &CeKernel,
        addr: u32,
        len: u32,
    ) -> Result<()> {
        if len == 0 {
            return Ok(());
        }
        let end = addr
            .checked_add(len)
            .ok_or_else(|| Error::InvalidArgument("heap mapping range overflow".to_owned()))?;
        let Some(mapping) = self.private_vm_mapping else {
            if kernel.current_process_birth_key().is_some() {
                return Err(Error::Backend(
                    "owner-qualified heap allocation has no native private page context".to_owned(),
                ));
            }
            // Birthless fixture adapters are not a process heap authority.
            return self.ensure_heap_mapped(addr, len);
        };
        if kernel.handles.process_birth_key(mapping.owner.process_id()) != Some(mapping.owner)
            || kernel.current_process_birth_key() != Some(mapping.owner)
        {
            return Err(Error::Backend(
                "fixed heap mapping owner differs from selected process birth".to_owned(),
            ));
        }
        let (heap_base, heap_size) = kernel
            .memory
            .fixed_heap_reservation(mapping.owner)
            .ok_or_else(|| {
                Error::Backend("selected birth has no fixed heap reservation".to_owned())
            })?;
        let heap_end = u64::from(heap_base) + u64::from(heap_size);
        if addr < heap_base || u64::from(end) > heap_end {
            return Err(Error::InvalidArgument(
                "heap mapping crosses selected birth's fixed reservation".to_owned(),
            ));
        }
        self.sealed_host_write_guard
            .check_write(u64::from(addr), len as usize)?;
        // Complete preflight before any native map. Growth has already been
        // published by the allocator's checked private-VM transaction; host
        // access must never manufacture an uncommitted heap page.
        let first_page = addr & !0xfff;
        let last_page = (end - 1) & !0xfff;
        let mut pins = Vec::new();
        let mut page = first_page;
        loop {
            pins.push(
                kernel
                    .memory
                    .private_page_pin(mapping.owner, page)
                    .ok_or_else(|| {
                        Error::InvalidArgument(format!(
                            "fixed heap page 0x{page:08x} is not committed by HeapAlloc"
                        ))
                    })?,
            );
            if page == last_page {
                break;
            }
            page += 0x1000;
        }
        let result = {
            let mut mapped = mapping.mapped.borrow_mut();
            pins.into_iter().try_for_each(|pin| {
                map_private_slab_page(
                    self.uc,
                    kernel,
                    &mut mapped,
                    mapping.owner,
                    pin,
                    mapping.native_pins,
                    Some(mapping.active_guards),
                )
            })
        };
        if let Err(err) = result {
            self.note_private_vm_transaction_failure(Error::Backend(format!(
                "fixed heap native mapping failed: {err}"
            )));
            return Err(err);
        }
        self.validate_private_host_access(
            addr,
            len as usize,
            unicorn_engine::Prot::WRITE.0 as u32,
        )?;
        Ok(())
    }

    fn apply_prepared_private_vm(
        &mut self,
        kernel: &CeKernel,
        prepared: &PreparedPrivateVm,
    ) -> Result<()> {
        let mapping = self.private_vm_mapping.ok_or_else(|| {
            Error::Unsupported(
                "public private VM has no captured native mapping context".to_owned(),
            )
        })?;
        if prepared.owner() != mapping.owner
            || kernel.handles.process_birth_key(mapping.owner.process_id()) != Some(mapping.owner)
        {
            return Err(Error::Backend(format!(
                "prepared private VM owner differs from native process {}",
                mapping.owner.process_id()
            )));
        }
        self.reconcile_private_vm_mapping(kernel)?;
        let mut mapped = mapping.mapped.borrow_mut();
        if mapped.heap_generation != kernel.memory.heap_generation()
            || mapped.virtual_generation != kernel.memory.virtual_generation()
        {
            return Err(Error::Backend(
                "private VM native ledger is stale before allocation".to_owned(),
            ));
        }
        let applied_generation = mapped.virtual_generation;
        if prepared.creates_reservation() {
            // A reservation is a guest-VA promise even when no page is yet
            // committed. Do not publish it over image, stack, heap or another
            // native region that a later commit would be unable to own.
            let start = u64::from(prepared.base());
            let end = start + u64::from(prepared.allocation().size);
            let regions = self.uc.mem_regions().map_err(|err| {
                Error::Backend(format!("preflight native private reservation: {err:?}"))
            })?;
            if regions.iter().any(|region| {
                let region_end = region.end.saturating_add(1);
                start < region_end && region.begin < end
            }) || mapped.ranges.iter().any(|(base, size)| {
                let other_start = u64::from(*base);
                let other_end = other_start + u64::from(*size);
                start < other_end && other_start < end
            }) {
                return Err(Error::Backend(format!(
                    "prepared private reservation 0x{:08x}+0x{:x} overlaps native guest memory",
                    prepared.base(),
                    prepared.allocation().size
                )));
            }
        }
        for pin in prepared.new_page_pins() {
            self.sealed_host_write_guard.check_write(
                u64::from(pin.identity().page_base()),
                STABLE_PRIVATE_PAGE_SIZE,
            )?;
        }
        map_prepared_private_slab_pages(
            self.uc,
            &mut mapped,
            prepared,
            mapping.native_pins,
            mapping.active_guards,
        )?;
        self.private_vm_applied_generation = Some(applied_generation);
        Ok(())
    }

    fn apply_prepared_private_vm_change(
        &mut self,
        kernel: &CeKernel,
        change: &PreparedPrivateVmChange,
    ) -> Result<()> {
        let mapping = self.private_vm_mapping.ok_or_else(|| {
            Error::Unsupported(
                "private VM change has no captured native mapping context".to_owned(),
            )
        })?;
        if change.owner() != mapping.owner
            || kernel.handles.process_birth_key(mapping.owner.process_id()) != Some(mapping.owner)
        {
            return Err(Error::Backend(format!(
                "private VM change owner differs from native process {}",
                mapping.owner.process_id()
            )));
        }
        self.reconcile_private_vm_mapping(kernel)?;
        let mut mapped = mapping.mapped.borrow_mut();
        if mapped.heap_generation != kernel.memory.heap_generation()
            || mapped.virtual_generation != kernel.memory.virtual_generation()
        {
            return Err(Error::Backend(
                "private VM native ledger is stale before change".to_owned(),
            ));
        }
        let applied_generation = mapped.virtual_generation;
        // Validate the whole change before unmapping or protecting any page:
        // a later overlap must not leave an earlier page half-committed.
        for action in change.native_page_changes() {
            self.sealed_host_write_guard.check_write(
                u64::from(action.pin().identity().page_base()),
                STABLE_PRIVATE_PAGE_SIZE,
            )?;
        }
        for action in change.native_page_changes() {
            let pin = action.pin();
            let identity = pin.identity();
            let page = identity.page_base();
            if identity.owner() != mapping.owner
                || identity.allocation_base() != change.allocation_base()
                || !kernel.memory.contains_private_page_pin(pin)
            {
                return Err(Error::Backend(format!(
                    "private VM change has stale page identity 0x{page:08x}"
                )));
            }
            let expected = mapped.private_pages.get(&page).ok_or_else(|| {
                Error::Backend(format!(
                    "private VM change page 0x{page:08x} has no native owner record"
                ))
            })?;
            if expected.identity != identity
                || expected.host_address != pin.native_ptr() as usize
                || native_page_perms(self.uc, page)? != Some(expected.perms)
            {
                return Err(Error::Backend(format!(
                    "private VM change page 0x{page:08x} differs from native owner"
                )));
            }
            match action {
                PrivateVmNativePageChange::Unmap(_) => {
                    #[cfg(test)]
                    if self.fail_next_private_unmap_for_test {
                        self.fail_next_private_unmap_for_test = false;
                        return Err(Error::Backend(
                            "injected checked private VM unmap failure".to_owned(),
                        ));
                    }
                    unmap_private_slab_page_checked(self.uc, &mapped, mapping.native_pins, page)?;
                    mapping
                        .active_guards
                        .borrow_mut()
                        .remove(&(pin.native_ptr() as usize));
                    if !mapping
                        .native_pins
                        .release_private_after_unmap(identity, pin.native_ptr() as usize)
                    {
                        return Err(Error::Backend(format!(
                            "checked private VM unmap 0x{page:08x} has no matching native pin"
                        )));
                    }
                    mapped.private_pages.remove(&page);
                    remove_mapped_guest_page(&mut mapped, page);
                }
                PrivateVmNativePageChange::Protect { new_protect, .. } => {
                    let perms = unicorn_perms(virtual_allocation_perms(*new_protect));
                    self.uc
                        .mem_protect(u64::from(page), STABLE_PRIVATE_PAGE_SIZE as u64, perms)
                        .map_err(|err| {
                            Error::Backend(format!("protect private VM page 0x{page:08x}: {err:?}"))
                        })?;
                    mapped
                        .private_pages
                        .get_mut(&page)
                        .expect("validated native page record")
                        .perms = perms.0 as u32;
                }
            }
        }
        self.private_vm_applied_generation = Some(applied_generation);
        Ok(())
    }

    fn private_vm_commit_complete(&mut self, generation: u64) {
        let Some(mapping) = self.private_vm_mapping else {
            return;
        };
        let Some(applied_generation) = self.private_vm_applied_generation.take() else {
            self.note_private_vm_transaction_failure(Error::Backend(
                "private VM metadata committed without a checked native apply".to_owned(),
            ));
            return;
        };
        let mut mapped = mapping.mapped.borrow_mut();
        if mapped.virtual_generation != applied_generation
            || generation != applied_generation.wrapping_add(1)
        {
            drop(mapped);
            self.note_private_vm_transaction_failure(Error::Backend(
                "private VM generation changed during native transaction".to_owned(),
            ));
            return;
        }
        // The checked token applied every private page change to this same
        // native ledger. A later generic import mapper must see this as
        // already synchronized, not start a new fallible publication step.
        mapped.virtual_generation = generation;
    }

    fn validate_writable_u32(&self, addr: u32) -> Result<()> {
        self.sealed_host_write_guard
            .check_write(u64::from(addr), 4)?;
        self.validate_private_host_access(addr, 4, unicorn_engine::Prot::WRITE.0 as u32)?;
        let end = addr.checked_add(4).ok_or_else(|| {
            Error::InvalidArgument("VirtualProtect output pointer wraps guest VA".to_owned())
        })?;
        let regions = self.uc.mem_regions().map_err(|err| {
            Error::Backend(format!("preflight VirtualProtect output pointer: {err:?}"))
        })?;
        let write = unicorn_engine::Prot::WRITE.0 as u32;
        for byte in addr..end {
            if !regions.iter().any(|region| {
                u64::from(byte) >= region.begin
                    && u64::from(byte) <= region.end
                    && region.perms & write == write
            }) {
                return Err(Error::InvalidArgument(format!(
                    "VirtualProtect output 0x{addr:08x} is not writable guest memory"
                )));
            }
        }
        Ok(())
    }

    fn note_private_vm_transaction_failure(&mut self, error: Error) {
        let Some(mapping) = self.private_vm_mapping else {
            return;
        };
        let error = match self.uc.emu_stop() {
            Ok(()) => error,
            Err(stop_error) => Error::Backend(format!(
                "private VM transaction failed: {error}; stop native attempt: {stop_error:?}"
            )),
        };
        let mut terminal = mapping.terminal_error.borrow_mut();
        if terminal.is_none() {
            *terminal = Some(error);
        }
    }

    fn read_u8(&self, addr: u32) -> Result<u8> {
        self.validate_private_host_access(addr, 1, unicorn_engine::Prot::READ.0 as u32)?;
        let mut bytes = [0; 1];
        self.uc
            .mem_read(u64::from(addr), &mut bytes)
            .map_err(|err| Error::Backend(format!("read_u8 0x{addr:08x}: {err:?}")))?;
        Ok(bytes[0])
    }

    fn write_u8(&mut self, addr: u32, value: u8) -> Result<()> {
        self.validate_private_host_access(addr, 1, unicorn_engine::Prot::WRITE.0 as u32)?;
        checked_host_write(
            self.uc,
            &self.sealed_host_write_guard,
            u64::from(addr),
            &[value],
        )
        .map_err(|err| Error::Backend(format!("write_u8 0x{addr:08x}: {err:?}")))?;
        Ok(())
    }

    fn read_u32(&self, addr: u32) -> Result<u32> {
        self.validate_private_host_access(addr, 4, unicorn_engine::Prot::READ.0 as u32)?;
        let mut bytes = [0; 4];
        self.uc
            .mem_read(u64::from(addr), &mut bytes)
            .map_err(|err| Error::Backend(format!("read_u32 0x{addr:08x}: {err:?}")))?;
        Ok(u32::from_le_bytes(bytes))
    }

    fn write_u32(&mut self, addr: u32, value: u32) -> Result<()> {
        self.validate_private_host_access(addr, 4, unicorn_engine::Prot::WRITE.0 as u32)?;
        checked_host_write(
            self.uc,
            &self.sealed_host_write_guard,
            u64::from(addr),
            &value.to_le_bytes(),
        )
        .map_err(|err| Error::Backend(format!("write_u32 0x{addr:08x}: {err:?}")))?;
        Ok(())
    }

    fn write_prevalidated_vm_protect_result_u32(&mut self, addr: u32, value: u32) -> Result<()> {
        // COREDLL checked the old-protect slot while it was still writable.
        // The slot may itself have become read-only in this same transaction;
        // Unicorn's host write is the narrow post-commit publication step.
        checked_host_write(
            self.uc,
            &self.sealed_host_write_guard,
            u64::from(addr),
            &value.to_le_bytes(),
        )
        .map_err(|err| {
            Error::Backend(format!(
                "write prevalidated VirtualProtect result 0x{addr:08x}: {err:?}"
            ))
        })?;
        Ok(())
    }

    fn read_u16(&self, addr: u32) -> Result<u16> {
        self.validate_private_host_access(addr, 2, unicorn_engine::Prot::READ.0 as u32)?;
        let mut bytes = [0; 2];
        self.uc
            .mem_read(u64::from(addr), &mut bytes)
            .map_err(|err| Error::Backend(format!("read_u16 0x{addr:08x}: {err:?}")))?;
        Ok(u16::from_le_bytes(bytes))
    }

    fn write_u16(&mut self, addr: u32, value: u16) -> Result<()> {
        self.validate_private_host_access(addr, 2, unicorn_engine::Prot::WRITE.0 as u32)?;
        checked_host_write(
            self.uc,
            &self.sealed_host_write_guard,
            u64::from(addr),
            &value.to_le_bytes(),
        )
        .map_err(|err| Error::Backend(format!("write_u16 0x{addr:08x}: {err:?}")))?;
        Ok(())
    }

    fn read_bytes(&self, addr: u32, out: &mut [u8]) -> Result<()> {
        self.validate_private_host_access(addr, out.len(), unicorn_engine::Prot::READ.0 as u32)?;
        self.uc
            .mem_read(u64::from(addr), out)
            .map_err(|err| Error::Backend(format!("read_bytes 0x{addr:08x}: {err:?}")))?;
        Ok(())
    }

    fn write_bytes(&mut self, addr: u32, bytes: &[u8]) -> Result<()> {
        self.validate_private_host_access(addr, bytes.len(), unicorn_engine::Prot::WRITE.0 as u32)?;
        checked_host_write(
            self.uc,
            &self.sealed_host_write_guard,
            u64::from(addr),
            bytes,
        )
        .map_err(|err| Error::Backend(format!("write_bytes 0x{addr:08x}: {err:?}")))?;
        Ok(())
    }

    fn ensure_mapped(&mut self, addr: u32, len: u32) -> Result<()> {
        if len == 0 {
            return Ok(());
        }
        if self
            .private_vm_mapping
            .is_some_and(|mapping| overlaps_fixed_system_slab(&mapping.mapped.borrow(), addr, len))
        {
            return Err(Error::InvalidArgument(
                "ordinary native mapping cannot own fixed system slab pages".to_owned(),
            ));
        }
        let start = addr & !0xfff;
        let end = addr
            .checked_add(len)
            .and_then(|value| value.checked_add(0xfff))
            .map(|value| value & !0xfff)
            .ok_or_else(|| Error::InvalidArgument("guest mapping range overflow".to_owned()))?;
        self.sealed_host_write_guard
            .check_write(u64::from(start), (end - start) as usize)?;
        let mut page = start;
        while page < end {
            let mut probe = [0u8; 1];
            if self.uc.mem_read(u64::from(page), &mut probe).is_err() {
                self.uc
                    .mem_map(u64::from(page), 0x1000, unicorn_engine::Prot::ALL)
                    .map_err(|err| {
                        Error::Backend(format!("map guest page 0x{page:08x}: {err:?}"))
                    })?;
            }
            page = page
                .checked_add(0x1000)
                .ok_or_else(|| Error::InvalidArgument("guest mapping page overflow".to_owned()))?;
        }
        Ok(())
    }

    fn ensure_heap_mapped(&mut self, addr: u32, len: u32) -> Result<()> {
        if len == 0 {
            return Ok(());
        }
        if self
            .private_vm_mapping
            .is_some_and(|mapping| overlaps_fixed_system_slab(&mapping.mapped.borrow(), addr, len))
        {
            return Err(Error::InvalidArgument(
                "fixed heap requires owner-qualified canonical page pins".to_owned(),
            ));
        }
        if self.heap_mapping.is_some() {
            return Err(Error::Backend(
                "kernel-less heap mapping cannot publish process heap pages".to_owned(),
            ));
        }
        {
            // Legacy memory-only adapters are used by non-allocating blocked
            // I/O and standalone fixtures; immediate runtime allocators carry
            // the engine's persistent mapping context.
            validate_heap_destination(self.uc, None, addr, len, true)?;
            self.ensure_mapped(addr, len)?;
            validate_heap_destination(self.uc, None, addr, len, false)
        }
    }

    fn fill_bytes(&mut self, addr: u32, value: u8, len: u32) -> Result<()> {
        const FILL_CHUNK: usize = 4096;

        // Reject the entire request before writing the first chunk. A sealed
        // page late in a fill must not leave an earlier writable page changed.
        self.sealed_host_write_guard
            .check_write(u64::from(addr), len as usize)?;

        let chunk = [value; FILL_CHUNK];
        let mut remaining = len as usize;
        let mut cursor = addr;
        while remaining != 0 {
            let count = remaining.min(FILL_CHUNK);
            checked_host_write(
                self.uc,
                &self.sealed_host_write_guard,
                u64::from(cursor),
                &chunk[..count],
            )
            .map_err(|err| Error::Backend(format!("fill_bytes 0x{cursor:08x}: {err:?}")))?;
            cursor = cursor.wrapping_add(count as u32);
            remaining -= count;
        }
        Ok(())
    }
}

