    #[test]
    fn admitted_slot_refuses_boxed_parked_child_and_returns_original_tree() -> crate::Result<()> {
        use crate::emulator::cpu_custody::{CpuCustodyError, CpuCustodyState};

        let kernel = phase1_kernel("admission-tree.exe")?;
        let birth = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let mut root = super::UnicornMips::new()?;
        root.parked_child_processes.push_back(super::ParkedProcess {
            application: Some("parked-child.exe".to_owned()),
            process_handle: None,
            thread_handle: None,
            process_state: crate::ce::kernel::CurrentProcessState {
                process_id: birth.process_id() + 1,
                exit_code: crate::ce::kernel::STILL_ACTIVE,
                signaled: false,
            },
            thread_id: MAIN_GUEST_THREAD_ID,
            cpu: Box::new(super::UnicornMips::new()?),
            blocked_send_id: None,
            module_base: 0,
            module_path: "parked-child.exe".to_owned(),
            module_host_path: std::path::PathBuf::new(),
            command_line: String::new(),
            current_directory: None,
        });
        let child_ptr = &*root.parked_child_processes[0].cpu as *const super::UnicornMips;
        let mut directory =
            super::CpuCustody::new().map_err(|error| Error::Backend(error.to_string()))?;
        let key = directory
            .reserve(birth)
            .map_err(|error| Error::Backend(error.to_string()))?;

        let (error, mut returned) = directory
            .admit_reserved(key, birth, root)
            .expect_err("a process slot cannot own a boxed child CPU");
        assert_eq!(error, CpuCustodyError::ParkedChildProcessTree);
        assert_eq!(
            directory.snapshot_exact(key, birth).unwrap().state,
            CpuCustodyState::Reserved
        );
        assert_eq!(returned.parked_child_process_count(), 1);
        assert_eq!(
            &*returned.parked_child_processes[0].cpu as *const super::UnicornMips, child_ptr,
            "refusal must return the original boxed child, not a clone",
        );

        let child = returned.parked_child_processes.pop_front().unwrap();
        directory
            .admit_reserved(key, birth, returned)
            .map_err(|(error, _)| Error::Backend(error.to_string()))?;
        assert_eq!(
            directory.snapshot_exact(key, birth).unwrap().state,
            CpuCustodyState::Runnable
        );
        assert_eq!(&*child.cpu as *const super::UnicornMips, child_ptr);
        Ok(())
    }

    #[test]
    fn native_entry_preseeded_busy_refuses_before_guest_execution_then_retries() -> crate::Result<()>
    {
        let mut kernel = phase1_kernel("native-entry-busy.exe")?;
        let mut cpu = phase1_counter_cpu(0x1000, "native-entry-busy.exe")?;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let counter_before = phase1_counter(&cpu);
        let limits = super::UnicornRunLimits {
            instruction_limit: 20,
            wall_clock_limit_ms: 500,
            stop_pc: None,
            live_pump: false,
        };
        let outer = super::NativeGuestExecutionGuard::enter().expect("outer native entry");
        let refused = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        assert!(matches!(
            refused.result,
            Err(Error::Backend(ref message)) if message.contains("nested native guest execution")
        ));
        assert_eq!(refused.report.attempt_id(), None);
        assert_eq!(
            refused.report.final_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        assert_eq!(
            refused.report.failure_operation(),
            Some("enter native guest execution")
        );
        assert_eq!(
            refused.report.native_result(),
            &super::AttemptObservation::Uncollected
        );
        assert_eq!(
            refused.report.count_stop_query(),
            &super::AttemptObservation::Uncollected
        );
        assert_eq!(
            refused.report.context_capture(),
            &super::AttemptObservation::Uncollected
        );
        assert_eq!(phase1_counter(&cpu), counter_before);
        assert!(cpu.native_engine_identity_for_test().is_none());
        assert!(super::NativeGuestExecutionGuard::enter().is_err());
        drop(outer);

        let retried = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        retried.result?;
        assert!(retried.report.attempt_id().is_some());
        assert_eq!(
            retried.report.native_result(),
            &super::AttemptObservation::Value(())
        );
        assert!(phase1_counter(&cpu) > counter_before);
        Ok(())
    }

