    fn tiny_mips_spinner_pe() -> Vec<u8> {
        let mut bytes = vec![0; 0x400];
        bytes[0..2].copy_from_slice(b"MZ");
        write_vec_u32(&mut bytes, 0x3c, 0x80);
        bytes[0x80..0x84].copy_from_slice(b"PE\0\0");

        let coff = 0x84;
        write_vec_u16(&mut bytes, coff, 0x0166);
        write_vec_u16(&mut bytes, coff + 2, 1);
        write_vec_u16(&mut bytes, coff + 16, 0x00e0);
        write_vec_u16(&mut bytes, coff + 18, 0x0102);

        let optional = 0x98;
        write_vec_u16(&mut bytes, optional, 0x010b);
        bytes[optional + 2] = 8;
        write_vec_u32(&mut bytes, optional + 4, 0x200);
        write_vec_u32(&mut bytes, optional + 16, 0x1000);
        write_vec_u32(&mut bytes, optional + 20, 0x1000);
        write_vec_u32(&mut bytes, optional + 24, 0x1000);
        write_vec_u32(&mut bytes, optional + 28, 0x0040_0000);
        write_vec_u32(&mut bytes, optional + 32, 0x1000);
        write_vec_u32(&mut bytes, optional + 36, 0x200);
        write_vec_u16(&mut bytes, optional + 40, 4);
        write_vec_u16(&mut bytes, optional + 48, 4);
        write_vec_u32(&mut bytes, optional + 56, 0x2000);
        write_vec_u32(&mut bytes, optional + 60, 0x200);
        write_vec_u16(&mut bytes, optional + 68, 9);
        write_vec_u32(&mut bytes, optional + 72, 0x10000);
        write_vec_u32(&mut bytes, optional + 76, 0x1000);
        write_vec_u32(&mut bytes, optional + 80, 0x10000);
        write_vec_u32(&mut bytes, optional + 84, 0x1000);
        write_vec_u32(&mut bytes, optional + 92, 16);

        let section = 0x178;
        bytes[section..section + 8].copy_from_slice(b".text\0\0\0");
        write_vec_u32(&mut bytes, section + 8, 0x100);
        write_vec_u32(&mut bytes, section + 12, 0x1000);
        write_vec_u32(&mut bytes, section + 16, 0x200);
        write_vec_u32(&mut bytes, section + 20, 0x200);
        write_vec_u32(&mut bytes, section + 36, 0x6000_0020);

        // beq zero, zero, -1; nop
        write_vec_u32(&mut bytes, 0x200, 0x1000_ffff);
        write_vec_u32(&mut bytes, 0x204, 0);
        bytes
    }

    fn tiny_mips_create_process_then_return_pe() -> Vec<u8> {
        let mut bytes = tiny_mips_spinner_pe();
        bytes.resize(0x600, 0);
        // The main image really imports COREDLL CreateProcessW by ordinal.
        // The loader, not this test, patches its IAT to an import trap.
        write_vec_u16(&mut bytes, 0x84 + 2, 2);
        write_vec_u32(&mut bytes, 0x98 + 56, 0x3000);
        write_vec_u32(&mut bytes, 0x98 + 96 + 8, 0x2000);
        write_vec_u32(&mut bytes, 0x98 + 96 + 12, 0x28);
        let idata_section = 0x178 + 40;
        bytes[idata_section..idata_section + 8].copy_from_slice(b".idata\0\0");
        write_vec_u32(&mut bytes, idata_section + 8, 0x200);
        write_vec_u32(&mut bytes, idata_section + 12, 0x2000);
        write_vec_u32(&mut bytes, idata_section + 16, 0x200);
        write_vec_u32(&mut bytes, idata_section + 20, 0x400);
        write_vec_u32(&mut bytes, idata_section + 36, 0xc000_0040);
        write_vec_u32(&mut bytes, 0x400, 0x2050); // original first thunk
        write_vec_u32(&mut bytes, 0x40c, 0x2040); // COREDLL.dll
        write_vec_u32(&mut bytes, 0x410, 0x2070); // first thunk / IAT
        bytes[0x440..0x44c].copy_from_slice(b"COREDLL.dll\0");
        let create_process_ordinal = crate::ce::coredll_ordinals::ORD_CREATE_PROCESS_W;
        write_vec_u32(&mut bytes, 0x450, 0x8000_0000 | create_process_ordinal);
        write_vec_u32(&mut bytes, 0x470, 0x8000_0000 | create_process_ordinal);
        for (index, wide) in "survivor.exe"
            .encode_utf16()
            .chain(std::iter::once(0))
            .enumerate()
        {
            write_vec_u16(&mut bytes, 0x480 + index * 2, wide);
        }

        // The PE entry's saved startup RA is the emulator's thread-exit stub.
        // Preserve it across JALR, invoke CreateProcessW through the real IAT,
        // then return 0x63 through that original RA in the same first slice.
        let words = [
            0x27bd_ff00, // addiu sp,sp,-0x100
            0x03e0_8021, // move s0,ra
            0x3c04_0040, // lui a0,0x40
            0x3484_2080, // ori a0,a0,0x2080: L"survivor.exe"
            0x0000_2821, // move a1,zero
            0x0000_3021, // move a2,zero
            0x0000_3821, // move a3,zero
            0xafa0_0010, // sw zero,16(sp): arg 4
            0xafa0_0014, // sw zero,20(sp): arg 5
            0xafa0_0018, // sw zero,24(sp): arg 6
            0xafa0_001c, // sw zero,28(sp): arg 7
            0xafa0_0020, // sw zero,32(sp): arg 8
            0x27a8_0080, // addiu t0,sp,0x80: PROCESS_INFORMATION
            0xafa8_0024, // sw t0,36(sp): arg 9
            0x3c08_0040, // lui t0,0x40
            0x8d19_2070, // lw t9,0x2070(t0): patched IAT
            0x0320_f809, // jalr t9
            0,           // delay slot
            0x0200_f821, // move ra,s0
            0x2402_0063, // addiu v0,zero,0x63
            0x03e0_0008, // jr ra
            0,           // delay slot
        ];
        for (index, word) in words.into_iter().enumerate() {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        bytes
    }

    fn tiny_mips_create_process_then_spin_pe() -> Vec<u8> {
        let mut bytes = tiny_mips_create_process_then_return_pe();
        // Preserve the real ordinal-493 IAT call and its PROCESS_INFORMATION
        // output, but leave the creator live after the import return.
        write_vec_u32(&mut bytes, 0x200 + 18 * 4, 0x2411_55aa); // addiu s1,zero,0x55aa
        write_vec_u32(&mut bytes, 0x200 + 19 * 4, 0x1000_ffff); // safety spinner
        write_vec_u32(&mut bytes, 0x200 + 20 * 4, 0);
        bytes
    }

    fn tiny_mips_direct_shell_execute_then_spin_pe() -> Vec<u8> {
        let mut bytes = tiny_mips_create_process_then_spin_pe();
        let shell_ordinal = crate::ce::coredll_ordinals::ORD_SHELL_EXECUTE_EX;
        write_vec_u32(&mut bytes, 0x450, 0x8000_0000 | shell_ordinal);
        write_vec_u32(&mut bytes, 0x470, 0x8000_0000 | shell_ordinal);
        // The real IAT call receives a guest SHELLEXECUTEINFOW at RVA 0x20a0.
        // Its original, non-shortcut file is a direct .exe; the other fields
        // remain zero except nShow. The section is writable for hInstApp.
        write_vec_u32(&mut bytes, 0x200 + 3 * 4, 0x3484_20a0); // ori a0,a0,info RVA
        write_vec_u32(&mut bytes, 0x4a0, 60); // cbSize
        write_vec_u32(&mut bytes, 0x4a0 + 16, 0x0040_2100); // lpFile
        write_vec_u32(&mut bytes, 0x4a0 + 28, 1); // nShow
        for (index, wide) in "survivor.exe"
            .encode_utf16()
            .chain(std::iter::once(0))
            .enumerate()
        {
            write_vec_u16(&mut bytes, 0x500 + index * 2, wide);
        }
        bytes
    }

    fn tiny_mips_event_has_occurred_then_spin_pe() -> Vec<u8> {
        let mut bytes = tiny_mips_create_process_then_spin_pe();
        let event_ordinal = crate::ce::coredll_ordinals::ORD_CE_EVENT_HAS_OCCURRED;
        write_vec_u32(&mut bytes, 0x450, 0x8000_0000 | event_ordinal);
        write_vec_u32(&mut bytes, 0x470, 0x8000_0000 | event_ordinal);
        write_vec_u32(&mut bytes, 0x200 + 2 * 4, 0x2404_0002); // addiu a0,zero,2
        write_vec_u32(&mut bytes, 0x200 + 3 * 4, 0); // a1 remains NULL
        bytes
    }

    fn tiny_mips_direct_pseudo_exit_pe() -> Vec<u8> {
        let mut bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x2405_0063_u32, // addiu a1,zero,0x63: guest exit code
            0x2408_f3fa,     // addiu t0,zero,-3078: encoded CE syscall target
            0x0100_f809,     // jalr t0
            0x2404_0042,     // delay slot: current-process pseudo handle
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        bytes
    }

    fn write_guest_fixture_bytes(parent: &mut super::UnicornMips, address: u32, bytes: &[u8]) {
        let blob = parent
            .mapped_blobs
            .iter_mut()
            .find(|blob| {
                address
                    .checked_sub(blob.base)
                    .and_then(|offset| (offset as usize).checked_add(bytes.len()))
                    .is_some_and(|end| end <= blob.bytes.len())
            })
            .expect("fixture guest address is mapped");
        let offset = (address - blob.base) as usize;
        blob.bytes
            .as_mut_owned()
            .expect("fixture guest image must remain mutable")[offset..offset + bytes.len()]
            .copy_from_slice(bytes);
    }

    fn write_guest_fixture_stack_bytes(
        parent: &super::UnicornMips,
        kernel: &mut CeKernel,
        address: u32,
        bytes: &[u8],
    ) {
        let owner = kernel
            .current_process_birth_key()
            .expect("fixture process birth");
        super::reserve_fixed_system_slabs(
            &parent.memory,
            &parent.mapped_blobs,
            kernel,
            Some(owner),
        )
        .expect("reserve fixture heap and stack without byte blobs");
        let len = u32::try_from(bytes.len()).expect("bounded fixture stack input");
        let prepared = kernel
            .memory
            .prepare_fixed_private_span(owner, address, len)
            .expect("prepare canonical fixture stack span");
        if !prepared.new_page_pins().is_empty() {
            assert_eq!(
                kernel.memory.commit_prepared_private_vm(prepared),
                Some(address & !0xfff),
                "publish canonical fixture stack pages"
            );
        }
        let mut copied = 0usize;
        while copied < bytes.len() {
            let guest_address = address + copied as u32;
            let page = guest_address & !0xfff;
            let offset = (guest_address & 0xfff) as usize;
            let count = (0x1000 - offset).min(bytes.len() - copied);
            kernel
                .memory
                .private_page_pin(owner, page)
                .expect("canonical fixture stack pin")
                .write_bytes(offset, &bytes[copied..copied + count])
                .expect("seed canonical fixture stack bytes");
            copied += count;
        }
    }

    #[test]
    fn fsdmgr_file_lock_callout_enters_acquire_then_release_callbacks() {
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x3000_0000, 0x1000, Prot::ALL).unwrap();
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default().unwrap());
        let pending = Rc::new(RefCell::new(Vec::new()));
        let return_pc = 0x0040_1000;
        let acquire = 0x0040_2000;
        let release = 0x0040_3000;
        let file_handle = 0x55aa;
        let file_lock_state = 0x3000_0200;

        uc.reg_write(RegisterMIPS::SP, 0x3000_0800).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7777_0101).unwrap();
        assert!(super::try_enter_fsdmgr_file_lock_callout(
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Fsdmgr,
            Some(34),
            None,
            &[acquire, release, file_handle, 1, 4, 8, 0],
            &pending,
        ));
        let slot = 0x3000_0800 - super::WNDPROC_CALL_FRAME_BYTES;
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, acquire);
        assert_eq!(uc.reg_read(RegisterMIPS::T9).unwrap() as u32, acquire);
        assert_eq!(uc.reg_read(RegisterMIPS::A0).unwrap() as u32, file_handle);
        assert_eq!(uc.reg_read(RegisterMIPS::A1).unwrap() as u32, slot);
        assert_eq!(
            uc.reg_read(RegisterMIPS::RA).unwrap() as u32,
            super::FSDMGR_FILE_LOCK_RETURN_STUB_ADDR
        );

        write_u32(&mut uc, u64::from(slot), file_lock_state);
        write_u32(&mut uc, u64::from(file_lock_state + 28), 0);
        uc.reg_write(RegisterMIPS::V0, 1).unwrap();
        assert!(super::handle_fsdmgr_file_lock_return_stub(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            9,
            &pending,
        ));
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, release);
        assert_eq!(uc.reg_read(RegisterMIPS::T9).unwrap() as u32, release);
        assert_eq!(uc.reg_read(RegisterMIPS::A0).unwrap() as u32, file_handle);
        assert_eq!(uc.reg_read(RegisterMIPS::A1).unwrap() as u32, slot);
        assert_eq!(
            pending.borrow()[0].phase,
            super::FsdmgrFileLockPhase::Release
        );

        uc.reg_write(RegisterMIPS::V0, 1).unwrap();
        assert!(super::handle_fsdmgr_file_lock_return_stub(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            9,
            &pending,
        ));
        assert!(pending.borrow().is_empty());
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7777_0101);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 1);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, return_pc);
        assert_eq!(kernel.threads.get_last_error(9), 0);
    }

