    #[test]
    fn refresh_import_trap_page_blob_replaces_existing_blob() {
        let mut blobs = vec![
            super::MappedBlob {
                name: "ce-import-traps".to_owned(),
                base: 0x1234_0000,
                bytes: vec![0xaa; 16].into(),
            },
            super::MappedBlob {
                name: "other".to_owned(),
                base: 0x2000_0000,
                bytes: vec![1, 2, 3].into(),
            },
        ];

        super::refresh_import_trap_page_blob(
            &mut blobs,
            &crate::emulator::imports::ImportTrapTable::new(),
        );

        assert_eq!(blobs.len(), 2);
        let trap_blob = blobs
            .iter()
            .find(|blob| blob.name == "ce-import-traps")
            .unwrap();
        assert_eq!(trap_blob.base, crate::emulator::imports::IMPORT_TRAP_BASE);
        assert_eq!(
            trap_blob.bytes.len(),
            crate::emulator::imports::IMPORT_TRAP_PAGE_SIZE as usize
        );
        assert_eq!(trap_blob.bytes[0], 0);
        let dynamic_offset = (crate::emulator::imports::DYNAMIC_COREDLL_PROC_TRAP_BASE
            - crate::emulator::imports::IMPORT_TRAP_BASE) as usize;
        assert_eq!(
            &trap_blob.bytes[dynamic_offset..dynamic_offset + 4],
            &0x03e0_0008u32.to_le_bytes()
        );
        assert!(blobs.iter().any(|blob| blob.name == "other"));
    }

    #[test]
    fn mapped_code_index_reads_static_code_before_unicorn_memory() -> crate::Result<()> {
        let cpu = sealed_spinner_cpu()?;
        let blob = cpu
            .mapped_blobs
            .iter()
            .find(|blob| blob.bytes.sealed_pin().is_some())
            .expect("production loader's sealed main-image run");
        let mapped_code = super::MappedCodeIndex::new(&cpu.mapped_blobs);
        let static_code = mapped_code
            .read_static_code_u32(blob.base)
            .expect("sealed entry instruction");
        let live_code = static_code ^ u32::MAX;
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(u64::from(blob.base), blob.bytes.len() as u64, Prot::ALL)
            .unwrap();
        uc.mem_write(u64::from(blob.base), &live_code.to_le_bytes())
            .unwrap();

        assert_eq!(
            super::read_unicorn_code_u32(&uc, &mapped_code, blob.base),
            Some(static_code)
        );
        Ok(())
    }

