    #[test]
    fn persistent_native_memory_reconciles_owned_pages_and_discards_transient_pages() {
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x1000, 0x2000, Prot::ALL).unwrap();
        uc.mem_map(0x9000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(0x1000, &0x12345678u32.to_le_bytes()).unwrap();
        let mut memory = MemoryMap::default();
        memory
            .map(0x1000, 0x1000, MemoryPerms::READ, "owned")
            .unwrap();
        memory
            .map(
                0x4000,
                0x1000,
                MemoryPerms::READ | MemoryPerms::WRITE,
                "added",
            )
            .unwrap();
        let ranges =
            reconcile_persistent_native_memory(&mut uc, &memory, &[], &HashSet::new()).unwrap();
        assert_eq!(read_unicorn_u32(&uc, 0x1000), Some(0x12345678));
        assert_eq!(read_unicorn_u32(&uc, 0x4000), Some(0));
        assert!(uc.mem_read_as_vec(0x2000, 1).is_err());
        assert!(uc.mem_read_as_vec(0x9000, 1).is_err());
        assert!(ranges.iter().any(|range| *range == (0x4000, 0x1000)));
        assert_eq!(
            uc.mem_regions()
                .unwrap()
                .iter()
                .find(|r| r.begin == 0x1000)
                .unwrap()
                .perms,
            Prot::READ.0 as u32
        );
    }

    #[test]
    fn persistent_native_memory_retains_tracked_virtual_pages_without_heap_blobs() {
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x9000, 0x1000, Prot::READ).unwrap();
        uc.mem_write(0x9000, &0xabcdef01u32.to_le_bytes()).unwrap();
        reconcile_persistent_native_memory(
            &mut uc,
            &MemoryMap::default(),
            &[],
            &HashSet::from([0x9000]),
        )
        .unwrap();
        assert_eq!(read_unicorn_u32(&uc, 0x9000), Some(0xabcdef01));
        assert_eq!(read_unicorn_u32(&uc, 0x5000), None);
        assert!(uc.mem_read_as_vec(0x4000, 1).is_err());
        assert!(uc.mem_read_as_vec(0x6000, 1).is_err());
        assert!(
            reconcile_persistent_native_memory(
                &mut uc,
                &MemoryMap::default(),
                &[],
                &HashSet::from([0xa000])
            )
            .is_err()
        );
    }

    #[test]
    fn persistent_native_memory_compares_bytes_and_observes_host_edits() {
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x1000, 0x21000, Prot::ALL).unwrap();
        let mut blobs = vec![MappedBlob {
            name: "ram:test".to_owned(),
            base: 0x1000,
            bytes: vec![7; 0x20004].into(),
        }];
        let sealed_host_write_guard =
            super::SealedHostWriteGuard::from_mapped_blobs(&blobs).unwrap();
        assert_eq!(
            sync_persisted_blobs_to_native(&mut uc, &blobs, false, &sealed_host_write_guard)
                .unwrap(),
            0x20004
        );
        assert_eq!(
            sync_persisted_blobs_to_native(&mut uc, &blobs, true, &sealed_host_write_guard)
                .unwrap(),
            0
        );
        blobs[0]
            .bytes
            .as_mut_owned()
            .expect("RAM fixture must remain mutable")[0x10001] = 9;
        assert_eq!(
            sync_persisted_blobs_to_native(&mut uc, &blobs, true, &sealed_host_write_guard)
                .unwrap(),
            0x10000
        );
        assert_eq!(uc.mem_read_as_vec(0x11001, 1).unwrap(), vec![9]);
        assert_eq!(
            sync_persisted_blobs_to_native(&mut uc, &blobs, true, &sealed_host_write_guard)
                .unwrap(),
            0
        );
    }

    #[test]
    fn malformed_owned_blob_cannot_partially_overwrite_sealed_image() -> crate::Result<()> {
        const WRITABLE_PREFIX_SIZE: usize = 0x11000;
        let cpu = sealed_spinner_cpu()?;
        let sealed = cpu
            .mapped_blobs
            .iter()
            .find(|blob| blob.bytes.sealed_pin().is_some())
            .expect("synthetic main image has a sealed run");
        let backing = sealed.bytes.sealed_pin().unwrap();
        let pointer = backing.as_ptr();
        let before = backing.to_vec();
        // The first 64-KiB sync chunk is fully writable. Without the
        // whole-blob preflight it would change before the later chunk hits
        // the sealed image.
        let prefix_base = sealed.base - WRITABLE_PREFIX_SIZE as u32;
        let kernel = phase1_kernel("sealed-spinner.exe")?;
        let expected = super::expected_sealed_image_runs(
            &cpu.mapped_blobs,
            &cpu.memory,
            kernel.current_process_birth_key(),
        )?;
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(
            u64::from(prefix_base),
            WRITABLE_PREFIX_SIZE as u64,
            Prot::ALL,
        )
        .unwrap();
        uc.mem_write(u64::from(prefix_base), &[0x5a; WRITABLE_PREFIX_SIZE])
            .unwrap();
        let pins = super::NativeMappingPins::default();
        let mut mapped = super::KernelMemoryMappings::new(&cpu.mapped_blobs);
        super::map_sealed_image_runs(&mut uc, &cpu.mapped_blobs, &mut mapped, &expected, &pins)?;

        let mut blobs = vec![sealed.clone()];
        blobs.push(MappedBlob {
            name: "ram:malformed-overlap".to_owned(),
            base: prefix_base,
            bytes: vec![0xcc; WRITABLE_PREFIX_SIZE + 0x1000].into(),
        });
        let guard = super::SealedHostWriteGuard::from_mapped_blobs(&blobs)?;
        let err = sync_persisted_blobs_to_native(&mut uc, &blobs, false, &guard)
            .expect_err("whole malformed blob must be rejected before its writable prefix");
        assert!(format!("{err}").contains("overlaps sealed image"));
        assert!(guard.poison_error().is_some());
        assert_eq!(
            uc.mem_read_as_vec(u64::from(prefix_base), WRITABLE_PREFIX_SIZE)
                .unwrap(),
            vec![0x5a; WRITABLE_PREFIX_SIZE]
        );
        assert_eq!(
            uc.mem_read_as_vec(u64::from(sealed.base), before.len())
                .unwrap(),
            before
        );
        assert_eq!(backing.as_ptr(), pointer);
        assert_eq!(&backing[..], &before);
        drop(uc); // Native owner must die before its raw-pointer pin.
        drop(mapped);
        drop(pins);
        Ok(())
    }

