    // STAGED ONLY. Insert this fragment into the existing unicorn.rs tests module.
    // It uses its tiny_mips_spinner_pe/write_vec_u32 helpers and the production
    // run/park/rotate paths. Root applies, formats, compiles and runs it.
    // Integration dependency: native_engine_identity_for_test() delegates to the
    // actual ProcessNativeEngine owner and returns Option<usize> while idle.
    // There is no duplicate scheduler, fabricated native snapshot or seeded GPRs.

    // The fixed heap is only writable after HeapAlloc commits its high-water
    // pages. These scheduler fixtures need independent, test-only scratch RAM.
    const PHASE1_COUNTER_ADDRESS: u32 = 0x4800_0000;

    fn phase1_counter_cpu(seed: u16, name: &str) -> crate::Result<super::UnicornMips> {
        phase1_counter_cpu_with_backing(seed, name, true)
    }

    fn phase1_view_counter_cpu(seed: u16, name: &str) -> crate::Result<super::UnicornMips> {
        phase1_counter_cpu_with_backing(seed, name, false)
    }

    fn phase1_counter_cpu_with_backing(
        seed: u16,
        name: &str,
        persistent_ram_blob: bool,
    ) -> crate::Result<super::UnicornMips> {
        let mut bytes = tiny_mips_spinner_pe();
        write_vec_u32(&mut bytes, 0x178 + 8, 0x200);
        let mut words = vec![
            0x3c08_0000 | (PHASE1_COUNTER_ADDRESS >> 16), // lui t0, counter_hi
            0x3508_0000 | (PHASE1_COUNTER_ADDRESS & 0xffff), // ori t0,t0,counter_lo
            0x2409_0000 | u32::from(seed),                // addiu t1,zero,seed
            0xad09_0000,                                  // sw t1,0(t0)
            0x2410_0000 | u32::from(seed + 0x100),        // addiu s0,zero,callee marker
            0x0200_0011,                                  // mthi s0
            0x0120_0013,                                  // mtlo t1
            0,                                            // nop: first 20 stops after a SW
        ];
        for _ in 0..57 {
            words.push(0x2529_0001); // addiu t1,t1,1
            words.push(0xad09_0000); // sw t1,0(t0)
        }
        words.extend([0x1000_ffff, 0]); // terminal spinner, not reached by tests
        assert_eq!(words.len(), 124);
        for (index, word) in words.into_iter().enumerate() {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.map_region(
            PHASE1_COUNTER_ADDRESS,
            0x1000,
            MemoryPerms::READ | MemoryPerms::WRITE,
            "phase1-counter",
        )?;
        if persistent_ram_blob {
            super::ensure_mapped_ram_blob(
                &mut cpu.mapped_blobs,
                "phase1-counter",
                PHASE1_COUNTER_ADDRESS,
                0x1000,
            )?;
        }
        Ok(cpu)
    }

    fn phase1_persistent_counter_cpu(seed: u16, name: &str) -> crate::Result<super::UnicornMips> {
        let mut cpu = phase1_counter_cpu(seed, name)?;
        cpu.native_engine = super::ProcessNativeEngine::new_persistent_for_test(
            Arch::MIPS,
            Mode::MIPS32 | Mode::LITTLE_ENDIAN,
        );
        Ok(cpu)
    }

    fn phase1_global_hook_straight_line_cpu(name: &str) -> crate::Result<super::UnicornMips> {
        // One long basic block lets the per-instruction global hook reach its
        // 4096-instruction service point before the amortized block scheduler.
        const CODE_WORDS: usize = 16384;
        const CODE_BYTES: usize = CODE_WORDS * 4;
        let mut bytes = tiny_mips_spinner_pe();
        bytes.resize(0x200 + CODE_BYTES, 0);
        write_vec_u32(&mut bytes, 0x98 + 4, CODE_BYTES as u32); // SizeOfCode
        write_vec_u32(&mut bytes, 0x98 + 56, 0x1000 + CODE_BYTES as u32); // SizeOfImage
        write_vec_u32(&mut bytes, 0x178 + 8, CODE_BYTES as u32); // virtual size
        write_vec_u32(&mut bytes, 0x178 + 16, CODE_BYTES as u32); // raw size
        bytes[0x200..0x200 + CODE_BYTES].fill(0); // MIPS NOPs
        write_vec_u32(&mut bytes, 0x200 + CODE_BYTES - 8, 0x1000_ffff);
        let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        Ok(cpu)
    }

    fn phase1_sparse_hook_cpu(name: &str) -> crate::Result<super::UnicornMips> {
        // Each page has an unreachable jr site so the native sparse hook
        // covers the running NOP stream. Fixture-only non-direct trampoline
        // metadata makes the selector choose Sparse when scoped hooks are set;
        // this does not claim that a guest trampoline executes in this test.
        const CODE_WORDS: usize = 16384;
        const CODE_BYTES: usize = CODE_WORDS * 4;
        let mut bytes = tiny_mips_spinner_pe();
        bytes.resize(0x200 + CODE_BYTES, 0);
        write_vec_u32(&mut bytes, 0x98 + 4, CODE_BYTES as u32);
        write_vec_u32(&mut bytes, 0x98 + 56, 0x1000 + CODE_BYTES as u32);
        write_vec_u32(&mut bytes, 0x178 + 8, CODE_BYTES as u32);
        write_vec_u32(&mut bytes, 0x178 + 16, CODE_BYTES as u32);
        bytes[0x200..0x200 + CODE_BYTES].fill(0);
        for page in 0..16 {
            let page_offset = page * 0x1000;
            let jump_target = 0x0040_1000 + page_offset as u32 + 0x804;
            write_vec_u32(
                &mut bytes,
                0x200 + page_offset,
                0x0800_0000 | ((jump_target >> 2) & 0x03ff_ffff),
            );
            write_vec_u32(&mut bytes, 0x200 + page_offset + 0x800, 0x03e0_0008); // jr ra
        }
        write_vec_u32(&mut bytes, 0x200 + CODE_BYTES - 8, 0x1000_ffff);
        let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        let entry = cpu.entry.expect("sparse fixture entry");
        cpu.trampoline_jumps.push(super::MipsTrampolineJump {
            origin: entry + 0x800,
            stub: entry + 0x804,
            byte_len: 0x10,
        });
        assert!(!cpu.trampoline_origins_all_direct());
        assert_eq!(
            super::select_unicorn_code_hook_mode(false, false, true, false),
            super::UnicornCodeHookMode::Sparse
        );
        Ok(cpu)
    }

    fn run_sparse_test_in_isolated_process(test_name: &str) -> bool {
        if std::env::var_os("WINCE_EMU_SPARSE_TEST_CHILD").is_some() {
            assert!(std::env::var_os("WINCE_EMU_SCOPED_HOOKS").is_some());
            return true;
        }
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .arg(test_name)
            .arg("--nocapture")
            .env("WINCE_EMU_SCOPED_HOOKS", "1")
            .env("WINCE_EMU_SPARSE_TEST_CHILD", "1")
            .env_remove("WINCE_EMU_GLOBAL_CODE_HOOK")
            .env_remove("WINCE_EMU_FULL_TRACE")
            .env_remove("WINCE_EMU_CRASH_CODE_TRACE")
            .env_remove("WINCE_EMU_INAVI_GLOBAL_TRACE")
            .env_remove("WINCE_EMU_RESOURCE_TRACE")
            .env_remove("WINCE_EMU_SLOT_TRACE")
            .env_remove("WINCE_EMU_PROGRESS_FILE")
            .output()
            .unwrap();
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            output.status.success() && stdout.contains("1 passed"),
            "sparse child failed or did not run exactly one test: {stdout}\n{stderr}"
        );
        false
    }

    fn phase1_kernel(name: &str) -> crate::Result<crate::ce::kernel::CeKernel> {
        let mut kernel =
            crate::ce::kernel::CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        kernel.set_process_module_base(0x0040_0000);
        kernel.set_process_module_path(format!("\\Test\\{name}"));
        kernel.set_process_module_host_path(std::path::PathBuf::from(name));
        Ok(kernel)
    }

    /// Stage a private page before any native owner exists. Runtime public
    /// imports use the same proposal, but check native mapping before commit.
    fn phase1_publish_private_page_without_native_owner(
        kernel: &mut crate::ce::kernel::CeKernel,
        owner: crate::ce::object::ProcessBirthKey,
    ) -> u32 {
        use crate::ce::memory::{MEM_COMMIT, MEM_RESERVE, VirtualAllocationSource};

        let proposal = kernel
            .memory
            .prepare_private_vm(
                owner,
                VirtualAllocationSource::Private,
                0,
                0x1000,
                MEM_COMMIT | MEM_RESERVE,
                0x04,
            )
            .expect("prepare canonical private page before native owner exists");
        let base = proposal.result_ptr();
        assert_eq!(
            kernel.memory.commit_prepared_private_vm(proposal),
            Some(base),
            "publish canonical private page before native owner exists"
        );
        base
    }

