    #[test]
    fn pre_cpu_file_view_refusal_retains_exact_pending_launch_for_retry() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        let child_path = test_root.join("child.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        std::fs::write(&child_path, tiny_mips_spinner_pe()).unwrap();

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path);
        let parent_pid = kernel.current_process_id();
        let parent_birth = kernel.current_process_birth_key().expect("parent birth");
        let launch = kernel.queue_process_launch(Some("child.exe".to_owned()), None);
        let child_birth = launch.process_birth.expect("published child birth");
        let base = kernel
            .memory
            .virtual_alloc(
                parent_birth,
                crate::ce::memory::VirtualAllocationSource::FileViewLegacy,
                0,
                4,
                0x3000,
                0x04,
            )
            .expect("test lazy file-view allocation");
        assert!(
            kernel
                .memory
                .set_virtual_initial_bytes(parent_birth, base, vec![0; 4])
        );
        let mut view_handles = Vec::new();
        for view_pid in [parent_pid, launch.process_id] {
            let handle = kernel.handles.create_file_mapping(None, 4, 4, None);
            kernel.handles.file_mapping_mut(handle)?.views.push(
                crate::ce::object::FileMappingView {
                    base,
                    size: 4,
                    offset: 0,
                    process_id: view_pid,
                    process_birth: None,
                },
            );
            view_handles.push(handle);
        }
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;

        let error = super::run_pending_process_launches(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits::default(),
            &[],
            &parked,
        )
        .expect_err("conflicting lazy file views must refuse before child CPU admission");
        assert!(
            format!("{error}").contains("ambiguous lazy file-view seed"),
            "pre-CPU setup error: {error}"
        );
        assert!(parked.borrow().is_empty(), "no child CPU was constructed");
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            record.process_id == Some(launch.process_id)
                && matches!(
                    record.op,
                    "CreateProcessResolved"
                        | "CreateProcessResolveFailed"
                        | "CreateProcessChildError"
                        | "CreateProcessChildParked"
                )
        }));

        let retained = kernel.take_pending_process_launches();
        assert_eq!(
            retained,
            vec![launch.clone()],
            "retryable pre-CPU failure must preserve the exact published launch"
        );
        kernel.restore_pending_process_launches(retained);
        // Remove only the conflicting lazy view; retry the *same* birth and
        // require its first real MIPS slice to become CPU-reachable.
        kernel
            .handles
            .file_mapping_mut(view_handles[1])?
            .views
            .clear();
        let mut retry_custody =
            super::CpuCustody::new().expect("retry child CPU custody initializes");
        let mut quarantined_child_fault = false;
        super::run_pending_process_launches_with_custody(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut retry_custody),
            &mut quarantined_child_fault,
            None,
            None,
        )?;
        assert!(kernel.take_pending_process_launches().is_empty());
        assert_eq!(parked.borrow().len(), 1);
        assert_eq!(
            parked.borrow()[0].process_state.process_id,
            launch.process_id
        );
        assert_eq!(
            parked.borrow()[0]
                .cpu
                .owned_process_launch
                .as_ref()
                .and_then(|owned| owned.process_birth),
            Some(child_birth)
        );
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        Ok(())
    }

    #[test]
    fn pre_cpu_bad_pe_retains_current_and_following_exact_launches() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        std::fs::write(test_root.join("bad-child.exe"), b"not a MIPS PE").unwrap();
        std::fs::write(test_root.join("later-child.exe"), tiny_mips_spinner_pe()).unwrap();

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path);
        let parent_pid = kernel.current_process_id();
        let bad = kernel.queue_process_launch(Some("bad-child.exe".to_owned()), None);
        let later = kernel.queue_process_launch(Some("later-child.exe".to_owned()), None);
        let bad_birth = bad.process_birth.expect("first child birth");
        let later_birth = later.process_birth.expect("following child birth");
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let error = super::run_pending_process_launches(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits::default(),
            &[],
            &parked,
        )
        .expect_err("invalid first image must refuse before CPU construction");
        assert!(parked.borrow().is_empty());
        assert_eq!(kernel.current_process_id(), parent_pid);
        for (launch, birth) in [(&bad, bad_birth), (&later, later_birth)] {
            assert!(kernel.handles.process_execution_live_by_birth(birth));
            assert_eq!(
                kernel.process_exit_code(launch.process_handle),
                Some(crate::ce::kernel::STILL_ACTIVE)
            );
            assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        }
        assert!(kernel.recent_process_ops().iter().any(|record| {
            record.op == "CreateProcessResolved" && record.process_id == Some(bad.process_id)
        }));
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            record.process_id == Some(bad.process_id)
                && matches!(
                    record.op,
                    "CreateProcessResolveFailed"
                        | "CreateProcessChildError"
                        | "CreateProcessChildParked"
                )
        }));
        assert_eq!(
            kernel.take_pending_process_launches(),
            vec![bad, later],
            "the popped child and untouched tail keep original order and births"
        );
        Ok(())
    }

    #[test]
    fn pending_launch_batch_keeps_unattempted_siblings_visible_at_claim() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        for name in ["event.exe", "child.exe", "later.exe"] {
            std::fs::write(test_root.join(name), tiny_mips_spinner_pe()).unwrap();
        }

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path);
        let parent_pid = kernel.current_process_id();
        let event = kernel.queue_process_launch(Some("event.exe".to_owned()), None);
        let child = kernel.queue_process_launch(Some("child.exe".to_owned()), None);
        let later = kernel.queue_process_launch(Some("later.exe".to_owned()), None);
        let event_birth = event.process_birth.expect("event birth");
        let child_birth = child.process_birth.expect("child birth");
        let later_birth = later.process_birth.expect("later birth");
        let observed_event = std::cell::Cell::new(false);
        let observed_child = std::cell::Cell::new(false);
        let observed_admitted_event = std::cell::Cell::new(false);
        let observed_admitted_child = std::cell::Cell::new(false);
        let observer =
            |kernel: &CeKernel, claimed: &crate::ce::kernel::PendingProcessLaunch| match claimed
                .process_birth
            {
                Some(birth) if birth == event_birth => {
                    observed_event.set(true);
                    assert_eq!(
                        kernel.pending_process_launch_for_birth(event_birth),
                        Some(&event)
                    );
                    assert_eq!(
                        kernel.pending_process_launch_for_birth(child_birth),
                        Some(&child)
                    );
                    assert_eq!(
                        kernel.pending_process_launch_for_birth(later_birth),
                        Some(&later)
                    );
                    assert!(
                        kernel.has_pending_process_launches(),
                        "B and C must remain Kernel-visible while E is claimed"
                    );
                    assert!(kernel.handles.process_execution_live_by_birth(child_birth));
                    assert!(kernel.handles.process_execution_live_by_birth(later_birth));
                }
                Some(birth) if birth == child_birth => {
                    observed_child.set(true);
                    assert_eq!(
                        kernel.pending_process_launch_for_birth(child_birth),
                        Some(&child)
                    );
                    assert_eq!(
                        kernel.pending_process_launch_for_birth(later_birth),
                        Some(&later)
                    );
                    assert!(
                        kernel.has_pending_process_launches(),
                        "C must remain Kernel-visible while B is claimed"
                    );
                    assert!(kernel.handles.process_execution_live_by_birth(later_birth));
                }
                _ => {}
            };
        let admission_observer =
            |kernel: &mut CeKernel, admitted: &crate::ce::kernel::PendingProcessLaunch| {
                match admitted.process_birth {
                    Some(birth) if birth == event_birth => {
                        assert!(!observed_admitted_event.replace(true));
                        assert_eq!(kernel.pending_process_launch_for_birth(event_birth), None);
                        assert_eq!(
                            kernel.pending_process_launch_for_birth(child_birth),
                            Some(&child)
                        );
                        assert_eq!(
                            kernel.pending_process_launch_for_birth(later_birth),
                            Some(&later)
                        );
                        assert!(
                            kernel.has_pending_process_launches(),
                            "B and C remain Kernel-visible just before E's native slice"
                        );
                    }
                    Some(birth) if birth == child_birth => {
                        assert!(!observed_admitted_child.replace(true));
                        assert_eq!(kernel.pending_process_launch_for_birth(child_birth), None);
                        assert_eq!(
                            kernel.pending_process_launch_for_birth(later_birth),
                            Some(&later)
                        );
                        assert!(
                            kernel.has_pending_process_launches(),
                            "C remains Kernel-visible just before B's native slice"
                        );
                    }
                    _ => {}
                }
            };
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let mut custody = super::CpuCustody::new().expect("sibling CPU custody initializes");
        let mut quarantined_child_fault = false;
        super::run_pending_process_launches_with_custody(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            Some(&observer),
            Some(&admission_observer),
        )?;
        assert!(observed_event.get() && observed_child.get());
        assert!(observed_admitted_event.get() && observed_admitted_child.get());
        assert!(!quarantined_child_fault);
        Ok(())
    }

    #[test]
    fn pending_launch_claim_refuses_missing_or_reused_primary_before_cpu() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        for name in ["stale-primary.exe", "sibling.exe"] {
            std::fs::write(test_root.join(name), tiny_mips_spinner_pe()).unwrap();
        }

        for reused_tid in [false, true] {
            let mut kernel = phase1_kernel("parent.exe")?;
            kernel.set_process_module_host_path(parent_path.clone());
            let parent_pid = kernel.current_process_id();
            let stale = kernel.queue_process_launch(Some("stale-primary.exe".to_owned()), None);
            let sibling = kernel.queue_process_launch(Some("sibling.exe".to_owned()), None);
            let owner = stale.process_birth.expect("published process birth");
            let sibling_birth = sibling.process_birth.expect("published sibling birth");
            let primary = stale.primary_thread_birth.expect("published primary birth");
            if reused_tid {
                assert!(kernel.mark_guest_thread_exited(stale.thread_handle, 0x31));
                assert!(kernel.close_handle(stale.thread_handle)?);
                let worker_handle = kernel.handles.try_create_thread_in_birth(
                    owner,
                    stale.thread_id,
                    0,
                    0,
                    false,
                )?;
                assert_ne!(
                    kernel.handles.thread_birth_key_for_handle(worker_handle),
                    Some(primary)
                );
            } else {
                assert!(
                    kernel
                        .handles
                        .discard_unpublished_thread(stale.thread_handle, stale.thread_id)
                );
                assert_eq!(kernel.handles.process_primary_thread_birth(owner), None);
            }
            let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
                .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
            let guard = super::SealedHostWriteGuard::default();
            let parked = Rc::new(RefCell::new(VecDeque::new()));
            let mut framebuffer = VirtualFramebuffer::default_primary()?;
            super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.set(None));
            let error = super::run_pending_process_launches(
                &mut parent_uc,
                &mut kernel,
                parent_pid,
                &guard,
                &mut framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 128,
                    wall_clock_limit_ms: 500,
                    stop_pc: None,
                    live_pump: false,
                },
                &[],
                &parked,
            )
            .expect_err("an invalid original primary cannot claim a child CPU");
            assert!(
                matches!(&error, Error::Backend(detail) if detail.contains("canonical process or primary thread birth is stale")),
                "missing/reused primary must fail at exact claim, not later: {error}"
            );
            assert_eq!(
                super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.take()),
                None
            );
            assert!(parked.borrow().is_empty(), "no child CPU was admitted");
            assert!(!kernel.recent_process_ops().iter().any(|record| {
                record.process_id == Some(stale.process_id) && record.op == "CreateProcessResolved"
            }));
            for (launch, birth) in [(&stale, owner), (&sibling, sibling_birth)] {
                assert!(kernel.handles.process_execution_live_by_birth(birth));
                assert_eq!(
                    kernel.process_exit_code(launch.process_handle),
                    Some(crate::ce::kernel::STILL_ACTIVE)
                );
                assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
            }
            assert_eq!(
                kernel.take_pending_process_launches(),
                vec![stale, sibling],
                "a refused claim preserves the original queue order and births"
            );
        }
        Ok(())
    }

    #[test]
    fn nested_pending_launch_batch_preserves_new_child_before_outer_siblings() -> crate::Result<()>
    {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        std::fs::write(
            test_root.join("event.exe"),
            tiny_mips_create_process_then_spin_pe(),
        )
        .unwrap();
        for name in ["child.exe", "later.exe", "survivor.exe"] {
            std::fs::write(test_root.join(name), tiny_mips_spinner_pe()).unwrap();
        }

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path);
        let parent_pid = kernel.current_process_id();
        let event = kernel.queue_process_launch(Some("event.exe".to_owned()), None);
        let child = kernel.queue_process_launch(Some("child.exe".to_owned()), None);
        let later = kernel.queue_process_launch(Some("later.exe".to_owned()), None);
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let mut custody = super::CpuCustody::new()
            .map_err(|error| Error::Backend(format!("fixture custody: {error}")))?;
        let mut quarantined_child_fault = false;

        let error = super::run_pending_process_launches_with_custody(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            None,
        )
        .expect_err("nested returned CPU tree must stop before sibling admission");
        assert!(
            matches!(&error, Error::Backend(message) if message.contains("returned child CPU tree disagrees")),
            "nested child stop: {error}"
        );
        let resolved: Vec<_> = kernel
            .recent_process_ops()
            .iter()
            .filter(|record| record.op == "CreateProcessResolved")
            .map(|record| record.process_id.expect("resolved child PID"))
            .collect();
        assert_eq!(resolved.len(), 2, "E and nested D resolve before the stop");
        assert_eq!(resolved[0], event.process_id);
        let nested_pid = resolved[1];
        assert_ne!(nested_pid, event.process_id);
        assert_ne!(nested_pid, child.process_id);
        assert_ne!(nested_pid, later.process_id);
        let nested_handle = kernel
            .recent_process_ops()
            .iter()
            .find(|record| {
                record.op == "CreateProcessWQueued" && record.process_id == Some(nested_pid)
            })
            .and_then(|record| record.process_handle)
            .expect("nested D retained its original process handle");
        let nested_birth = kernel
            .handles
            .process_birth_key_for_handle(nested_handle)
            .expect("nested D retained its exact process birth");
        let nested_primary = kernel
            .handles
            .process_primary_thread_birth(nested_birth)
            .expect("nested D retained its primary thread birth");
        let event_birth = event.process_birth.expect("original E process birth");
        assert_eq!(
            kernel.take_pending_process_launches(),
            vec![child, later],
            "untouched outer siblings retain their FIFO order"
        );
        assert_eq!(custody.counts().unverified_stopped_trees, 1);
        assert_eq!(custody.counts().abandoned_unbound_trees, 0);
        let retained = custody.retained_tree_snapshots();
        assert_eq!(
            retained.len(),
            1,
            "one whole nested tree remains in custody"
        );
        assert_eq!(retained[0].origin_birth, event_birth);
        custody
            .with_retained_tree(retained[0].key, |tree| {
                let root = tree
                    .owned_process_launch
                    .as_ref()
                    .expect("returned root owns nested D's original CPU");
                assert_eq!(root.process_birth, Some(nested_birth));
                assert_eq!(root.process_handle, nested_handle);
                assert_eq!(root.process_id, nested_pid);
                assert_eq!(root.primary_thread_birth, Some(nested_primary));
                assert_eq!(tree.saved_context_thread_birth, Some(nested_primary));
                assert!(tree.saved_context.is_some(), "D's CPU context is retained");
                assert!(tree.run_slice_generation > 0, "D executed guest MIPS");
                assert_eq!(tree.parked_child_processes.len(), 1);
                let parked_event = &tree.parked_child_processes[0];
                assert_eq!(parked_event.process_state.process_id, event.process_id);
                assert_eq!(parked_event.process_handle, Some(event.process_handle));
                assert_eq!(parked_event.thread_handle, Some(event.thread_handle));
                assert_eq!(parked_event.thread_id, event.thread_id);
                assert_eq!(
                    parked_event
                        .cpu
                        .owned_process_launch
                        .as_ref()
                        .and_then(|launch| launch.process_birth),
                    Some(event_birth),
                    "parked E remains its original CPU payload"
                );
                assert_eq!(
                    parked_event.cpu.saved_context_thread_birth,
                    event.primary_thread_birth
                );
                assert!(
                    parked_event.cpu.saved_context.is_some(),
                    "E's CPU context is retained"
                );
                assert!(parked_event.cpu.run_slice_generation > 0);
                assert!(parked_event.cpu.parked_child_processes.is_empty());
            })
            .expect("whole nested tree remains in its unverified holding cell");
        for (birth, handle) in [
            (event_birth, event.process_handle),
            (nested_birth, nested_handle),
        ] {
            assert!(kernel.handles.process_execution_live_by_birth(birth));
            assert_eq!(
                kernel.process_exit_code(handle),
                Some(crate::ce::kernel::STILL_ACTIVE)
            );
            assert_eq!(kernel.is_wait_ready(handle, 1), Some(false));
        }
        assert!(!quarantined_child_fault);
        assert!(parked.borrow().is_empty());
        Ok(())
    }

    #[test]
    fn requested_pending_child_framebuffer_mismatch_requeues_same_birth_before_first_slice()
    -> crate::Result<()> {
        let mut kernel = phase1_kernel("d011-pending-parent.exe")?;
        let parent_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(
            Some("\\Test\\intentionally-absent-d011-child.exe".to_owned()),
            None,
        );
        let birth = launch.process_birth.expect("pending child birth");
        let receiver = launch
            .primary_thread_birth
            .expect("pending child primary thread birth");
        let mut compatible =
            VirtualFramebuffer::new(8, 8, crate::ce::framebuffer::PixelFormat::Rgb565)?;
        kernel.set_current_process_id(launch.process_id);
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver,
                "D011_PENDING_CHILD",
                "",
                None,
                None,
                0,
                crate::ce::gwe::WS_VISIBLE,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 4, 4),
            )
            .expect("pending child-owned window");
        assert!(kernel.capture_window_backing_store(hwnd, &compatible));
        kernel.set_current_process_id(parent_pid);
        assert!(kernel.terminate_process(launch.process_handle, 0x6b));
        let trace_len = kernel.recent_process_ops().len();
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let parent_pc = parent_uc
            .reg_read(RegisterMIPS::PC)
            .map_err(|err| Error::Backend(format!("read fixture parent PC: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut incompatible =
            VirtualFramebuffer::new(8, 8, crate::ce::framebuffer::PixelFormat::Bgra8888)?;
        let error = super::run_pending_process_launches(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut incompatible,
            super::UnicornRunLimits::default(),
            &[],
            &parked,
        )
        .expect_err("incompatible saved image requires recovery");
        assert!(matches!(
            error,
            Error::HostExitRecoveryRequired { process_id, hwnd: Some(rejected_hwnd), .. }
                if process_id == launch.process_id && rejected_hwnd == hwnd
        ));
        assert_eq!(kernel.current_process_id(), parent_pid);
        assert_eq!(parent_uc.reg_read(RegisterMIPS::PC).unwrap(), parent_pc);
        assert!(parked.borrow().is_empty());
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert!(kernel.gwe.is_window(hwnd));
        assert_eq!(kernel.recent_process_ops().len(), trace_len);
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            record.op == "CreateProcessResolved" && record.process_id == Some(launch.process_id)
        }));
        let retained = kernel.take_pending_process_launches();
        assert_eq!(retained.len(), 1);
        assert_eq!(retained[0].process_birth, Some(birth));
        assert_eq!(retained[0].process_handle, launch.process_handle);
        assert_eq!(retained[0].thread_handle, launch.thread_handle);
        kernel.restore_pending_process_launches(retained);

        super::run_pending_process_launches(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut compatible,
            super::UnicornRunLimits::default(),
            &[],
            &parked,
        )?;
        assert!(kernel.take_pending_process_launches().is_empty());
        assert_eq!(parent_uc.reg_read(RegisterMIPS::PC).unwrap(), parent_pc);
        assert!(parked.borrow().is_empty());
        assert_eq!(kernel.current_process_id(), parent_pid);
        assert!(!kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(kernel.process_exit_code(launch.process_handle), Some(0x6b));
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(true));
        assert!(!kernel.gwe.is_window(hwnd));
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            record.op == "CreateProcessResolved" && record.process_id == Some(launch.process_id)
        }));
        Ok(())
    }

    #[test]
    fn direct_kernel_real_handle_terminate_fails_closed_without_pc_zero_resume() -> crate::Result<()>
    {
        let mut kernel = phase1_kernel("direct-real-handle-parent.exe")?;
        let launch =
            kernel.queue_process_launch(Some("\\Test\\direct-target.exe".to_owned()), None);
        let birth = launch.process_birth.expect("target birth");
        let _ = kernel.take_pending_process_launches();
        let mut bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x3c04_0000 | (launch.process_handle >> 16),
            0x3484_0000 | (launch.process_handle & 0xffff),
            0x2405_0003, // addiu a1,zero,3
            0x2408_f3fa, // addiu t0,zero,-3078: direct CE syscall target
            0x0100_f809, // jalr t0
            0,
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("direct-real-handle-parent.exe", &bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 100,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let err = attempt
            .result
            .expect_err("direct real-handle PC-zero continuation is unsupported");
        assert!(
            format!("{err:#}").contains("no safe continuation"),
            "{err:#}"
        );
        assert_eq!(
            attempt.report.failure_operation(),
            Some("unsupported direct-kernel real-handle exit")
        );
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert_eq!(
            kernel
                .handles
                .process_termination_requested_exit_code_by_birth(birth),
            None
        );
        Ok(())
    }

    fn phase1_assert_native_markers(cpu: &super::UnicornMips, seed: u16) {
        let expected_counter = phase1_counter(cpu);
        let existing_engine = phase1_engine_id(cpu);
        {
            // This idle diagnostic lease must reuse the actual process-owned engine,
            // not instantiate one or use only its serialized RAM mirror. Preserve
            // the production mapping ledger; do not execute or alter CPU context.
            let mut native = cpu.native_engine.lease().unwrap();
            assert!(native.reused());
            assert_eq!(native.identity(), existing_engine);
            let actual = native
                .mem_read_as_vec(u64::from(PHASE1_COUNTER_ADDRESS), 4)
                .unwrap();
            assert_eq!(actual, expected_counter.to_le_bytes());
            let ledger = native.take_metadata().unwrap();
            native.set_metadata(ledger);
            native.finish().unwrap();
        }
        assert_eq!(phase1_engine_id(cpu), existing_engine);
        let saved = cpu
            .saved_context
            .as_ref()
            .expect("native attempt captured its continuation");
        assert_eq!(saved.regs.regs[16], u32::from(seed + 0x100));
        assert_eq!(saved.regs.hi, u32::from(seed + 0x100));
        assert_eq!(saved.regs.lo, u32::from(seed));
        assert_eq!(saved.regs.regs[9], expected_counter);
        let snapshot = cpu
            .last_debug_snapshot()
            .expect("actual backend stop was captured");
        assert!(snapshot.memory_fault.is_none());
        assert!(snapshot.interrupt_probe.is_none());
        assert!(snapshot.invalid_instruction_probe.is_none());
        assert!(
            snapshot.pc_stop.is_none(),
            "ordinary count stop, not an exact-PC shortcut"
        );
    }

    #[test]
    fn phase1_backend_reuses_engine_and_real_ram_across_ordinary_counted_runs() -> crate::Result<()>
    {
        let mut kernel = phase1_kernel("phase1-repeat.exe")?;
        let mut cpu = phase1_persistent_counter_cpu(0x1000, "phase1-repeat.exe")?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        assert!(cpu.native_engine_identity_for_test().is_none());
        phase1_run_twenty(&mut cpu, &mut kernel, &mut framebuffer)?;
        let engine = phase1_engine_id(&cpu);
        assert_eq!(phase1_counter(&cpu), 0x1006);
        phase1_assert_native_markers(&cpu, 0x1000);
        phase1_run_twenty(&mut cpu, &mut kernel, &mut framebuffer)?;
        assert_eq!(
            phase1_engine_id(&cpu),
            engine,
            "same process retains its native handle"
        );
        assert_eq!(phase1_counter(&cpu), 0x1010);
        phase1_assert_native_markers(&cpu, 0x1000);
        assert_eq!(kernel.current_process_id(), 1);
        Ok(())
    }

    #[test]
    fn phase1_backend_none_entry_resets_reused_native_registers() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-fresh-entry.exe")?;
        let mut cpu = phase1_persistent_counter_cpu(0x5000, "phase1-fresh-entry.exe")?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        phase1_run_twenty(&mut cpu, &mut kernel, &mut framebuffer)?;
        let identity = phase1_engine_id(&cpu);
        let original_f0;
        {
            let mut native = cpu.native_engine.lease().unwrap();
            original_f0 = native.reg_read(RegisterMIPS::F0).unwrap();
            native
                .reg_write(RegisterMIPS::F0, original_f0 ^ 0x3f80_0000)
                .unwrap();
            native.reg_write(RegisterMIPS::T2, 0xabcdef01).unwrap();
            let ledger = native.take_metadata().unwrap();
            native.set_metadata(ledger);
            native.finish().unwrap();
        }
        // A caller requests a fresh entry, as guest-exit cleanup can do. There
        // is no fabricated runtime stop or native result in this fixture.
        assert!(cpu.owned_process_launch.is_none());
        assert!(!cpu.has_active_blocked_state(&kernel));
        cpu.saved_context = None;
        phase1_run_twenty(&mut cpu, &mut kernel, &mut framebuffer)?;
        assert_eq!(phase1_engine_id(&cpu), identity);
        assert_eq!(phase1_counter(&cpu), 0x5006);
        assert_eq!(cpu.saved_context.as_ref().unwrap().regs.regs[10], 0);
        {
            let mut native = cpu.native_engine.lease().unwrap();
            assert_eq!(native.reg_read(RegisterMIPS::F0).unwrap(), original_f0);
            let ledger = native.take_metadata().unwrap();
            native.set_metadata(ledger);
            native.finish().unwrap();
        }
        phase1_assert_native_markers(&cpu, 0x5000);
        Ok(())
    }

    #[test]
    fn phase1_backend_clone_owns_distinct_engine_context_and_ram() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-clone.exe")?;
        let mut parent = phase1_persistent_counter_cpu(0x2000, "phase1-clone.exe")?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        phase1_run_twenty(&mut parent, &mut kernel, &mut framebuffer)?;
        let parent_engine = phase1_engine_id(&parent);
        let mut checkpoint = parent.clone();
        assert_eq!(phase1_counter(&checkpoint), 0x2006);
        // Clone is allowed to instantiate its independent engine lazily.
        if let Some(identity) = checkpoint.native_engine_identity_for_test() {
            assert_ne!(identity, parent_engine);
        }
        phase1_run_twenty(&mut checkpoint, &mut kernel, &mut framebuffer)?;
        assert_ne!(phase1_engine_id(&checkpoint), parent_engine);
        assert_eq!(phase1_counter(&checkpoint), 0x2010);
        assert_eq!(
            phase1_counter(&parent),
            0x2006,
            "checkpoint RAM changes do not touch the owner"
        );
        assert_eq!(phase1_engine_id(&parent), parent_engine);
        phase1_assert_native_markers(&parent, 0x2000);
        phase1_run_twenty(&mut parent, &mut kernel, &mut framebuffer)?;
        assert_eq!(phase1_engine_id(&parent), parent_engine);
        assert_eq!(
            phase1_counter(&parent),
            0x2010,
            "parent resumed its own actual counter/context"
        );
        phase1_assert_native_markers(&parent, 0x2000);
        phase1_assert_native_markers(&checkpoint, 0x2000);
        Ok(())
    }

    fn phase1_actor_cpu<'a>(
        active: &'a super::UnicornMips,
        kernel: &crate::ce::kernel::CeKernel,
        pid: u32,
    ) -> &'a super::UnicornMips {
        if kernel.current_process_id() == pid {
            active
        } else {
            &active
                .parked_child_processes
                .iter()
                .find(|parked| parked.process_state.process_id == pid)
                .expect("production switch retains exactly this parked owner")
                .cpu
        }
    }

    fn phase1_select_actor(
        active: &mut super::UnicornMips,
        kernel: &mut crate::ce::kernel::CeKernel,
        pid: u32,
    ) {
        if kernel.current_process_id() != pid {
            assert!(active.rotate_to_parked_process_id(kernel, pid));
        }
        assert_eq!(kernel.current_process_id(), pid);
    }

    #[test]
    fn phase1_backend_real_park_rotate_moves_engine_and_same_va_ram_owner() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-parent.exe")?;
        let mut active = phase1_persistent_counter_cpu(0x3000, "phase1-parent.exe")?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        phase1_run_twenty(&mut active, &mut kernel, &mut framebuffer)?;
        let parent_state = kernel.current_process_state();
        let parent_engine = phase1_engine_id(&active);
        let launch = kernel.queue_process_launch(Some("\\Test\\phase1-child.exe".to_owned()), None);
        // Test fixture fulfills the queued launch below using real allocated IDs and
        // handles; it does not ask the loader to launch a nonexistent host fixture.
        let queued = kernel.take_pending_process_launches();
        assert!(
            queued
                .iter()
                .any(|item| item.process_id == launch.process_id)
        );
        let child_state = crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        };
        let mut child = phase1_persistent_counter_cpu(0x4000, "phase1-child.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        kernel.set_current_process_state(child_state);
        kernel.set_process_module_path("\\Test\\phase1-child.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("phase1-child.exe"));
        phase1_run_twenty(&mut child, &mut kernel, &mut framebuffer)?;
        assert_eq!(child.current_thread_id(), launch.thread_id);
        let child_engine = phase1_engine_id(&child);
        assert_ne!(child_engine, parent_engine);
        assert_eq!(phase1_counter(&active), 0x3006);
        assert_eq!(phase1_counter(&child), 0x4006);
        kernel.set_current_process_state(parent_state);
        kernel.set_process_module_path("\\Test\\phase1-parent.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("phase1-parent.exe"));
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: child_state,
                thread_id: launch.thread_id,
                cpu: Box::new(child),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\phase1-child.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("phase1-child.exe"),
                command_line: String::new(),
                current_directory: None,
            });
        phase1_select_actor(&mut active, &mut kernel, launch.process_id);
        assert_eq!(phase1_engine_id(&active), child_engine);
        assert_eq!(phase1_counter(&active), 0x4006);
        phase1_run_twenty(&mut active, &mut kernel, &mut framebuffer)?;
        let child_after = phase1_actor_cpu(&active, &kernel, launch.process_id);
        assert_eq!(phase1_engine_id(child_after), child_engine);
        assert_eq!(phase1_counter(child_after), 0x4010);
        phase1_assert_native_markers(child_after, 0x4000);
        assert_eq!(
            phase1_counter(phase1_actor_cpu(&active, &kernel, 1)),
            0x3006
        );
        phase1_select_actor(&mut active, &mut kernel, 1);
        assert_eq!(phase1_engine_id(&active), parent_engine);
        phase1_run_twenty(&mut active, &mut kernel, &mut framebuffer)?;
        let parent_after = phase1_actor_cpu(&active, &kernel, 1);
        assert_eq!(phase1_engine_id(parent_after), parent_engine);
        assert_eq!(phase1_counter(parent_after), 0x3010);
        phase1_assert_native_markers(parent_after, 0x3000);
        assert_eq!(
            phase1_counter(phase1_actor_cpu(&active, &kernel, launch.process_id)),
            0x4010
        );
        Ok(())
    }

    #[test]
    fn blocked_sender_idle_releases_slice_end_token_for_runnable_parked_process()
    -> crate::Result<()> {
        let mut kernel = phase1_kernel("blocked-sender-fairness.exe")?;
        let mut active = phase1_counter_cpu(0x1000, "blocked-sender-fairness.exe")?;
        let entry = active.entry.expect("loaded parent entry");
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .handles
            .thread_birth_key_by_id(receiver_thread)
            .expect("boot receiver birth");
        let (sender_handle, sender_thread) = kernel.create_guest_thread(entry + 4, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let started_ms = kernel.timers.tick_count();
        let sleep_frame = kernel
            .try_publish_finite_sleep_wait_for_birth(
                receiver_birth,
                crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
                started_ms,
                60_000,
            )
            .expect("exact finite Sleep frame");
        let hwnd = kernel.create_window_ex_w(
            receiver_thread,
            "BLOCKED_SENDER_FAIRNESS",
            "",
            None,
            0,
            0,
            0,
        );
        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 0x76,
                0,
                0,
                None,
            )
            .expect("send queued behind exact Sleep frame");
        assert_eq!(
            kernel
                .gwe
                .sent_message(send_id)
                .unwrap()
                .deferred_from_sleep_frame,
            Some(sleep_frame)
        );
        let send_kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id: receiver_thread,
            result_ptr: None,
            previous_running_thread: Some((sender_thread, sender_handle)),
        };
        let send_wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                sender_birth,
                sender_handle,
                Vec::new(),
                super::scheduler_blocked_wait_kind(send_kind),
                started_ms,
                crate::ce::timer::INFINITE,
            )
            .expect("exact sender wait");
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[29] = active.stack_top.expect("parent stack") - 0x100;
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[29] = active.stack_top.expect("parent stack") - 0x200;
        active.blocked_wait_threads.push(super::BlockedWaitThread {
            frame_ref: Some(sleep_frame),
            wait_id: sleep_frame.wait_id(),
            thread_id: receiver_thread,
            thread_handle: crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
            wait_handles: Vec::new(),
            kind: super::BlockedWaitKind::Sleep,
            wait_started_ms: started_ms,
            timeout_ms: 60_000,
            regs: receiver_regs,
            return_pc: entry + 8,
        });
        active.blocked_wait_threads.push(super::BlockedWaitThread {
            frame_ref: None,
            wait_id: send_wait_id,
            thread_id: sender_thread,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind: send_kind,
            wait_started_ms: started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: sender_regs.clone(),
            return_pc: entry + 8,
        });
        active.current_thread_id = sender_thread;
        active.saved_context = Some(super::SavedCpuContext {
            pc: entry + 4,
            regs: sender_regs,
        });
        stamp_synthetic_saved_context(&mut active, &kernel);
        active.slice_end_rotation_pending = true;
        assert!(
            active
                .blocked_sender_finite_sleep_idle_delay_ms(&kernel)
                .is_some(),
            "fixture must prove no runnable active continuation"
        );

        let launch =
            kernel.queue_process_launch(Some("\\Test\\fairness-child.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let mut child = phase1_counter_cpu(0x2000, "fairness-child.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        let mut child_regs = super::MipsGuestContext::zero();
        child_regs.regs[29] = child.stack_top.expect("child stack") - 0x100;
        child.saved_context = Some(super::SavedCpuContext {
            pc: child.entry.expect("child entry"),
            regs: child_regs,
        });
        stamp_synthetic_saved_context(&mut child, &kernel);
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: crate::ce::kernel::CurrentProcessState {
                    process_id: launch.process_id,
                    exit_code: crate::ce::kernel::STILL_ACTIVE,
                    signaled: false,
                },
                thread_id: launch.thread_id,
                cpu: Box::new(child),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\fairness-child.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("fairness-child.exe"),
                command_line: String::new(),
                current_directory: None,
            });
        assert!(active.has_runnable_parked_process(&kernel));

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let limits = super::UnicornRunLimits {
            instruction_limit: 20,
            wall_clock_limit_ms: 20,
            stop_pc: None,
            live_pump: true,
        };
        let idle = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        idle.result?;
        assert_eq!(idle.report.attempt_id(), None);
        assert_eq!(
            idle.report.final_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        assert!(!active.slice_end_rotation_pending());
        assert_eq!(kernel.current_process_id(), 1);
        assert_eq!(active.saved_context_pc(), Some(entry + 4));
        assert!(kernel.is_blocked_finite_sleep_frame(sleep_frame));
        assert!(kernel.blocked_waiter(send_wait_id).is_some());
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![send_id]
        );

        let rotated = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        rotated.result?;
        assert_eq!(rotated.report.attempt_id(), None);
        assert_eq!(
            rotated.report.final_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        assert_eq!(kernel.current_process_id(), launch.process_id);
        let parent = phase1_actor_cpu(&active, &kernel, 1);
        assert!(
            parent
                .blocked_wait_threads
                .iter()
                .any(|wait| wait.wait_id == send_wait_id)
        );
        assert!(
            parent
                .blocked_wait_threads
                .iter()
                .any(|wait| wait.frame_ref == Some(sleep_frame))
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![send_id]
        );
        Ok(())
    }

    #[test]
    fn slice_end_reads_outgoing_shared_view_before_rotating_to_child() -> crate::Result<()> {
        let mut kernel = phase1_kernel("view-writer.exe")?;
        let mapping_handle = kernel.handles.create_file_mapping(None, 4, 4, None);
        kernel.handles.file_mapping_mut(mapping_handle)?.views.push(
            crate::ce::object::FileMappingView {
                base: PHASE1_COUNTER_ADDRESS,
                size: 4,
                offset: 0,
                process_id: 1,
                process_birth: None,
            },
        );
        let mut active = phase1_view_counter_cpu(0x3000, "view-writer.exe")?;
        // This parent was selected by the preceding slice-end handoff. Force
        // its real native attempt before the preflight runnable-child gate.
        active.slice_end_rotation_pending = true;

        let launch = kernel.queue_process_launch(Some("\\Test\\view-reader.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let mut child = phase1_counter_cpu(0x4000, "view-reader.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        let mut child_regs = super::MipsGuestContext::zero();
        child_regs.regs[29] = child.stack_top.unwrap() - 0x100;
        child.saved_context = Some(super::SavedCpuContext {
            pc: child.entry.unwrap(),
            regs: child_regs,
        });
        stamp_synthetic_saved_context(&mut child, &kernel);
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: crate::ce::kernel::CurrentProcessState {
                    process_id: launch.process_id,
                    exit_code: crate::ce::kernel::STILL_ACTIVE,
                    signaled: false,
                },
                thread_id: launch.thread_id,
                cpu: Box::new(child),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\view-reader.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("view-reader.exe"),
                command_line: String::new(),
                current_directory: None,
            });

        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let execution = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        execution.result?;
        let parent_report = execution.report;
        let parent_attempt_id = parent_report
            .attempt_id()
            .expect("the parent ran a real native attempt");
        assert_eq!(parent_report.start_process_id(), Some(1));
        assert_eq!(parent_report.end_process_id(), Some(1));
        assert_eq!(
            parent_report.final_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        assert!(matches!(
            parent_report.native_result(),
            super::AttemptObservation::Value(())
        ));
        assert!(matches!(
            parent_report.count_stop_query(),
            super::AttemptObservation::Value(true)
        ));
        assert!(matches!(
            parent_report.timeout_query(),
            super::AttemptObservation::Value(false)
        ));
        assert_eq!(kernel.current_process_id(), launch.process_id);
        assert!(active.slice_end_rotation_pending());
        let outgoing = active
            .parked_child_processes
            .iter()
            .find(|parked| parked.process_state.process_id == 1)
            .expect("actual slice-end handoff parked the writer");
        assert_eq!(
            outgoing
                .cpu
                .saved_context
                .as_ref()
                .expect("outgoing guest context")
                .regs
                .regs[9],
            0x3006
        );
        assert!(
            outgoing
                .cpu
                .read_mapped_bytes(PHASE1_COUNTER_ADDRESS, 4)
                .is_none(),
            "view bytes must not have a competing test RAM blob"
        );
        assert_eq!(
            &kernel
                .handles
                .file_mapping(mapping_handle)?
                .legacy_data()
                .unwrap()[..4],
            &0x3006u32.to_le_bytes(),
            "outgoing native view bytes must reach canonical mapping backing before PID rotation"
        );
        // The result was detached before rotation. Its owner and native facts
        // must not change when the incoming child receives its own native run.
        let child_execution = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        child_execution.result?;
        assert_eq!(
            child_execution.report.start_process_id(),
            Some(launch.process_id)
        );
        assert_ne!(child_execution.report.attempt_id(), Some(parent_attempt_id));
        assert_eq!(parent_report.attempt_id(), Some(parent_attempt_id));
        assert_eq!(parent_report.start_process_id(), Some(1));
        assert_eq!(parent_report.end_process_id(), Some(1));
        assert_eq!(
            parent_report.final_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        Ok(())
    }

    #[test]
    fn slice_end_finish_failure_stays_with_outgoing_parent() -> crate::Result<()> {
        let mut kernel = phase1_kernel("finish-writer.exe")?;
        let mapping_handle = kernel.handles.create_file_mapping(None, 4, 4, None);
        kernel.handles.file_mapping_mut(mapping_handle)?.views.push(
            crate::ce::object::FileMappingView {
                base: PHASE1_COUNTER_ADDRESS,
                size: 4,
                offset: 0,
                process_id: 1,
                process_birth: None,
            },
        );
        let mut active = phase1_view_counter_cpu(0x3000, "finish-writer.exe")?;
        // The prior handoff selected this parent. Its native attempt must run
        // before the preflight runnable-child gate can rotate again.
        active.slice_end_rotation_pending = true;
        active.native_engine.arm_finish_failure_once_for_test();

        let launch =
            kernel.queue_process_launch(Some("\\Test\\finish-reader.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let mut child = phase1_counter_cpu(0x4000, "finish-reader.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        let mut child_regs = super::MipsGuestContext::zero();
        child_regs.regs[29] = child.stack_top.unwrap() - 0x100;
        child.saved_context = Some(super::SavedCpuContext {
            pc: child.entry.unwrap(),
            regs: child_regs,
        });
        stamp_synthetic_saved_context(&mut child, &kernel);
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: crate::ce::kernel::CurrentProcessState {
                    process_id: launch.process_id,
                    exit_code: crate::ce::kernel::STILL_ACTIVE,
                    signaled: false,
                },
                thread_id: launch.thread_id,
                cpu: Box::new(child),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\finish-reader.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("finish-reader.exe"),
                command_line: String::new(),
                current_directory: None,
            });

        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let execution = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        let report = execution.report;
        let error = execution
            .result
            .expect_err("injected checked-finish failure must reach the caller");
        assert!(report.attempt_id().is_some());
        assert_eq!(report.start_process_id(), Some(1));
        assert_eq!(report.end_process_id(), Some(1));
        assert_eq!(
            report.final_outcome(),
            super::NativeSliceOutcome::BackendError
        );
        assert!(matches!(
            report.native_result(),
            super::AttemptObservation::Value(())
        ));
        assert!(matches!(
            report.count_stop_query(),
            super::AttemptObservation::Value(true)
        ));
        assert!(matches!(
            report.timeout_query(),
            super::AttemptObservation::Value(false)
        ));
        assert!(
            report.partial_effects_possible(),
            "guest and outgoing file-view writes precede the checked finish failure"
        );
        assert!(
            report.failure_operation().is_some(),
            "a sealed backend failure needs its failing operation"
        );
        let detail = format!("{error:#}");
        assert!(
            detail.contains("release native slice hooks")
                || detail.contains("finish owner-bound native slice"),
            "{detail}"
        );
        assert_eq!(
            kernel.current_process_id(),
            1,
            "failed parent cannot hand off"
        );
        assert!(
            active
                .read_mapped_bytes(PHASE1_COUNTER_ADDRESS, 4)
                .is_none(),
            "view bytes must not have a competing test RAM blob"
        );
        assert_eq!(
            &kernel
                .handles
                .file_mapping(mapping_handle)?
                .legacy_data()
                .unwrap()[..4],
            &0x3006u32.to_le_bytes(),
            "outgoing native view readback must precede checked finish"
        );
        assert_eq!(
            active.last_native_slice_outcome(),
            super::NativeSliceOutcome::BackendError,
            "finish failure belongs to the outgoing parent"
        );
        assert!(!active.slice_end_rotation_pending());
        assert!(active.native_engine_identity_for_test().is_none());
        let parked_child = active
            .parked_child_processes
            .iter()
            .find(|parked| parked.process_state.process_id == launch.process_id)
            .expect("child must remain parked after failed parent finish");
        assert_eq!(
            parked_child.cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        assert!(parked_child.cpu.native_engine_identity_for_test().is_none());
        Ok(())
    }

    #[test]
    fn ordinary_finish_failure_rejects_retry_before_another_native_attempt() -> crate::Result<()> {
        let mut kernel = phase1_kernel("finish-retry.exe")?;
        let mut cpu = phase1_counter_cpu(0x3000, "finish-retry.exe")?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let limits = super::UnicornRunLimits {
            instruction_limit: 20,
            wall_clock_limit_ms: 500,
            stop_pc: None,
            live_pump: false,
        };
        cpu.native_engine.arm_finish_failure_once_for_test();

        let first = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        assert!(
            first.result.is_err(),
            "the checked finish injection must fire"
        );
        assert!(first.report.attempt_id().is_some(), "real MIPS ran");
        assert_eq!(
            first.report.final_outcome(),
            super::NativeSliceOutcome::BackendError
        );
        assert_eq!(kernel.current_process_id(), 1);
        let counter_after_failure = phase1_counter(&cpu);
        assert_eq!(counter_after_failure, 0x3006);
        assert!(cpu.native_engine_identity_for_test().is_none());

        // The failed lease discarded its native owner after guest effects and
        // before a continuation was safely published. A second call must not
        // restore the provisional scalar context into a fresh owner and run.
        let retry = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        let counter_after_retry = phase1_counter(&cpu);
        assert_eq!(
            retry.report.attempt_id(),
            None,
            "a rejected retry must not enter native MIPS: result_ok={} counter_before=0x{counter_after_failure:08x} counter_after=0x{counter_after_retry:08x}",
            retry.result.is_ok()
        );
        assert!(
            retry.result.is_err(),
            "uncertain continuation must fail closed"
        );
        assert_eq!(
            retry.report.final_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        assert_eq!(counter_after_retry, counter_after_failure);
        assert_eq!(kernel.current_process_id(), 1);
        Ok(())
    }

    #[test]
    fn native_two_process_same_va_file_views_isolate_bytes_across_a_b_a() -> crate::Result<()> {
        const PARENT_BYTES: u32 = 0x1122_3344;
        const CHILD_BYTES: u32 = 0x5566_7788;

        // Test-only view injection is required because MemorySystem currently
        // allocates virtual addresses from one global cursor. Both process
        // slices below still execute real guest MIPS on their own native CPU.
        let mut kernel = phase1_kernel("same-va-parent.exe")?;
        let parent_state = kernel.current_process_state();
        let parent_birth = kernel.current_process_birth_key().expect("parent birth");
        let parent_mapping =
            kernel
                .handles
                .create_file_mapping(Some("same-va-parent".to_owned()), 4, 4, None);
        let child_mapping =
            kernel
                .handles
                .create_file_mapping(Some("same-va-child".to_owned()), 4, 4, None);
        assert_ne!(parent_mapping, child_mapping);
        let launch =
            kernel.queue_process_launch(Some("\\Test\\same-va-child.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let child_birth = kernel
            .handles
            .process_birth_key(launch.process_id)
            .expect("queued child birth");
        assert_ne!(parent_birth, child_birth);
        for (handle, process_id, initial) in [
            (parent_mapping, 1, PARENT_BYTES),
            (child_mapping, launch.process_id, CHILD_BYTES),
        ] {
            let mapping = kernel.handles.file_mapping_mut(handle)?;
            mapping.legacy_data_mut().unwrap()[..4].copy_from_slice(&initial.to_le_bytes());
            mapping.views.push(crate::ce::object::FileMappingView {
                base: PHASE1_COUNTER_ADDRESS,
                size: 4,
                offset: 0,
                process_id,
                process_birth: None,
            });
        }

        let make_reader_writer = |name: &str| -> crate::Result<super::UnicornMips> {
            let mut bytes = tiny_mips_spinner_pe();
            write_vec_u32(&mut bytes, 0x178 + 8, 0x200);
            let words = [
                0x3c08_0000 | (PHASE1_COUNTER_ADDRESS >> 16), // lui t0,view_hi
                0x3508_0000 | (PHASE1_COUNTER_ADDRESS & 0xffff), // ori t0,t0,view_lo
                0x8d09_0000,                                  // lw t1,0(t0)
                0x2529_0001,                                  // addiu t1,t1,1
                0xad09_0000,                                  // sw t1,0(t0)
                0x8d09_0000, // parent resume: read its own canonical bytes
                0x2529_0001, // increment again after the child has run
                0xad09_0000, // write only the parent's mapping
                0x1000_ffff, // terminal spinner, not reached by these runs
                0,
            ];
            for (index, word) in words.into_iter().enumerate() {
                write_vec_u32(&mut bytes, 0x200 + index * 4, word);
            }
            let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
            let mut cpu = super::UnicornMips::new()?;
            cpu.load_pe_image(&image)?;
            cpu.map_region(
                PHASE1_COUNTER_ADDRESS,
                0x1000,
                MemoryPerms::READ | MemoryPerms::WRITE,
                "phase1-file-view",
            )?;
            cpu.native_engine = super::ProcessNativeEngine::with_lifetime(
                Arch::MIPS,
                Mode::MIPS32 | Mode::LITTLE_ENDIAN,
                crate::emulator::native_engine::NativeEngineLifetime::FreshPerSlice,
            );
            Ok(cpu)
        };
        let mut parent = make_reader_writer("same-va-parent.exe")?;
        let mut child = make_reader_writer("same-va-child.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let limits = super::UnicornRunLimits {
            instruction_limit: 5,
            wall_clock_limit_ms: 500,
            stop_pc: None,
            live_pump: false,
        };

        let a_first = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        a_first.result?;
        assert_eq!(a_first.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_first.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            parent.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        assert!(parent.native_engine_identity_for_test().is_none());
        let parent_seen = parent
            .saved_context
            .as_ref()
            .expect("parent's real native slice saved MIPS registers")
            .regs
            .regs[9];
        let parent_data_after_parent = u32::from_le_bytes(
            kernel
                .handles
                .file_mapping(parent_mapping)?
                .legacy_data()
                .unwrap()[..4]
                .try_into()
                .unwrap(),
        );
        let child_data_after_parent = u32::from_le_bytes(
            kernel
                .handles
                .file_mapping(child_mapping)?
                .legacy_data()
                .unwrap()[..4]
                .try_into()
                .unwrap(),
        );

        kernel.set_current_process_state(crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        });
        kernel.set_process_module_path("\\Test\\same-va-child.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("same-va-child.exe"));
        let b = child.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        b.result?;
        assert_eq!(b.report.start_process_birth(), Some(child_birth));
        assert_eq!(b.report.end_process_birth(), Some(child_birth));
        assert_eq!(
            child.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        assert!(child.native_engine_identity_for_test().is_none());
        let child_seen = child
            .saved_context
            .as_ref()
            .expect("child's real native slice saved MIPS registers")
            .regs
            .regs[9];
        let parent_data_after_child = u32::from_le_bytes(
            kernel
                .handles
                .file_mapping(parent_mapping)?
                .legacy_data()
                .unwrap()[..4]
                .try_into()
                .unwrap(),
        );
        let child_data_after_child = u32::from_le_bytes(
            kernel
                .handles
                .file_mapping(child_mapping)?
                .legacy_data()
                .unwrap()[..4]
                .try_into()
                .unwrap(),
        );

        let observed = (
            parent_seen,
            parent_data_after_parent,
            child_data_after_parent,
            child_seen,
            parent_data_after_child,
            child_data_after_child,
        );
        let expected = (
            PARENT_BYTES + 1,
            PARENT_BYTES + 1,
            CHILD_BYTES,
            CHILD_BYTES + 1,
            PARENT_BYTES + 1,
            CHILD_BYTES + 1,
        );
        assert_eq!(
            observed, expected,
            "each actual native PID slice must read and write only its own mapping at the same guest VA"
        );

        kernel.set_current_process_state(parent_state);
        kernel.set_process_module_path("\\Test\\same-va-parent.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("same-va-parent.exe"));
        let a_second = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 3,
                ..limits
            },
        );
        a_second.result?;
        assert_eq!(a_second.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_second.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            parent.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        assert!(parent.native_engine_identity_for_test().is_none());
        assert_eq!(kernel.current_process_id(), parent_state.process_id);
        assert_eq!(
            parent
                .saved_context
                .as_ref()
                .expect("parent resumed")
                .regs
                .regs[9],
            PARENT_BYTES + 2,
            "the resumed parent must read its own bytes from a new native owner"
        );
        assert_eq!(
            &kernel
                .handles
                .file_mapping(parent_mapping)?
                .legacy_data()
                .unwrap()[..4],
            &(PARENT_BYTES + 2).to_le_bytes(),
            "A's second guest store must reach only A's canonical mapping"
        );
        assert_eq!(
            &kernel
                .handles
                .file_mapping(child_mapping)?
                .legacy_data()
                .unwrap()[..4],
            &(CHILD_BYTES + 1).to_le_bytes(),
            "A's resumed native readback must not overwrite B's mapping"
        );
        Ok(())
    }

    #[test]
    fn native_file_view_closed_handle_readback_uses_exact_mapping() -> crate::Result<()> {
        const BASE: u32 = 0x3018_0000;
        let mut kernel = phase1_kernel("closed-view-owner.exe")?;
        let other = kernel
            .handles
            .create_file_mapping(Some("other-view".to_owned()), 4, 4, None);
        let closed = kernel
            .handles
            .create_file_mapping(Some("closed-view".to_owned()), 4, 4, None);
        for (handle, process_id, initial) in [(other, 1, 0x1122_3344u32), (closed, 2, 0)] {
            let mapping = kernel.handles.file_mapping_mut(handle)?;
            mapping.legacy_data_mut().unwrap()[..4].copy_from_slice(&initial.to_le_bytes());
            mapping.views.push(crate::ce::object::FileMappingView {
                base: BASE,
                size: 4,
                offset: 0,
                process_id,
                process_birth: None,
            });
        }
        assert!(
            kernel
                .handles
                .close_file_mapping_handle_with_live_views(closed)?
        );
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(u64::from(BASE), 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(BASE), &0xaabb_ccddu32.to_le_bytes())
            .unwrap();

        super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, 2)?;
        assert_eq!(
            &kernel.handles.file_mapping(other)?.legacy_data().unwrap()[..4],
            &0x1122_3344u32.to_le_bytes()
        );
        let crate::ce::object::KernelObject::FileMapping(mapping) = kernel.handles.get(closed)?
        else {
            panic!("closed live-view object changed type");
        };
        assert!(mapping.closed);
        assert_eq!(
            &mapping.legacy_data().unwrap()[..4],
            &0xaabb_ccddu32.to_le_bytes()
        );
        Ok(())
    }

    #[test]
    fn native_file_view_fresh_owner_reads_only_mapped_pages() -> crate::Result<()> {
        const SIZE: usize = 0x2000;
        let mut kernel = phase1_kernel("fresh-lazy-view.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let base = kernel
            .memory
            .virtual_alloc(
                owner,
                crate::ce::memory::VirtualAllocationSource::FileViewLegacy,
                0,
                SIZE as u32,
                0x3000,
                0x04,
            )
            .expect("lazy file-view reservation");
        let mut canonical = vec![0x5a; SIZE];
        canonical[0x1000..0x1004].copy_from_slice(&0x1122_3344u32.to_le_bytes());
        assert!(
            kernel
                .memory
                .set_virtual_initial_bytes(owner, base, canonical.clone())
        );
        let handle = kernel
            .handles
            .create_file_mapping(None, SIZE as u32, 4, None);
        let mapping = kernel.handles.file_mapping_mut(handle)?;
        mapping
            .legacy_data_mut()
            .unwrap()
            .copy_from_slice(&canonical);
        mapping.views.push(crate::ce::object::FileMappingView {
            base,
            size: SIZE as u32,
            offset: 0,
            process_id: owner.process_id(),
            process_birth: None,
        });

        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        // A fresh owner may finish a slice without touching this view at all.
        // Its canonical seed must survive rather than causing READ_UNMAPPED.
        super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, owner.process_id())?;
        assert_eq!(
            kernel.handles.file_mapping(handle)?.legacy_data().unwrap(),
            canonical
        );
        assert_eq!(
            kernel
                .memory
                .virtual_allocation_by_base_legacy(base)
                .expect("lazy view")
                .initial_bytes,
            canonical
        );

        // The next owner maps only the first page. Read back the guest's
        // write there without zeroing or touching the unmapped second page.
        uc.mem_map(u64::from(base), 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(base), &canonical[..0x1000]).unwrap();
        uc.mem_write(u64::from(base), &0xaabb_ccddu32.to_le_bytes())
            .unwrap();
        assert!(uc.mem_read(u64::from(base) + 0x1000, &mut [0; 4]).is_err());
        super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, owner.process_id())?;
        let mut expected = canonical;
        expected[..4].copy_from_slice(&0xaabb_ccddu32.to_le_bytes());
        assert_eq!(
            kernel.handles.file_mapping(handle)?.legacy_data().unwrap(),
            expected
        );
        assert_eq!(
            kernel
                .memory
                .virtual_allocation_by_base_legacy(base)
                .expect("refreshed lazy view")
                .initial_bytes,
            expected
        );
        Ok(())
    }

