    #[test]
    fn native_file_view_partial_private_slab_overlap_is_rejected_before_sync() -> crate::Result<()>
    {
        let mut kernel = phase1_kernel("slab-view-overlap.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        kernel
            .memory
            .private_page_pin(owner, base)
            .expect("canonical private page")
            .write_bytes(0, &[1, 2, 3, 4])
            .expect("seed canonical private bytes");
        let handle = kernel.handles.create_file_mapping(None, 4, 4, None);
        let mapping = kernel.handles.file_mapping_mut(handle)?;
        mapping.legacy_data_mut().unwrap()[..4].copy_from_slice(&[5, 6, 7, 8]);
        mapping.views.push(crate::ce::object::FileMappingView {
            base: base + 2,
            size: 4,
            offset: 0,
            process_id: owner.process_id(),
            process_birth: None,
        });
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(u64::from(base), 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(base), &[9, 10, 11, 12]).unwrap();

        let to_err =
            super::sync_file_mapping_views_to_unicorn(&mut uc, &kernel, owner.process_id())
                .unwrap_err();
        assert!(format!("{to_err:?}").contains("overlaps private slab reservation"));
        let from_err =
            super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, owner.process_id())
                .unwrap_err();
        assert!(format!("{from_err:?}").contains("overlaps private slab reservation"));

        let mut native = [0; 4];
        uc.mem_read(u64::from(base), &mut native).unwrap();
        assert_eq!(native, [9, 10, 11, 12]);
        assert_eq!(
            &kernel.handles.file_mapping(handle)?.legacy_data().unwrap()[..4],
            &[5, 6, 7, 8]
        );
        let mut canonical = [0; 4];
        kernel
            .memory
            .private_page_pin(owner, base)
            .expect("stable page")
            .read_bytes(0, &mut canonical)
            .expect("canonical read");
        assert_eq!(canonical, [1, 2, 3, 4]);

        // Outgoing readback refreshes lazy seeds for *every* process by VA.
        // A foreign-PID view must therefore be rejected even though the
        // native readback itself is restricted to the active owner.
        let foreign_view = &mut kernel.handles.file_mapping_mut(handle)?.views[0];
        foreign_view.process_id = owner.process_id().wrapping_add(1);
        foreign_view.base = base;
        let to_err =
            super::sync_file_mapping_views_to_unicorn(&mut uc, &kernel, owner.process_id())
                .unwrap_err();
        assert!(format!("{to_err:?}").contains("overlaps private slab reservation"));
        let from_err =
            super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, owner.process_id())
                .unwrap_err();
        assert!(format!("{from_err:?}").contains("overlaps private slab reservation"));
        assert_eq!(
            &kernel.handles.file_mapping(handle)?.legacy_data().unwrap()[..4],
            &[5, 6, 7, 8]
        );
        kernel
            .memory
            .private_page_pin(owner, base)
            .expect("stable page")
            .read_bytes(0, &mut canonical)
            .expect("canonical read");
        assert_eq!(canonical, [1, 2, 3, 4]);
        Ok(())
    }

    #[test]
    fn native_file_view_rejects_partial_sealed_image_overlap_in_both_directions()
    -> crate::Result<()> {
        let cpu = sealed_spinner_cpu()?;
        let sealed = cpu
            .mapped_blobs
            .iter()
            .find(|blob| blob.bytes.sealed_pin().is_some())
            .expect("synthetic main image has a sealed run");
        let backing = sealed.bytes.sealed_pin().unwrap();
        let pointer = backing.as_ptr();
        let before = backing.to_vec();
        let view_base = sealed.base - 2;
        let mut kernel = phase1_kernel("sealed-view-overlap.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let handle = kernel.handles.create_file_mapping(None, 4, 4, None);
        let mapping = kernel.handles.file_mapping_mut(handle)?;
        mapping.legacy_data_mut().unwrap()[..4].copy_from_slice(&[5, 6, 7, 8]);
        mapping.views.push(crate::ce::object::FileMappingView {
            base: view_base,
            size: 4,
            offset: 0,
            process_id: owner.process_id(),
            process_birth: None,
        });
        let expected =
            super::expected_sealed_image_runs(&cpu.mapped_blobs, &cpu.memory, Some(owner))?;
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(u64::from(sealed.base - 0x1000), 0x1000, Prot::ALL)
            .unwrap();
        uc.mem_write(u64::from(view_base), &[9, 10]).unwrap();
        let pins = super::NativeMappingPins::default();
        let mut mapped = super::KernelMemoryMappings::new(&cpu.mapped_blobs);
        super::map_sealed_image_runs(&mut uc, &cpu.mapped_blobs, &mut mapped, &expected, &pins)?;
        let guard = super::SealedHostWriteGuard::from_mapped_blobs(&cpu.mapped_blobs)?;

        let to_err = super::sync_file_mapping_views_to_unicorn_guarded(
            &mut uc,
            &kernel,
            owner.process_id(),
            &guard,
        )
        .expect_err("incoming view must reject overlap before native mutation");
        assert!(format!("{to_err}").contains("file view"));
        assert!(format!("{to_err}").contains("overlaps sealed image"));
        let from_err = super::sync_file_mapping_views_from_unicorn_guarded(
            &mut uc,
            &mut kernel,
            owner.process_id(),
            &guard,
        )
        .expect_err("outgoing view must reject overlap before canonical mutation");
        assert!(format!("{from_err}").contains("file view"));
        assert!(format!("{from_err}").contains("overlaps sealed image"));

        assert_eq!(
            uc.mem_read_as_vec(u64::from(view_base), 2).unwrap(),
            vec![9, 10]
        );
        assert_eq!(
            uc.mem_read_as_vec(u64::from(sealed.base), before.len())
                .unwrap(),
            before
        );
        assert_eq!(
            &kernel.handles.file_mapping(handle)?.legacy_data().unwrap()[..4],
            &[5, 6, 7, 8]
        );
        assert_eq!(backing.as_ptr(), pointer);
        assert_eq!(&backing[..], &before);
        drop(uc); // Native owner must die before its raw-pointer pin.
        drop(mapped);
        drop(pins);
        Ok(())
    }

    #[test]
    fn native_file_view_rejects_writable_image_overlap_before_both_sync_directions()
    -> crate::Result<()> {
        const BASE: u32 = 0x6300_0000;
        let mut kernel = phase1_kernel("writable-image-view-overlap.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let identity = crate::ce::memory::WritableImageRunIdentity::new(owner, BASE, 1, BASE)
            .expect("aligned image run");
        let pin = kernel
            .memory
            .commit_prepared_writable_image_run(
                kernel
                    .memory
                    .prepare_writable_image_run(identity, &vec![0x5a; 0x1000])
                    .expect("prepare image run"),
            )
            .expect("publish image run");
        let handle = kernel.handles.create_file_mapping(None, 4, 4, None);
        let mapping = kernel.handles.file_mapping_mut(handle)?;
        mapping.legacy_data_mut().unwrap()[..4].copy_from_slice(&[5, 6, 7, 8]);
        mapping.views.push(crate::ce::object::FileMappingView {
            base: BASE - 2,
            size: 4,
            offset: 0,
            process_id: owner.process_id(),
            process_birth: None,
        });
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(u64::from(BASE - 0x1000), 0x3000, Prot::ALL)
            .unwrap();
        uc.mem_write(u64::from(BASE - 2), &[9, 10, 11, 12]).unwrap();

        // Both a same-PID view and a foreign-PID view are global VA hazards:
        // outgoing sync refreshes every legacy lazy seed, not just this CPU.
        for view_pid in [owner.process_id(), owner.process_id().wrapping_add(1)] {
            kernel.handles.file_mapping_mut(handle)?.views[0].process_id = view_pid;
            let to_err =
                super::sync_file_mapping_views_to_unicorn(&mut uc, &kernel, owner.process_id())
                    .expect_err("incoming overlap must fail before native mutation");
            assert!(format!("{to_err}").contains("overlaps writable image run"));
            let from_err = super::sync_file_mapping_views_from_unicorn(
                &mut uc,
                &mut kernel,
                owner.process_id(),
            )
            .expect_err("outgoing overlap must fail before file mutation");
            assert!(format!("{from_err}").contains("overlaps writable image run"));
            assert_eq!(
                uc.mem_read_as_vec(u64::from(BASE - 2), 4).unwrap(),
                vec![9, 10, 11, 12]
            );
            assert_eq!(
                &kernel.handles.file_mapping(handle)?.legacy_data().unwrap()[..4],
                &[5, 6, 7, 8]
            );
            let mut canonical = [0; 4];
            pin.read_bytes(0, &mut canonical)
                .expect("canonical image bytes");
            assert_eq!(canonical, [0x5a; 4]);
        }

        // Removing the VM directory entry does not release a pinned native
        // backing; it remains a conflicting range until checked close.
        assert_eq!(
            kernel.memory.retire_writable_image_module(owner, BASE, 1),
            Some(1)
        );
        let retired_err =
            super::sync_file_mapping_views_to_unicorn(&mut uc, &kernel, owner.process_id())
                .expect_err("retired pinned overlap must remain fenced");
        assert!(format!("{retired_err}").contains("overlaps writable image run"));

        // Exact end adjacency is not overlap. The ordinary legacy file-view
        // copy/readback path must still work outside the image range.
        let view = &mut kernel.handles.file_mapping_mut(handle)?.views[0];
        view.base = BASE + 0x1000;
        view.process_id = owner.process_id();
        super::sync_file_mapping_views_to_unicorn(&mut uc, &kernel, owner.process_id())?;
        assert_eq!(
            uc.mem_read_as_vec(u64::from(BASE + 0x1000), 4).unwrap(),
            vec![5, 6, 7, 8]
        );
        uc.mem_write(u64::from(BASE + 0x1000), &[1, 2, 3, 4])
            .unwrap();
        super::sync_file_mapping_views_from_unicorn(&mut uc, &mut kernel, owner.process_id())?;
        assert_eq!(
            &kernel.handles.file_mapping(handle)?.legacy_data().unwrap()[..4],
            &[1, 2, 3, 4]
        );
        let mut canonical = [0; 4];
        pin.read_bytes(0, &mut canonical)
            .expect("retired pinned image bytes");
        assert_eq!(canonical, [0x5a; 4]);
        Ok(())
    }

    #[test]
    fn native_private_slab_mapper_rejects_unowned_ram_before_pin_or_ffi() -> crate::Result<()> {
        let mut kernel = phase1_kernel("slab-collision.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let pin = kernel
            .memory
            .private_page_pin(owner, base)
            .expect("stable page");
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let same_perms = super::unicorn_perms(super::virtual_allocation_perms(0x04));
        uc.mem_map(u64::from(base), 0x1000, same_perms).unwrap();
        uc.mem_write(u64::from(base), &[0xa1, 0xb2, 0xc3, 0xd4])
            .unwrap();
        let mut mapped = super::KernelMemoryMappings::new(&[]);
        let native_pins = super::NativeMappingPins::default();

        let err = super::map_private_slab_page(
            &mut uc,
            &kernel,
            &mut mapped,
            owner,
            pin,
            &native_pins,
            None,
        )
        .unwrap_err();
        assert!(format!("{err:?}").contains("collides with an unowned native mapping"));
        assert_eq!(
            native_pins.len(),
            0,
            "collision rejected before raw pointer pin"
        );
        assert!(mapped.private_pages.is_empty());
        assert_eq!(
            super::native_page_perms(&uc, base)?,
            Some(same_perms.0 as u32)
        );
        let mut native = [0; 4];
        uc.mem_read(u64::from(base), &mut native).unwrap();
        assert_eq!(native, [0xa1, 0xb2, 0xc3, 0xd4]);
        Ok(())
    }

    #[test]
    fn native_private_slab_mapper_rejects_cloned_and_released_pins_before_ffi() -> crate::Result<()>
    {
        use crate::ce::memory::MEM_RELEASE;

        let mut kernel = phase1_kernel("slab-stale-pin.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let source_pin = kernel
            .memory
            .private_page_pin(owner, base)
            .expect("source pin");
        let cloned_pin = kernel
            .memory
            .clone()
            .private_page_pin(owner, base)
            .expect("deep-cloned pin");
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let mut mapped = super::KernelMemoryMappings::new(&[]);
        let native_pins = super::NativeMappingPins::default();

        for stale_pin in [cloned_pin, source_pin.clone()] {
            if stale_pin.native_ptr() == source_pin.native_ptr() {
                let release = kernel
                    .memory
                    .prepare_private_vm_free(owner, base, 0, MEM_RELEASE)
                    .expect("prepare release before native mapping");
                assert_eq!(
                    kernel.memory.commit_prepared_private_vm_change(release),
                    Some(crate::ce::memory::PrivateVmChangeResult::Free)
                );
            }
            let err = super::map_private_slab_page(
                &mut uc,
                &kernel,
                &mut mapped,
                owner,
                stale_pin,
                &native_pins,
                None,
            )
            .unwrap_err();
            assert!(format!("{err:?}").contains("stale or unaligned private slab page"));
            assert_eq!(native_pins.len(), 0, "stale pin rejected before FFI");
            assert!(mapped.private_pages.is_empty());
            assert_eq!(super::native_page_perms(&uc, base)?, None);
        }
        Ok(())
    }

    #[test]
    fn native_private_vm_sixty_four_checked_unmaps_reclaim_pins_and_budget() -> crate::Result<()> {
        use crate::ce::coredll::CoredllGuestMemory;
        use crate::ce::memory::{MEM_COMMIT, MEM_RELEASE, MEM_RESERVE, VirtualAllocationSource};

        const BASE: u32 = 0x5b00_0000;
        const PAGE_BYTES: u64 = 0x1000;
        let mut kernel = phase1_kernel("private-checked-churn.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        kernel.memory.set_private_commit_limit_bytes(PAGE_BYTES);
        let native_pins = super::NativeMappingPins::default();
        let guards = RefCell::new(BTreeMap::new());
        let terminal_error = RefCell::new(None);
        let mut blobs: Vec<MappedBlob> = Vec::new();
        let mut native_ledger = super::KernelMemoryMappings::new(&blobs);
        native_ledger.heap_generation = kernel.memory.heap_generation();
        native_ledger.virtual_generation = kernel.memory.virtual_generation();
        let mapped = RefCell::new(native_ledger);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();

        for cycle in 0..64 {
            let proposal = kernel
                .memory
                .prepare_private_vm(
                    owner,
                    VirtualAllocationSource::Private,
                    BASE,
                    0x1000,
                    MEM_RESERVE | MEM_COMMIT,
                    0x04,
                )
                .expect("prepare fixed private page within one-page budget");
            {
                // SAFETY: blobs belongs to this live, sequential adapter and
                // the ledger records this exact native owner for the test.
                let mut guest = unsafe {
                    super::UnicornGuestMemory::with_heap_mapping(
                        &mut uc,
                        &mapped,
                        &mut blobs as *mut _,
                    )
                }
                .with_private_vm_mapping(super::UnicornPrivateVmMapping {
                    mapped: &mapped,
                    owner,
                    native_pins: &native_pins,
                    active_guards: &guards,
                    terminal_error: &terminal_error,
                });
                guest.apply_prepared_private_vm(&kernel, &proposal)?;
                assert_eq!(
                    native_pins.private_len(),
                    1,
                    "cycle {cycle}: exactly the live page must be pinned"
                );
                assert_eq!(
                    kernel.memory.commit_prepared_private_vm(proposal),
                    Some(BASE)
                );
                guest.private_vm_commit_complete(kernel.memory.virtual_generation());
            }
            assert_eq!(kernel.memory.private_commit_used_bytes(), PAGE_BYTES);
            assert_eq!(
                super::native_page_perms(&uc, BASE)?,
                Some(super::unicorn_perms(super::virtual_allocation_perms(0x04)).0 as u32)
            );
            let release = kernel
                .memory
                .prepare_private_vm_free(owner, BASE, 0, MEM_RELEASE)
                .expect("prepare checked native unmap");
            {
                // SAFETY: same live owner and ledger as the allocation above.
                let mut guest = unsafe {
                    super::UnicornGuestMemory::with_heap_mapping(
                        &mut uc,
                        &mapped,
                        &mut blobs as *mut _,
                    )
                }
                .with_private_vm_mapping(super::UnicornPrivateVmMapping {
                    mapped: &mapped,
                    owner,
                    native_pins: &native_pins,
                    active_guards: &guards,
                    terminal_error: &terminal_error,
                });
                guest.apply_prepared_private_vm_change(&kernel, &release)?;
                assert_eq!(
                    kernel.memory.commit_prepared_private_vm_change(release),
                    Some(crate::ce::memory::PrivateVmChangeResult::Free)
                );
                guest.private_vm_commit_complete(kernel.memory.virtual_generation());
            }
            assert_eq!(native_pins.private_len(), 0, "cycle {cycle}: stale pin");
            assert!(mapped.borrow().private_pages.is_empty());
            assert!(guards.borrow().is_empty());
            assert_eq!(super::native_page_perms(&uc, BASE)?, None);
            assert_eq!(
                kernel.memory.private_commit_used_bytes(),
                0,
                "cycle {cycle}: checked unmap must return the page budget"
            );
            assert!(terminal_error.borrow().is_none());
        }
        Ok(())
    }

    #[test]
    fn native_private_vm_injected_unmap_failure_retains_pin_and_budget() -> crate::Result<()> {
        use crate::ce::coredll::CoredllGuestMemory;
        use crate::ce::memory::{MEM_COMMIT, MEM_RELEASE, MEM_RESERVE, VirtualAllocationSource};

        const BASE: u32 = 0x5b10_0000;
        let mut kernel = phase1_kernel("private-unmap-reject.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        kernel.memory.set_private_commit_limit_bytes(0x1000);
        let native_pins = super::NativeMappingPins::default();
        let guards = RefCell::new(BTreeMap::new());
        let terminal_error = RefCell::new(None);
        let mut blobs: Vec<MappedBlob> = Vec::new();
        let mut native_ledger = super::KernelMemoryMappings::new(&blobs);
        native_ledger.heap_generation = kernel.memory.heap_generation();
        native_ledger.virtual_generation = kernel.memory.virtual_generation();
        let mapped = RefCell::new(native_ledger);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let proposal = kernel
            .memory
            .prepare_private_vm(
                owner,
                VirtualAllocationSource::Private,
                BASE,
                0x1000,
                MEM_RESERVE | MEM_COMMIT,
                0x04,
            )
            .expect("prepare private page");
        {
            // SAFETY: the blob pointer and ledger outlive this synchronous adapter.
            let mut guest = unsafe {
                super::UnicornGuestMemory::with_heap_mapping(&mut uc, &mapped, &mut blobs as *mut _)
            }
            .with_private_vm_mapping(super::UnicornPrivateVmMapping {
                mapped: &mapped,
                owner,
                native_pins: &native_pins,
                active_guards: &guards,
                terminal_error: &terminal_error,
            });
            guest.apply_prepared_private_vm(&kernel, &proposal)?;
            assert_eq!(
                kernel.memory.commit_prepared_private_vm(proposal),
                Some(BASE)
            );
            guest.private_vm_commit_complete(kernel.memory.virtual_generation());
        }
        assert_eq!(native_pins.private_len(), 1);
        assert_eq!(kernel.memory.private_commit_used_bytes(), 0x1000);

        // The test seam fires after the native owner/permission preflight and
        // before checked uc_mem_unmap can take effect. Failure must keep the
        // page pinned, committed, and charged to the same owner.
        let release = kernel
            .memory
            .prepare_private_vm_free(owner, BASE, 0, MEM_RELEASE)
            .expect("prepare release of live private page");
        {
            // SAFETY: same live blob pointer and native owner as above.
            let mut guest = unsafe {
                super::UnicornGuestMemory::with_heap_mapping(&mut uc, &mapped, &mut blobs as *mut _)
            }
            .with_private_vm_mapping(super::UnicornPrivateVmMapping {
                mapped: &mapped,
                owner,
                native_pins: &native_pins,
                active_guards: &guards,
                terminal_error: &terminal_error,
            });
            guest.fail_next_private_unmap_for_test = true;
            let error = guest
                .apply_prepared_private_vm_change(&kernel, &release)
                .expect_err("injected native unmap failure must prevent release");
            assert!(format!("{error:#}").contains("injected checked private VM unmap failure"));
        }
        drop(release);
        assert!(kernel.memory.private_page_pin(owner, BASE).is_some());
        assert_eq!(native_pins.private_len(), 1, "failed unmap retains the pin");
        assert_eq!(kernel.memory.private_commit_used_bytes(), 0x1000);
        assert_eq!(
            super::native_page_perms(&uc, BASE)?,
            Some(super::unicorn_perms(super::virtual_allocation_perms(0x04)).0 as u32),
            "the native owner still maps the failed-unmap page"
        );
        assert!(
            kernel
                .memory
                .prepare_private_vm(
                    owner,
                    VirtualAllocationSource::Private,
                    BASE + 0x1_0000,
                    0x1000,
                    MEM_RESERVE | MEM_COMMIT,
                    0x04,
                )
                .is_none(),
            "retained private page still exhausts the one-page budget"
        );

        // The one-shot fault has cleared; a later checked unmap must reclaim
        // both resources rather than leaving this fixture dirty.
        let retry = kernel
            .memory
            .prepare_private_vm_free(owner, BASE, 0, MEM_RELEASE)
            .expect("retry release after one-shot unmap failure");
        {
            // SAFETY: same synchronous owner and blob pointer as above.
            let mut guest = unsafe {
                super::UnicornGuestMemory::with_heap_mapping(&mut uc, &mapped, &mut blobs as *mut _)
            }
            .with_private_vm_mapping(super::UnicornPrivateVmMapping {
                mapped: &mapped,
                owner,
                native_pins: &native_pins,
                active_guards: &guards,
                terminal_error: &terminal_error,
            });
            guest.apply_prepared_private_vm_change(&kernel, &retry)?;
            assert_eq!(
                kernel.memory.commit_prepared_private_vm_change(retry),
                Some(crate::ce::memory::PrivateVmChangeResult::Free)
            );
            guest.private_vm_commit_complete(kernel.memory.virtual_generation());
        }
        assert_eq!(native_pins.private_len(), 0);
        assert_eq!(kernel.memory.private_commit_used_bytes(), 0);
        assert_eq!(super::native_page_perms(&uc, BASE)?, None);
        assert!(terminal_error.borrow().is_none());
        Ok(())
    }

    #[test]
    // E18's seeded read/modify/write now enters through the real public
    // VirtualAlloc ordinal, rather than a test-only backing selector.
    fn native_private_virtual_write_survives_closed_owner_next_slice() -> crate::Result<()> {
        use crate::ce::memory::{MEM_COMMIT, MEM_RESERVE};

        const INITIAL: u32 = 0x1122_3344;
        const PAGE_READWRITE: u32 = 0x04;

        let mut kernel = phase1_kernel("private-virtual-fresh.exe")?;
        let boot_owner = kernel.current_process_birth_key().expect("boot birth");
        let trap = crate::emulator::imports::IMPORT_TRAP_BASE;
        let mut bytes = tiny_mips_spinner_pe();
        write_vec_u32(&mut bytes, 0x178 + 8, 0x200);
        let words = [
            0x3c19_0000 | (trap >> 16),    // lui t9,VirtualAlloc trap high
            0x3739_0000 | (trap & 0xffff), // ori t9,t9,trap low
            0x0320_f809,                   // jalr t9: public VirtualAlloc import
            0,                             // delay-slot nop
            0x8c49_0000,                   // lw t1,0(v0): canonical seed
            0x2529_0001,                   // addiu t1,t1,1
            0xac49_0000,                   // sw t1,0(v0)
            0x8c4a_0000,                   // lw t2,0(v0) after fresh owner
            0x1000_ffff,                   // bounded safety spinner
            0,
        ];
        for (index, word) in words.into_iter().enumerate() {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("private-virtual-fresh.exe", &bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        let entry = cpu.entry.expect("fixture PE entry");
        cpu.import_traps
            .insert(crate::emulator::imports::ImportTrap {
                address: trap,
                module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(crate::ce::coredll_ordinals::ORD_VIRTUAL_ALLOC),
                name: Some("VirtualAlloc".to_owned()),
                iat_va: 0,
            });
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[4] = 0; // lpAddress
        regs.regs[5] = 0x1000; // dwSize
        regs.regs[6] = MEM_COMMIT | MEM_RESERVE; // flAllocationType
        regs.regs[7] = PAGE_READWRITE; // flProtect
        regs.regs[29] = cpu.stack_top.expect("guest stack") - 0x100;
        cpu.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((cpu.current_thread_id, u32::MAX));
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let run = |instruction_limit| super::UnicornRunLimits {
            instruction_limit,
            wall_clock_limit_ms: 500,
            stop_pc: None,
            live_pump: false,
        };

        // Let the import finish, then seed its published canonical page while
        // the native execution fence is down. No test-only allocation or
        // reseed hook participates in this path.
        cpu.run_until_import_trap_with_framebuffer_limits(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                stop_pc: Some(entry + 0x10),
                ..run(64)
            },
        )?;
        let imported = cpu
            .saved_context
            .as_ref()
            .expect("public import continuation");
        assert_eq!(imported.pc, entry + 0x10);
        let private_base = imported.regs.regs[2];
        assert_ne!(private_base, 0, "public VirtualAlloc returned a page");
        let private_pin = kernel
            .memory
            .private_page_pin(boot_owner, private_base)
            .expect("public import published a canonical private page");
        private_pin
            .write_bytes(0, &INITIAL.to_le_bytes())
            .expect("seed public canonical private page");

        cpu.run_until_import_trap_with_framebuffer_limits(&mut kernel, &mut framebuffer, run(3))?;
        let first = cpu
            .saved_context
            .as_ref()
            .expect("first native slice saved a continuation");
        assert_eq!(first.pc, entry + 7 * 4, "the guest store completed");
        assert_eq!(first.regs.regs[9], INITIAL + 1);
        let first_written = first.regs.regs[9];
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit,
            "first slice must have the count witness, not a native deadline"
        );
        assert!(
            cpu.last_debug_snapshot()
                .is_some_and(|snapshot| snapshot.memory_fault.is_none())
        );
        let mut canonical = [0; 4];
        private_pin
            .read_bytes(0, &mut canonical)
            .expect("read canonical slab");
        assert_eq!(
            canonical,
            (INITIAL + 1).to_le_bytes(),
            "first guest store must reach canonical private bytes before owner closure"
        );
        // The completed slice closed its owner; the next lease must rebuild
        // native mappings from the canonical private page.
        assert!(cpu.native_engine_identity_for_test().is_none());

        cpu.run_until_import_trap_with_framebuffer_limits(&mut kernel, &mut framebuffer, run(1))?;
        let second = cpu
            .saved_context
            .as_ref()
            .expect("fresh native slice saved a continuation");
        assert_eq!(second.pc, entry + 8 * 4, "the second guest load completed");
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit,
            "second slice must have the count witness, not a native deadline"
        );
        assert!(
            cpu.last_debug_snapshot()
                .is_some_and(|snapshot| snapshot.memory_fault.is_none())
        );
        eprintln!(
            "fresh_private_virtual_bytes first_written=0x{:08x} second_read=0x{:08x} initial=0x{:08x}",
            first_written, second.regs.regs[10], INITIAL
        );
        assert_eq!(
            second.regs.regs[10],
            INITIAL + 1,
            "guest-written private VirtualAlloc bytes must survive native owner closure"
        );
        Ok(())
    }

    /// Public-ordinal counterpart to the E25 internal slab diagnostic. This
    /// remains expected red while ordinary VirtualAlloc selects LegacySeed:
    /// the guest store can reach native RAM, but not canonical private bytes.
    /// Keep this control non-ignored so the public backing switch and its
    /// fresh-owner proof land together.
    #[test]
    fn public_virtual_alloc_ordinal_store_survives_fresh_native_owner() -> crate::Result<()> {
        use crate::ce::memory::{MEM_COMMIT, MEM_RESERVE, VirtualAllocationSource};

        const WRITTEN: u32 = 0x1122_3345;
        const PAGE_READWRITE: u32 = 0x04;
        let trap = crate::emulator::imports::IMPORT_TRAP_BASE;
        let mut bytes = tiny_mips_spinner_pe();
        let words = [
            0x3c19_0000 | (trap >> 16),    // lui t9,VirtualAlloc trap high
            0x3739_0000 | (trap & 0xffff), // ori t9,t9,trap low
            0x0320_f809,                   // jalr t9: real guest public import
            0,                             // delay-slot nop
            0x3c09_1122,                   // lui t1,0x1122
            0x3529_3345,                   // ori t1,t1,0x3345
            0xac49_0000,                   // sw t1,0(v0): returned allocation
            0x8c4a_0000,                   // lw t2,0(v0): fresh owner only
            0x1000_ffff,                   // bounded safety spinner
            0,
        ];
        for (index, word) in words.into_iter().enumerate() {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("public-virtual-fresh.exe", &bytes)?;
        let mut kernel = phase1_kernel("public-virtual-fresh.exe")?;
        let boot_pid = kernel.current_process_id();
        let boot_birth = kernel.current_process_birth_key().expect("boot birth");
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        let entry = cpu.entry.expect("fixture PE entry");
        cpu.import_traps
            .insert(crate::emulator::imports::ImportTrap {
                address: trap,
                module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(crate::ce::coredll_ordinals::ORD_VIRTUAL_ALLOC),
                name: Some("VirtualAlloc".to_owned()),
                iat_va: 0,
            });
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let thread_id = cpu.current_thread_id;
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[4] = 0; // lpAddress
        regs.regs[5] = 0x1000; // dwSize
        regs.regs[6] = MEM_COMMIT | MEM_RESERVE; // flAllocationType
        regs.regs[7] = PAGE_READWRITE; // flProtect
        regs.regs[29] = cpu.stack_top.expect("guest stack") - 0x100;
        cpu.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((thread_id, u32::MAX));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let run_to = |stop_pc| super::UnicornRunLimits {
            instruction_limit: 64,
            wall_clock_limit_ms: 500,
            stop_pc: Some(stop_pc),
            live_pump: false,
        };

        let first = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(entry + 0x1c),
        );
        first.result?;
        assert_eq!(first.report.start_process_id(), Some(boot_pid));
        assert_eq!(first.report.end_process_id(), Some(boot_pid));
        assert_eq!(first.report.start_process_birth(), Some(boot_birth));
        assert_eq!(first.report.end_process_birth(), Some(boot_birth));
        assert_eq!(first.report.start_thread_id(), Some(thread_id));
        assert_eq!(first.report.end_thread_id(), Some(thread_id));
        assert_eq!(
            first.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert_eq!(kernel.current_process_id(), boot_pid);
        let saved = cpu.saved_context.as_ref().expect("post-store continuation");
        assert_eq!(saved.pc, entry + 0x1c, "guest store completed");
        assert_eq!(saved.regs.regs[9], WRITTEN);
        let public_ptr = saved.regs.regs[2];
        assert_ne!(public_ptr, 0, "public VirtualAlloc returned a pointer");
        assert_eq!(
            kernel
                .memory
                .virtual_allocation(boot_birth, public_ptr)
                .expect("public allocation belongs to the exact process birth")
                .source,
            VirtualAllocationSource::Private
        );
        let snapshot = cpu.last_debug_snapshot().expect("first native snapshot");
        assert_eq!(snapshot.pc, entry + 0x1c);
        assert_eq!(
            snapshot.pc_stop.as_ref().map(|stop| stop.pc),
            Some(entry + 0x1c)
        );
        assert!(
            snapshot.memory_fault.is_none(),
            "no unhandled native fault; this does not prove pre-return mapping"
        );
        assert_eq!(
            snapshot
                .import_counts
                .iter()
                .filter(|count| {
                    count.ordinal == Some(crate::ce::coredll_ordinals::ORD_VIRTUAL_ALLOC)
                })
                .map(|count| count.count)
                .sum::<u64>(),
            1,
            "one real public VirtualAlloc import dispatched"
        );

        // This is the intentional legacy red checkpoint. The public call
        // must make the guest-written bytes canonical before any owner close.
        let pin = kernel
            .memory
            .private_page_pin(boot_birth, public_ptr)
            .expect("public VirtualAlloc must publish canonical private backing");
        let mut canonical = [0; 4];
        pin.read_bytes(0, &mut canonical)
            .expect("read canonical public allocation");
        assert_eq!(canonical, WRITTEN.to_le_bytes());

        // The production lease closed its owner after the guest store. The
        // next run must map the same canonical private bytes into a new one.
        assert!(cpu.native_engine_identity_for_test().is_none());
        let second = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(entry + 0x20),
        );
        second.result?;
        assert_eq!(second.report.start_process_id(), Some(boot_pid));
        assert_eq!(second.report.end_process_id(), Some(boot_pid));
        assert_eq!(second.report.start_process_birth(), Some(boot_birth));
        assert_eq!(second.report.end_process_birth(), Some(boot_birth));
        assert_eq!(second.report.start_thread_id(), Some(thread_id));
        assert_eq!(second.report.end_thread_id(), Some(thread_id));
        assert_eq!(
            second.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert_eq!(kernel.current_process_id(), boot_pid);
        let saved = cpu
            .saved_context
            .as_ref()
            .expect("fresh-owner continuation");
        assert_eq!(saved.pc, entry + 0x20, "fresh guest load completed");
        assert_eq!(saved.regs.regs[10], WRITTEN);
        let snapshot = cpu.last_debug_snapshot().expect("fresh native snapshot");
        assert_eq!(snapshot.pc, entry + 0x20);
        assert_eq!(
            snapshot.pc_stop.as_ref().map(|stop| stop.pc),
            Some(entry + 0x20)
        );
        assert!(snapshot.memory_fault.is_none(), "no unhandled native fault");
        Ok(())
    }

    #[test]
    fn public_two_process_same_va_private_bytes_survive_native_a_b_a() -> crate::Result<()> {
        use crate::ce::memory::{MEM_COMMIT, MEM_RESERVE, VirtualAllocationSource};

        const BASE: u32 = 0x5200_0000;
        const PARENT_BYTES: u32 = 0x1122_3344;
        const CHILD_BYTES: u32 = 0x5566_7788;
        const PAGE_READWRITE: u32 = 0x04;

        let mut kernel = phase1_kernel("same-va-private-parent.exe")?;
        let parent_state = kernel.current_process_state();
        let parent_birth = kernel.current_process_birth_key().expect("parent birth");
        let launch =
            kernel.queue_process_launch(Some("\\Test\\same-va-private-child.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let child_state = crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        };
        let child_birth = kernel
            .handles
            .process_birth_key(launch.process_id)
            .expect("queued child birth");
        assert_ne!(parent_birth, child_birth);

        let trap = crate::emulator::imports::IMPORT_TRAP_BASE;
        let make_cpu = |name: &str,
                        thread_id: u32,
                        initial: u32|
         -> crate::Result<(super::UnicornMips, u32)> {
            let mut bytes = tiny_mips_spinner_pe();
            let words = [
                0x3c19_0000 | (trap >> 16),       // lui t9,VirtualAlloc trap high
                0x3739_0000 | (trap & 0xffff),    // ori t9,t9,trap low
                0x0320_f809,                      // jalr t9: public VirtualAlloc
                0,                                // delay-slot nop
                0x0040_4021,                      // addu t0,v0,zero: private VA
                0x3c09_0000 | (initial >> 16),    // lui t1,initial high
                0x3529_0000 | (initial & 0xffff), // ori t1,t1,initial low
                0xad09_0000,                      // sw t1,0(t0)
                0x8d0a_0000,                      // parent resume: lw t2,0(t0)
                0x254a_0001,                      // addiu t2,t2,1
                0xad0a_0000,                      // sw t2,0(t0)
                0x1000_ffff,                      // bounded safety spinner
                0,
            ];
            for (index, word) in words.into_iter().enumerate() {
                write_vec_u32(&mut bytes, 0x200 + index * 4, word);
            }
            let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
            let mut cpu = super::UnicornMips::new()?;
            cpu.load_pe_image(&image)?;
            cpu.native_engine = super::ProcessNativeEngine::with_lifetime(
                Arch::MIPS,
                Mode::MIPS32 | Mode::LITTLE_ENDIAN,
                crate::emulator::native_engine::NativeEngineLifetime::FreshPerSlice,
            );
            cpu.set_initial_thread_id(thread_id);
            cpu.import_traps
                .insert(crate::emulator::imports::ImportTrap {
                    address: trap,
                    module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                    module_name: "COREDLL.dll".to_owned(),
                    ordinal: Some(crate::ce::coredll_ordinals::ORD_VIRTUAL_ALLOC),
                    name: Some("VirtualAlloc".to_owned()),
                    iat_va: 0,
                });
            super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
            let entry = cpu.entry.expect("fixture PE entry");
            let mut regs = super::MipsGuestContext::zero();
            regs.regs[4] = BASE;
            regs.regs[5] = 0x1000;
            regs.regs[6] = MEM_COMMIT | MEM_RESERVE;
            regs.regs[7] = PAGE_READWRITE;
            regs.regs[29] = cpu.stack_top.expect("guest stack") - 0x100;
            cpu.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
            stamp_synthetic_saved_context(&mut cpu, &kernel);
            cpu.running_guest_thread = Some((thread_id, u32::MAX));
            Ok((cpu, entry))
        };
        let (mut parent, parent_entry) = make_cpu("same-va-private-parent.exe", 1, PARENT_BYTES)?;
        let (mut child, child_entry) =
            make_cpu("same-va-private-child.exe", launch.thread_id, CHILD_BYTES)?;
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let run_to = |stop_pc| super::UnicornRunLimits {
            instruction_limit: 64,
            wall_clock_limit_ms: 500,
            stop_pc: Some(stop_pc),
            live_pump: false,
        };

        let a_first = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(parent_entry + 8 * 4),
        );
        a_first.result?;
        assert_eq!(a_first.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_first.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            a_first.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        let a_context = parent.saved_context.as_ref().expect("A after guest store");
        assert_eq!(a_context.pc, parent_entry + 8 * 4);
        assert_eq!(a_context.regs.regs[2], BASE, "A's public allocation");
        assert_eq!(a_context.regs.regs[9], PARENT_BYTES);
        assert!(parent.native_engine_identity_for_test().is_none());
        let a_pin = kernel
            .memory
            .private_page_pin(parent_birth, BASE)
            .expect("A's canonical slab");
        let mut actual = [0; 4];
        a_pin.read_bytes(0, &mut actual).expect("A's written bytes");
        assert_eq!(actual, PARENT_BYTES.to_le_bytes());

        kernel.set_current_process_state(child_state);
        kernel.set_process_module_path("\\Test\\same-va-private-child.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("same-va-private-child.exe"));
        let b = child.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(child_entry + 8 * 4),
        );
        b.result?;
        assert_eq!(b.report.start_process_birth(), Some(child_birth));
        assert_eq!(b.report.end_process_birth(), Some(child_birth));
        assert_eq!(
            b.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        let b_context = child.saved_context.as_ref().expect("B after guest store");
        assert_eq!(b_context.pc, child_entry + 8 * 4);
        assert_eq!(
            b_context.regs.regs[2], BASE,
            "B's public same-VA allocation"
        );
        assert_eq!(b_context.regs.regs[9], CHILD_BYTES);
        assert!(child.native_engine_identity_for_test().is_none());
        let b_pin = kernel
            .memory
            .private_page_pin(child_birth, BASE)
            .expect("B's distinct canonical slab");
        b_pin.read_bytes(0, &mut actual).expect("B's written bytes");
        assert_eq!(actual, CHILD_BYTES.to_le_bytes());
        a_pin.read_bytes(0, &mut actual).expect("A survives B");
        assert_eq!(actual, PARENT_BYTES.to_le_bytes());
        assert_eq!(
            kernel
                .memory
                .virtual_allocation(parent_birth, BASE)
                .expect("A allocation")
                .source,
            VirtualAllocationSource::Private
        );
        assert_eq!(
            kernel
                .memory
                .virtual_allocation(child_birth, BASE)
                .expect("B allocation")
                .source,
            VirtualAllocationSource::Private
        );

        kernel.set_current_process_state(parent_state);
        kernel.set_process_module_path("\\Test\\same-va-private-parent.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("same-va-private-parent.exe"));
        let a_second = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(parent_entry + 11 * 4),
        );
        a_second.result?;
        assert_eq!(a_second.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_second.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            a_second.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        let a_context = parent.saved_context.as_ref().expect("A after resume");
        assert_eq!(a_context.pc, parent_entry + 11 * 4);
        assert_eq!(
            a_context.regs.regs[10],
            PARENT_BYTES + 1,
            "A must reload its own guest bytes after B ran at the same VA"
        );
        assert!(parent.native_engine_identity_for_test().is_none());
        a_pin
            .read_bytes(0, &mut actual)
            .expect("A after second store");
        assert_eq!(actual, (PARENT_BYTES + 1).to_le_bytes());
        b_pin
            .read_bytes(0, &mut actual)
            .expect("B remains isolated");
        assert_eq!(actual, CHILD_BYTES.to_le_bytes());
        Ok(())
    }

    #[test]
    fn public_named_file_view_same_va_aliases_share_one_native_page() -> crate::Result<()> {
        const A_BYTES: u32 = 0x1122_3344;
        const B_BYTES: u32 = 0x5566_7788;
        const ALIAS_BYTES: u32 = 0xaabb_ccdd;
        const NAME_VA: u32 = 0x0040_1180;

        let mut kernel = phase1_kernel("shared-view-parent.exe")?;
        let parent_state = kernel.current_process_state();
        let parent_birth = kernel.current_process_birth_key().expect("parent birth");
        let launch =
            kernel.queue_process_launch(Some("\\Test\\shared-view-child.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let child_state = crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        };
        let child_birth = kernel
            .handles
            .process_birth_key(launch.process_id)
            .expect("queued child birth");
        assert_ne!(parent_birth, child_birth);
        let committed_before = kernel.memory.private_commit_used_bytes();

        let create_trap = crate::emulator::imports::IMPORT_TRAP_BASE;
        let view_trap = create_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let make_cpu = |name: &str,
                        thread_id: u32,
                        initial: u32|
         -> crate::Result<(super::UnicornMips, u32)> {
            let mut bytes = tiny_mips_spinner_pe();
            write_vec_u32(&mut bytes, 0x178 + 8, 0x200); // include the UTF-16 name
            write_vec_u32(&mut bytes, 0x380, 0x0000_0058); // "X\0" at NAME_VA
            let words = [
                0x3c08_0000 | (NAME_VA >> 16),        // lui t0,NAME_VA high
                0x3508_0000 | (NAME_VA & 0xffff),     // ori t0,t0,NAME_VA low
                0x2404_ffff,                          // addiu a0,zero,-1: anonymous section
                0x0000_2821,                          // addu a1,zero,zero: attributes
                0x2406_0004,                          // addiu a2,zero,PAGE_READWRITE
                0x0000_3821,                          // addu a3,zero,zero: size high
                0x2409_1000,                          // addiu t1,zero,4096
                0xafa9_0010,                          // sw t1,16(sp): size low
                0xafa8_0014,                          // sw t0,20(sp): UTF-16 name
                0x3c19_0000 | (create_trap >> 16),    // lui t9,CreateFileMappingW high
                0x3739_0000 | (create_trap & 0xffff), // ori t9,t9,low
                0x0320_f809,                          // jalr t9
                0,                                    // delay slot
                0x0040_8021,                          // addu s0,v0,zero: mapping handle
                0x0200_2021,                          // addu a0,s0,zero
                0x0000_2821,                          // addu a1,zero,zero: access
                0x0000_3021,                          // addu a2,zero,zero: offset high
                0x0000_3821,                          // addu a3,zero,zero: offset low
                0x3c19_0000 | (view_trap >> 16),      // lui t9,MapViewOfFile high
                0x3739_0000 | (view_trap & 0xffff),   // ori t9,t9,low
                0x0320_f809,                          // jalr t9
                0,                                    // delay slot
                0x0040_8821,                          // addu s1,v0,zero: first view
                0x8e2a_0000,                          // lw t2,0(s1): prior owner's bytes
                0x3c09_0000 | (initial >> 16),        // lui t1,initial high
                0x3529_0000 | (initial & 0xffff),     // ori t1,t1,initial low
                0xae29_0000,                          // sw t1,0(s1): canonical page
                0x8e2a_0000,                          // resume: lw t2,0(s1)
                0x0200_2021,                          // addu a0,s0,zero
                0x0000_2821,                          // addu a1,zero,zero
                0x0000_3021,                          // addu a2,zero,zero
                0x0000_3821,                          // addu a3,zero,zero
                0x3c19_0000 | (view_trap >> 16),      // lui t9,MapViewOfFile high
                0x3739_0000 | (view_trap & 0xffff),   // ori t9,t9,low
                0x0320_f809,                          // jalr t9: second A alias
                0,                                    // delay slot
                0x0040_9021,                          // addu s2,v0,zero: alias view
                0x3c0b_0000 | (ALIAS_BYTES >> 16),    // lui t3,alias high
                0x356b_0000 | (ALIAS_BYTES & 0xffff), // ori t3,t3,alias low
                0xae2b_0000,                          // sw t3,0(s1): no flush/import
                0x8e4c_0000,                          // lw t4,0(s2): alias sees store
                0x1000_ffff,                          // bounded safety spinner
                0,
            ];
            for (index, word) in words.into_iter().enumerate() {
                write_vec_u32(&mut bytes, 0x200 + index * 4, word);
            }
            let image = crate::pe::PeImage::parse_bytes(name, &bytes)?;
            let mut cpu = super::UnicornMips::new()?;
            cpu.load_pe_image(&image)?;
            cpu.native_engine = super::ProcessNativeEngine::with_lifetime(
                Arch::MIPS,
                Mode::MIPS32 | Mode::LITTLE_ENDIAN,
                crate::emulator::native_engine::NativeEngineLifetime::FreshPerSlice,
            );
            cpu.set_initial_thread_id(thread_id);
            for (address, ordinal, import_name) in [
                (
                    create_trap,
                    crate::ce::coredll_ordinals::ORD_CREATE_FILE_MAPPING_W,
                    "CreateFileMappingW",
                ),
                (
                    view_trap,
                    crate::ce::coredll_ordinals::ORD_MAP_VIEW_OF_FILE,
                    "MapViewOfFile",
                ),
            ] {
                cpu.import_traps
                    .insert(crate::emulator::imports::ImportTrap {
                        address,
                        module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                        module_name: "COREDLL.dll".to_owned(),
                        ordinal: Some(ordinal),
                        name: Some(import_name.to_owned()),
                        iat_va: 0,
                    });
            }
            super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
            let entry = cpu.entry.expect("fixture PE entry");
            let mut regs = super::MipsGuestContext::zero();
            regs.regs[29] = cpu.stack_top.expect("guest stack") - 0x100;
            cpu.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
            stamp_synthetic_saved_context(&mut cpu, &kernel);
            cpu.running_guest_thread = Some((thread_id, u32::MAX));
            Ok((cpu, entry))
        };

        let (mut parent, parent_entry) = make_cpu("shared-view-parent.exe", 1, A_BYTES)?;
        let (mut child, child_entry) =
            make_cpu("shared-view-child.exe", launch.thread_id, B_BYTES)?;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let run_to = |stop_pc| super::UnicornRunLimits {
            instruction_limit: 96,
            wall_clock_limit_ms: 500,
            stop_pc: Some(stop_pc),
            live_pump: false,
        };

        let a_first = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(parent_entry + 27 * 4),
        );
        a_first.result?;
        assert_eq!(a_first.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_first.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            a_first.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert!(parent.native_engine_identity_for_test().is_none());
        let a_saved = parent.saved_context.as_ref().expect("A after guest store");
        assert_eq!(a_saved.pc, parent_entry + 27 * 4);
        let mapping_handle = a_saved.regs.regs[16];
        let view_base = a_saved.regs.regs[17];
        assert_ne!(mapping_handle, 0, "public CreateFileMappingW result");
        assert_ne!(view_base, 0, "public MapViewOfFile result");
        assert_eq!(a_saved.regs.regs[10], 0, "new anonymous page starts zero");
        let parent_stack_page = parent.stack_top.expect("parent stack") - 0x1000;
        assert!(
            kernel
                .memory
                .private_page_pin(parent_birth, parent_stack_page)
                .is_some(),
            "parent's real stack arguments commit one fixed slab page"
        );
        assert_eq!(
            kernel.memory.private_commit_used_bytes(),
            committed_before + 2 * 4096,
            "one shared view page plus the parent's stack page"
        );
        assert_eq!(
            kernel
                .memory
                .virtual_allocation(parent_birth, view_base)
                .expect("A public view allocation")
                .source,
            crate::ce::memory::VirtualAllocationSource::FileViewSlab
        );
        let a_pin = kernel
            .memory
            .stable_page_pin(parent_birth, view_base)
            .expect("A's canonical shared page pin");
        let mut actual = [0; 4];
        // Flush/write-back must source the page, even before an explicit flush.
        assert!(
            kernel
                .memory
                .shared_mapping_read(mapping_handle, 0, &mut actual)
        );
        assert_eq!(actual, A_BYTES.to_le_bytes());
        assert_eq!(
            kernel.handles.file_mapping(mapping_handle)?.views[0].process_birth,
            Some(parent_birth)
        );

        kernel.set_current_process_state(child_state);
        kernel.set_process_module_path("\\Test\\shared-view-child.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("shared-view-child.exe"));
        let b_first = child.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(child_entry + 27 * 4),
        );
        b_first.result?;
        assert_eq!(b_first.report.start_process_birth(), Some(child_birth));
        assert_eq!(b_first.report.end_process_birth(), Some(child_birth));
        assert_eq!(
            b_first.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert!(child.native_engine_identity_for_test().is_none());
        let b_saved = child.saved_context.as_ref().expect("B after guest store");
        assert_eq!(b_saved.pc, child_entry + 27 * 4);
        assert_eq!(b_saved.regs.regs[16], mapping_handle, "named reopen");
        assert_eq!(b_saved.regs.regs[17], view_base, "same guest VA, new owner");
        assert_eq!(b_saved.regs.regs[10], A_BYTES, "B loaded A's guest store");
        let child_stack_page = child.stack_top.expect("child stack") - 0x1000;
        assert!(
            kernel
                .memory
                .private_page_pin(child_birth, child_stack_page)
                .is_some(),
            "child's real stack arguments commit its own fixed slab page"
        );
        assert_eq!(
            kernel.memory.private_commit_used_bytes(),
            committed_before + 3 * 4096,
            "the named view reuses one shared page; the child adds one stack page"
        );
        let b_pin = kernel
            .memory
            .stable_page_pin(child_birth, view_base)
            .expect("B's canonical shared page pin");
        assert_eq!(a_pin.native_ptr(), b_pin.native_ptr(), "one shared page");
        assert!(
            kernel
                .memory
                .shared_mapping_read(mapping_handle, 0, &mut actual)
        );
        assert_eq!(actual, B_BYTES.to_le_bytes());

        kernel.set_current_process_state(parent_state);
        kernel.set_process_module_path("\\Test\\shared-view-parent.exe");
        kernel.set_process_module_host_path(std::path::PathBuf::from("shared-view-parent.exe"));
        let a_second = parent.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            run_to(parent_entry + 41 * 4),
        );
        a_second.result?;
        assert_eq!(a_second.report.start_process_birth(), Some(parent_birth));
        assert_eq!(a_second.report.end_process_birth(), Some(parent_birth));
        assert_eq!(
            a_second.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert!(parent.native_engine_identity_for_test().is_none());
        let a_saved = parent.saved_context.as_ref().expect("A fresh-owner resume");
        assert_eq!(a_saved.pc, parent_entry + 41 * 4);
        assert_eq!(a_saved.regs.regs[10], B_BYTES, "A loaded B's guest store");
        let alias_base = a_saved.regs.regs[18];
        assert_ne!(alias_base, 0, "second public MapViewOfFile result");
        assert_ne!(alias_base, view_base, "same-owner views have distinct VAs");
        assert_eq!(
            a_saved.regs.regs[12], ALIAS_BYTES,
            "A's alias loaded its unflushed same-slice guest store"
        );
        assert_eq!(
            kernel.memory.private_commit_used_bytes(),
            committed_before + 3 * 4096,
            "same-owner alias reuses the shared page and the parent's existing stack"
        );
        let alias_pin = kernel
            .memory
            .stable_page_pin(parent_birth, alias_base)
            .expect("A's second shared view pin");
        assert_eq!(a_pin.native_ptr(), alias_pin.native_ptr(), "alias one page");
        assert!(
            kernel
                .memory
                .shared_mapping_read(mapping_handle, 0, &mut actual)
        );
        assert_eq!(actual, ALIAS_BYTES.to_le_bytes());
        let views = &kernel.handles.file_mapping(mapping_handle)?.views;
        assert_eq!(views.len(), 3);
        assert_eq!(views[1].process_birth, Some(child_birth));
        assert_eq!(views[2].process_birth, Some(parent_birth));
        Ok(())
    }

    #[test]
    fn preflight_rotation_clears_incoming_stale_native_outcome() -> crate::Result<()> {
        let mut kernel = phase1_kernel("idle-parent.exe")?;
        let parent_state = kernel.current_process_state();
        let mut active = phase1_counter_cpu(0x1000, "idle-parent.exe")?;
        let launch =
            kernel.queue_process_launch(Some("\\Test\\visible-child.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let child_state = crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        };
        kernel.set_current_process_state(child_state);
        let child_window = kernel.create_window_ex_w(
            launch.thread_id,
            "visible_child",
            "",
            None,
            0,
            crate::ce::gwe::WS_VISIBLE,
            0,
        );
        assert!(kernel.gwe.validate_window(child_window));
        kernel.set_current_process_state(parent_state);

        let mut child = phase1_counter_cpu(0x2000, "visible-child.exe")?;
        child.set_initial_thread_id(launch.thread_id);
        let mut child_regs = super::MipsGuestContext::zero();
        child_regs.regs[29] = child.stack_top.unwrap() - 0x100;
        child.saved_context = Some(super::SavedCpuContext {
            pc: child.entry.unwrap(),
            regs: child_regs,
        });
        child.last_native_slice_outcome = super::NativeSliceOutcome::UnknownNormalStop;
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: child_state,
                thread_id: launch.thread_id,
                cpu: Box::new(child),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\visible-child.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("visible-child.exe"),
                command_line: String::new(),
                current_directory: None,
            });

        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let execution = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        execution.result?;
        let report = execution.report;
        assert_eq!(report.final_outcome(), super::NativeSliceOutcome::NoAttempt);
        assert_eq!(report.attempt_id(), None);
        assert!(matches!(
            report.native_result(),
            super::AttemptObservation::Uncollected
        ));
        assert!(matches!(
            report.count_stop_query(),
            super::AttemptObservation::Uncollected
        ));
        assert!(matches!(
            report.timeout_query(),
            super::AttemptObservation::Uncollected
        ));
        assert!(matches!(
            report.context_capture(),
            super::AttemptObservation::Uncollected
        ));
        assert_eq!(kernel.current_process_id(), launch.process_id);
        assert_eq!(
            active.last_native_slice_outcome(),
            super::NativeSliceOutcome::NoAttempt,
            "the preflight handoff made no native attempt on the incoming CPU"
        );
        assert!(active.native_engine_identity_for_test().is_none());
        Ok(())
    }

    #[test]
    fn private_native_error_report_keeps_primary_failure_class() -> crate::Result<()> {
        let mut kernel = phase1_kernel("private-native-error.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let mut cpu = phase1_counter_cpu(0x1000, "private-native-error.exe")?;
        cpu.entry = Some(0x7000_0000); // deliberately unmapped guest fetch
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let limits = super::UnicornRunLimits {
            instruction_limit: 20,
            wall_clock_limit_ms: 500,
            stop_pc: None,
            live_pump: false,
        };
        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        let report = execution.report;
        let error = execution
            .result
            .expect_err("unmapped native fetch must fail");
        assert!(
            format!("{error:#}").contains("Unicorn run failed"),
            "{error:#}"
        );
        assert!(report.attempt_id().is_some());
        assert!(matches!(
            report.native_result(),
            super::AttemptObservation::Error(_)
        ));
        assert_eq!(
            report.final_outcome(),
            super::NativeSliceOutcome::NativeError
        );
        assert_eq!(report.failure_operation(), Some("execute native slice"));
        assert_eq!(report.start_process_birth(), Some(owner));
        assert_eq!(report.end_process_birth(), Some(owner));
        assert!(cpu.private_slab_attempt_poisoned);
        let rejected = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            limits,
        );
        assert!(rejected.result.is_err());
        assert_eq!(rejected.report.attempt_id(), None);
        assert_eq!(
            rejected.report.final_outcome(),
            super::NativeSliceOutcome::NoAttempt
        );
        Ok(())
    }

    fn native_timeout_query_loop() -> Unicorn<'static, ()> {
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x1000, 0x1000, Prot::ALL).unwrap();
        write_words(&mut uc, 0x1000, &[0x2610_0001, 0x0800_0400, 0]);
        uc
    }

    #[test]
    fn native_timeout_query_distinguishes_configured_timeout_from_instruction_count_stop() {
        let mut uc = native_timeout_query_loop();
        uc.emu_start(0x1000, 0, 1_000_000, 16).unwrap();
        let configured_ns = uc.ctl_get_timeout().unwrap();
        let actually_expired = uc
            .query(unicorn_engine::unicorn_const::Query::TIMEOUT)
            .unwrap();
        let count_stopped = uc
            .query(unicorn_engine::unicorn_const::Query::COUNT_STOP)
            .unwrap();
        eprintln!(
            "native_timeout_query count_stop configured_us=1000000 configured_ns={configured_ns} actually_expired={actually_expired}"
        );
        assert_eq!(configured_ns, 1_000_000_000);
        assert_eq!(actually_expired, 0);
        assert_eq!(count_stopped, 1);
    }

    #[test]
    fn native_timeout_query_distinguishes_configured_timeout_from_voluntary_block_stop() {
        let mut uc = native_timeout_query_loop();
        let stopped = Rc::new(std::cell::Cell::new(false));
        let stopped_hook = Rc::clone(&stopped);
        uc.add_block_hook(1, 0, move |uc, pc, _size| {
            if pc == 0x1000 {
                stopped_hook.set(true);
                uc.reg_write(RegisterMIPS::PC, pc).unwrap();
                uc.emu_stop().unwrap();
            }
        })
        .unwrap();
        uc.emu_start(0x1000, 0, 1_000_000, 16).unwrap();
        let configured_ns = uc.ctl_get_timeout().unwrap();
        let actually_expired = uc
            .query(unicorn_engine::unicorn_const::Query::TIMEOUT)
            .unwrap();
        let count_stopped = uc
            .query(unicorn_engine::unicorn_const::Query::COUNT_STOP)
            .unwrap();
        eprintln!(
            "native_timeout_query voluntary_stop configured_us=1000000 configured_ns={configured_ns} actually_expired={actually_expired} pc={:#x}",
            uc.reg_read(RegisterMIPS::PC).unwrap()
        );
        assert!(stopped.get());
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap(), 0x1000);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap(), 0);
        assert_eq!(configured_ns, 1_000_000_000);
        assert_eq!(actually_expired, 0);
        assert_eq!(count_stopped, 0);
    }

    #[test]
    fn native_timeout_query_reports_actual_native_deadline_expiry() {
        let mut uc = native_timeout_query_loop();
        // A bounded native deadline, no count hook: this control only checks
        // the API's actual expiry flag, not replay of asynchronous branch state.
        uc.emu_start(0x1000, 0, 2_000, 0).unwrap();
        let configured_ns = uc.ctl_get_timeout().unwrap();
        let actually_expired = uc
            .query(unicorn_engine::unicorn_const::Query::TIMEOUT)
            .unwrap();
        let count_stopped = uc
            .query(unicorn_engine::unicorn_const::Query::COUNT_STOP)
            .unwrap();
        eprintln!(
            "native_timeout_query expired configured_us=2000 configured_ns={configured_ns} actually_expired={actually_expired}"
        );
        assert_eq!(configured_ns, 2_000_000);
        assert_eq!(actually_expired, 1);
        assert_eq!(count_stopped, 0);
    }

    #[test]
    fn native_count_stop_query_resets_before_a_no_count_run() {
        let mut uc = native_timeout_query_loop();
        uc.emu_start(0x1000, 0, 1_000_000, 1).unwrap();
        assert_eq!(
            uc.query(unicorn_engine::unicorn_const::Query::COUNT_STOP)
                .unwrap(),
            1
        );
        uc.add_code_hook(1, 0, |uc, _, _| {
            uc.emu_stop().unwrap();
        })
        .unwrap();
        uc.emu_start(0x1000, 0, 1_000_000, 0).unwrap();
        assert_eq!(
            uc.query(unicorn_engine::unicorn_const::Query::COUNT_STOP)
                .unwrap(),
            0,
            "a later explicit stop must not inherit the prior count witness"
        );
    }

    #[test]
    fn native_deadline_jr_repair_must_not_override_typed_safe_hook_stop() {
        use super::{NativeHookStopReason, NativeSliceOutcome};

        let should_repair = super::should_repair_native_deadline_jr_import_thunk;
        assert!(should_repair(
            true,
            false,
            NativeSliceOutcome::NativeDeadline,
            None,
        ));
        assert!(!should_repair(
            false,
            false,
            NativeSliceOutcome::NativeDeadline,
            None,
        ));
        assert!(!should_repair(
            true,
            true,
            NativeSliceOutcome::NativeDeadline,
            None,
        ));
        assert!(!should_repair(
            true,
            false,
            NativeSliceOutcome::HookStop(NativeHookStopReason::HostWallBudget),
            Some(NativeHookStopReason::HostWallBudget),
        ));
        assert!(!should_repair(
            true,
            false,
            NativeSliceOutcome::NativeDeadline,
            Some(NativeHookStopReason::HostWallBudget),
        ));
        assert!(!should_repair(
            true,
            false,
            NativeSliceOutcome::NativeError,
            None,
        ));

        assert!(
            !should_repair(
                true,
                false,
                NativeSliceOutcome::NativeDeadline,
                Some(NativeHookStopReason::VisibleParkedPeerYield),
            ),
            "a typed safe peer yield must not be overridden by a concurrent native deadline"
        );
    }

    /// A real MIPS jump reaches a safe JR block while a visible parked peer
    /// requests a checked hook stop and Unicorn's own timer also expires.
    /// The outgoing attempt must retain both raw facts without promoting the
    /// deadline-only debug marker or rewriting the peer's raw JR continuation;
    /// resuming that continuation must dispatch the real import exactly once.
    #[test]
    fn mixed_native_deadline_visible_peer_yield_preserves_checked_jr_continuation()
    -> crate::Result<()> {
        use super::{AttemptObservation, NativeHookStopReason, NativeMixedJrStopProbe};

        let trap = crate::emulator::imports::IMPORT_TRAP_BASE;
        let mut bytes = tiny_mips_spinner_pe();
        let entry = 0x0040_1000u32;
        let jump_pc = entry + 8;
        let jr_pc = entry + 16;
        // The setup attempt executes lui/ori and stops before this jump. The
        // mixed attempt executes j/nop, then enters the real JR block.
        write_vec_u32(&mut bytes, 0x200, 0x3c19_0000 | (trap >> 16)); // lui t9,trap_hi
        write_vec_u32(&mut bytes, 0x204, 0x3739_0000 | (trap & 0xffff)); // ori t9,t9,trap_lo
        write_vec_u32(
            &mut bytes,
            0x208,
            0x0800_0000 | ((jr_pc >> 2) & 0x03ff_ffff),
        ); // j jr_pc
        write_vec_u32(&mut bytes, 0x20c, 0); // delay-slot nop
        write_vec_u32(&mut bytes, 0x210, 0x0320_0008); // jr t9
        write_vec_u32(&mut bytes, 0x214, 0); // delay-slot nop
        write_vec_u32(&mut bytes, 0x218, 0x2610_0001); // addiu s0,s0,1 after import return
        write_vec_u32(&mut bytes, 0x21c, 0x1000_ffff); // bounded by count on resume
        write_vec_u32(&mut bytes, 0x220, 0);
        let image = crate::pe::PeImage::parse_bytes("e34-mixed-jr-parent.exe", &bytes)?;
        assert_eq!(image.entry_point_va(), entry);
        let mut kernel = phase1_kernel("e34-mixed-jr-parent.exe")?;
        let parent_state = kernel.current_process_state();
        let parent_birth = kernel.current_process_birth_key().expect("boot birth");
        let mut active = super::UnicornMips::new()?;
        active.load_pe_image(&image)?;
        active
            .import_traps
            .insert(crate::emulator::imports::ImportTrap {
                address: trap,
                module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(crate::ce::coredll_ordinals::ORD_GET_TICK_COUNT),
                name: Some("GetTickCount".to_owned()),
                iat_va: 0,
            });
        super::refresh_import_trap_page_blob(&mut active.mapped_blobs, &active.import_traps);
        assert!(active.trampoline_origins_all_direct());
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[29] = active.stack_top.expect("stack") - 0x100;
        regs.regs[31] = entry + 24;
        active.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
        stamp_synthetic_saved_context(&mut active, &kernel);
        active.running_guest_thread = Some((1, u32::MAX));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let setup = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: Some(jump_pc),
                live_pump: false,
            },
        );
        setup.result?;
        assert_eq!(
            setup.report.final_outcome(),
            super::NativeSliceOutcome::RequestedPcStop
        );
        assert_eq!(active.saved_context_pc(), Some(jump_pc));
        assert_eq!(
            active.last_debug_snapshot().expect("setup snapshot").t9,
            trap,
            "the real MIPS lui/ori pair must establish the import target"
        );
        assert!(
            active
                .last_debug_snapshot()
                .expect("setup snapshot")
                .import_counts
                .is_empty(),
            "setup must not dispatch the import"
        );

        let launch =
            kernel.queue_process_launch(Some("\\Test\\e34-visible-peer.exe".to_owned()), None);
        assert!(
            kernel
                .take_pending_process_launches()
                .iter()
                .any(|queued| queued.process_id == launch.process_id)
        );
        let peer_state = crate::ce::kernel::CurrentProcessState {
            process_id: launch.process_id,
            exit_code: crate::ce::kernel::STILL_ACTIVE,
            signaled: false,
        };
        kernel.set_current_process_state(peer_state);
        let peer_window = kernel.create_window_ex_w_with_rect(
            launch.thread_id,
            "e34_visible_peer",
            "",
            None,
            0,
            crate::ce::gwe::WS_VISIBLE,
            0,
            crate::ce::gwe::Rect::from_origin_size(0, 0, 800, 480),
        );
        assert!(kernel.gwe.validate_window(peer_window));
        kernel.set_current_process_state(parent_state);
        let mut peer = phase1_counter_cpu(0x2000, "e34-visible-peer.exe")?;
        peer.set_initial_thread_id(launch.thread_id);
        let mut peer_regs = super::MipsGuestContext::zero();
        peer_regs.regs[29] = peer.stack_top.expect("peer stack") - 0x100;
        peer.saved_context = Some(super::SavedCpuContext {
            pc: peer.entry.expect("peer entry"),
            regs: peer_regs,
        });
        stamp_synthetic_saved_context(&mut peer, &kernel);
        active
            .parked_child_processes
            .push_back(super::ParkedProcess {
                application: launch.application.clone(),
                process_handle: Some(launch.process_handle),
                thread_handle: Some(launch.thread_handle),
                process_state: peer_state,
                thread_id: launch.thread_id,
                cpu: Box::new(peer),
                blocked_send_id: None,
                module_base: 0x0040_0000,
                module_path: "\\Test\\e34-visible-peer.exe".to_owned(),
                module_host_path: std::path::PathBuf::from("e34-visible-peer.exe"),
                command_line: String::new(),
                current_directory: None,
            });
        assert!(active.active_should_yield_to_visible_parked_process(&kernel));
        let probe = Rc::new(std::cell::Cell::new(NativeMixedJrStopProbe {
            jr_pc,
            native_timeout_us: 1_000_000,
            pause_after_checked_stop: std::time::Duration::from_millis(1_500),
            service_forced: false,
            checked_stop_seen: false,
        }));
        active.native_mixed_jr_stop_probe = Some(Rc::clone(&probe));
        // A prior slice-end selection keeps the parent for exactly this
        // native attempt instead of rotating to the visible peer in preflight.
        active.slice_end_rotation_pending = true;
        let mixed = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 0,
                stop_pc: None,
                live_pump: true,
            },
        );
        mixed.result?;
        let report = mixed.report;
        assert!(probe.get().service_forced && probe.get().checked_stop_seen);
        assert!(report.attempt_id().is_some());
        assert_eq!(report.start_process_id(), Some(parent_state.process_id));
        assert_eq!(report.end_process_id(), Some(parent_state.process_id));
        assert_eq!(report.start_process_birth(), Some(parent_birth));
        assert_eq!(report.end_process_birth(), Some(parent_birth));
        assert_eq!(report.start_thread_id(), Some(1));
        assert_eq!(report.end_thread_id(), Some(1));
        assert_eq!(report.start_pc(), Some(jump_pc));
        assert_eq!(report.native_result(), &AttemptObservation::Value(()));
        assert_eq!(report.count_stop_query(), &AttemptObservation::Value(false));
        assert_eq!(
            report.timeout_query(),
            &AttemptObservation::Value(true),
            "Unicorn's own timer must expire during this native attempt"
        );
        assert_eq!(
            report.hook_stop_reason(),
            Some(NativeHookStopReason::VisibleParkedPeerYield)
        );
        assert_eq!(report.requested_pc_stop(), None);
        assert_eq!(report.raw_stop_pc(), &AttemptObservation::Value(jr_pc));
        assert_eq!(
            report.final_outcome(),
            super::NativeSliceOutcome::NativeDeadline
        );
        assert_eq!(kernel.current_process_id(), launch.process_id);
        let outgoing = active
            .parked_child_processes
            .iter()
            .find(|process| process.process_state.process_id == parent_state.process_id)
            .expect("outgoing parent is parked after real native handoff");
        let snapshot = outgoing.cpu.last_debug_snapshot().expect("parent snapshot");
        let saved_pc = outgoing
            .cpu
            .saved_context_pc()
            .expect("parent continuation");
        assert!(
            outgoing.cpu.native_engine_identity_for_test().is_none(),
            "the outgoing parent's native owner closed before handoff"
        );
        eprintln!(
            "E34 mixed JR: raw={:?} saved=0x{saved_pc:08x} snapshot=0x{:08x} marker={} outcome={:?}",
            report.raw_stop_pc(),
            snapshot.pc,
            snapshot.host_wall_clock_stop.is_some(),
            report.final_outcome()
        );
        assert!(
            snapshot.host_wall_clock_stop.is_none(),
            "a checked typed peer yield cannot acquire the deadline-only debug marker"
        );
        assert_eq!(
            saved_pc, jr_pc,
            "the checked JR continuation must not be rewritten"
        );
        assert_eq!(snapshot.pc, jr_pc);
        assert!(
            snapshot.import_counts.is_empty(),
            "the import must not dispatch before resume"
        );

        // The slice-end handoff selected the peer; explicitly return to the
        // parked parent before testing the saved raw JR continuation.
        assert!(active.rotate_to_next_parked_process(&mut kernel));
        assert_eq!(kernel.current_process_id(), parent_state.process_id);
        active.slice_end_rotation_pending = true;
        let resumed = active.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        resumed.result?;
        assert_eq!(
            resumed.report.start_process_id(),
            Some(parent_state.process_id)
        );
        let resumed_parent = if kernel.current_process_id() == parent_state.process_id {
            &active
        } else {
            &active
                .parked_child_processes
                .iter()
                .find(|process| process.process_state.process_id == parent_state.process_id)
                .expect("resumed parent remains parked after handoff")
                .cpu
        };
        assert!(
            resumed_parent
                .last_debug_snapshot()
                .expect("resumed parent snapshot")
                .import_counts
                .iter()
                .any(|count| count.ordinal
                    == Some(crate::ce::coredll_ordinals::ORD_GET_TICK_COUNT)
                    && count.count == 1),
            "resuming the protected JR must dispatch exactly one real GetTickCount import"
        );
        Ok(())
    }

    #[test]
    fn native_count_stop_classification_requires_uncontested_success() {
        let clean = super::NativeStopEvidence {
            count_stop_requested: true,
            ..Default::default()
        };
        assert_eq!(clean.outcome(), super::NativeSliceOutcome::CountLimit);
        for competing in [
            super::NativeStopEvidence {
                requested_pc_stop: true,
                ..clean
            },
            super::NativeStopEvidence {
                native_deadline_expired: true,
                ..clean
            },
            super::NativeStopEvidence {
                hook_stop_reason: Some(super::NativeHookStopReason::HostWallBudget),
                ..clean
            },
        ] {
            assert_eq!(
                competing.outcome(),
                super::NativeSliceOutcome::UnknownNormalStop,
                "competing successful stop facts are not a proven count limit"
            );
        }
        assert_eq!(
            super::NativeStopEvidence {
                native_error: true,
                ..clean
            }
            .outcome(),
            super::NativeSliceOutcome::NativeError
        );
        for failed_tail in [
            super::NativeStopEvidence {
                capture_error: true,
                ..clean
            },
            super::NativeStopEvidence {
                hook_control_error: true,
                ..clean
            },
        ] {
            assert_eq!(
                failed_tail.outcome(),
                super::NativeSliceOutcome::BackendError
            );
        }
    }

    #[test]
    fn failed_host_budget_control_is_backend_error_unless_native_failed_first() {
        let stopped = super::NativeStopEvidence {
            hook_control_error: true,
            count_stop_requested: false,
            requested_pc_stop: true,
            native_deadline_expired: true,
            hook_stop_reason: Some(super::NativeHookStopReason::HostWallBudget),
            ..Default::default()
        };
        assert_eq!(stopped.outcome(), super::NativeSliceOutcome::BackendError);
        assert_eq!(
            super::NativeStopEvidence {
                native_error: true,
                ..stopped
            }
            .outcome(),
            super::NativeSliceOutcome::NativeError,
            "a primary native result or timeout-query failure wins"
        );
        assert_eq!(
            super::NativeStopEvidence {
                capture_error: true,
                ..stopped
            }
            .outcome(),
            super::NativeSliceOutcome::BackendError,
            "native capture remains a hard failure"
        );
    }

    #[test]
    fn real_mips_count_query_adapter_error_keeps_native_failure_report() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-count-query-error.exe")?;
        let mut cpu = phase1_counter_cpu(0x1000, "phase1-count-query-error.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        // This seam observes a genuine native count witness of 1, then
        // substitutes RESOURCE in the Rust lease adapter only.
        cpu.native_engine
            .arm_count_stop_query_error_once_for_test(1);
        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let report = execution.report;
        let err = execution
            .result
            .expect_err("injected query error must fail the run");
        assert!(format!("{err:#}").contains("query native count stop"));
        assert_eq!(phase1_counter(&cpu), 0x1006, "real MIPS stores must occur");
        assert!(report.attempt_id().is_some());
        assert_eq!(report.start_process_birth(), Some(owner));
        assert_eq!(report.end_process_birth(), Some(owner));
        assert_eq!(
            report.native_result(),
            &super::AttemptObservation::Value(())
        );
        assert!(matches!(
            report.count_stop_query(),
            super::AttemptObservation::Error(message) if message.contains("RESOURCE")
        ));
        assert_eq!(
            report.timeout_query(),
            &super::AttemptObservation::Value(false)
        );
        assert_eq!(
            report.final_outcome(),
            super::NativeSliceOutcome::NativeError
        );
        assert_eq!(report.failure_operation(), Some("query native count stop"));
        assert!(report.partial_effects_possible());
        assert!(!report.final_outcome().is_service_boundary());
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::NativeError
        );
        assert!(cpu.native_engine_identity_for_test().is_none());
        Ok(())
    }

