    #[test]
    fn private_pre_entry_fence_failure_preserves_executed_thread_wait() -> crate::Result<()> {
        let mut kernel = phase1_kernel("private-pre-entry-fence-wait.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let private_base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let private_pin = kernel
            .memory
            .private_page_pin(owner, private_base)
            .expect("committed private page");
        let held_guard = private_pin
            .begin_native_execution()
            .expect("hold the page fence through pre-entry validation");
        let mut cpu = phase1_counter_cpu(0x1000, "private-pre-entry-fence-wait.exe")?;
        let orphaned_return = archived_test_record();
        cpu.orphaned_wndproc_returns.push(orphaned_return.clone());
        let wait_id = phase1_seed_executed_thread_sleep_wait(&mut kernel, &mut cpu);
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;

        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let report = execution.report;
        let err = execution
            .result
            .expect_err("held page fence must reject pre-entry setup");
        assert!(
            format!("{err:#}").contains(&format!(
                "fence stable page 0x{private_base:08x}: NativeExecutionActive"
            )),
            "{err:#}"
        );
        assert_eq!(report.final_outcome(), super::NativeSliceOutcome::NoAttempt);
        assert_eq!(report.attempt_id(), None);
        assert!(matches!(
            report.native_result(),
            super::AttemptObservation::Uncollected
        ));
        assert!(kernel.blocked_waiter(wait_id).is_some());
        assert!(
            cpu.blocked_wait_threads
                .iter()
                .any(|wait| wait.wait_id == wait_id),
            "pre-entry failure must not lose the CPU-side wait moved into run-state handles"
        );
        assert_eq!(
            cpu.orphaned_wndproc_returns.as_slice(),
            &[orphaned_return],
            "pre-entry failure must restore the orphaned WNDPROC return moved into its Rc handle"
        );
        drop(held_guard);
        Ok(())
    }

    #[test]
    fn private_pre_entry_fence_failure_must_not_consume_ready_worker_wait() -> crate::Result<()> {
        let mut kernel = phase1_kernel("private-pre-entry-ready-wait.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let private_base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let private_pin = kernel
            .memory
            .private_page_pin(owner, private_base)
            .expect("committed private page");
        let held_guard = private_pin
            .begin_native_execution()
            .expect("hold the page fence through pre-entry validation");

        let mut cpu = phase1_counter_cpu(0x1000, "private-pre-entry-ready-wait.exe")?;
        let main_thread_id = cpu.current_thread_id();
        let entry = cpu.entry.expect("loaded guest entry");
        let resume_pc = entry + 0x20;
        let (worker_handle, worker_thread_id) = kernel.create_guest_thread(entry, 0, false);
        assert_ne!(worker_thread_id, main_thread_id);
        let ready_event = kernel.create_event_w(None, true, true);
        let wait_started_ms = kernel.timers.tick_count();
        let wait_id = kernel.register_blocked_waiter(
            worker_thread_id,
            worker_handle,
            vec![ready_event],
            crate::ce::scheduler::SchedulerBlockedWaitKind::Kernel,
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[16] = 0x1357_2468;
        regs.regs[29] = cpu.stack_top.expect("loaded guest stack") - 0x200;
        cpu.blocked_wait_threads.push(super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: worker_thread_id,
            thread_handle: worker_handle,
            wait_handles: vec![ready_event],
            kind: super::BlockedWaitKind::Kernel,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs,
            return_pc: resume_pc,
        });
        assert_eq!(
            kernel.select_ready_blocked_waiter(main_thread_id, wait_started_ms, |wait, kernel| {
                super::scheduler_blocked_wait_is_ready(wait, kernel)
            }),
            Some(wait_id),
            "the ready worker must be selectable before the fence failure"
        );
        let counter_before = phase1_counter(&cpu);
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;

        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let report = execution.report;
        let err = execution
            .result
            .expect_err("held page fence must reject pre-entry setup");
        assert!(
            format!("{err:#}").contains(&format!(
                "fence stable page 0x{private_base:08x}: NativeExecutionActive"
            )),
            "{err:#}"
        );
        assert_eq!(report.final_outcome(), super::NativeSliceOutcome::NoAttempt);
        assert_eq!(report.attempt_id(), None);
        assert!(matches!(
            report.native_result(),
            super::AttemptObservation::Uncollected
        ));
        assert_eq!(phase1_counter(&cpu), counter_before);

        let kernel_wait_survived = kernel.blocked_waiter(wait_id).is_some();
        let cpu_wait_survived = cpu
            .blocked_wait_threads
            .iter()
            .any(|wait| wait.wait_id == wait_id);
        assert!(
            kernel_wait_survived && cpu_wait_survived && cpu.current_thread_id() == main_thread_id,
            "rejected pre-entry resume consumed a ready wait or switched threads: \
             kernel_wait={kernel_wait_survived} cpu_wait={cpu_wait_survived} \
             current_tid={} main_tid={main_thread_id} saved_pc={:?} discarded_resume_pc=0x{resume_pc:08x}",
            cpu.current_thread_id(),
            cpu.saved_context_pc(),
        );
        drop(held_guard);
        Ok(())
    }

    #[test]
    fn ready_object_wait_runs_next_native_slice_with_verified_birth() -> crate::Result<()> {
        let mut kernel = phase1_kernel("ready-object-wait-birth.exe")?;
        let mut cpu = phase1_counter_cpu(0x1000, "ready-object-wait-birth.exe")?;
        let main_thread_id = cpu.current_thread_id();
        let entry = cpu.entry.expect("loaded guest entry");
        let resume_pc = entry + 0x20;
        let (worker_handle, worker_thread_id) = kernel.create_guest_thread(entry, 0, false);
        assert_ne!(worker_thread_id, main_thread_id);
        let worker_birth = kernel
            .handles
            .thread_birth_key_by_id(worker_thread_id)
            .expect("blocked worker birth");
        let event = kernel.create_event_w(None, false, false);
        let wait_started_ms = kernel.timers.tick_count();
        let wait_id = kernel.register_blocked_waiter(
            worker_thread_id,
            worker_handle,
            vec![event],
            crate::ce::scheduler::SchedulerBlockedWaitKind::Kernel,
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        assert_ne!(wait_id, 0);
        assert_eq!(
            kernel
                .blocked_waiter(wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(worker_birth),
        );
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[8] = PHASE1_COUNTER_ADDRESS;
        regs.regs[9] = 0x1000;
        regs.regs[29] = cpu.stack_top.expect("loaded guest stack") - 0x200;
        cpu.blocked_wait_threads.push(super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: worker_thread_id,
            thread_handle: worker_handle,
            wait_handles: vec![event],
            kind: super::BlockedWaitKind::Kernel,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs,
            return_pc: resume_pc,
        });
        assert!(kernel.set_event(event));
        assert_eq!(kernel.is_wait_ready(event, worker_thread_id), Some(true));
        assert_eq!(
            kernel.select_ready_blocked_waiter(
                main_thread_id,
                kernel.timers.tick_count(),
                |wait, kernel| super::scheduler_blocked_wait_is_ready(wait, kernel),
            ),
            Some(wait_id),
            "the worker must be ready before the native slice",
        );
        let mut framebuffer = VirtualFramebuffer::default_primary()?;

        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let report = execution.report;
        execution.result?;
        assert_eq!(report.start_thread_id(), Some(worker_thread_id));
        assert_eq!(report.start_pc(), Some(resume_pc));
        assert_eq!(report.end_thread_id(), Some(worker_thread_id));
        assert_eq!(cpu.current_thread_id(), worker_thread_id);
        assert!(phase1_counter(&cpu) > 0x1000);
        assert_eq!(cpu.staging_provenance_rejections, 0);
        assert_eq!(cpu.saved_context_thread_birth, Some(worker_birth));
        assert!(cpu.blocked_wait_threads.is_empty());
        assert!(kernel.blocked_waiter(wait_id).is_none());
        assert_eq!(kernel.is_wait_ready(event, worker_thread_id), Some(false));
        Ok(())
    }

    #[test]
    fn private_ready_get_message_writes_guarded_slab_before_native_slice() -> crate::Result<()> {
        let mut kernel = phase1_kernel("private-ready-get-message.exe")?;
        let owner = kernel.current_process_birth_key().expect("boot birth");
        let private_base = phase1_publish_private_page_without_native_owner(&mut kernel, owner);
        let private_pin = kernel
            .memory
            .private_page_pin(owner, private_base)
            .expect("committed private page");
        private_pin
            .write_bytes(0, &[0xa5; 28])
            .expect("seed canonical private MSG bytes");
        let mut cpu = phase1_counter_cpu(0x1000, "private-ready-get-message.exe")?;
        let main_thread_id = cpu.current_thread_id();
        let entry = cpu.entry.expect("loaded guest entry");
        let resume_pc = entry + 0x20;
        let (worker_handle, worker_thread_id) = kernel.create_guest_thread(entry, 0, false);
        assert_ne!(worker_thread_id, main_thread_id);
        let worker_birth = kernel
            .handles
            .thread_birth_key_by_id(worker_thread_id)
            .expect("GetMessage worker birth");
        let wait_id = kernel.register_blocked_waiter(
            worker_thread_id,
            worker_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            },
            kernel.timers.tick_count(),
            crate::ce::timer::INFINITE,
        );
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[8] = PHASE1_COUNTER_ADDRESS;
        regs.regs[9] = 0x1000;
        regs.regs[29] = cpu.stack_top.expect("loaded guest stack") - 0x200;
        cpu.blocked_guest_thread = Some(super::BlockedGuestThread {
            wait_id,
            thread_id: worker_thread_id,
            thread_birth: worker_birth,
            thread_handle: worker_handle,
            regs,
            import_pc: 0,
            return_pc: resume_pc,
            msg_ptr: private_base,
            hwnd: None,
            min_msg: 0,
            max_msg: 0,
        });
        let message_id = crate::ce::gwe::WM_USER + 0x52;
        assert!(kernel.post_thread_message_w(worker_thread_id, message_id, 0x53, 0x54));
        assert_eq!(
            kernel.select_ready_blocked_waiter(
                main_thread_id,
                kernel.timers.tick_count(),
                |wait, kernel| super::scheduler_blocked_wait_is_ready(wait, kernel)
            ),
            Some(wait_id),
            "the GetMessage worker must be ready before the native slice"
        );
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;

        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 20,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        let report = execution.report;
        execution.result?;
        assert_eq!(report.start_process_birth(), Some(owner));
        assert_eq!(report.start_thread_id(), Some(worker_thread_id));
        assert_eq!(report.start_pc(), Some(resume_pc));
        assert_eq!(report.end_thread_id(), Some(worker_thread_id));
        assert_eq!(cpu.current_thread_id(), worker_thread_id);
        assert!(
            phase1_counter(&cpu) > 0x1000,
            "the resumed worker must execute MIPS stores"
        );
        assert!(kernel.blocked_waiter(wait_id).is_none());
        assert!(cpu.blocked_guest_thread.is_none());
        assert!(!cpu.private_slab_attempt_poisoned);
        assert_eq!(cpu.staging_provenance_rejections, 0);
        assert_eq!(cpu.saved_context_thread_birth, Some(worker_birth));

        // The per-slice fence has been released, so inspect the canonical
        // pointer-backed bytes rather than a separate Unicorn memory copy.
        let mut msg_bytes = [0u8; 16];
        private_pin
            .read_bytes(0, &mut msg_bytes)
            .expect("read canonical MSG bytes after the native slice");
        assert_eq!(u32::from_le_bytes(msg_bytes[0..4].try_into().unwrap()), 0);
        assert_eq!(
            u32::from_le_bytes(msg_bytes[4..8].try_into().unwrap()),
            message_id
        );
        assert_eq!(
            u32::from_le_bytes(msg_bytes[8..12].try_into().unwrap()),
            0x53
        );
        assert_eq!(
            u32::from_le_bytes(msg_bytes[12..16].try_into().unwrap()),
            0x54
        );
        Ok(())
    }

