    #[test]
    fn native_count_boundary_is_service_without_fabricated_deadline() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-count-classification.exe")?;
        let mut cpu = phase1_persistent_counter_cpu(0x1000, "phase1-count-classification.exe")?;
        let entry = cpu.entry.unwrap();
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        phase1_run_twenty(&mut cpu, &mut kernel, &mut framebuffer)?;

        let mut native = cpu.native_engine.lease().unwrap();
        assert!(native.reused());
        assert_eq!(
            native.reg_read(RegisterMIPS::PC).unwrap(),
            u64::from(entry + 20 * 4)
        );
        assert_eq!(
            native
                .mem_read_as_vec(u64::from(PHASE1_COUNTER_ADDRESS), 4)
                .unwrap(),
            0x1006_u32.to_le_bytes()
        );
        assert!(native.ctl_get_timeout().unwrap() > 0);
        assert_eq!(
            native
                .query(unicorn_engine::unicorn_const::Query::TIMEOUT)
                .unwrap(),
            0,
            "the configured native deadline did not expire"
        );
        let ledger = native.take_metadata().unwrap();
        native.set_metadata(ledger);
        native.finish().unwrap();

        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::CountLimit
        );
        assert!(cpu.last_native_slice_outcome().is_service_boundary());
        assert!(
            cpu.last_debug_snapshot()
                .unwrap()
                .host_wall_clock_stop
                .is_none()
        );
        Ok(())
    }

    #[test]
    fn scheduler_block_preseeded_busy_fails_before_machine_state_access() -> crate::Result<()> {
        let mut kernel = phase1_kernel("scheduler-block-busy.exe")?;
        let mut cpu = phase1_counter_cpu(0x1000, "scheduler-block-busy.exe")?;
        assert!(cpu.trampoline_origins_all_direct());
        let busy = Rc::new(std::cell::Cell::new(true));
        cpu.scheduler_block_busy_probe = Some(Rc::clone(&busy));
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let frame_before = framebuffer.clone();
        let process_before = kernel.current_process_id();

        let attempted = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 1_000_000,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        assert!(matches!(
            attempted.result,
            Err(crate::Error::Backend(ref message))
                if message.contains("reentrant scheduler block state access")
        ));
        assert_eq!(
            attempted.report.failure_operation(),
            Some("scheduler block state access")
        );
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::BackendError
        );
        assert!(matches!(
            attempted.report.raw_stop_pc(),
            super::AttemptObservation::Value(pc) if *pc != 0
        ));
        assert_eq!(kernel.current_process_id(), process_before);
        assert_eq!(framebuffer, frame_before);
        assert!(
            busy.get(),
            "failed entry must not release another owner's guard"
        );
        assert!(cpu.native_engine_identity_for_test().is_none());
        assert!(cpu.private_slab_attempt_poisoned);
        assert!(cpu.saved_context.is_none());

        let mut unbusy_kernel = phase1_kernel("scheduler-block-unbusy.exe")?;
        let mut unbusy_cpu = phase1_counter_cpu(0x1000, "scheduler-block-unbusy.exe")?;
        let unbusy = Rc::new(std::cell::Cell::new(false));
        unbusy_cpu.scheduler_block_busy_probe = Some(Rc::clone(&unbusy));
        let mut unbusy_framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let control = unbusy_cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut unbusy_kernel,
            &mut unbusy_framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 1_000_000,
                wall_clock_limit_ms: 1,
                stop_pc: None,
                live_pump: true,
            },
        );
        control.result?;
        assert_eq!(control.report.failure_operation(), None);
        assert_eq!(
            unbusy_cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::HookStop(super::NativeHookStopReason::HostWallBudget)
        );
        assert!(!unbusy.get());
        Ok(())
    }

    #[test]
    fn elapsed_host_budget_block_hook_has_typed_stop_reason() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-host-budget-stop.exe")?;
        let mut cpu = phase1_counter_cpu(0x1000, "phase1-host-budget-stop.exe")?;
        assert!(
            cpu.trampoline_origins_all_direct(),
            "the fixture must use the hookless code path and its scheduler block hook"
        );
        let mut framebuffer = crate::ce::framebuffer::VirtualFramebuffer::default_primary()?;
        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 1_000_000,
                wall_clock_limit_ms: 1,
                stop_pc: None,
                live_pump: true,
            },
        );
        execution.result?;
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::HookStop(super::NativeHookStopReason::HostWallBudget),
            "only the checked safe-PC budget hook may publish this label"
        );
        assert!(cpu.last_native_slice_outcome().is_service_boundary());
        assert!(cpu.saved_context_pc().is_some());
        assert_eq!(
            execution.report.timeout_query(),
            &super::AttemptObservation::Value(false),
            "the native one-second deadline did not cause this stop"
        );
        assert_eq!(
            execution.report.raw_stop_pc(),
            &super::AttemptObservation::Value(cpu.saved_context_pc().unwrap())
        );
        assert!(cpu.native_engine_identity_for_test().is_none());
        Ok(())
    }

    fn assert_global_deferred_hook_stop(
        cpu: &super::UnicornMips,
        report: &super::NativeAttemptReport,
        reason: super::NativeHookStopReason,
    ) {
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::HookStop(reason)
        );
        let entry = cpu.entry.unwrap();
        let saved_pc = cpu.saved_context_pc().expect("saved safe global-hook PC");
        assert!(saved_pc >= entry + 0x4000 && saved_pc < entry + 0x10000);
        assert_eq!(
            (saved_pc - entry) % 0x4000,
            0,
            "the global code hook stops after a 4096-instruction service point"
        );
        let snapshot = cpu.last_debug_snapshot().unwrap();
        assert_eq!(snapshot.pc, saved_pc);
        assert_eq!(
            snapshot.host_wall_clock_stop.as_ref().map(|stop| stop.pc),
            Some(saved_pc)
        );
        assert_eq!(
            report.raw_stop_pc(),
            &super::AttemptObservation::Value(saved_pc)
        );
        assert_eq!(
            report.timeout_query(),
            &super::AttemptObservation::Value(false),
            "the native one-second deadline did not cause the deferred stop"
        );
        assert!(cpu.native_engine_identity_for_test().is_none());
    }

    #[test]
    fn global_code_hook_deferred_host_budget_has_typed_stop_reason() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-global-budget.exe")?;
        let mut cpu = phase1_global_hook_straight_line_cpu("phase1-global-budget.exe")?;
        let mut framebuffer = PausingFramebuffer {
            inner: VirtualFramebuffer::default_primary()?,
            ticks: 0,
        };
        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 1_000_000,
                wall_clock_limit_ms: 200,
                stop_pc: Some(0xdead_beef), // unreachable; selects the global hook
                live_pump: true,
            },
        );
        execution.result?;
        assert_eq!(framebuffer.ticks, 1, "the global hook serviced the pause");
        assert_global_deferred_hook_stop(
            &cpu,
            &execution.report,
            super::NativeHookStopReason::HostWallBudget,
        );
        Ok(())
    }

    #[test]
    fn global_code_hook_deferred_remote_control_has_typed_stop_reason() -> crate::Result<()> {
        let mut kernel = phase1_kernel("phase1-global-remote.exe")?;
        let mut cpu = phase1_global_hook_straight_line_cpu("phase1-global-remote.exe")?;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let server =
            crate::remote_server::RemoteServer::start(crate::remote_server::RemoteServerConfig {
                addr: "127.0.0.1:0".parse().unwrap(),
                ..crate::remote_server::RemoteServerConfig::default()
            })?;
        kernel.set_remote_server(server.clone());
        kernel.remote.set_framebuffer_size(800, 480);
        let thread_id = cpu.current_thread_id();
        let hwnd = kernel.create_window_ex_w(
            thread_id,
            "GLOBAL_REMOTE",
            "",
            None,
            0,
            crate::ce::gwe::WS_VISIBLE,
            0,
        );
        for _ in 0..16 {
            if kernel.gwe.get_message(thread_id).is_none() {
                break;
            }
        }
        server.enqueue_control_message_for_test(serde_json::json!({
            "type": "touch",
            "phase": "tap",
            "x": 12,
            "y": 34,
        }));
        assert_eq!(server.pending_control_count(), 1);
        let execution = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 1_000_000,
                wall_clock_limit_ms: 0,
                stop_pc: Some(0xdead_beef), // unreachable; selects the global hook
                live_pump: true,
            },
        );
        execution.result?;
        assert_global_deferred_hook_stop(
            &cpu,
            &execution.report,
            super::NativeHookStopReason::RemoteControlService,
        );
        assert_eq!(server.pending_control_count(), 0);
        let mut delivered = false;
        for _ in 0..64 {
            let Some(message) = kernel.gwe.get_message(thread_id) else {
                break;
            };
            delivered |= message.hwnd == hwnd && message.msg == crate::ce::gwe::WM_LBUTTONDOWN;
        }
        assert!(
            delivered,
            "the queued remote touch reached the guest window"
        );
        Ok(())
    }

    fn assert_sparse_hook_stop(
        cpu: &super::UnicornMips,
        report: &super::NativeAttemptReport,
        reason: super::NativeHookStopReason,
    ) {
        assert_eq!(
            cpu.last_native_slice_outcome(),
            super::NativeSliceOutcome::HookStop(reason)
        );
        let entry = cpu.entry.unwrap();
        let saved_pc = cpu.saved_context_pc().expect("saved sparse safe PC");
        let expected_offsets = match reason {
            super::NativeHookStopReason::HostWallBudget => 0x6000..0x9000,
            super::NativeHookStopReason::RemoteControlService
            | super::NativeHookStopReason::VisibleParkedPeerYield
            | super::NativeHookStopReason::ReadyParkedPeerYield => 0..0x1000,
        };
        let offset = saved_pc
            .checked_sub(entry)
            .expect("sparse stop below entry");
        assert!(
            expected_offsets.contains(&offset),
            "sparse stop must occur at its code-hook service point, not a later block-hook stop"
        );
        let snapshot = cpu.last_debug_snapshot().unwrap();
        assert_eq!(snapshot.pc, saved_pc);
        assert_eq!(
            snapshot.host_wall_clock_stop.as_ref().map(|stop| stop.pc),
            Some(saved_pc)
        );
        assert_eq!(
            report.raw_stop_pc(),
            &super::AttemptObservation::Value(saved_pc)
        );
        assert_eq!(
            report.timeout_query(),
            &super::AttemptObservation::Value(false),
            "the native deadline did not cause the sparse stop"
        );
        assert!(cpu.native_engine_identity_for_test().is_none());
    }

