    #[test]
    fn decoded_pseudo_exit_refuses_unrestorable_backing_before_exit_effects() -> crate::Result<()> {
        let (mut kernel, mut cpu, launch, worker_handle, heap_ptr) =
            decoded_child_pseudo_exit_cpu("decoded-child-backing.exe")?;
        let birth = launch.process_birth.expect("child birth");
        let caller = launch.primary_thread_birth.expect("primary birth");
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                caller,
                "DECODED_PSEUDO_BACKING",
                "saved image",
                None,
                None,
                0,
                crate::ce::gwe::WS_VISIBLE,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 4, 4),
            )
            .expect("birth-owned window");
        let source = VirtualFramebuffer::new(8, 8, crate::ce::framebuffer::PixelFormat::Rgb565)?;
        assert!(kernel.capture_window_backing_store(hwnd, &source));
        let mut incompatible =
            VirtualFramebuffer::new(8, 8, crate::ce::framebuffer::PixelFormat::Bgra8888)?;
        incompatible.pixels_mut().fill(0x5a);
        let pixels_before = incompatible.pixels().to_vec();

        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut incompatible,
            super::UnicornRunLimits {
                instruction_limit: 100,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        assert!(matches!(
            attempt.result,
            Err(crate::Error::HostExitRecoveryRequired {
                process_id,
                hwnd: Some(rejected),
                ..
            }) if process_id == launch.process_id && rejected == hwnd
        ));
        assert!(!cpu.active_process_execution_completed());
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert!(kernel.handles.thread_execution_live_by_id(launch.thread_id));
        assert!(kernel.handles.thread_execution_live_by_id(
            kernel.handles.thread_id(worker_handle).expect("worker TID")
        ));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert_eq!(
            kernel
                .memory
                .heap_size(birth, crate::ce::memory::PROCESS_HEAP_HANDLE, 0, heap_ptr),
            Some(16)
        );
        assert!(kernel.gwe.is_window(hwnd));
        assert_eq!(incompatible.pixels(), pixels_before.as_slice());
        Ok(())
    }

    #[test]
    fn decoded_forged_ra_branch_to_zero_cannot_complete_child_exit() -> crate::Result<()> {
        let mut kernel = phase1_kernel("decoded-forged-ra.exe")?;
        let launch =
            kernel.queue_process_launch(Some("\\Test\\decoded-forged-ra.exe".to_owned()), None);
        let birth = launch.process_birth.expect("child birth");
        let _ = kernel.take_pending_process_launches();
        kernel.set_current_process_id(launch.process_id);

        let entry = 0x0040_1000_u32;
        let return_pc = entry + 0x24;
        let mut bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x2405_0003,                        // addiu a1,zero,3
            0x2404_0042,                        // addiu a0,zero,66
            0x3c1f_0000 | (return_pc >> 16),    // forge RA high
            0x37ff_0000 | (return_pc & 0xffff), // forge RA low
            0x0000_0008,                        // jr zero, never reach JALR below
            0,
            0x2408_f3fa, // exit-shaped addiu t0,zero,-3078
            0x0100_f809, // exit-shaped jalr t0, never executed
            0,
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("decoded-forged-ra.exe", &bytes)?;
        assert_eq!(image.entry_point_va(), entry);
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.owned_process_launch = Some(launch.clone());
        cpu.set_initial_thread_id(launch.thread_id);
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[29] = cpu.stack_top.expect("fixture stack") - 0x100;
        cpu.saved_context = Some(super::SavedCpuContext { pc: entry, regs });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((launch.thread_id, launch.thread_handle));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;

        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 100,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        assert!(attempt.result.is_err(), "forged RA must not authorize exit");
        assert!(!cpu.active_process_execution_completed());
        assert!(matches!(
            super::classify_uncompleted_deferred_child(&cpu, &kernel),
            super::ChildProcessRunOutcome::Parked
        ));
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        Ok(())
    }

    #[test]
    fn decoded_static_exit_site_with_different_live_target_cannot_exit() -> crate::Result<()> {
        let (mut kernel, mut cpu, launch, _worker_handle, _heap_ptr) =
            decoded_child_pseudo_exit_cpu("decoded-stale-target.exe")?;
        let birth = launch.process_birth.expect("child birth");
        let entry = cpu.entry.expect("fixture entry");
        let saved = cpu.saved_context.as_mut().expect("fixture context");
        // Start at the static exit-shaped JALR without executing its preceding
        // ADDIU. The mapped words and eventual RA still look like an exit,
        // but the live source GPR points to zero, not the encoded method.
        saved.pc = entry + 8;
        saved.regs.regs[8] = 0;
        saved.regs.regs[4] = crate::ce::kernel::CE_CURRENT_PROCESS_PSEUDO_HANDLE;
        saved.regs.regs[5] = 3;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 100,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        assert!(
            attempt.result.is_err(),
            "live target mismatch must reject exit"
        );
        assert!(!cpu.active_process_execution_completed());
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        Ok(())
    }

    #[test]
    fn real_mips_direct_completed_skips_empty_held_parent_queue() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("direct-exit.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        std::fs::write(&child_path, tiny_mips_direct_pseudo_exit_pe()).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("direct-exit.exe".to_owned()), None);
        let child_birth = launch.process_birth.expect("exact child birth");
        let thread_birth = launch
            .primary_thread_birth
            .expect("exact primary thread birth");
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = BorrowParentQueueOnRestore {
            inner: VirtualFramebuffer::default_primary()?,
            parent_queue: parked.as_ref(),
            held_parent_borrow: None,
            restore_dirty_calls: 0,
        };
        let root_process_state = kernel.current_process_state();
        kernel.set_current_process_id(launch.process_id);
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                thread_birth,
                "DIRECT_EXIT_BORROW",
                "saved image",
                None,
                None,
                0,
                crate::ce::gwe::WS_VISIBLE,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 4, 4),
            )
            .expect("child birth-owned window");
        assert!(kernel.capture_window_backing_store(hwnd, &framebuffer));
        kernel.set_current_process_state(root_process_state);

        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let mut custody =
            super::CpuCustody::new().expect("completed child CPU custody initializes");
        let mut quarantined_child_fault = false;
        let attempt = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            super::run_pending_process_launches_with_custody(
                &mut root_uc,
                &mut kernel,
                root_pid,
                &guard,
                &mut framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 128,
                    wall_clock_limit_ms: 500,
                    stop_pc: None,
                    live_pump: false,
                },
                &[],
                &parked,
                Some(&mut custody),
                &mut quarantined_child_fault,
                None,
                None,
            )
        }));

        assert_eq!(framebuffer.restore_dirty_calls, 1, "real window restore");
        assert!(framebuffer.held_parent_borrow.is_some());
        assert!(!kernel.gwe.is_window(hwnd));
        assert_eq!(kernel.current_process_id(), root_pid);
        assert!(!kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(kernel.process_exit_code(launch.process_handle), Some(0x63));
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(true));
        assert_eq!(
            kernel
                .recent_process_ops()
                .iter()
                .filter(|record| {
                    record.op == "CreateProcessExited"
                        && record.process_id == Some(launch.process_id)
                })
                .count(),
            1,
            "exact child exit committed once"
        );
        assert!(parked.borrow().is_empty(), "no live descendant CPU to lose");
        let result = attempt.expect("Completed must not panic on a held parent queue");
        result?;
        Ok(())
    }

    #[test]
    fn real_mips_primary_return_completes_exact_child_process() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("primary-return.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        let mut child_image = tiny_mips_spinner_pe();
        write_vec_u32(&mut child_image, 0x200, 0x2402_0063); // addiu v0,zero,0x63
        write_vec_u32(&mut child_image, 0x204, 0x03e0_0008); // jr ra
        write_vec_u32(&mut child_image, 0x208, 0); // delay slot
        std::fs::write(&child_path, child_image).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("primary-return.exe".to_owned()), None);
        let owner = launch.process_birth.expect("queued child birth");
        let primary = launch
            .primary_thread_birth
            .expect("canonical primary birth");
        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let mut custody = super::CpuCustody::new().expect("primary child CPU custody initializes");
        let mut quarantined_child_fault = false;
        super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.set(None));
        let result = super::run_pending_process_launches_with_custody(
            &mut root_uc,
            &mut kernel,
            root_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            None,
        );
        let executed = super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.take());
        assert_eq!(executed, Some((THREAD_EXIT_STUB_ADDR, 0x63, primary)));
        result?;
        assert!(!kernel.handles.process_execution_live_by_birth(owner));
        assert_eq!(kernel.process_exit_code(launch.process_handle), Some(0x63));
        assert_eq!(
            kernel.guest_thread_exit_code(launch.thread_handle),
            Some(0x63)
        );
        assert!(
            parked.borrow().is_empty(),
            "completed child has no CPU to park"
        );
        Ok(())
    }

    #[test]
    fn real_mips_reused_primary_tid_worker_return_keeps_child_cpu_and_process() -> crate::Result<()>
    {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("reused-primary-tid.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        let mut child_image = tiny_mips_spinner_pe();
        write_vec_u32(&mut child_image, 0x200, 0x2402_0063); // addiu v0,zero,0x63
        write_vec_u32(&mut child_image, 0x204, 0x03e0_0008); // jr ra
        write_vec_u32(&mut child_image, 0x208, 0); // delay slot
        std::fs::write(&child_path, child_image).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("reused-primary-tid.exe".to_owned()), None);
        let owner = launch.process_birth.expect("queued child birth");
        let primary = launch
            .primary_thread_birth
            .expect("canonical primary birth");
        // This is an intentionally synthetic stale/reuse safety state, not a
        // normal CE main-thread lifetime: a separate live worker makes a
        // whole-process exit visibly wrong, but this fixture does not give
        // that worker an independently runnable CPU context. Create it only
        // after the original launch passes its exact-birth admission gate.
        let survivor_tid = launch.thread_id.checked_add(1).expect("fixture worker TID");
        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let late_births = std::cell::Cell::new(None);
        let post_admission =
            |kernel: &mut CeKernel, admitted: &crate::ce::kernel::PendingProcessLaunch| {
                assert_eq!(admitted, &launch);
                assert!(late_births.get().is_none(), "one admitted child mutation");
                assert_eq!(kernel.pending_process_launch_for_birth(owner), None);
                assert!(kernel.mark_guest_thread_exited(launch.thread_handle, 0x31));
                assert_eq!(
                    kernel.guest_thread_exit_code(launch.thread_handle),
                    Some(0x31)
                );
                assert!(kernel.close_handle(launch.thread_handle).unwrap());
                assert!(!kernel.handles.contains_thread_birth(primary));
                let survivor_handle = kernel
                    .handles
                    .try_create_thread_in_birth(owner, survivor_tid, 0, 0, false)
                    .unwrap();
                let survivor = kernel
                    .handles
                    .thread_birth_key_for_handle(survivor_handle)
                    .expect("independent live worker birth");
                // The allocator normally advances; inject numeric reuse
                // through the canonical birth API after CPU admission.
                let worker_handle = kernel
                    .handles
                    .try_create_thread_in_birth(owner, launch.thread_id, 0, 0, false)
                    .unwrap();
                let worker = kernel
                    .handles
                    .thread_birth_key_for_handle(worker_handle)
                    .expect("replacement worker birth");
                assert_ne!(worker, primary);
                assert_eq!(
                    kernel.handles.process_primary_thread_birth(owner),
                    Some(primary)
                );
                late_births.set(Some((survivor_handle, survivor, worker_handle, worker)));
            };
        let mut custody =
            super::CpuCustody::new().expect("reused-TID child CPU custody initializes");
        let mut quarantined_child_fault = false;
        super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.set(None));
        let result = super::run_pending_process_launches_with_custody(
            &mut root_uc,
            &mut kernel,
            root_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            Some(&post_admission),
        );
        let (survivor_handle, survivor, worker_handle, worker) =
            late_births.get().expect("post-admission mutation ran once");
        assert!(!quarantined_child_fault);
        assert_eq!(
            kernel.guest_thread_exit_code(survivor_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        let executed = super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.take());
        assert_eq!(
            executed,
            Some((THREAD_EXIT_STUB_ADDR, 0x63, worker)),
            "the replacement worker must execute the patched MIPS return stub in this attempt"
        );
        if let Err(error) = result {
            assert!(
                error.is_host_exit_recovery_required(),
                "unexpected child stop instead of checked recovery: {error}"
            );
        }

        assert!(
            kernel.handles.process_execution_live_by_birth(owner),
            "the replacement worker's real MIPS return must not complete its process"
        );
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.guest_thread_exit_code(worker_handle), Some(0x63));
        assert_eq!(
            kernel.handles.thread_birth_key_for_handle(survivor_handle),
            Some(survivor)
        );
        assert!(kernel.handles.thread_execution_live_by_id(survivor_tid));
        assert_eq!(
            kernel.handles.thread_creation_owner_by_id(survivor_tid),
            Some(owner)
        );
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            matches!(
                record.op,
                "CreateProcessExited" | "CreateProcessChildReturned"
            ) && record.process_id == Some(launch.process_id)
        }));
        let parked = parked.borrow();
        assert_eq!(parked.len(), 1, "the stopped child CPU must remain owned");
        let retained = parked.front().expect("parked child CPU");
        assert_eq!(retained.cpu.owned_process_launch.as_ref(), Some(&launch));
        assert!(!retained.cpu.completed_active_process_exit);
        assert_eq!(retained.cpu.current_thread_id, launch.thread_id);
        assert!(
            retained.cpu.run_slice_generation > 0,
            "the retained CPU must have executed a real MIPS slice"
        );
        assert_eq!(
            kernel.handles.process_primary_thread_birth(owner),
            Some(primary)
        );
        assert_eq!(
            kernel.handles.thread_birth_key_for_handle(worker_handle),
            Some(worker)
        );
        Ok(())
    }

    #[test]
    fn real_mips_missing_primary_birth_exit_requires_recovery_and_retains_cpu() -> crate::Result<()>
    {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("missing-primary.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        let mut child_image = tiny_mips_spinner_pe();
        write_vec_u32(&mut child_image, 0x200, 0x2402_0063); // addiu v0,zero,0x63
        write_vec_u32(&mut child_image, 0x204, 0x03e0_0008); // jr ra
        write_vec_u32(&mut child_image, 0x208, 0); // delay slot
        std::fs::write(&child_path, child_image).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("missing-primary.exe".to_owned()), None);
        let owner = launch.process_birth.expect("queued child birth");
        let original_primary = launch.primary_thread_birth.expect("launch primary birth");
        // Synthetic interrupted-publish state: the launch still names the
        // original primary, but its unpublished alias/record was rolled back.
        // A same-TID worker can run; it cannot become process-exit authority.
        // Inject this state after exact-birth child CPU admission.

        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let pixels_before = framebuffer.pixels().to_vec();
        let dirty_before = framebuffer.dirty_rects().to_vec();
        let late_worker = std::cell::Cell::new(None);
        let post_admission =
            |kernel: &mut CeKernel, admitted: &crate::ce::kernel::PendingProcessLaunch| {
                assert_eq!(admitted, &launch);
                assert!(late_worker.get().is_none(), "one admitted child mutation");
                assert_eq!(kernel.pending_process_launch_for_birth(owner), None);
                assert!(
                    kernel
                        .handles
                        .discard_unpublished_thread(launch.thread_handle, launch.thread_id)
                );
                assert_eq!(kernel.handles.process_primary_thread_birth(owner), None);
                let worker_handle = kernel
                    .handles
                    .try_create_thread_in_birth(owner, launch.thread_id, 0, 0, false)
                    .unwrap();
                let worker = kernel
                    .handles
                    .thread_birth_key_for_handle(worker_handle)
                    .expect("replacement worker birth");
                assert_ne!(worker, original_primary);
                late_worker.set(Some((worker_handle, worker)));
            };
        let mut custody = super::CpuCustody::new()
            .map_err(|error| Error::Backend(format!("fixture custody: {error}")))?;
        let mut quarantined_child_fault = false;
        super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.set(None));
        let result = super::run_pending_process_launches_with_custody(
            &mut root_uc,
            &mut kernel,
            root_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            Some(&post_admission),
        );
        let (worker_handle, worker) = late_worker.get().expect("post-admission mutation ran once");
        assert!(!quarantined_child_fault);
        let executed = super::TEST_NATIVE_EXIT_STUB_WITNESS.with(|witness| witness.take());
        assert_eq!(
            executed,
            Some((THREAD_EXIT_STUB_ADDR, 0x63, worker)),
            "guest MIPS must reach the raw exit stub in this attempt"
        );
        assert!(
            matches!(&result, Err(Error::Backend(message)) if message.contains("returned child CPU tree disagrees")),
            "missing primary must stop before returned-tree classification: {result:?}"
        );
        assert!(kernel.handles.process_execution_live_by_birth(owner));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(
            kernel.guest_thread_exit_code(worker_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            matches!(
                record.op,
                "CreateProcessExited" | "CreateProcessChildReturned"
            ) && record.process_id == Some(launch.process_id)
        }));
        assert_eq!(framebuffer.pixels(), pixels_before.as_slice());
        assert_eq!(framebuffer.dirty_rects(), dirty_before.as_slice());
        assert!(parked.borrow().is_empty(), "unverified CPU is not runnable");
        assert_eq!(custody.counts().unverified_stopped_trees, 1);
        assert_eq!(custody.counts().abandoned_unbound_trees, 0);
        let retained = custody.retained_tree_snapshots();
        assert_eq!(retained.len(), 1);
        assert_eq!(retained[0].origin_birth, owner);
        custody
            .with_retained_tree(retained[0].key, |tree| {
                assert_eq!(tree.owned_process_launch.as_ref(), Some(&launch));
                assert!(tree.private_slab_attempt_poisoned);
                assert!(!tree.completed_active_process_exit);
                assert_eq!(tree.saved_context_thread_birth, None);
                assert!(tree.saved_context.is_none());
                assert!(tree.run_slice_generation > 0);
            })
            .expect("failed exit retains the original child CPU tree");
        Ok(())
    }

    #[test]
    fn admitted_child_pre_entry_refusal_can_retire_quarantined_cpu() -> crate::Result<()> {
        const EXIT_CODE: u32 = 0x6c;
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("pre-entry-child.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        std::fs::write(&child_path, tiny_mips_spinner_pe()).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("pre-entry-child.exe".to_owned()), None);
        let child_birth = launch.process_birth.expect("exact child birth");
        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let mut custody = super::CpuCustody::new()
            .map_err(|error| Error::Backend(format!("create fixture CPU custody: {error}")))?;
        let mut quarantined_child_fault = false;

        // Synthetic precondition refusal: normal deferred launch occurs only
        // after the parent releases its native-entry permit. This exercises
        // the producer/consumer contract before B ever executes guest MIPS.
        let outer_native_entry = super::NativeGuestExecutionGuard::enter()?;
        let error = super::run_pending_process_launches_with_custody(
            &mut root_uc,
            &mut kernel,
            root_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            None,
        )
        .expect_err("nested native entry must refuse B before its first slice");
        drop(outer_native_entry);
        assert!(
            error.to_string().contains("nested native guest execution"),
            "pre-entry refusal: {error}"
        );
        assert!(quarantined_child_fault);
        assert_eq!(kernel.current_process_id(), root_pid);
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert_eq!(custody.counts().reserved, 0);
        assert_eq!(custody.counts().quarantined, 1);
        assert_eq!(custody.counts().abandoned_unbound_trees, 0);
        assert!(parked.borrow().is_empty(), "B has no legacy parked CPU");
        let snapshot = custody.snapshots().pop().expect("sole original B CPU");
        assert_eq!(snapshot.birth, child_birth);
        assert_eq!(snapshot.state, super::CpuCustodyState::Quarantined);
        assert_eq!(
            snapshot.native_outcome,
            Some(super::NativeSliceOutcome::NoAttempt)
        );
        assert!(snapshot.memory_fault.is_none());
        assert!(snapshot.mapped_blob_bytes > 0, "loaded B image is retained");
        custody
            .with_quarantined(snapshot.key, child_birth, |retained| {
                assert_eq!(retained.owned_process_launch.as_ref(), Some(&launch));
                assert_eq!(retained.run_slice_generation, 0);
                assert!(retained.private_slab_attempt_poisoned);
                assert!(retained.saved_context.is_none());
                assert_eq!(retained.saved_context_thread_birth, None);
                assert_eq!(retained.saved_worker_exit_birth, None);
                assert_eq!(retained.native_engine_identity_for_test(), None);
            })
            .map_err(|error| Error::Backend(format!("borrow child CPU custody: {error}")))?;

        assert!(kernel.terminate_process(launch.process_handle, EXIT_CODE));
        assert_eq!(
            custody.counts().quarantined,
            1,
            "request is not accepted exit"
        );
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        let mut root_cpu = super::UnicornMips::new()?;
        assert_eq!(
            root_cpu.try_complete_requested_quarantined_process_exits_with_framebuffer(
                &mut kernel,
                Some(&mut framebuffer),
                &mut custody,
            )?,
            1
        );
        assert!(!custody.has_any_custody());
        assert!(!kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(EXIT_CODE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(true));
        Ok(())
    }

    #[test]
    fn no_custody_child_launch_refuses_before_cpu_admission() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let root_path = test_root.join("root.exe");
        let child_path = test_root.join("child.exe");
        std::fs::write(&root_path, tiny_mips_spinner_pe()).unwrap();
        let mut child_image = tiny_mips_spinner_pe();
        write_vec_u32(&mut child_image, 0x200, 0x3c08_2000); // lui t0,0x2000
        write_vec_u32(&mut child_image, 0x204, 0x8d02_0000); // lw v0,0(t0): READ_UNMAPPED
        std::fs::write(&child_path, child_image).unwrap();

        let mut kernel = phase1_kernel("root.exe")?;
        kernel.set_process_module_host_path(root_path);
        let root_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("child.exe".to_owned()), None);
        let child_birth = launch.process_birth.expect("exact child birth");
        let mut root_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native root: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let admission_seen = std::cell::Cell::new(false);
        let admission_observer = |_: &mut CeKernel, _: &crate::ce::kernel::PendingProcessLaunch| {
            admission_seen.set(true);
        };
        let mut quarantined_child_fault = false;
        let error = super::run_pending_process_launches_with_custody(
            &mut root_uc,
            &mut kernel,
            root_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            None,
            &mut quarantined_child_fault,
            None,
            Some(&admission_observer),
        )
        .expect_err("a child CPU must not be admitted without machine custody");
        assert!(
            !admission_seen.get(),
            "child was admitted without custody: error={error}; exact_pending={}; live={}; parked={}",
            kernel
                .pending_process_launch_for_birth(child_birth)
                .is_some(),
            kernel.handles.process_execution_live_by_birth(child_birth),
            parked.borrow().len()
        );
        assert!(
            matches!(error, Error::Backend(ref message) if message.contains("requires machine custody")),
            "typed pre-admission refusal: {error}"
        );
        assert_eq!(
            kernel.pending_process_launch_for_birth(child_birth),
            Some(&launch)
        );
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert!(parked.borrow().is_empty());
        assert!(!quarantined_child_fault);
        Ok(())
    }

    #[test]
    fn ordinary_first_slice_native_fault_retains_admitted_child_cpu() -> crate::Result<()> {
        const STACK_VALUE: u32 = 0x7e31_a5c2;
        const EXIT_CODE: u32 = 0x6b;
        let stack_page = super::IMPORT_TRAP_BASE - 0x10000 - 0x3000;
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        let child_path = test_root.join("survivor.exe");
        std::fs::write(&parent_path, tiny_mips_create_process_then_spin_pe()).unwrap();
        let mut child_bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x3c08_0000 | (stack_page >> 16),    // lui t0, fixed stack page high
            0x3508_0000 | (stack_page & 0xffff), // ori t0, t0, fixed stack page low
            0x3c09_0000 | (STACK_VALUE >> 16),   // lui t1, stack value high
            0x3529_0000 | (STACK_VALUE & 0xffff), // ori t1, t1, stack value low
            0xad09_0000,                         // sw t1, 0(t0): native first touch
            0x8d0a_0000,                         // lw t2, 0(t0): guest readback
            0x2550_0001,                         // addiu s0,t2,1: reached past load
            0x3c0b_2000,                         // lui t3,0x2000
            0x8d62_0000,                         // lw v0,0(t3): native read fault
            0x2403_55aa,                         // must not execute
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut child_bytes, 0x200 + index * 4, word);
        }
        std::fs::write(&child_path, child_bytes).unwrap();

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path.clone());
        let parent_birth = kernel.current_process_birth_key().expect("parent birth");
        let image = crate::pe::PeImage::inspect(&parent_path)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        let parent_entry = cpu.entry.expect("parent entry");
        let mut custody = super::CpuCustody::new()
            .map_err(|error| Error::Backend(format!("create fixture CPU custody: {error}")))?;
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        assert!(
            kernel
                .handles
                .file_mappings()
                .all(|mapping| mapping.views.is_empty())
        );
        let first = cpu.run_until_import_trap_with_framebuffer_limits_report_with_custody(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &mut custody,
        );
        let error = first
            .result
            .expect_err("guest-created child must encounter its native read fault");
        assert!(
            matches!(error, Error::Backend(_)),
            "ordinary fault: {error}"
        );
        assert_eq!(first.report.start_process_birth(), Some(parent_birth));
        assert_eq!(
            first.report.raw_stop_pc(),
            &super::AttemptObservation::Value(parent_entry + 18 * 4),
            "A executed its CreateProcessW import before the deferred B slice"
        );
        assert_eq!(
            first.report.failure_operation(),
            Some("deferred child CPU execution")
        );
        let parent_saved = cpu.saved_context.as_ref().expect("staged A return context");
        assert_eq!(parent_saved.pc, parent_entry + 18 * 4);
        assert_eq!(parent_saved.regs.regs[2], 1, "CreateProcessW BOOL return");
        assert_eq!(
            parent_saved.regs.regs[17], 0,
            "A did not replay past the import"
        );
        assert!(!cpu.private_slab_attempt_poisoned);
        assert_eq!(kernel.current_process_birth_key(), Some(parent_birth));
        assert!(!kernel.has_pending_process_launches());

        let queued: Vec<_> = kernel
            .recent_process_ops()
            .iter()
            .filter(|record| record.op == "CreateProcessWQueued")
            .collect();
        assert_eq!(queued.len(), 1, "one executed guest CreateProcessW");
        let child_handle = queued[0].process_handle.expect("child process handle");
        let child_tid = queued[0].thread_id.expect("child thread ID");
        let child_birth = kernel
            .handles
            .process_birth_key_for_handle(child_handle)
            .expect("exact child birth");
        assert_eq!(queued[0].process_id, Some(child_birth.process_id()));
        assert_eq!(
            kernel
                .handles
                .process_primary_thread_birth(child_birth)
                .map(|birth| birth.thread_id()),
            Some(child_tid)
        );
        let child_error = kernel
            .recent_process_ops()
            .iter()
            .find(|record| {
                record.op == "CreateProcessChildError"
                    && record.process_id == Some(child_birth.process_id())
            })
            .expect("child loaded and attempted its first native slice");
        assert_eq!(
            child_error.path.as_deref(),
            Some(child_path.to_str().unwrap())
        );
        assert!(
            child_error
                .error
                .as_deref()
                .is_some_and(|error| error.contains("Unicorn run failed: READ_UNMAPPED")),
            "child failure must be the injected native read fault: {:?}",
            child_error.error
        );
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(
            kernel.process_exit_code(child_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(child_handle, 1), Some(false));
        assert_eq!(custody.counts().reserved, 0);
        assert_eq!(custody.counts().quarantined, 1);
        assert_eq!(custody.counts().abandoned_unbound_trees, 0);
        assert!(
            cpu.parked_child_processes.is_empty(),
            "B is not a legacy parked CPU"
        );
        let snapshots = custody.snapshots();
        assert_eq!(snapshots.len(), 1, "sole original B CPU owner");
        let child = &snapshots[0];
        assert_eq!(child.birth, child_birth);
        assert_eq!(child.state, super::CpuCustodyState::Quarantined);
        assert_eq!(
            custody
                .snapshot_exact(child.key, child_birth)
                .map_err(|error| Error::Backend(format!("inspect child CPU custody: {error}")))?,
            *child
        );
        assert_eq!(
            child.native_outcome,
            Some(super::NativeSliceOutcome::NativeError)
        );
        let fault = child.memory_fault.as_ref().expect("native memory fault");
        assert_eq!(fault.address, 0x2000_0000);
        assert_eq!(fault.pc, 0x0040_1000 + 8 * 4);
        assert!(fault.access.contains("READ_UNMAPPED"));
        custody
            .with_quarantined(child.key, child_birth, |retained| {
                assert_eq!(
                    retained
                        .owned_process_launch
                        .as_ref()
                        .and_then(|launch| launch.process_birth),
                    Some(child_birth)
                );
                assert!(retained.private_slab_attempt_poisoned);
                assert!(retained.saved_context.is_none());
                assert!(retained.run_slice_generation > 0);
                assert!(retained.parked_child_processes.is_empty());
                assert_eq!(retained.native_engine_identity_for_test(), None);
            })
            .map_err(|error| Error::Backend(format!("borrow child CPU custody: {error}")))?;
        let pin = kernel
            .memory
            .private_page_pin(child_birth, stack_page)
            .expect("B's real MIPS store committed its fixed stack page");
        assert_eq!(pin.identity().owner(), child_birth);
        assert!(pin.is_host_block_backed());
        let mut stored = [0_u8; 4];
        pin.read_bytes(0, &mut stored)
            .expect("canonical B stack value");
        assert_eq!(u32::from_le_bytes(stored), STACK_VALUE);
        assert!(
            kernel
                .handles
                .file_mappings()
                .all(|mapping| mapping.views.is_empty())
        );

        assert!(kernel.terminate_process(child_handle, EXIT_CODE));
        assert_eq!(
            custody.counts().quarantined,
            1,
            "request is not accepted exit"
        );
        assert!(kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(kernel.is_wait_ready(child_handle, 1), Some(false));
        assert_eq!(
            cpu.try_complete_requested_quarantined_process_exits_with_framebuffer(
                &mut kernel,
                Some(&mut framebuffer),
                &mut custody,
            )?,
            1
        );
        assert!(!custody.has_any_custody());
        assert!(cpu.parked_child_processes.is_empty());
        assert!(!kernel.handles.process_execution_live_by_birth(child_birth));
        assert_eq!(kernel.process_exit_code(child_handle), Some(EXIT_CODE));
        assert_eq!(kernel.is_wait_ready(child_handle, 1), Some(true));
        assert!(kernel.memory.private_page_pins_for(child_birth).is_empty());
        Ok(())
    }

    #[test]
    fn deferred_child_forged_ra_branch_to_zero_cannot_report_exit() -> crate::Result<()> {
        let test_root = create_process_timeout_test_root();
        let _cleanup = TestDirectoryCleanup(test_root.clone());
        std::fs::create_dir_all(&test_root).unwrap();
        let parent_path = test_root.join("parent.exe");
        let child_path = test_root.join("child.exe");
        std::fs::write(&parent_path, tiny_mips_spinner_pe()).unwrap();
        let entry = 0x0040_1000_u32;
        let return_pc = entry + 0x24;
        let mut child_bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x2405_0003,                        // addiu a1,zero,3
            0x2404_0042,                        // addiu a0,zero,66
            0x3c1f_0000 | (return_pc >> 16),    // forge RA high
            0x37ff_0000 | (return_pc & 0xffff), // forge RA low
            0x0000_0008,                        // jr zero, never reach JALR
            0,
            0x2408_f3fa, // exit-shaped addiu t0,zero,-3078
            0x0100_f809, // exit-shaped jalr t0, never executed
            0,
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut child_bytes, 0x200 + index * 4, word);
        }
        std::fs::write(&child_path, child_bytes).unwrap();

        let mut kernel = phase1_kernel("parent.exe")?;
        kernel.set_process_module_host_path(parent_path);
        let parent_pid = kernel.current_process_id();
        let launch = kernel.queue_process_launch(Some("child.exe".to_owned()), None);
        let birth = launch.process_birth.expect("child birth");
        let mut parent_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN)
            .map_err(|err| Error::Backend(format!("fixture native parent: {err:?}")))?;
        let guard = super::SealedHostWriteGuard::default();
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let mut custody =
            super::CpuCustody::new().expect("forged-return child CPU custody initializes");
        let mut quarantined_child_fault = false;
        let error = super::run_pending_process_launches_with_custody(
            &mut parent_uc,
            &mut kernel,
            parent_pid,
            &guard,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 100,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
            &[],
            &parked,
            Some(&mut custody),
            &mut quarantined_child_fault,
            None,
            None,
        )
        .expect_err("forged child exit must fail closed");
        assert!(matches!(
            error,
            Error::HostExitAuthorityRecoveryRequired { .. }
        ));
        assert!(kernel.handles.process_execution_live_by_birth(birth));
        assert_eq!(
            kernel.process_exit_code(launch.process_handle),
            Some(crate::ce::kernel::STILL_ACTIVE)
        );
        assert_eq!(kernel.is_wait_ready(launch.process_handle, 1), Some(false));
        assert!(!kernel.recent_process_ops().iter().any(|record| {
            record.op == "CreateProcessChildReturned"
                && record.process_id == Some(launch.process_id)
        }));
        Ok(())
    }

    #[test]
    fn branch_likely_trampoline_annuls_delay_slot_when_condition_is_false() {
        let pc = 0x6002_4220;
        let stub_pc = 0x6002_a000;
        let branch = super::decode_mips_branch_likely(0x0683_0003).unwrap();
        let words = super::branch_likely_stub_words(pc, branch, 0x2442_0001, stub_pc).unwrap();

        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x6002_4000, 0x0000_7000, Prot::ALL).unwrap();
        write_words(&mut uc, stub_pc, &words);
        uc.reg_write(RegisterMIPS::S4, u64::MAX).unwrap();
        uc.reg_write(RegisterMIPS::V0, 41).unwrap();

        uc.emu_start(u64::from(stub_pc), 0, 0, 4).unwrap();

        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap(), u64::from(pc + 8));
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap(), 41);
    }

