    #[test]
    fn saved_context_does_not_resurrect_blocked_get_message_receiver() -> crate::Result<()> {
        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let thread_id = super::MAIN_GUEST_THREAD_ID;
        let birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("boot receiver birth");
        let wait_id = kernel.register_blocked_waiter(
            thread_id,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                hwnd: None,
                min_msg: 0,
                max_msg: 0,
            },
            0,
            crate::ce::timer::INFINITE,
        );
        assert_ne!(wait_id, 0);
        let blocked = super::BlockedGuestThread {
            wait_id,
            thread_id,
            thread_birth: birth,
            thread_handle: crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
            regs: super::MipsGuestContext::zero(),
            import_pc: 0x7fff_0420,
            return_pc: 0x0040_1000,
            msg_ptr: 0,
            hwnd: None,
            min_msg: 0,
            max_msg: 0,
        };
        let mut running_thread = None;
        assert!(!super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(birth),
            &[],
            Some(&blocked),
            &[],
            &mut running_thread,
        ));
        assert_eq!(running_thread, None);
        assert!(!super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(birth),
            &[],
            None,
            std::slice::from_ref(&blocked),
            &mut running_thread,
        ));
        assert_eq!(running_thread, None);
        let mut stale = blocked;
        stale.wait_id = wait_id + 100;
        assert!(!super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(birth),
            &[],
            Some(&stale),
            &[],
            &mut running_thread,
        ));
        assert_eq!(running_thread, None);
        Ok(())
    }

    #[test]
    fn saved_context_does_not_resurrect_same_birth_orphaned_get_message_payload()
    -> crate::Result<()> {
        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let sender_thread_id = super::MAIN_GUEST_THREAD_ID;
        let sender_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let sender_birth = kernel
            .live_thread_birth_key_by_id(sender_thread_id)
            .expect("boot sender birth");
        let (receiver_handle, receiver_thread_id) =
            kernel.create_guest_thread(0x0040_3000, 0, false);
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread_id)
            .expect("live receiver birth");
        assert_eq!(
            kernel.handles.thread_birth_key_for_handle(receiver_handle),
            Some(receiver_birth)
        );
        // This is an ordinary live window, not the temporary wait gap while a
        // modal dialog is being dismissed.
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "ORPHANED_GET_MESSAGE_RECEIVER",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned live receiver HWND");
        let started_ms = kernel.timers.tick_count();
        let get_wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                receiver_birth,
                receiver_handle,
                Vec::new(),
                crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                    hwnd: Some(hwnd),
                    min_msg: 0,
                    max_msg: 0,
                },
                started_ms,
                crate::ce::timer::INFINITE,
            )
            .expect("exact receiver GetMessage wait");
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[16] = 0xb0b0_0011;
        receiver_regs.regs[29] = 0x3000_0800;
        receiver_regs.regs[31] = 0x0040_3008;
        receiver_regs.hi = 0xb0b0_0022;
        receiver_regs.lo = 0xb0b0_0033;
        receiver_regs.fprs[0] = 0x0000_0000_b0b0_0044;
        let blocked = super::BlockedGuestThread {
            wait_id: get_wait_id,
            thread_id: receiver_thread_id,
            thread_birth: receiver_birth,
            thread_handle: receiver_handle,
            regs: receiver_regs,
            import_pc: super::IMPORT_TRAP_BASE + 0x700,
            return_pc: 0x0040_3008,
            msg_ptr: 0x3000_0400,
            hwnd: Some(hwnd),
            min_msg: 0,
            max_msg: 0,
        };
        let blocked_before = blocked.clone();
        assert_eq!(
            super::verified_get_message_wait_birth(
                &kernel,
                get_wait_id,
                receiver_thread_id,
                receiver_handle,
            ),
            Some(receiver_birth)
        );

        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 0x7a,
                0x55,
                0x66,
                None,
            )
            .expect("one ordinary birth-owned queued send");
        let sender_wait_kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id,
            result_ptr: None,
            previous_running_thread: Some((sender_thread_id, sender_handle)),
        };
        let sender_wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                sender_birth,
                sender_handle,
                Vec::new(),
                super::scheduler_blocked_wait_kind(sender_wait_kind),
                started_ms,
                crate::ce::timer::INFINITE,
            )
            .expect("exact sender SendMessage wait");
        let sender_native_wait = super::BlockedWaitThread {
            frame_ref: None,
            wait_id: sender_wait_id,
            thread_id: sender_thread_id,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind: sender_wait_kind,
            wait_started_ms: started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0x0040_2008,
        };
        assert_eq!(
            super::verified_native_send_wait_birth(&kernel, &sender_native_wait),
            Some(sender_birth)
        );

        // Fault-inject only the scheduler index. B's exact birth, HWND and
        // captured native GetMessage payload still exist; A's send stays pending.
        assert!(kernel.remove_blocked_waiter(get_wait_id).is_some());
        assert!(kernel.blocked_waiter(get_wait_id).is_none());
        assert_eq!(
            super::verified_get_message_wait_birth(
                &kernel,
                get_wait_id,
                receiver_thread_id,
                receiver_handle,
            ),
            None
        );
        let mut running_thread = None;
        let recovered = super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            receiver_thread_id,
            Some(receiver_birth),
            std::slice::from_ref(&sender_native_wait),
            Some(&blocked),
            &[],
            &mut running_thread,
        );

        assert_eq!(blocked, blocked_before);
        assert_eq!(
            kernel.live_thread_birth_key_by_id(receiver_thread_id),
            Some(receiver_birth)
        );
        assert_eq!(
            kernel.handles.thread_birth_key_for_handle(receiver_handle),
            Some(receiver_birth)
        );
        assert!(
            kernel
                .gwe
                .window(hwnd)
                .is_some_and(|window| !window.destroyed)
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![send_id]
        );
        let send = kernel
            .gwe
            .sent_message(send_id)
            .expect("A send remains queued");
        assert_eq!(send.receiver_birth, Some(receiver_birth));
        assert_eq!(send.result, None);
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread_id), None);
        assert_eq!(
            kernel
                .blocked_waiter(sender_wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(sender_birth)
        );
        assert_eq!(
            super::verified_native_send_wait_birth(&kernel, &sender_native_wait),
            Some(sender_birth)
        );
        assert!(
            !recovered,
            "missing exact B wait must not revive B from saved GetMessage payload"
        );
        assert_eq!(running_thread, None);
        Ok(())
    }

    #[test]
    fn saved_context_recovery_does_not_borrow_reused_tid_or_stale_wait() -> crate::Result<()> {
        let mut kernel = CeKernel::boot(crate::config::RuntimeConfig::load_default()?);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let (old_handle, thread_id) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let old_birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("old worker birth");
        assert!(kernel.mark_guest_thread_exited_by_birth(old_birth, 0));
        assert!(kernel.close_handle(old_handle)?);
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, thread_id, 0x0040_4000, 0, false)?;
        let new_birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("reused worker birth");
        assert_ne!(old_birth, new_birth);
        assert!(
            super::validate_saved_context_birth_for_native_entry(
                &kernel,
                thread_id,
                Some(old_birth),
                0x0040_3000,
            )
            .is_err()
        );
        let mut running_thread = None;
        assert!(!super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(old_birth),
            &[],
            None,
            &[],
            &mut running_thread,
        ));
        assert_eq!(running_thread, None);

        let stale_sleep_wait_id = kernel
            .scheduler
            .register_blocked_wait_for_birth_with_keys_and_pins(
                old_birth,
                old_handle,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                crate::ce::scheduler::SchedulerBlockedWaitKind::Sleep,
                0,
                crate::ce::timer::INFINITE,
            );
        let stale_native_wait = super::BlockedWaitThread {
            frame_ref: None,
            wait_id: stale_sleep_wait_id,
            thread_id,
            thread_handle: old_handle,
            wait_handles: Vec::new(),
            kind: super::BlockedWaitKind::Sleep,
            wait_started_ms: 0,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0x0040_3000,
        };
        assert!(super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(new_birth),
            &[stale_native_wait],
            None,
            &[],
            &mut running_thread,
        ));
        assert_eq!(running_thread, Some((thread_id, new_handle)));

        let stale_get_wait_id = kernel
            .scheduler
            .register_blocked_wait_for_birth_with_keys_and_pins(
                old_birth,
                old_handle,
                Vec::new(),
                Vec::new(),
                Vec::new(),
                crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage {
                    hwnd: None,
                    min_msg: 0,
                    max_msg: 0,
                },
                0,
                crate::ce::timer::INFINITE,
            );
        let stale_get_message = super::BlockedGuestThread {
            wait_id: stale_get_wait_id,
            thread_id,
            thread_birth: old_birth,
            thread_handle: old_handle,
            regs: super::MipsGuestContext::zero(),
            import_pc: 0x7fff_0420,
            return_pc: 0x0040_3000,
            msg_ptr: 0,
            hwnd: None,
            min_msg: 0,
            max_msg: 0,
        };
        running_thread = None;
        assert!(super::recover_running_guest_thread_for_saved_context(
            &kernel,
            true,
            thread_id,
            Some(new_birth),
            &[],
            Some(&stale_get_message),
            &[],
            &mut running_thread,
        ));
        assert_eq!(running_thread, Some((thread_id, new_handle)));
        // R: the old payload can share the numeric TID and import PC with
        // B-prime, but neither the late replay fence nor recovery may borrow
        // its old birth to condemn the replacement's fresh native entry.
        let uc = unicorn_engine::Unicorn::new(
            unicorn_engine::Arch::MIPS,
            unicorn_engine::Mode::MIPS32 | unicorn_engine::Mode::LITTLE_ENDIAN,
        )
        .expect("native R fixture");
        let current = super::NativeCurrentThread::new(thread_id, Some(new_birth));
        assert_eq!(
            super::orphaned_blocked_get_message_wait_before_native_entry(
                &kernel,
                &uc,
                &current,
                stale_get_message.import_pc,
                Some(&stale_get_message),
                &[],
                &[],
            ),
            None,
        );
        Ok(())
    }

    #[test]
    fn native_finite_sleep_defers_active_sent_callout_for_same_receiver() -> crate::Result<()> {
        use crate::ce::coredll_ordinals::ORD_SLEEP;
        use crate::emulator::imports::{ImportModuleKind, ImportTrap};

        let trap = super::IMPORT_TRAP_BASE + 0x400;
        let mut image_bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x3c19_0000 | (trap >> 16),
            0x3739_0000 | (trap & 0xffff),
            0x0320_f809, // jalr t9: real MIPS call into the Sleep import
            0,
            0x1000_ffff, // displaced peer spins until the bounded count stop
            0,
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut image_bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("sleep-sent-callout.exe", &image_bytes)?;
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .handles
            .thread_birth_key_by_id(receiver_thread)
            .expect("boot receiver birth");
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(receiver_thread);
        cpu.import_traps.insert(ImportTrap {
            address: trap,
            module_kind: ImportModuleKind::Coredll,
            module_name: "COREDLL.dll".to_owned(),
            ordinal: Some(ORD_SLEEP),
            name: Some("Sleep".to_owned()),
            iat_va: 0,
        });
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let entry = cpu.entry.expect("fixture entry");
        let sleep_return_pc = entry + 16;
        let receiver_sp = cpu.stack_top.expect("fixture stack") - 0x100;
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[4] = 10_000;
        receiver_regs.regs[16] = 0xa1a1_0010;
        receiver_regs.regs[29] = receiver_sp;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: entry,
            regs: receiver_regs,
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((
            receiver_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ));

        // A ready displaced peer prevents the implementation's inline Sleep
        // shortcut and gives the native attempt a real context to run next.
        let (peer_handle, peer_thread) = kernel.create_guest_thread(sleep_return_pc, 0, false);
        let peer_birth = kernel
            .handles
            .thread_birth_key_by_id(peer_thread)
            .expect("live peer birth");
        let mut peer_regs = super::MipsGuestContext::zero();
        peer_regs.regs[29] = receiver_sp - 0x100;
        cpu.suspended_guest_thread = Some(super::SuspendedGuestThread {
            thread_id: peer_thread,
            thread_birth: Some(peer_birth),
            thread_handle: Some(peer_handle),
            regs: peer_regs,
            pc: sleep_return_pc,
        });

        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "FINITE_SLEEP_RECEIVER", "", None, 0, 0, 0);
        let wndproc = entry + 0x40;
        assert!(
            kernel
                .gwe
                .set_window_long(hwnd, GWL_WNDPROC, wndproc)
                .is_some()
        );
        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        attempt.result?;
        assert!(
            attempt.report.attempt_id().is_some(),
            "native MIPS attempt did not start"
        );
        let sleep = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(wait.kind, super::BlockedWaitKind::Sleep)
            })
            .cloned()
            .expect("real MIPS Sleep must retain a native wait payload");
        assert_eq!(sleep.return_pc, sleep_return_pc);
        assert_eq!(sleep.regs.regs[16], 0xa1a1_0010);
        assert_eq!(sleep.regs.regs[29], receiver_sp);
        assert_eq!(sleep.timeout_ms, 10_001);
        let scheduler_wait = kernel
            .blocked_waiter(sleep.wait_id)
            .expect("Sleep must retain its exact scheduler wait");
        assert_eq!(scheduler_wait.owner_birth, Some(receiver_birth));
        assert_eq!(cpu.current_thread_id, peer_thread);

        // This is the kernel/GWE transaction produced by a no-timeout
        // cross-process SendMessageW. The sender import itself is not run by
        // this receiver-side fixture; the active main-loop selector is.
        let launch = kernel.queue_process_launch(Some("\\Test\\sleep-sender.exe".to_owned()), None);
        let _ = kernel.take_pending_process_launches();
        let receiver_process = kernel.current_process_id();
        kernel.set_current_process_id(launch.process_id);
        let send_id = kernel
            .begin_cross_thread_send_message_w(
                launch.thread_id,
                hwnd,
                crate::ce::gwe::WM_USER + 0x71,
                0x55,
                0,
                None,
            )
            .expect("cross-process no-timeout send queued");
        kernel.set_current_process_id(receiver_process);
        assert!(kernel.thread_has_pending_sent_message(receiver_thread));
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(cpu.tracked_thread_ids().contains(&receiver_thread));

        let entered = cpu.prepare_active_sent_message_callout(&mut kernel);
        assert!(
            !entered,
            "active sent-callout selector entered WNDPROC for finite-Sleep receiver: wait={} send={} active_send={:?}",
            sleep.wait_id,
            send_id,
            kernel.gwe.active_sent_message_id(receiver_thread),
        );
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert!(kernel.thread_has_pending_sent_message(receiver_thread));
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(kernel.blocked_waiter(sleep.wait_id).is_some());
        assert_eq!(cpu.blocked_wait_threads.len(), 1);
        assert_eq!(cpu.blocked_wait_threads[0].wait_id, sleep.wait_id);
        assert_eq!(cpu.blocked_wait_threads[0].regs, sleep.regs);
        assert_eq!(cpu.blocked_wait_threads[0].return_pc, sleep.return_pc);
        assert_eq!(cpu.current_thread_id, peer_thread);
        Ok(())
    }

    #[derive(Clone, Copy)]
    enum NativeSleepSendRetrieval {
        GetMessageW,
        PeekRemove,
        GetMessageWNoWait,
    }

