    fn native_modal_button_tap_fixture(remove_modal_wait: bool) -> crate::Result<()> {
        use crate::ce::coredll_ordinals::ORD_GET_MESSAGE_W;
        use crate::ce::{
            coredll::CoredllGuestMemory,
            gwe::{Point, WM_LBUTTONUP, WM_PAINT},
            scheduler::SchedulerBlockedWaitKind,
            timer::INFINITE,
        };
        use crate::emulator::imports::{ImportModuleKind, ImportTrap};

        #[derive(Default)]
        struct ModalTextMemory {
            bytes: BTreeMap<u32, u8>,
        }

        impl CoredllGuestMemory for ModalTextMemory {
            fn read_u8(&self, addr: u32) -> crate::Result<u8> {
                Ok(self.bytes.get(&addr).copied().unwrap_or(0))
            }

            fn write_u8(&mut self, addr: u32, value: u8) -> crate::Result<()> {
                self.bytes.insert(addr, value);
                Ok(())
            }

            fn read_u32(&self, addr: u32) -> crate::Result<u32> {
                let mut bytes = [0; 4];
                self.read_bytes(addr, &mut bytes)?;
                Ok(u32::from_le_bytes(bytes))
            }

            fn write_u32(&mut self, addr: u32, value: u32) -> crate::Result<()> {
                self.write_bytes(addr, &value.to_le_bytes())
            }

            fn read_u16(&self, addr: u32) -> crate::Result<u16> {
                let mut bytes = [0; 2];
                self.read_bytes(addr, &mut bytes)?;
                Ok(u16::from_le_bytes(bytes))
            }

            fn write_u16(&mut self, addr: u32, value: u16) -> crate::Result<()> {
                self.write_bytes(addr, &value.to_le_bytes())
            }
        }

        let mut image_bytes = tiny_mips_spinner_pe();
        write_vec_u32(&mut image_bytes, 0x200, 0x2610_0001); // addiu s0, s0, 1
        write_vec_u32(&mut image_bytes, 0x204, 0x1000_ffff); // spin after one instruction
        let image = crate::pe::PeImage::parse_bytes("modal-get-message-gap.exe", &image_bytes)?;
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let thread_id = super::MAIN_GUEST_THREAD_ID;
        let birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("boot modal thread birth");
        let thread_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(thread_id);
        let entry = cpu.entry.expect("fixture entry");
        let get_trap = super::IMPORT_TRAP_BASE + 0x700;
        cpu.import_traps.insert(ImportTrap {
            address: get_trap,
            module_kind: ImportModuleKind::Coredll,
            module_name: "COREDLL.dll".to_owned(),
            ordinal: Some(ORD_GET_MESSAGE_W),
            name: Some("GetMessageW".to_owned()),
            iat_va: 0,
        });
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);

        let mut memory = ModalTextMemory::default();
        let text_ptr = 0x2000;
        let caption_ptr = 0x2100;
        for (addr, value) in [(text_ptr, "Continue"), (caption_ptr, "Modal")].into_iter() {
            for (index, unit) in value.encode_utf16().chain(std::iter::once(0)).enumerate() {
                memory.write_u16(addr + index as u32 * 2, unit)?;
            }
        }
        let modal_state = crate::ce::coredll::message_box_w_prepare(
            &mut kernel,
            &memory,
            None,
            None,
            thread_id,
            &[0, text_ptr, caption_ptr, 0],
        )
        .map_err(|result| Error::Backend(format!("prepare MessageBoxW returned {result}")))?;
        let dialog = modal_state.dialog_hwnd();
        let button = kernel
            .gwe
            .get_dlg_item(dialog, 1)
            .expect("MessageBox OK button");
        let modal_wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                birth,
                thread_handle,
                Vec::new(),
                SchedulerBlockedWaitKind::ModalMessageBox {
                    dialog_hwnd: dialog,
                },
                kernel.timers.tick_count(),
                INFINITE,
            )
            .expect("birth-owned modal wait");
        let get_wait_id = kernel
            .try_register_opaque_waiter_for_birth(
                birth,
                thread_handle,
                Vec::new(),
                SchedulerBlockedWaitKind::GetMessage {
                    hwnd: Some(dialog),
                    min_msg: WM_PAINT,
                    max_msg: WM_LBUTTONUP,
                },
                kernel.timers.tick_count(),
                INFINITE,
            )
            .expect("birth-owned dialog GetMessage wait");
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[29] = cpu.stack_top.expect("fixture stack") - 0x100;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: get_trap,
            regs: regs.clone(),
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.current_thread_id = thread_id;
        cpu.running_guest_thread = None;
        cpu.blocked_guest_thread = Some(super::BlockedGuestThread {
            wait_id: get_wait_id,
            thread_id,
            thread_birth: birth,
            thread_handle,
            regs: regs.clone(),
            import_pc: get_trap,
            return_pc: entry,
            msg_ptr: regs.regs[29] - 0x400,
            hwnd: Some(dialog),
            min_msg: WM_PAINT,
            max_msg: WM_LBUTTONUP,
        });
        cpu.blocked_modal_message_box = Some(super::BlockedModalMessageBox {
            wait_id: modal_wait_id,
            thread_id,
            thread_handle,
            regs,
            return_pc: entry,
            modal_state,
        });

        kernel.remote.set_framebuffer_size(800, 480);
        let rect = kernel
            .gwe
            .get_window_rect(button)
            .expect("button screen rect");
        let point = Point {
            x: rect.left + rect.width() / 2,
            y: rect.top + rect.height() / 2,
        };
        assert_eq!(
            kernel.gwe.window_from_point_for_thread(thread_id, point),
            Some(button)
        );
        kernel
            .remote
            .enqueue_touch("tap", point.x, point.y)
            .unwrap();
        assert_eq!(
            kernel.drain_remote_input_to_thread_window(thread_id, Some(dialog)),
            2
        );
        // A real button tap removes only the dialog's GetMessage wait. The
        // still-live modal selector must consume this gap before the A13 fence.
        assert_eq!(kernel.live_thread_birth_key_by_id(thread_id), Some(birth));
        assert!(kernel.blocked_waiter(modal_wait_id).is_some());
        assert!(kernel.blocked_waiter(get_wait_id).is_none());
        assert_eq!(
            cpu.blocked_guest_thread.as_ref().map(|slot| slot.wait_id),
            Some(get_wait_id)
        );
        assert!(kernel.has_modal_dialog_result(thread_id, dialog));
        assert!(kernel.gwe.is_window(dialog));
        assert_eq!(kernel.shell.message_boxes().count(), 0);

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        if remove_modal_wait {
            let blocked_before = cpu
                .blocked_guest_thread
                .as_ref()
                .expect("parked GetMessage payload")
                .clone();
            let modal_before = cpu
                .blocked_modal_message_box
                .as_ref()
                .expect("parked MessageBox payload")
                .clone();
            // Fault-inject only the modal scheduler record after the real
            // button tap. The queued button result must not be consumed by an
            // unowned modal return, nor may the stale GetMessage PC run.
            assert!(kernel.remove_blocked_waiter(modal_wait_id).is_some());
            let rejected = cpu.run_until_import_trap_with_framebuffer_limits_report(
                &mut kernel,
                &mut framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 64,
                    wall_clock_limit_ms: 500,
                    stop_pc: Some(entry + 4),
                    live_pump: false,
                },
            );
            assert!(
                matches!(&rejected.result, Err(Error::Backend(reason)) if reason.contains("modal")),
                "missing exact modal wait must fail closed: {:?}; report={:?}",
                rejected.result,
                rejected.report,
            );
            assert!(matches!(
                rejected.report.native_result(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.count_stop_query(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.timeout_query(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.context_capture(),
                super::AttemptObservation::Uncollected
            ));
            assert_eq!(cpu.blocked_guest_thread.as_ref(), Some(&blocked_before));
            let retained_modal = cpu
                .blocked_modal_message_box
                .as_ref()
                .expect("unconsumed MessageBox payload");
            assert_eq!(retained_modal.wait_id, modal_before.wait_id);
            assert_eq!(retained_modal.thread_id, modal_before.thread_id);
            assert_eq!(retained_modal.thread_handle, modal_before.thread_handle);
            assert_eq!(retained_modal.regs, modal_before.regs);
            assert_eq!(retained_modal.return_pc, modal_before.return_pc);
            assert_eq!(retained_modal.modal_state.dialog_hwnd(), dialog);
            assert!(kernel.has_modal_dialog_result(thread_id, dialog));
            assert!(kernel.gwe.is_window(dialog));
            assert!(kernel.blocked_waiter(modal_wait_id).is_none());
            assert!(kernel.blocked_waiter(get_wait_id).is_none());
            assert_eq!(kernel.shell.message_boxes().count(), 0);
            return Ok(());
        }
        let resumed = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: Some(entry + 4),
                live_pump: false,
            },
        );
        assert!(
            resumed.result.is_ok(),
            "modal continuation: {:?}",
            resumed.result
        );
        assert_eq!(resumed.report.start_thread_id(), Some(thread_id));
        assert_eq!(resumed.report.start_pc(), Some(entry));
        assert_eq!(
            cpu.saved_context
                .as_ref()
                .expect("continued context")
                .regs
                .regs[16],
            1
        );
        assert_eq!(
            cpu.saved_context
                .as_ref()
                .expect("continued context")
                .regs
                .regs[2],
            1
        );
        assert!(cpu.blocked_guest_thread.is_none());
        assert!(cpu.blocked_modal_message_box.is_none());
        assert!(kernel.blocked_waiter(modal_wait_id).is_none());
        assert!(kernel.blocked_waiter(get_wait_id).is_none());
        assert!(!kernel.gwe.is_window(dialog));
        assert_eq!(kernel.shell.message_boxes().count(), 1);
        assert_eq!(
            kernel.shell.last_message_box().map(|record| record.result),
            Some(1)
        );
        assert!(
            cpu.last_debug_snapshot()
                .expect("modal native snapshot")
                .last_imports
                .iter()
                .all(|import| import.ordinal != Some(ORD_GET_MESSAGE_W))
        );
        Ok(())
    }

    // The ordinary one-way Send controls above do not cover a receiver that
    // sends back to its blocked sender before its own GetMessageW can return.
    // Exercise the next-lease receiver handoff and unwind both exact Send
    // waits on their own saved stacks without replaying either import.
    #[test]
    fn native_same_process_reciprocal_send_enters_blocked_sender_on_own_stack() -> crate::Result<()>
    {
        reciprocal_send_fixture(false, false)
    }

    #[test]
    fn native_same_process_reciprocal_send_rejects_wrong_parent_birth() -> crate::Result<()> {
        reciprocal_send_fixture(true, false)
    }

    #[test]
    fn bound_cpu_reciprocal_send_refuses_before_queue_or_wait_handoff() -> crate::Result<()> {
        reciprocal_send_fixture(false, true)
    }

    fn reciprocal_send_fixture(
        corrupt_parent_birth: bool,
        bound_directory: bool,
    ) -> crate::Result<()> {
        use crate::ce::coredll_ordinals::{ORD_GET_MESSAGE_W, ORD_SEND_MESSAGE_W, ORD_SLEEP};
        use crate::emulator::imports::{ImportModuleKind, ImportTrap};

        let sleep_trap = super::IMPORT_TRAP_BASE + 0xb00;
        let send_trap = sleep_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let get_trap = send_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("boot T birth");
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_1060, 0, false);
        let sender_birth = kernel
            .live_thread_birth_key_by_id(sender_thread)
            .expect("live S birth");
        assert_ne!(sender_birth, receiver_birth);
        let sender_hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                sender_birth,
                "RECIPROCAL_S",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned S HWND");
        let receiver_hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "RECIPROCAL_T",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned T HWND");
        assert_ne!(sender_hwnd, receiver_hwnd);

        let mut image_bytes = tiny_mips_spinner_pe();
        write_vec_u32(&mut image_bytes, 0x178 + 8, 0x200);
        for (offset, words) in [
            (
                0x200,
                &[
                    0x3c19_0000 | (sleep_trap >> 16),
                    0x3739_0000 | (sleep_trap & 0xffff),
                    0x0320_f809, // T: real finite Sleep import
                    0,
                    0x27a4_fc00, // T: MSG buffer on T's stack
                    0x0000_2821,
                    0x0000_3021,
                    0x0000_3821,
                    0x3c19_0000 | (get_trap >> 16),
                    0x3739_0000 | (get_trap & 0xffff),
                    0x0320_f809, // T: real GetMessageW import after Sleep
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
            (
                0x260,
                &[
                    0x3c19_0000 | (send_trap >> 16),
                    0x3739_0000 | (send_trap & 0xffff),
                    0x0320_f809, // S: real outer SendMessageW import
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
            (
                0x2a0,
                &[
                    0x27bd_ffe0, // T WNDPROC: preserve its return address
                    0xafbf_001c,
                    0x3c04_0000 | (sender_hwnd >> 16),
                    0x3484_0000 | (sender_hwnd & 0xffff),
                    0x2405_0477, // WM_USER + 0x77
                    0x2406_005a,
                    0x0000_3821,
                    0x3c19_0000 | (send_trap >> 16),
                    0x3739_0000 | (send_trap & 0xffff),
                    0x0320_f809, // T: real inner SendMessageW before GetMessageW returns
                    0,
                    0x8fbf_001c,
                    0x27bd_0020,
                    0x2402_0077,
                    0x03e0_0008,
                    0,
                ][..],
            ),
            (0x320, &[0x2402_0088, 0x03e0_0008, 0][..]),
        ] {
            for (index, word) in words.iter().copied().enumerate() {
                write_vec_u32(&mut image_bytes, offset + index * 4, word);
            }
        }
        let image = crate::pe::PeImage::parse_bytes("reciprocal-native-send.exe", &image_bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(receiver_thread);
        for (address, ordinal, name) in [
            (sleep_trap, ORD_SLEEP, "Sleep"),
            (send_trap, ORD_SEND_MESSAGE_W, "SendMessageW"),
            (get_trap, ORD_GET_MESSAGE_W, "GetMessageW"),
        ] {
            cpu.import_traps.insert(ImportTrap {
                address,
                module_kind: ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(ordinal),
                name: Some(name.to_owned()),
                iat_va: 0,
            });
        }
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let entry = cpu.entry.expect("fixture entry");
        assert_eq!(entry, 0x0040_1000);
        let sender_entry = entry + 0x60;
        let receiver_wndproc = entry + 0xa0;
        let sender_wndproc = entry + 0x120;
        assert!(
            kernel
                .gwe
                .set_window_long(receiver_hwnd, GWL_WNDPROC, receiver_wndproc)
                .is_some()
        );
        assert!(
            kernel
                .gwe
                .set_window_long(sender_hwnd, GWL_WNDPROC, sender_wndproc)
                .is_some()
        );
        let receiver_sp = cpu.stack_top.expect("fixture stack") - 0x100;
        let sender_sp = receiver_sp - 0x3000;
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[4] = 10_001;
        receiver_regs.regs[16] = 0xb0b0_0011;
        receiver_regs.regs[29] = receiver_sp;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: entry,
            regs: receiver_regs,
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((
            receiver_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ));
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[4] = receiver_hwnd;
        sender_regs.regs[5] = crate::ce::gwe::WM_USER + 0x76;
        sender_regs.regs[6] = 0x66;
        sender_regs.regs[16] = 0xa0a0_0011;
        sender_regs.regs[29] = sender_sp;
        sender_regs.hi = 0xa0a0_0022;
        sender_regs.lo = 0xa0a0_0033;
        sender_regs.fprs[2] = 0x0000_0000_a0a0_0044;
        sender_regs.fcsr = 1;
        cpu.suspended_guest_thread = Some(super::SuspendedGuestThread {
            thread_id: sender_thread,
            thread_birth: Some(sender_birth),
            thread_handle: Some(sender_handle),
            regs: sender_regs,
            pc: sender_entry,
        });

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let queued = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(receiver_wndproc),
                live_pump: true,
            },
        );
        assert!(
            queued.result.is_ok(),
            "T Sleep → S outer Send setup: {:?}; {:?}",
            queued.result,
            queued.report
        );
        let sleep = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(wait.kind, super::BlockedWaitKind::Sleep)
            })
            .expect("T real finite Sleep wait");
        let sleep_wait_id = sleep.wait_id;
        assert_eq!(sleep.return_pc, entry + 0x10);
        assert_eq!(sleep.regs.regs[29], receiver_sp);
        assert_eq!(
            kernel
                .blocked_waiter(sleep_wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(receiver_birth)
        );
        let outer_ids = kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]);
        assert_eq!(outer_ids.len(), 1, "S real outer Send must be queued once");
        let outer_id = outer_ids[0];
        let outer_sent = kernel.gwe.sent_message(outer_id).expect("outer GWE send");
        assert_eq!(outer_sent.sender_thread_id(), Some(sender_thread));
        assert_eq!(outer_sent.receiver_thread_id, receiver_thread);
        assert_eq!(outer_sent.receiver_birth, Some(receiver_birth));
        assert_eq!(outer_sent.result, None);
        let outer = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| {
                wait.thread_id == sender_thread
                    && matches!(wait.kind, super::BlockedWaitKind::SendMessage { send_id, .. } if send_id == outer_id)
            })
            .expect("S real outer Send native wait");
        let outer_wait_id = outer.wait_id;
        let outer_return_pc = outer.return_pc;
        assert_eq!(outer.regs.regs[29], sender_sp);
        assert_eq!(outer.regs.regs[16], 0xa0a0_0011);
        assert_eq!(outer.regs.hi, 0xa0a0_0022);
        assert_eq!(outer.regs.lo, 0xa0a0_0033);
        assert_eq!(outer.regs.fprs[2], 0x0000_0000_a0a0_0044);
        assert_eq!(outer.regs.fcsr, 1);
        assert_eq!(outer.thread_handle, sender_handle);
        let outer_scheduler = kernel
            .blocked_waiter(outer_wait_id)
            .expect("exact outer scheduler wait");
        assert_eq!(outer_scheduler.thread_id, outer.thread_id);
        assert_eq!(outer_scheduler.thread_handle, outer.thread_handle);
        assert_eq!(
            outer_scheduler.kind,
            crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id: outer_id }
        );
        assert_eq!(outer_scheduler.owner_birth, Some(sender_birth));
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);

        let pre_deadline = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 100,
                stop_pc: None,
                live_pump: true,
            },
        );
        assert!(
            pre_deadline.result.is_ok(),
            "pre-deadline: {:?}",
            pre_deadline.result
        );
        assert!(
            pre_deadline.report.attempt_id().is_none(),
            "S's blocked outer Send replayed before T's finite Sleep deadline: {:?}",
            pre_deadline.report
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
            outer_ids
        );
        assert!(kernel.blocked_waiter(sleep_wait_id).is_some());
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert!(cpu.pending_wndproc_returns.is_empty());

        kernel.timers.sleep_ms(10_001);
        let wake = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(entry + 0x10),
                live_pump: true,
            },
        );
        assert!(
            wake.result.is_ok(),
            "T finite Sleep wake: {:?}; {:?}",
            wake.result,
            wake.report
        );
        assert_eq!(cpu.saved_context_pc(), Some(entry + 0x10));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert!(kernel.blocked_waiter(sleep_wait_id).is_none());
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
            outer_ids
        );

        let delivery = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(receiver_wndproc),
                live_pump: true,
            },
        );
        assert!(
            delivery.result.is_ok(),
            "T real GetMessageW delivery: {:?}; {:?}",
            delivery.result,
            delivery.report
        );
        assert_eq!(cpu.saved_context_pc(), Some(receiver_wndproc));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert_eq!(
            cpu.saved_context
                .as_ref()
                .expect("T WNDPROC context")
                .regs
                .regs[29],
            receiver_sp - super::WNDPROC_CALL_FRAME_BYTES
        );
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(outer_id)
        );
        assert_eq!(cpu.pending_wndproc_returns.len(), 1);
        assert_eq!(
            cpu.pending_wndproc_returns[0].source,
            "GetMessageW/SentMessage"
        );
        assert_eq!(
            cpu.pending_wndproc_returns[0]
                .resume_import
                .as_ref()
                .map(|parent| parent.import_pc),
            Some(get_trap)
        );
        let parent = cpu.pending_wndproc_returns[0]
            .resume_import
            .as_ref()
            .expect("T pending GetMessage parent");
        assert_eq!(parent.thread_id, receiver_thread);
        assert_eq!(parent.thread_birth, receiver_birth);
        assert_eq!(parent.sent_message_id, Some(outer_id));
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());

        let reverse = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sender_wndproc),
                live_pump: true,
            },
        );
        let inner_ids = kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]);
        assert_eq!(
            inner_ids.len(),
            1,
            "T WNDPROC must execute one real reverse Send before GetMessageW returns: {:?}; {:?}",
            reverse.result,
            reverse.report
        );
        let inner_id = inner_ids[0];
        assert_ne!(outer_id, inner_id);
        let inner_sent = kernel.gwe.sent_message(inner_id).expect("inner GWE send");
        assert_eq!(inner_sent.sender_thread_id(), Some(receiver_thread));
        assert_eq!(inner_sent.receiver_thread_id, sender_thread);
        assert_eq!(inner_sent.receiver_birth, Some(sender_birth));
        assert_eq!(inner_sent.result, None);
        let inner = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(wait.kind, super::BlockedWaitKind::SendMessage { send_id, .. } if send_id == inner_id)
            })
            .expect("T real inner Send native wait");
        let inner_wait_id = inner.wait_id;
        let inner_return_pc = inner.return_pc;
        assert_eq!(
            inner.regs.regs[29],
            receiver_sp - super::WNDPROC_CALL_FRAME_BYTES - 0x20
        );
        let inner_scheduler = kernel
            .blocked_waiter(inner_wait_id)
            .expect("exact inner scheduler wait");
        assert_eq!(inner_scheduler.thread_id, inner.thread_id);
        assert_eq!(inner_scheduler.thread_handle, inner.thread_handle);
        assert_eq!(
            inner_scheduler.kind,
            crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id: inner_id }
        );
        assert_eq!(inner_scheduler.owner_birth, Some(receiver_birth));
        assert!(
            kernel.blocked_waiter(outer_wait_id).is_some(),
            "outer S wait must survive reverse Send"
        );
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(outer_id)
        );
        assert_eq!(kernel.gwe.active_sent_message_id(sender_thread), None);
        assert_eq!(
            cpu.pending_wndproc_returns.len(),
            1,
            "T's outer WNDPROC parent must remain pending"
        );

        // The current native lease must stop safely at T's inner Send import.
        // Switching to S is legal only when the next lease begins. Both exact
        // waits and T's outer GetMessage parent still exist at that boundary.
        assert!(
            reverse.result.is_ok(),
            "reverse Send safe-stop boundary: {:?}; {:?}",
            reverse.result,
            reverse.report
        );
        assert_eq!(cpu.saved_context_pc(), Some(send_trap));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert!(kernel.blocked_waiter(inner_wait_id).is_some());
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
            outer_ids
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]),
            inner_ids
        );

        if bound_directory {
            let outer_send_before = kernel.gwe.sent_message(outer_id).cloned();
            let inner_send_before = kernel.gwe.sent_message(inner_id).cloned();
            let outer_wait_before = kernel.blocked_waiter(outer_wait_id).cloned();
            let inner_wait_before = kernel.blocked_waiter(inner_wait_id).cloned();
            let mut directory =
                super::CpuCustody::new().map_err(|error| Error::Backend(error.to_string()))?;
            let owner = kernel
                .current_process_birth_key()
                .expect("boot process birth");
            kernel
                .bind_cpu_machine_lineage(directory.machine_lineage())
                .map_err(|error| Error::Backend(error.to_string()))?;
            let key = directory
                .reserve(owner)
                .map_err(|error| Error::Backend(error.to_string()))?;
            directory
                .admit_reserved(key, owner, cpu)
                .map_err(|(error, _cpu)| Error::Backend(error.to_string()))?;
            let mut leaf = directory
                .issue_leaf(key, owner, receiver_birth, None)
                .map_err(|error| Error::Backend(error.to_string()))?;
            let handle = directory
                .acquire_cpu_handle(key, owner)
                .map_err(|error| Error::Backend(error.to_string()))?;
            let permit = leaf.permit();
            let cpu_before = handle
                .with_cpu_mut(permit, |cpu| {
                    (
                        cpu.saved_context.clone(),
                        cpu.saved_context_thread_birth,
                        cpu.current_thread_id,
                        cpu.blocked_wait_threads.clone(),
                        cpu.pending_wndproc_returns.clone(),
                    )
                })
                .map_err(|error| Error::Backend(error.to_string()))?;
            let rejected = handle
                .with_cpu_mut(permit, |cpu| {
                    cpu.run_until_import_trap_with_framebuffer_limits_report_with_custody(
                        &mut kernel,
                        &mut framebuffer,
                        super::UnicornRunLimits {
                            instruction_limit: 128,
                            wall_clock_limit_ms: 500,
                            stop_pc: Some(sender_wndproc),
                            live_pump: true,
                        },
                        &mut directory,
                    )
                })
                .map_err(|error| Error::Backend(error.to_string()))?;
            assert!(
                matches!(&rejected.result, Err(Error::Backend(reason)) if reason.contains("CPU-directory Send handoff")),
                "bound reciprocal handoff must refuse before effects: {:?}; {:?}",
                rejected.result,
                rejected.report,
            );
            assert_eq!(rejected.report.attempt_id(), None);
            assert_eq!(rejected.report.start_pc(), None);
            assert_eq!(
                rejected.report.failure_operation(),
                Some("CPU custody Send handoff preflight")
            );
            assert_eq!(
                kernel.gwe.sent_message(outer_id),
                outer_send_before.as_ref()
            );
            assert_eq!(
                kernel.gwe.sent_message(inner_id),
                inner_send_before.as_ref()
            );
            assert_eq!(
                kernel.blocked_waiter(outer_wait_id),
                outer_wait_before.as_ref()
            );
            assert_eq!(
                kernel.blocked_waiter(inner_wait_id),
                inner_wait_before.as_ref()
            );
            assert_eq!(
                kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
                outer_ids
            );
            assert_eq!(
                kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]),
                inner_ids
            );
            let cpu_after = handle
                .with_cpu_mut(permit, |cpu| {
                    (
                        cpu.saved_context.clone(),
                        cpu.saved_context_thread_birth,
                        cpu.current_thread_id,
                        cpu.blocked_wait_threads.clone(),
                        cpu.pending_wndproc_returns.clone(),
                    )
                })
                .map_err(|error| Error::Backend(error.to_string()))?;
            assert_eq!(cpu_after, cpu_before, "bound handoff changed CPU state");
            directory
                .finish_leaf(
                    &mut leaf,
                    crate::emulator::cpu_custody::CpuLeaseEnd::Runnable,
                )
                .map_err(|error| Error::Backend(error.to_string()))?;
            return Ok(());
        }

        if corrupt_parent_birth {
            let parent = cpu.pending_wndproc_returns[0]
                .resume_import
                .as_mut()
                .expect("T exact outer GetMessage parent");
            parent.thread_birth = sender_birth;
            let rejected = cpu.run_until_import_trap_with_framebuffer_limits_report(
                &mut kernel,
                &mut framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 128,
                    wall_clock_limit_ms: 500,
                    stop_pc: Some(sender_wndproc),
                    live_pump: true,
                },
            );
            assert!(
                matches!(&rejected.result, Err(Error::Backend(reason)) if reason.contains("blocked SendMessage wait")),
                "wrong-parent-birth reciprocal handoff must fail before guest entry: {:?}; {:?}",
                rejected.result,
                rejected.report,
            );
            assert!(rejected.report.start_pc().is_none());
            assert_eq!(
                kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
                outer_ids
            );
            assert_eq!(
                kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]),
                inner_ids
            );
            assert_eq!(
                kernel
                    .gwe
                    .sent_message(outer_id)
                    .and_then(|send| send.result),
                None
            );
            assert_eq!(
                kernel
                    .gwe
                    .sent_message(inner_id)
                    .and_then(|send| send.result),
                None
            );
            assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
            assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 0);
            assert_eq!(
                kernel.gwe.active_sent_message_id(receiver_thread),
                Some(outer_id)
            );
            assert_eq!(kernel.gwe.active_sent_message_id(sender_thread), None);
            assert_eq!(cpu.pending_wndproc_returns.len(), 1);
            assert!(cpu.pending_wndproc_returns[0].send_restore.is_none());
            assert_eq!(
                cpu.pending_wndproc_returns[0]
                    .resume_import
                    .as_ref()
                    .map(|parent| parent.thread_birth),
                Some(sender_birth)
            );
            assert_eq!(
                cpu.blocked_wait_threads
                    .iter()
                    .filter(|wait| matches!(wait.kind, super::BlockedWaitKind::SendMessage { .. }))
                    .map(|wait| wait.wait_id)
                    .collect::<Vec<_>>(),
                vec![outer_wait_id, inner_wait_id],
            );
            assert_eq!(
                kernel
                    .blocked_waiter(outer_wait_id)
                    .and_then(|wait| wait.owner_birth),
                Some(sender_birth)
            );
            assert_eq!(
                kernel
                    .blocked_waiter(inner_wait_id)
                    .and_then(|wait| wait.owner_birth),
                Some(receiver_birth)
            );
            return Ok(());
        }

        let receiver_handoff = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sender_wndproc),
                live_pump: true,
            },
        );
        assert!(
            receiver_handoff.result.is_ok(),
            "next-lease reciprocal receiver handoff: {:?}; {:?}",
            receiver_handoff.result,
            receiver_handoff.report
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]),
            inner_ids,
            "next lease replayed T's inner Send import before S's callback: native_waits={:?}, report={:?}",
            cpu.blocked_wait_threads,
            receiver_handoff.report,
        );
        assert_eq!(
            cpu.blocked_wait_threads
                .iter()
                .filter(|wait| {
                    wait.thread_id == receiver_thread
                        && matches!(wait.kind, super::BlockedWaitKind::SendMessage { .. })
                })
                .map(|wait| wait.wait_id)
                .collect::<Vec<_>>(),
            vec![inner_wait_id],
            "next lease duplicated T's exact native Send wait",
        );
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert!(kernel.blocked_waiter(inner_wait_id).is_some());
        assert_eq!(
            cpu.saved_context_pc(),
            Some(sender_wndproc),
            "next-lease reciprocal receiver handoff did not enter S's WNDPROC: outer={outer_id}/{outer_wait_id}, inner={inner_id}/{inner_wait_id}, current={}, birth={:?}, pc={:?}, pending={:?}, native_waits={:?}, report={:?}",
            cpu.current_thread_id,
            cpu.saved_context_thread_birth,
            cpu.saved_context_pc(),
            cpu.pending_wndproc_returns,
            cpu.blocked_wait_threads,
            receiver_handoff.report,
        );
        assert_eq!(cpu.saved_context_thread_birth, Some(sender_birth));
        let sender_callback = &cpu
            .saved_context
            .as_ref()
            .expect("S inner WNDPROC context")
            .regs;
        assert_eq!(
            sender_callback.regs[29],
            sender_sp - super::WNDPROC_CALL_FRAME_BYTES
        );
        assert_eq!(sender_callback.regs[31], super::WNDPROC_RETURN_STUB_ADDR);
        assert_eq!(sender_callback.regs[16], 0xa0a0_0011);
        assert_eq!(sender_callback.hi, 0xa0a0_0022);
        assert_eq!(sender_callback.lo, 0xa0a0_0033);
        assert_eq!(sender_callback.fprs[2], 0x0000_0000_a0a0_0044);
        assert_eq!(sender_callback.fcsr, 1);
        assert_eq!(cpu.pending_wndproc_returns.len(), 2);
        let parent = &cpu.pending_wndproc_returns[0];
        assert_eq!(parent.source, "GetMessageW/SentMessage");
        assert_eq!(
            parent
                .resume_import
                .as_ref()
                .and_then(|resume| resume.sent_message_id),
            Some(outer_id)
        );
        let callback = &cpu.pending_wndproc_returns[1];
        assert_eq!(callback.source, "BlockedSendMessage/SentMessage");
        let token = callback
            .send_restore
            .as_ref()
            .expect("reciprocal inner token");
        assert_eq!(
            (token.outer_send_id, token.outer_wait_id),
            (outer_id, outer_wait_id)
        );
        assert_eq!((token.send_id, token.wait_id), (inner_id, inner_wait_id));
        assert_eq!(
            (token.receiver_birth, token.sender_birth),
            (sender_birth, receiver_birth)
        );

        // S replies from its real callback, but its blocked outer Send is not
        // a runnable continuation yet. T's inner Send and the outer parent
        // must remain exact until separate blank native leases unwind them.
        let inner_reply = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        assert!(
            inner_reply.result.is_ok(),
            "S inner WNDPROC return: {:?}; {:?}",
            inner_reply.result,
            inner_reply.report
        );
        assert_eq!(cpu.pending_wndproc_returns.len(), 1);
        assert_eq!(
            cpu.pending_wndproc_returns[0].source,
            "GetMessageW/SentMessage"
        );
        assert_eq!(kernel.gwe.active_sent_message_id(sender_thread), None);
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(outer_id)
        );
        assert_eq!(
            kernel
                .gwe
                .sent_message(inner_id)
                .and_then(|send| send.result),
            Some(0x88)
        );
        assert_eq!(
            kernel
                .gwe
                .sent_message(outer_id)
                .and_then(|send| send.result),
            None
        );
        assert!(kernel.blocked_waiter(inner_wait_id).is_some());
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 1);
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[sender_hwnd]),
            inner_ids
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[receiver_hwnd]),
            outer_ids
        );

        let inner_resume = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(inner_return_pc),
                live_pump: true,
            },
        );
        assert!(
            inner_resume.result.is_ok(),
            "T inner Send continuation: {:?}; {:?}",
            inner_resume.result,
            inner_resume.report
        );
        assert_eq!(inner_resume.report.start_thread_id(), Some(receiver_thread));
        assert_eq!(inner_resume.report.start_pc(), Some(inner_return_pc));
        assert_eq!(cpu.saved_context_pc(), Some(inner_return_pc));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        let receiver_continuation = &cpu
            .saved_context
            .as_ref()
            .expect("T inner Send return")
            .regs;
        assert_eq!(receiver_continuation.regs[2], 0x88);
        assert_eq!(
            receiver_continuation.regs[29],
            receiver_sp - super::WNDPROC_CALL_FRAME_BYTES - 0x20
        );
        assert!(kernel.blocked_waiter(inner_wait_id).is_none());
        assert!(
            cpu.blocked_wait_threads
                .iter()
                .all(|wait| wait.wait_id != inner_wait_id)
        );
        assert!(kernel.gwe.sent_message(inner_id).is_none());
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert_eq!(cpu.pending_wndproc_returns.len(), 1);
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 1);

        let outer_reply = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(get_trap),
                live_pump: true,
            },
        );
        assert!(
            outer_reply.result.is_ok(),
            "T outer WNDPROC return: {:?}; {:?}",
            outer_reply.result,
            outer_reply.report
        );
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert_eq!(
            kernel
                .gwe
                .sent_message(outer_id)
                .and_then(|send| send.result),
            Some(0x77)
        );
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 2);
        assert!(
            kernel
                .gwe
                .sent_message_ids_for_windows(&[sender_hwnd])
                .is_empty()
        );

        // T must park its resumed GetMessage import before S consumes its
        // ready outer result. This is the same next-lease boundary as A10.
        let receiver_park = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(outer_return_pc),
                live_pump: true,
            },
        );
        assert!(
            receiver_park.result.is_ok(),
            "T GetMessage park before S outer resume: {:?}; {:?}",
            receiver_park.result,
            receiver_park.report
        );
        assert_eq!(cpu.saved_context_pc(), Some(get_trap));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert!(kernel.blocked_waiter(outer_wait_id).is_some());
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 2);

        let outer_resume = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(outer_return_pc),
                live_pump: true,
            },
        );
        assert!(
            outer_resume.result.is_ok(),
            "S outer Send continuation: {:?}; {:?}",
            outer_resume.result,
            outer_resume.report
        );
        assert_eq!(outer_resume.report.start_thread_id(), Some(sender_thread));
        assert_eq!(outer_resume.report.start_pc(), Some(outer_return_pc));
        assert_eq!(cpu.saved_context_pc(), Some(outer_return_pc));
        assert_eq!(cpu.saved_context_thread_birth, Some(sender_birth));
        let sender_continuation = &cpu
            .saved_context
            .as_ref()
            .expect("S outer Send return")
            .regs;
        assert_eq!(sender_continuation.regs[2], 0x77);
        assert_eq!(sender_continuation.regs[29], sender_sp);
        assert_eq!(sender_continuation.regs[31], outer_return_pc);
        assert_eq!(sender_continuation.regs[16], 0xa0a0_0011);
        assert_eq!(sender_continuation.hi, 0xa0a0_0022);
        assert_eq!(sender_continuation.lo, 0xa0a0_0033);
        assert_eq!(sender_continuation.fprs[2], 0x0000_0000_a0a0_0044);
        assert_eq!(sender_continuation.fcsr, 1);
        assert!(kernel.blocked_waiter(outer_wait_id).is_none());
        assert!(
            cpu.blocked_wait_threads
                .iter()
                .all(|wait| wait.wait_id != outer_wait_id)
        );
        assert!(kernel.gwe.sent_message(outer_id).is_none());
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 2);
        assert!(
            kernel
                .gwe
                .sent_message_ids_for_windows(&[sender_hwnd, receiver_hwnd])
                .is_empty()
        );

        let no_replay = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 16,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: true,
            },
        );
        assert!(
            no_replay.result.is_ok(),
            "reciprocal no-replay: {:?}",
            no_replay.result
        );
        assert_eq!(kernel.gwe.stats().send_transaction_count, 2);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 2);
        assert!(
            kernel
                .gwe
                .sent_message_ids_for_windows(&[sender_hwnd, receiver_hwnd])
                .is_empty()
        );
        assert!(
            cpu.blocked_wait_threads
                .iter()
                .all(|wait| wait.wait_id != outer_wait_id && wait.wait_id != inner_wait_id)
        );
        Ok(())
    }

    fn native_get_message_blocked_receiver_send_fixture(
        spans_callback_slice: bool,
        two_receivers: bool,
        orphan_before_delivery: bool,
    ) -> crate::Result<()> {
        use crate::ce::coredll_ordinals::{ORD_GET_MESSAGE_W, ORD_SEND_MESSAGE_W};
        use crate::emulator::imports::{ImportModuleKind, ImportTrap};

        let get_trap = super::IMPORT_TRAP_BASE + 0x700;
        let send_trap = get_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let mut image_bytes = tiny_mips_spinner_pe();
        for (offset, words) in [
            (
                0x200,
                &[
                    0x27a4_fc00, // B: MSG buffer below B's stack pointer
                    0x0000_2821, // a1 = NULL HWND
                    0x0000_3021, // a2 = 0
                    0x0000_3821, // a3 = 0
                    0x3c19_0000 | (get_trap >> 16),
                    0x3739_0000 | (get_trap & 0xffff),
                    0x0320_f809, // real MIPS GetMessageW import
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
            (
                0x260,
                &[
                    0x3c19_0000 | (send_trap >> 16),
                    0x3739_0000 | (send_trap & 0xffff),
                    0x0320_f809, // A: real MIPS SendMessageW import
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
        ] {
            for (index, word) in words.iter().copied().enumerate() {
                write_vec_u32(&mut image_bytes, offset + index * 4, word);
            }
        }
        if spans_callback_slice {
            // The raw .text already has room for 72 straight-line instructions;
            // keep the section's virtual extent honest for an in-callback count stop.
            write_vec_u32(&mut image_bytes, 0x178 + 8, 0x200);
            for index in 0..72 {
                write_vec_u32(&mut image_bytes, 0x2a0 + index * 4, 0x2508_0001);
            }
            for (index, word) in [0x2402_0066, 0x03e0_0008, 0].into_iter().enumerate() {
                write_vec_u32(&mut image_bytes, 0x2a0 + (72 + index) * 4, word);
            }
        } else {
            for (index, word) in [0x2402_0066, 0x03e0_0008, 0].into_iter().enumerate() {
                write_vec_u32(&mut image_bytes, 0x2a0 + index * 4, word);
            }
        }
        if two_receivers {
            // B executes the same real GetMessage import from a distinct PC,
            // so the first stop cannot accidentally halt C before it blocks.
            image_bytes.copy_within(0x200..0x228, 0x230);
        }
        let image = crate::pe::PeImage::parse_bytes("get-blocked-native-send.exe", &image_bytes)?;
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("boot receiver birth");
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(receiver_thread);
        for (address, ordinal, name) in [
            (get_trap, ORD_GET_MESSAGE_W, "GetMessageW"),
            (send_trap, ORD_SEND_MESSAGE_W, "SendMessageW"),
        ] {
            cpu.import_traps.insert(ImportTrap {
                address,
                module_kind: ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(ordinal),
                name: Some(name.to_owned()),
                iat_va: 0,
            });
        }
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let entry = cpu.entry.expect("fixture entry");
        let middle_entry = entry + 0x30;
        let sender_entry = entry + 0x60;
        let wndproc = entry + 0xa0;
        let receiver_sp = cpu.stack_top.expect("fixture stack") - 0x100;
        let middle_sp = receiver_sp - 0x2000;
        let sender_sp = receiver_sp - 0x3000;
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "GET_BLOCKED_NATIVE_SEND",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned blocked GetMessage receiver HWND");
        assert!(
            kernel
                .gwe
                .set_window_long(hwnd, GWL_WNDPROC, wndproc)
                .is_some()
        );
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[16] = 0xb0b0_0011;
        receiver_regs.regs[29] = receiver_sp;
        receiver_regs.hi = 0xb0b0_0022;
        receiver_regs.lo = 0xb0b0_0033;
        receiver_regs.fprs[0] = 0x0000_0000_b0b0_0044;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: entry,
            regs: receiver_regs,
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((
            receiver_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ));

        let mut middle_wait_id = None;
        if two_receivers {
            // C is the boot receiver. Let C block first, then B; B occupies
            // the primary slot and C is displaced when A finally sends to C.
            let (middle_handle, middle_thread) = kernel.create_guest_thread(middle_entry, 0, false);
            let middle_birth = kernel
                .live_thread_birth_key_by_id(middle_thread)
                .expect("middle receiver birth");
            let middle_hwnd = kernel
                .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                    middle_birth,
                    "OTHER_GET_BLOCKED_NATIVE_SEND",
                    "",
                    None,
                    None,
                    0,
                    0,
                    0,
                    crate::ce::gwe::Rect::default(),
                )
                .expect("birth-owned other GetMessage receiver HWND");
            assert_ne!(middle_hwnd, hwnd);
            assert_eq!(
                kernel
                    .gwe
                    .window_thread_process_id(hwnd)
                    .map(|owner| owner.0),
                Some(receiver_thread)
            );
            assert_eq!(
                kernel
                    .gwe
                    .window_thread_process_id(middle_hwnd)
                    .map(|owner| owner.0),
                Some(middle_thread)
            );
            let mut middle_regs = super::MipsGuestContext::zero();
            middle_regs.regs[16] = 0xc0c0_0011;
            middle_regs.regs[29] = middle_sp;
            middle_regs.hi = 0xc0c0_0022;
            middle_regs.lo = 0xc0c0_0033;
            middle_regs.fprs[0] = 0x0000_0000_c0c0_0044;
            cpu.suspended_guest_thread = Some(super::SuspendedGuestThread {
                thread_id: middle_thread,
                thread_birth: Some(middle_birth),
                thread_handle: Some(middle_handle),
                regs: middle_regs,
                pc: middle_entry,
            });
            let mut first_framebuffer = VirtualFramebuffer::default_primary()?;
            let first_block = cpu.run_until_import_trap_with_framebuffer_limits_report(
                &mut kernel,
                &mut first_framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 128,
                    wall_clock_limit_ms: 500,
                    stop_pc: Some(middle_entry),
                    live_pump: true,
                },
            );
            assert!(
                first_block.result.is_ok(),
                "C GetMessageW → B activation failed before second receiver blocked: {:?}",
                first_block.result
            );
            assert_eq!(cpu.saved_context_pc(), Some(middle_entry));
            assert_eq!(cpu.saved_context_thread_birth, Some(middle_birth));
            assert_eq!(
                cpu.blocked_guest_thread
                    .as_ref()
                    .map(|thread| thread.thread_id),
                Some(receiver_thread)
            );
            assert!(cpu.displaced_blocked_get_messages.is_empty());
        }

        // A is ready, not CE-suspended; it runs only after the last receiver blocks.
        let (sender_handle, sender_thread) = kernel.create_guest_thread(sender_entry, 0, false);
        let sender_birth = kernel
            .live_thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[4] = hwnd;
        sender_regs.regs[5] = crate::ce::gwe::WM_USER + 0x74;
        sender_regs.regs[16] = 0xa0a0_0011;
        sender_regs.regs[29] = sender_sp;
        sender_regs.hi = 0xa0a0_0022;
        sender_regs.lo = 0xa0a0_0033;
        sender_regs.fprs[0] = 0x0000_0000_a0a0_0044;
        cpu.suspended_guest_thread = Some(super::SuspendedGuestThread {
            thread_id: sender_thread,
            thread_birth: Some(sender_birth),
            thread_handle: Some(sender_handle),
            regs: sender_regs,
            pc: sender_entry,
        });

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let blocked = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sender_entry),
                live_pump: true,
            },
        );
        assert!(
            blocked.result.is_ok(),
            "B GetMessageW → A activation failed before A sent: {:?}",
            blocked.result
        );
        assert_eq!(cpu.saved_context_pc(), Some(sender_entry));
        assert_eq!(cpu.saved_context_thread_birth, Some(sender_birth));
        let get_wait = kernel
            .blocked_waiters()
            .find(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(
                        wait.kind,
                        crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage { .. }
                    )
            })
            .expect("B must be blocked in real GetMessageW before A sends");
        assert_eq!(get_wait.owner_birth, Some(receiver_birth));
        let get_wait_id = get_wait.id;
        if two_receivers {
            let middle = cpu
                .blocked_guest_thread
                .as_ref()
                .expect("B primary GetMessage slot");
            assert_ne!(middle.thread_id, receiver_thread);
            assert_eq!(middle.regs.regs[29], middle_sp);
            assert_eq!(middle.regs.regs[16], 0xc0c0_0011);
            let displaced = cpu
                .displaced_blocked_get_messages
                .iter()
                .find(|thread| thread.thread_id == receiver_thread)
                .expect("C displaced GetMessage continuation");
            assert_eq!(displaced.wait_id, get_wait_id);
            assert_eq!(displaced.regs.regs[29], receiver_sp);
            let other_wait = kernel
                .blocked_waiter(middle.wait_id)
                .expect("B GetMessage scheduler wait");
            assert_eq!(other_wait.thread_id, middle.thread_id);
            assert_eq!(
                other_wait.owner_birth,
                kernel.live_thread_birth_key_by_id(middle.thread_id)
            );
            assert_ne!(middle.wait_id, get_wait_id);
            middle_wait_id = Some(middle.wait_id);
        } else {
            assert_eq!(
                cpu.blocked_guest_thread
                    .as_ref()
                    .map(|thread| thread.thread_id),
                Some(receiver_thread)
            );
        }

        let queued = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(wndproc),
                live_pump: true,
            },
        );
        assert!(
            queued.result.is_ok(),
            "phase A/queue: SendMessageW failed before receiver GetMessage handoff (spans_slice={spans_callback_slice}, two_receivers={two_receivers}): {:?}; report={:?}",
            queued.result,
            queued.report,
        );
        assert_eq!(queued.report.start_thread_id(), Some(sender_thread));
        assert_eq!(queued.report.end_thread_id(), Some(sender_thread));
        assert_eq!(cpu.current_thread_id, sender_thread);
        assert_eq!(cpu.saved_context_thread_birth, Some(sender_birth));
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        let send_ids = kernel.gwe.sent_message_ids_for_windows(&[hwnd]);
        assert_eq!(send_ids.len(), 1, "phase A/queue: exactly one send");
        assert_eq!(
            kernel
                .gwe
                .sent_message(send_ids[0])
                .and_then(|sent| sent.receiver_birth),
            Some(receiver_birth),
            "phase A/queue: send must be pinned to the target birth",
        );
        let sender_wait_ids: Vec<_> = cpu
            .blocked_wait_threads
            .iter()
            .filter(|wait| {
                wait.thread_id == sender_thread
                    && matches!(wait.kind, super::BlockedWaitKind::SendMessage { .. })
            })
            .map(|wait| wait.wait_id)
            .collect();
        assert_eq!(sender_wait_ids.len(), 1, "phase A/queue: one A send wait");
        assert!(kernel.blocked_waiter(sender_wait_ids[0]).is_some());
        assert!(kernel.blocked_waiter(get_wait_id).is_some());
        if let Some(other_wait_id) = middle_wait_id {
            assert!(kernel.blocked_waiter(other_wait_id).is_some());
        }

        if orphan_before_delivery {
            // Fault injection only: B really executed GetMessageW and A really
            // executed SendMessageW above. Select B from its captured native
            // registers, then remove only B's scheduler subscription. This
            // simulates an escaped selected CPU image, not a runnable B task.
            assert!(!spans_callback_slice && !two_receivers);
            let receiver_blocked = cpu
                .blocked_guest_thread
                .as_ref()
                .expect("real MIPS B GetMessage payload")
                .clone();
            assert_eq!(receiver_blocked.wait_id, get_wait_id);
            assert_eq!(receiver_blocked.thread_id, receiver_thread);
            assert_eq!(receiver_blocked.import_pc, get_trap);
            assert_eq!(receiver_blocked.regs.regs[29], receiver_sp);
            assert_eq!(
                super::verified_get_message_wait_birth(
                    &kernel,
                    get_wait_id,
                    receiver_thread,
                    receiver_blocked.thread_handle,
                ),
                Some(receiver_birth)
            );
            let sender_blocked = cpu
                .blocked_wait_threads
                .iter()
                .find(|wait| wait.wait_id == sender_wait_ids[0])
                .expect("real MIPS A SendMessage wait")
                .clone();
            assert_eq!(
                super::verified_native_send_wait_birth(&kernel, &sender_blocked),
                Some(sender_birth)
            );
            assert_eq!(cpu.running_guest_thread, None);
            assert!(cpu.suspended_guest_thread.is_none());
            let selected_slot = Rc::new(RefCell::new(Some(receiver_blocked.clone())));
            let selected_displaced = Rc::new(RefCell::new(Vec::new()));
            let (selected, selected_send_id, selected_birth) =
                super::preflight_ready_birth_owned_get_message_send(
                    &mut kernel,
                    sender_thread,
                    &selected_slot,
                    &selected_displaced,
                )
                .expect("B is the exact ready receiver before fault injection");
            assert_eq!(selected.wait_id, get_wait_id);
            assert_eq!(selected_send_id, send_ids[0]);
            assert_eq!(selected_birth, receiver_birth);

            cpu.current_thread_id = receiver_thread;
            cpu.saved_context = Some(super::SavedCpuContext {
                pc: receiver_blocked.import_pc,
                regs: receiver_blocked.regs.clone(),
            });
            cpu.saved_context_thread_birth = Some(receiver_birth);
            cpu.running_guest_thread = None;
            assert!(kernel.remove_blocked_waiter(get_wait_id).is_some());
            assert!(kernel.blocked_waiter(get_wait_id).is_none());
            assert_eq!(cpu.blocked_guest_thread.as_ref(), Some(&receiver_blocked));
            assert_eq!(
                super::verified_get_message_wait_birth(
                    &kernel,
                    get_wait_id,
                    receiver_thread,
                    receiver_blocked.thread_handle,
                ),
                None
            );
            assert_eq!(
                super::verified_native_send_wait_birth(&kernel, &sender_blocked),
                Some(sender_birth)
            );

            let rejected = cpu.run_until_import_trap_with_framebuffer_limits_report(
                &mut kernel,
                &mut framebuffer,
                super::UnicornRunLimits {
                    instruction_limit: 128,
                    wall_clock_limit_ms: 500,
                    stop_pc: Some(wndproc),
                    live_pump: true,
                },
            );
            assert!(
                matches!(&rejected.result, Err(Error::Backend(reason)) if reason.contains("orphaned GetMessage")),
                "selected B must fail closed before replaying GetMessage: {:?}; report={:?}",
                rejected.result,
                rejected.report,
            );
            assert_eq!(rejected.report.start_thread_id(), Some(receiver_thread));
            assert!(matches!(
                rejected.report.native_result(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.count_stop_query(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.timeout_query(),
                super::AttemptObservation::Uncollected
            ));
            assert!(matches!(
                rejected.report.context_capture(),
                super::AttemptObservation::Uncollected
            ));
            assert_eq!(cpu.blocked_guest_thread.as_ref(), Some(&receiver_blocked));
            assert!(cpu.pending_wndproc_returns.is_empty());
            assert_eq!(kernel.gwe.sent_message_ids_for_windows(&[hwnd]), send_ids);
            assert_eq!(kernel.gwe.stats().send_transaction_count, 1);
            assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
            assert!(kernel.gwe.sent_message(send_ids[0]).is_some_and(|send| {
                send.receiver_birth == Some(receiver_birth) && send.result.is_none()
            }));
            assert_eq!(
                cpu.blocked_wait_threads
                    .iter()
                    .find(|wait| wait.wait_id == sender_blocked.wait_id),
                Some(&sender_blocked)
            );
            assert_eq!(
                super::verified_native_send_wait_birth(&kernel, &sender_blocked),
                Some(sender_birth)
            );
            return Ok(());
        }

        let callback = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: if spans_callback_slice { 64 } else { 128 },
                wall_clock_limit_ms: 500,
                stop_pc: if spans_callback_slice {
                    None
                } else {
                    Some(wndproc)
                },
                live_pump: true,
            },
        );
        assert!(
            callback.result.is_ok(),
            "phase receiver/callback: queued Send did not enter target GetMessage WNDPROC (spans_slice={spans_callback_slice}, two_receivers={two_receivers}): {:?}; report={:?}",
            callback.result,
            callback.report
        );
        assert_eq!(callback.report.start_thread_id(), Some(receiver_thread));
        assert_eq!(callback.report.end_thread_id(), Some(receiver_thread));
        if spans_callback_slice {
            assert_eq!(callback.report.limits().stop_pc, None);
            assert_eq!(
                callback.report.final_outcome(),
                super::NativeSliceOutcome::CountLimit
            );
            assert_eq!(
                callback.report.count_stop_query(),
                &super::AttemptObservation::Value(true)
            );
            let stopped_pc = cpu.saved_context_pc().expect("B in-callback count-stop PC");
            assert!(
                (wndproc..wndproc + 72 * 4).contains(&stopped_pc),
                "count stop must land inside B's straight-line WNDPROC, got {stopped_pc:#x}"
            );
            assert_ne!(stopped_pc, 0);
        } else {
            assert_eq!(cpu.saved_context_pc(), Some(wndproc));
        }
        assert_eq!(cpu.current_thread_id, receiver_thread);
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        let callback_regs = &cpu.saved_context.as_ref().expect("B WNDPROC context").regs;
        assert_eq!(
            callback_regs.regs[29],
            receiver_sp - super::WNDPROC_CALL_FRAME_BYTES
        );
        assert_ne!(
            callback_regs.regs[29],
            sender_sp - super::WNDPROC_CALL_FRAME_BYTES
        );
        assert_eq!(callback_regs.regs[16], 0xb0b0_0011);
        assert_eq!(callback_regs.hi, 0xb0b0_0022);
        assert_eq!(callback_regs.lo, 0xb0b0_0033);
        assert_eq!(callback_regs.fprs[0], 0x0000_0000_b0b0_0044);
        assert_eq!(callback_regs.regs[31], super::WNDPROC_RETURN_STUB_ADDR);
        // A sent WNDPROC interrupts B's GetMessage import. The scheduler wait
        // is retired at queue take; the parent remains in ResumeImportAfterWndProc.
        assert!(kernel.blocked_waiter(get_wait_id).is_none());
        if let Some(other_wait_id) = middle_wait_id {
            let other_wait = kernel
                .blocked_waiter(other_wait_id)
                .expect("B GetMessage wait must be unaffected by A sending to C");
            assert_ne!(other_wait.thread_id, receiver_thread);
            assert_eq!(
                cpu.blocked_guest_thread
                    .as_ref()
                    .map(|thread| thread.wait_id),
                Some(other_wait_id)
            );
        }
        assert_eq!(cpu.pending_wndproc_returns.len(), 1);
        let pending = &cpu.pending_wndproc_returns[0];
        assert_eq!(pending.source, "GetMessageW/SentMessage");
        assert_eq!(pending.send_thread_id, Some(receiver_thread));
        let parent = pending
            .resume_import
            .as_ref()
            .expect("B GetMessageW parent import continuation");
        assert_eq!(parent.thread_id, receiver_thread);
        assert_eq!(parent.thread_birth, receiver_birth);
        assert_eq!(parent.import_pc, get_trap);
        assert_eq!(parent.regs.regs[29], receiver_sp);
        assert_eq!(parent.regs.regs[16], 0xb0b0_0011);
        assert_eq!(parent.regs.hi, 0xb0b0_0022);
        assert_eq!(parent.regs.lo, 0xb0b0_0033);
        assert_eq!(parent.regs.fprs[0], 0x0000_0000_b0b0_0044);
        assert_eq!(
            parent.running_thread,
            Some((
                receiver_thread,
                crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
            ))
        );
        assert_eq!(kernel.gwe.sent_message_ids_for_windows(&[hwnd]), send_ids);
        assert_eq!(
            cpu.blocked_wait_threads
                .iter()
                .filter(|wait| wait.thread_id == sender_thread)
                .map(|wait| wait.wait_id)
                .collect::<Vec<_>>(),
            sender_wait_ids,
            "phase receiver/callback: A's one wait must survive the handoff",
        );
        Ok(())
    }

    fn native_same_process_sleep_send_fixture(
        continue_after_send: bool,
        retrieval: NativeSleepSendRetrieval,
    ) -> crate::Result<()> {
        use crate::ce::coredll_ordinals::{
            ORD_GET_MESSAGE_W, ORD_GET_MESSAGE_WNO_WAIT, ORD_PEEK_MESSAGE_W, ORD_SEND_MESSAGE_W,
            ORD_SLEEP,
        };
        use crate::emulator::imports::{ImportModuleKind, ImportTrap};

        let sleep_trap = super::IMPORT_TRAP_BASE + 0x400;
        let send_trap = sleep_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let retrieval_trap = send_trap + crate::emulator::imports::IMPORT_TRAP_STRIDE;
        let (retrieval_ordinal, retrieval_name, retrieval_source) = match retrieval {
            NativeSleepSendRetrieval::GetMessageW => {
                (ORD_GET_MESSAGE_W, "GetMessageW", "GetMessageW/SentMessage")
            }
            NativeSleepSendRetrieval::PeekRemove => (
                ORD_PEEK_MESSAGE_W,
                "PeekMessageW",
                "PeekMessageW/SentMessage",
            ),
            NativeSleepSendRetrieval::GetMessageWNoWait => (
                ORD_GET_MESSAGE_WNO_WAIT,
                "GetMessageWNoWait",
                "GetMessageWNoWait/SentMessage",
            ),
        };
        let mut image_bytes = tiny_mips_spinner_pe();
        for (offset, words) in [
            (
                0x200,
                &[
                    0x3c19_0000 | (sleep_trap >> 16),
                    0x3739_0000 | (sleep_trap & 0xffff),
                    0x0320_f809, // T calls Sleep through a real MIPS jalr
                    0,
                    0x27a4_fc00, // addiu a0, sp, -0x400: writable MSG buffer
                    0x0000_2821, // move a1, zero: all windows
                    0x0000_3021, // move a2, zero: no minimum filter
                    0x0000_3821, // move a3, zero: no maximum filter
                    0x2408_0001, // addiu t0, zero, 1: PM_REMOVE for PeekMessageW
                    0xafa8_0010, // sw t0, 16(sp): fifth MIPS import argument
                    0x3c19_0000 | (retrieval_trap >> 16),
                    0x3739_0000 | (retrieval_trap & 0xffff),
                    0x0320_f809, // T enters real message retrieval after Sleep
                    0,
                    0x2404_0001, // finite Sleep(1) yields after nonblocking read
                    0x3c19_0000 | (sleep_trap >> 16),
                    0x3739_0000 | (sleep_trap & 0xffff),
                    0x0320_f809,
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
            (
                0x260,
                &[
                    0x3c19_0000 | (send_trap >> 16),
                    0x3739_0000 | (send_trap & 0xffff),
                    0x0320_f809, // S calls SendMessageW through a real MIPS jalr
                    0,
                    0x1000_ffff,
                    0,
                ][..],
            ),
        ] {
            for (index, word) in words.iter().copied().enumerate() {
                write_vec_u32(&mut image_bytes, offset + index * 4, word);
            }
        }
        for (index, word) in [0x2402_0077, 0x03e0_0008, 0].into_iter().enumerate() {
            write_vec_u32(&mut image_bytes, 0x2a0 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("sleep-native-send.exe", &image_bytes)?;
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let receiver_thread = super::MAIN_GUEST_THREAD_ID;
        let receiver_birth = kernel
            .handles
            .thread_birth_key_by_id(receiver_thread)
            .expect("boot receiver birth");
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(receiver_thread);
        for (address, ordinal, name) in [
            (sleep_trap, ORD_SLEEP, "Sleep"),
            (send_trap, ORD_SEND_MESSAGE_W, "SendMessageW"),
            (retrieval_trap, retrieval_ordinal, retrieval_name),
        ] {
            cpu.import_traps.insert(ImportTrap {
                address,
                module_kind: ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(ordinal),
                name: Some(name.to_owned()),
                iat_va: 0,
            });
        }
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        let entry = cpu.entry.expect("fixture entry");
        let wndproc = entry + 0xa0;
        let receiver_sp = cpu.stack_top.expect("fixture stack") - 0x100;
        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "SLEEP_NATIVE_SEND", "", None, 0, 0, 0);
        assert!(
            kernel
                .gwe
                .set_window_long(hwnd, GWL_WNDPROC, wndproc)
                .is_some()
        );
        let mut receiver_regs = super::MipsGuestContext::zero();
        receiver_regs.regs[4] = 10_000;
        receiver_regs.regs[16] = 0xa1a1_0020;
        receiver_regs.regs[29] = receiver_sp;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: entry,
            regs: receiver_regs,
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((
            receiver_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ));

        // S is a ready displaced context, not a CE-suspended task. It enters
        // the genuine SendMessageW import only after T's Sleep blocks.
        let (sender_handle, sender_thread) = kernel.create_guest_thread(entry + 0x60, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("live sender birth");
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[4] = hwnd;
        sender_regs.regs[5] = crate::ce::gwe::WM_USER + 0x72;
        sender_regs.regs[6] = 0x66;
        sender_regs.regs[29] = receiver_sp - 0x100;
        cpu.suspended_guest_thread = Some(super::SuspendedGuestThread {
            thread_id: sender_thread,
            thread_birth: Some(sender_birth),
            thread_handle: Some(sender_handle),
            regs: sender_regs,
            pc: entry + 0x60,
        });

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 64,
                wall_clock_limit_ms: 500,
                stop_pc: Some(wndproc),
                live_pump: true,
            },
        );
        // The current direct receiver-context branch marks T's staged
        // context unverified and can fail the post-run provenance check after
        // entering the callout. Keep the import/wait/send witnesses below as
        // the reachability gate; an error before them is a fixture failure.
        assert!(
            attempt.report.attempt_id().is_some(),
            "native MIPS attempt did not start"
        );
        let imports: Vec<_> = cpu
            .last_debug_snapshot()
            .expect("native attempt import trace")
            .last_imports
            .iter()
            .filter_map(|import| import.ordinal)
            .collect();
        assert!(
            imports
                .windows(2)
                .any(|pair| pair == [ORD_SLEEP, ORD_SEND_MESSAGE_W]),
            "real MIPS T→S import sequence missing: {imports:?}"
        );
        let sleep = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(wait.kind, super::BlockedWaitKind::Sleep)
            })
            .expect("receiver must still own its finite Sleep wait");
        assert_eq!(sleep.timeout_ms, 10_001);
        assert_ne!(sleep.return_pc, 0, "Sleep continuation must not be PC zero");
        assert_eq!(sleep.regs.regs[16], 0xa1a1_0020);
        assert_eq!(
            kernel
                .blocked_waiter(sleep.wait_id)
                .map(|wait| wait.owner_birth),
            Some(Some(receiver_birth)),
        );
        let send_ids = kernel.gwe.sent_message_ids_for_windows(&[hwnd]);
        assert_eq!(
            send_ids.len(),
            1,
            "native SendMessageW did not queue one send"
        );
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            None,
            "native SendMessageW entered T's WNDPROC before finite Sleep returned: wait={} send={}",
            sleep.wait_id,
            send_ids[0]
        );
        assert!(kernel.thread_has_pending_sent_message(receiver_thread));
        assert!(cpu.pending_wndproc_returns.is_empty());
        attempt.result?;
        if !continue_after_send {
            return Ok(());
        }

        let sleep_wait_id = sleep.wait_id;
        let sleep_return_pc = sleep.return_pc;
        assert_eq!(
            sleep_return_pc,
            entry + 0x10,
            "T Sleep must return into the native retrieval program"
        );
        let sender_wait_ids: Vec<_> = cpu
            .blocked_wait_threads
            .iter()
            .filter(|wait| {
                wait.thread_id == sender_thread
                    && matches!(wait.kind, super::BlockedWaitKind::SendMessage { .. })
            })
            .map(|wait| wait.wait_id)
            .collect();
        assert_eq!(
            sender_wait_ids.len(),
            1,
            "S must publish exactly one send wait"
        );
        let sender_return_pc = cpu
            .blocked_wait_threads
            .iter()
            .find(|wait| wait.wait_id == sender_wait_ids[0])
            .expect("native sender wait")
            .return_pc;
        let pre_deadline = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 100,
                stop_pc: None,
                live_pump: true,
            },
        );
        pre_deadline.result?;
        assert!(
            pre_deadline.report.attempt_id().is_none(),
            "blocked S import was replayed before T Sleep deadline: {:?}",
            pre_deadline.report,
        );
        assert_eq!(kernel.gwe.sent_message_ids_for_windows(&[hwnd]), send_ids);
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert_eq!(
            cpu.blocked_wait_threads
                .iter()
                .filter(|wait| wait.thread_id == sender_thread)
                .map(|wait| wait.wait_id)
                .collect::<Vec<_>>(),
            sender_wait_ids,
        );
        assert!(kernel.blocked_waiter(sleep_wait_id).is_some());
        let staged_sender_pc = cpu.saved_context.as_ref().map(|saved| saved.pc);
        let staged_running_thread = cpu.running_guest_thread;
        kernel.timers.sleep_ms(10_001);
        let wake_attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sleep_return_pc),
                live_pump: true,
            },
        );
        wake_attempt.result?;
        assert!(
            kernel.blocked_waiter(sleep_wait_id).is_none(),
            "timed-out Sleep did not retire its exact wait: return_pc=0x{sleep_return_pc:08x}, staged_sender_pc={staged_sender_pc:?}, staged_running_thread={staged_running_thread:?}, current={}, sends={:?}, blocked={:?}",
            cpu.current_thread_id,
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            cpu.blocked_wait_threads,
        );
        assert_eq!(cpu.saved_context_pc(), Some(sleep_return_pc));
        assert_eq!(
            cpu.saved_context_thread_birth,
            Some(receiver_birth),
            "Sleep return context lost T identity: report={:?}, current={}, running={:?}, native_waits={:?}, last_pc={:?}, provenance_rejections={}",
            wake_attempt.report,
            cpu.current_thread_id,
            cpu.running_guest_thread,
            cpu.blocked_wait_threads,
            cpu.last_debug_snapshot().map(|snapshot| snapshot.pc),
            cpu.staging_provenance_rejections,
        );
        assert_eq!(cpu.current_thread_id, receiver_thread);
        assert_eq!(kernel.gwe.sent_message_ids_for_windows(&[hwnd]), send_ids);
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert!(
            !cpu.prepare_active_sent_message_callout(&mut kernel),
            "deferred send was activated before T executed {retrieval_name}"
        );
        assert_eq!(kernel.gwe.sent_message_ids_for_windows(&[hwnd]), send_ids);
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        let delivery_attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(wndproc),
                live_pump: true,
            },
        );
        delivery_attempt.result?;
        assert_eq!(cpu.saved_context_pc(), Some(wndproc));
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert_eq!(cpu.current_thread_id, receiver_thread);
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(send_ids[0])
        );
        assert_eq!(cpu.pending_wndproc_returns.len(), 1);
        assert_eq!(cpu.pending_wndproc_returns[0].source, retrieval_source);
        assert_eq!(
            cpu.blocked_wait_threads
                .iter()
                .filter(|wait| wait.thread_id == sender_thread)
                .map(|wait| wait.wait_id)
                .collect::<Vec<_>>(),
            sender_wait_ids,
        );
        let wndproc_return_attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(retrieval_trap),
                live_pump: true,
            },
        );
        wndproc_return_attempt.result?;
        assert!(cpu.pending_wndproc_returns.is_empty());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(kernel.sent_message_result_ready(send_ids[0]));
        assert_eq!(
            kernel
                .gwe
                .sent_message(send_ids[0])
                .and_then(|send| send.result),
            Some(0x77),
        );
        let sender_resume_attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sender_return_pc),
                live_pump: true,
            },
        );
        sender_resume_attempt.result?;
        if !matches!(retrieval, NativeSleepSendRetrieval::GetMessageW) {
            let imports = &cpu
                .last_debug_snapshot()
                .expect("nonblocking read native return trace")
                .last_imports;
            assert!(
                imports.windows(2).any(|pair| {
                    pair[0].ordinal == Some(retrieval_ordinal) && pair[1].ordinal == Some(ORD_SLEEP)
                }),
                "T must issue a real finite Sleep after nonblocking {retrieval_name} before S resumes: {imports:?}"
            );
        }
        assert_eq!(
            cpu.saved_context_pc(),
            Some(
                if matches!(retrieval, NativeSleepSendRetrieval::GetMessageW) {
                    retrieval_trap
                } else {
                    sleep_trap
                }
            ),
        );
        assert_eq!(cpu.saved_context_thread_birth, Some(receiver_birth));
        assert!(cpu.running_guest_thread.is_none());
        if matches!(retrieval, NativeSleepSendRetrieval::GetMessageW) {
            assert_eq!(
                cpu.blocked_guest_thread.as_ref().map(|wait| wait.thread_id),
                Some(receiver_thread),
            );
        } else {
            assert!(cpu.blocked_wait_threads.iter().any(|wait| {
                wait.thread_id == receiver_thread
                    && matches!(wait.kind, super::BlockedWaitKind::Sleep)
            }));
        }
        assert!(kernel.blocked_waiter(sender_wait_ids[0]).is_some());
        assert!(kernel.sent_message_result_ready(send_ids[0]));
        assert_eq!(kernel.gwe.stats().send_transaction_count, 1);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 1);
        let sender_resume_attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 128,
                wall_clock_limit_ms: 500,
                stop_pc: Some(sender_return_pc),
                live_pump: true,
            },
        );
        sender_resume_attempt.result?;
        assert_eq!(
            sender_resume_attempt.report.start_thread_id(),
            Some(sender_thread)
        );
        assert_eq!(
            sender_resume_attempt.report.start_pc(),
            Some(sender_return_pc)
        );
        assert_eq!(
            cpu.saved_context_pc(),
            Some(sender_return_pc),
            "{retrieval_name} sender did not resume: entry=0x{entry:08x}, wndproc=0x{wndproc:08x}, retrieval_trap=0x{retrieval_trap:08x}, report={:?}, current={}, running={:?}, saved_birth={:?}, blocked={:?}, send={:?}, pending_returns={:?}, snapshot={:?}",
            sender_resume_attempt.report,
            cpu.current_thread_id,
            cpu.running_guest_thread,
            cpu.saved_context_thread_birth,
            cpu.blocked_wait_threads,
            kernel.gwe.sent_message(send_ids[0]),
            cpu.pending_wndproc_returns,
            cpu.last_debug_snapshot()
                .map(|snapshot| (&snapshot.pc, &snapshot.last_imports)),
        );
        assert_eq!(cpu.saved_context_thread_birth, Some(sender_birth));
        assert_eq!(cpu.current_thread_id, sender_thread);
        assert_eq!(
            cpu.saved_context
                .as_ref()
                .expect("sender continuation")
                .regs
                .regs[2],
            0x77,
        );
        assert!(kernel.blocked_waiter(sender_wait_ids[0]).is_none());
        assert!(
            cpu.blocked_wait_threads
                .iter()
                .all(|wait| wait.wait_id != sender_wait_ids[0])
        );
        assert!(kernel.gwe.sent_message(send_ids[0]).is_none());
        assert_eq!(kernel.gwe.stats().send_transaction_count, 1);
        assert_eq!(kernel.gwe.stats().send_transaction_completed_count, 1);
        Ok(())
    }

    #[test]
    fn active_saved_context_enters_pending_sent_message_callout() -> crate::Result<()> {
        let config = crate::config::RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let mut scheduler = super::UnicornMips::new()?;
        let receiver_launch =
            kernel.queue_process_launch(Some("\\Test\\pending-receiver.exe".to_owned()), None);
        let _ = kernel.take_pending_process_launches();
        let receiver_process = receiver_launch.process_id;
        let receiver_thread = receiver_launch.thread_id;
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("registered receiver birth");
        let sender_thread = 1;
        let wndproc = 0x0001_2570;
        let return_pc = 0x7fff_ffe0;

        kernel.set_current_process_id(receiver_process);
        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "PENDING_SEND_TARGET", "", None, 0, 0, 0);
        kernel
            .gwe
            .set_window_long(hwnd, crate::ce::gwe::GWL_WNDPROC, wndproc);
        let send_id = kernel
            .begin_cross_thread_send_message_w(
                sender_thread,
                hwnd,
                crate::ce::gwe::WM_USER + 1,
                0x0e,
                0,
                None,
            )
            .expect("queued send");

        scheduler.set_initial_thread_id(receiver_thread);
        scheduler.current_thread_id = receiver_thread;
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[29] = 0x7ffc_0000;
        regs.regs[31] = return_pc;
        scheduler.saved_context = Some(super::SavedCpuContext {
            pc: return_pc,
            regs,
        });
        scheduler.saved_context_thread_birth = Some(receiver_birth);

        assert!(scheduler.prepare_active_sent_message_callout(&mut kernel));
        assert_eq!(scheduler.current_thread_id, receiver_thread);
        assert_eq!(
            kernel.gwe.active_sent_message_id(receiver_thread),
            Some(send_id)
        );
        assert!(!kernel.thread_has_pending_sent_message(receiver_thread));
        let saved = scheduler
            .saved_context
            .as_ref()
            .expect("wndproc callout context");
        assert_eq!(saved.pc, wndproc);
        assert_eq!(saved.regs.regs[4], hwnd);
        assert_eq!(saved.regs.regs[5], crate::ce::gwe::WM_USER + 1);
        assert_eq!(saved.regs.regs[6], 0x0e);
        assert_eq!(saved.regs.regs[25], wndproc);
        assert_eq!(saved.regs.regs[31], super::WNDPROC_RETURN_STUB_ADDR);

        let callout_regs = saved.regs.clone();
        scheduler.saved_context = Some(super::SavedCpuContext {
            pc: return_pc,
            regs: {
                let mut regs = callout_regs;
                regs.regs[2] = 0x1234;
                regs.regs[31] = return_pc;
                regs
            },
        });
        assert!(scheduler.complete_escaped_direct_send_message_callout(&mut kernel)?);
        assert!(kernel.sent_message_result_ready(send_id));
        assert_eq!(
            kernel.take_completed_send_message_result(send_id),
            Some(0x1234)
        );

        Ok(())
    }

    #[test]
    fn send_message_receiver_context_requires_same_process_guest_wndproc() {
        assert!(super::should_receiver_context_send_message_wndproc(
            1,
            0,
            2,
            0,
            0x0001_3570
        ));
        assert!(!super::should_receiver_context_send_message_wndproc(
            1,
            0,
            1,
            0,
            0x0001_3570
        ));
        assert!(!super::should_receiver_context_send_message_wndproc(
            1,
            0,
            2,
            0x42,
            0x0001_3570
        ));
        assert!(!super::should_receiver_context_send_message_wndproc(
            1, 0, 2, 0, 0
        ));
        assert!(!super::should_receiver_context_send_message_wndproc(
            1,
            0,
            2,
            0,
            crate::ce::gwe::DEFAULT_WNDPROC
        ));
    }

    #[test]
    fn native_terminate_process_import_requires_captured_caller_birth() {
        use crate::ce::coredll_ordinals::ORD_TERMINATE_PROCESS;
        use crate::emulator::imports::ImportModuleKind;

        for process_handle in [crate::ce::kernel::CE_CURRENT_PROCESS_PSEUDO_HANDLE, 0x1234] {
            assert!(super::native_import_requires_verified_thread_birth(
                ImportModuleKind::Coredll,
                Some(ORD_TERMINATE_PROCESS),
                process_handle,
            ));
            assert!(!super::native_import_requires_verified_thread_birth(
                ImportModuleKind::Fsdmgr,
                Some(ORD_TERMINATE_PROCESS),
                process_handle,
            ));
        }
    }

    #[test]
    fn native_terminate_process_import_requires_matching_process_lease() {
        let mut kernel = crate::ce::kernel::CeKernel::boot(
            crate::config::RuntimeConfig::load_default().unwrap(),
        );
        let process_a = kernel.current_process_birth_key().expect("boot owner");
        let caller_a = kernel.live_thread_birth_key_by_id(1).expect("boot caller");
        let launch_b = kernel.queue_process_launch(None, None);
        let process_b = launch_b.process_birth.expect("B owner");
        let caller_b = launch_b.primary_thread_birth.expect("B caller");

        assert!(super::native_process_exit_import_caller_matches_owner(
            &kernel,
            Some(caller_a),
            Some(process_a),
        ));
        assert!(!super::native_process_exit_import_caller_matches_owner(
            &kernel,
            Some(caller_a),
            Some(process_b),
        ));
        kernel.set_current_process_id(launch_b.process_id);
        assert!(!super::native_process_exit_import_caller_matches_owner(
            &kernel,
            Some(caller_a),
            Some(process_a),
        ));
        assert!(!super::native_process_exit_import_caller_matches_owner(
            &kernel,
            None,
            Some(process_b),
        ));
        assert!(super::native_process_exit_import_caller_matches_owner(
            &kernel,
            Some(caller_b),
            Some(process_b),
        ));
    }

