    #[test]
    fn send_message_direct_wndproc_captures_caller_registers() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let thread_id = 1;
        let wndproc: u32 = 0x0001_3570;
        let return_pc: u32 = 0x0040_1000;
        let raw_return_pc: u32 = 0x008c_c9b0;
        let trampoline_jumps = [super::MipsTrampolineJump {
            origin: return_pc,
            stub: 0x008c_c9a0,
            byte_len: 0x20,
        }];
        let hwnd = kernel.create_window_ex_w(thread_id, "DIRECT_SEND", "", None, 0, 0, 0);
        kernel.gwe.set_window_long(hwnd, GWL_WNDPROC, wndproc);
        uc.reg_write(RegisterMIPS::RA, u64::from(raw_return_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::FP, 0x1234_5678).unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7777_0010).unwrap();

        let sender_birth = kernel
            .live_thread_birth_key_by_id(thread_id)
            .expect("boot sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            thread_id,
            Some(sender_birth),
        ));
        let running_thread = Rc::new(RefCell::new(Some((thread_id, 0x0000_0120))));
        let blocked_waits = Rc::new(RefCell::new(Vec::new()));
        let pending = Rc::new(RefCell::new(Vec::new()));
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let cross_process_send_yield = Rc::new(RefCell::new(None));
        assert!(super::try_enter_send_message_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W),
            &[hwnd, crate::ce::gwe::WM_USER + 88, 0x2716, 0],
            thread_id,
            &trampoline_jumps,
            &current_thread_id,
            &running_thread,
            &blocked_waits,
            &pending,
            &parked,
            &cross_process_send_yield,
            &std::cell::RefCell::new(None),
        ));

        assert_eq!(current_thread_id.get().0, thread_id);
        assert!(blocked_waits.borrow().is_empty());
        assert!(cross_process_send_yield.borrow().is_none());
        assert_eq!(uc.reg_read(RegisterMIPS::A0).unwrap() as u32, hwnd);
        assert_eq!(
            uc.reg_read(RegisterMIPS::A1).unwrap() as u32,
            crate::ce::gwe::WM_USER + 88
        );
        assert_eq!(uc.reg_read(RegisterMIPS::A2).unwrap() as u32, 0x2716);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, wndproc);

        let pending = pending.borrow();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].return_pc, return_pc);
        assert_eq!(pending[0].send_thread_id, Some(thread_id));
        assert!(pending[0].send_restore.is_none());
        let caller_regs = pending[0]
            .caller_regs
            .as_ref()
            .expect("direct SendMessageW should preserve caller registers");
        assert_eq!(caller_regs.regs[16], 0x7777_0010);
        assert_eq!(caller_regs.regs[30], 0x1234_5678);
    }

    #[test]
    fn stale_birth_owned_hwnd_native_send_stops_before_reused_tid_wndproc()
    -> crate::error::Result<()> {
        let config = RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let (old_handle, thread_id) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let old_birth = kernel
            .handles
            .thread_birth_key_for_handle(old_handle)
            .expect("old thread birth");
        let stale_hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                old_birth,
                "STALE_NATIVE_SEND",
                "old",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 20, 20),
            )
            .expect("old birth-owned HWND");
        assert!(
            kernel
                .gwe
                .set_window_long(stale_hwnd, GWL_WNDPROC, 0x0001_3570)
                .is_some()
        );
        assert!(kernel.mark_guest_thread_exited_by_birth(old_birth, 0));
        assert!(kernel.close_handle(old_handle)?);
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, thread_id, 0x0040_4000, 0, false)?;
        let new_birth = kernel
            .handles
            .thread_birth_key_for_handle(new_handle)
            .expect("reused thread birth");
        assert_ne!(old_birth, new_birth);
        let live_hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                new_birth,
                "LIVE_NATIVE_SEND",
                "new",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::from_origin_size(0, 0, 20, 20),
            )
            .expect("new birth-owned HWND");
        assert!(
            kernel
                .gwe
                .set_window_long(live_hwnd, GWL_WNDPROC, 0x0001_3570)
                .is_some()
        );
        assert!(kernel.gwe.is_window(stale_hwnd));
        assert!(kernel.gwe.is_window(live_hwnd));

        let (neighbor_handle, _neighbor_thread) = kernel.create_guest_thread(0x0040_5000, 0, false);
        let neighbor_birth = kernel
            .handles
            .thread_birth_key_for_handle(neighbor_handle)
            .expect("neighbor birth");
        let neighbor_frame = kernel
            .try_publish_finite_sleep_wait_for_birth(
                neighbor_birth,
                neighbor_handle,
                kernel.timers.tick_count(),
                60_000,
            )
            .expect("neighbor finite Sleep frame");
        let scheduler_before = kernel.scheduler_stats();

        for ordinal in [
            crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W,
            crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT,
        ] {
            let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
            let original_regs = [
                (RegisterMIPS::PC, 0x0040_1080_u64),
                (RegisterMIPS::RA, 0x0040_1090_u64),
                (RegisterMIPS::V0, 0x7777_0022_u64),
                (RegisterMIPS::A0, 0x8888_0033_u64),
            ];
            for &(register, value) in &original_regs {
                uc.reg_write(register, value).unwrap();
            }
            let current_thread_id =
                Rc::new(super::NativeCurrentThread::new(thread_id, Some(new_birth)));
            let running_thread = Rc::new(RefCell::new(Some((thread_id, new_handle))));
            let blocked_waits = Rc::new(RefCell::new(Vec::new()));
            let pending = Rc::new(RefCell::new(Vec::new()));
            let parked = Rc::new(RefCell::new(VecDeque::new()));
            let cross_process_send_yield = Rc::new(RefCell::new(None));
            let terminal_error = RefCell::new(None);
            assert!(super::try_enter_send_message_callout(
                &mut kernel,
                &mut uc,
                &super::SealedHostWriteGuard::default(),
                crate::emulator::imports::ImportModuleKind::Coredll,
                Some(ordinal),
                &[stale_hwnd, crate::ce::gwe::WM_USER + 1, 0, 0, 0, 1000, 0],
                thread_id,
                &[],
                &current_thread_id,
                &running_thread,
                &blocked_waits,
                &pending,
                &parked,
                &cross_process_send_yield,
                &terminal_error,
            ));
            assert!(matches!(
                terminal_error.borrow().as_ref(),
                Some(Error::Backend(reason)) if reason.contains("stale birth-owned HWND")
            ));
            assert_eq!(current_thread_id.get(), (thread_id, None));
            for &(register, value) in &original_regs {
                assert_eq!(uc.reg_read(register).unwrap(), value);
            }
            assert_eq!(*running_thread.borrow(), Some((thread_id, new_handle)));
            assert!(blocked_waits.borrow().is_empty());
            assert!(pending.borrow().is_empty());
            assert!(cross_process_send_yield.borrow().is_none());
            assert!(!kernel.gwe.in_send_message(thread_id));
            assert!(
                kernel
                    .gwe
                    .sent_message_ids_for_windows(&[stale_hwnd, live_hwnd])
                    .is_empty()
            );
            assert_eq!(kernel.scheduler_stats(), scheduler_before);
            assert_eq!(
                kernel.handles.active_finite_sleep_frame(neighbor_birth),
                Some(neighbor_frame)
            );
            assert!(kernel.blocked_waiter(neighbor_frame.wait_id()).is_some());
        }

        // The same numeric TID still reaches a WNDPROC through its live HWND.
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_1090).unwrap();
        let current_thread_id =
            Rc::new(super::NativeCurrentThread::new(thread_id, Some(new_birth)));
        let running_thread = Rc::new(RefCell::new(Some((thread_id, new_handle))));
        let blocked_waits = Rc::new(RefCell::new(Vec::new()));
        let pending = Rc::new(RefCell::new(Vec::new()));
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let cross_process_send_yield = Rc::new(RefCell::new(None));
        let terminal_error = RefCell::new(None);
        assert!(super::try_enter_send_message_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W),
            &[live_hwnd, crate::ce::gwe::WM_USER + 2, 0, 0],
            thread_id,
            &[],
            &current_thread_id,
            &running_thread,
            &blocked_waits,
            &pending,
            &parked,
            &cross_process_send_yield,
            &terminal_error,
        ));
        assert!(terminal_error.borrow().is_none());
        assert_eq!(current_thread_id.get(), (thread_id, Some(new_birth)));
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap(), 0x0001_3570);
        assert_eq!(pending.borrow().len(), 1);
        assert!(blocked_waits.borrow().is_empty());
        assert_eq!(
            kernel.handles.active_finite_sleep_frame(neighbor_birth),
            Some(neighbor_frame)
        );
        Ok(())
    }

    #[test]
    fn send_message_callout_queues_cross_thread_receiver_without_relabel() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let sender_thread = 1;
        let (_receiver_handle, receiver_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("receiver birth");
        let wndproc: u32 = 0x0001_3570;
        let return_pc: u32 = 0x0040_1000;
        let raw_return_pc: u32 = 0x008c_c9b0;
        let trampoline_jumps = [super::MipsTrampolineJump {
            origin: return_pc,
            stub: 0x008c_c9a0,
            byte_len: 0x20,
        }];
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "CROSS_SEND",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned receiver HWND");
        kernel.gwe.set_window_long(hwnd, GWL_WNDPROC, wndproc);
        uc.reg_write(RegisterMIPS::PC, 0x0040_0080).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(raw_return_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x0030_0000).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0x7777_0002).unwrap();
        uc.reg_write(RegisterMIPS::A0, 0x7777_0003).unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7777_0001).unwrap();
        let original_regs = [
            (RegisterMIPS::PC, 0x0040_0080_u64),
            (RegisterMIPS::RA, u64::from(raw_return_pc)),
            (RegisterMIPS::SP, 0x0030_0000),
            (RegisterMIPS::V0, 0x7777_0002),
            (RegisterMIPS::A0, 0x7777_0003),
            (RegisterMIPS::S0, 0x7777_0001),
        ];

        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("boot sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let running_thread = Rc::new(RefCell::new(Some((
            sender_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ))));
        let blocked_waits = Rc::new(RefCell::new(Vec::new()));
        let pending = Rc::new(RefCell::new(Vec::new()));
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let cross_process_send_yield = Rc::new(RefCell::new(None));
        let terminal_error = RefCell::new(None);
        assert!(super::try_enter_send_message_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W),
            &[hwnd, crate::ce::gwe::WM_USER + 88, 0x55, 0x66],
            sender_thread,
            &trampoline_jumps,
            &current_thread_id,
            &running_thread,
            &blocked_waits,
            &pending,
            &parked,
            &cross_process_send_yield,
            &terminal_error,
        ));

        assert!(terminal_error.borrow().is_none());
        assert_eq!(current_thread_id.get(), (sender_thread, Some(sender_birth)));
        assert_eq!(*running_thread.borrow(), None);
        for &(register, value) in &original_regs {
            assert_eq!(uc.reg_read(register).unwrap(), value, "{register:?}");
        }
        assert!(
            pending.borrow().is_empty(),
            "B's WNDPROC is not entered by A"
        );
        assert!(cross_process_send_yield.borrow().is_none());
        let send_ids = kernel.gwe.sent_message_ids_for_windows(&[hwnd]);
        assert_eq!(send_ids.len(), 1);
        let send_id = send_ids[0];
        assert_eq!(
            kernel
                .gwe
                .sent_message(send_id)
                .and_then(|sent| sent.receiver_birth),
            Some(receiver_birth)
        );
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(!kernel.gwe.in_send_message(receiver_thread));
        let blocked_waits = blocked_waits.borrow();
        assert_eq!(blocked_waits.len(), 1);
        assert_eq!(blocked_waits[0].thread_id, sender_thread);
        assert_eq!(
            blocked_waits[0].thread_handle,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE
        );
        assert_eq!(blocked_waits[0].return_pc, return_pc);
        assert_eq!(blocked_waits[0].regs.regs[16], 0x7777_0001);
        let super::BlockedWaitKind::SendMessage {
            send_id: blocked_send_id,
            receiver_thread_id: blocked_receiver,
            previous_running_thread,
            ..
        } = blocked_waits[0].kind
        else {
            panic!("sender should park as a SendMessage blocked wait");
        };
        assert_eq!(blocked_send_id, send_id);
        assert_eq!(blocked_receiver, receiver_thread);
        assert_eq!(
            previous_running_thread,
            Some((
                sender_thread,
                crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE
            ))
        );
        let scheduler_wait = kernel
            .blocked_waiter(blocked_waits[0].wait_id)
            .expect("exact sender wait is published");
        assert_eq!(scheduler_wait.owner_birth, Some(sender_birth));
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![send_id]
        );
    }

    #[test]
    fn receiver_context_send_stale_sender_birth_preserves_neighbor_queue() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let sender_thread = 1;
        let (_receiver_handle, receiver_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("receiver birth");
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "CROSS_SEND",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned receiver HWND");
        kernel.gwe.set_window_long(hwnd, GWL_WNDPROC, 0x0001_3570);
        let unrelated_send_id = kernel
            .begin_cross_thread_send_message_w(
                sender_thread,
                hwnd,
                crate::ce::gwe::WM_USER + 87,
                0,
                0,
                None,
            )
            .expect("neighboring queued send");
        let queued_before = kernel.gwe.sent_message_ids_for_windows(&[hwnd]);
        assert_eq!(queued_before, vec![unrelated_send_id]);
        assert_eq!(
            kernel
                .gwe
                .sent_message(unrelated_send_id)
                .and_then(|sent| sent.receiver_birth),
            Some(receiver_birth)
        );
        let scheduler_before = kernel.scheduler_stats();
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(sender_thread, None));
        let running_thread = Rc::new(RefCell::new(Some((
            sender_thread,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE,
        ))));
        let blocked_waits = Rc::new(RefCell::new(Vec::new()));
        let pending = Rc::new(RefCell::new(Vec::new()));
        let parked = Rc::new(RefCell::new(VecDeque::new()));
        let cross_process_send_yield = Rc::new(RefCell::new(None));
        let terminal_error = RefCell::new(None);
        let original_regs = [
            (RegisterMIPS::PC, 0x0040_8880_u64),
            (RegisterMIPS::RA, 0x0040_1000),
            (RegisterMIPS::V0, 0xa5a5_1234),
            (RegisterMIPS::SP, 0x0030_0000),
            (RegisterMIPS::A0, 0x1111_1111),
            (RegisterMIPS::A1, 0x2222_2222),
            (RegisterMIPS::A2, 0x3333_3333),
            (RegisterMIPS::A3, 0x4444_4444),
            (RegisterMIPS::T9, 0x5555_5555),
        ];
        for &(register, value) in &original_regs {
            uc.reg_write(register, value).unwrap();
        }

        // A cannot publish a second send without a verified native sender
        // birth. Its unrelated neighbor must remain queued and untouched.
        assert!(super::try_enter_send_message_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W),
            &[hwnd, crate::ce::gwe::WM_USER + 88, 0x55, 0x66],
            sender_thread,
            &[],
            &current_thread_id,
            &running_thread,
            &blocked_waits,
            &pending,
            &parked,
            &cross_process_send_yield,
            &terminal_error,
        ));
        assert!(matches!(
            terminal_error.borrow().as_ref(),
            Some(crate::error::Error::Backend(reason))
                if reason.contains("stale sender birth")
        ));
        assert_eq!(current_thread_id.get(), (sender_thread, None));
        assert_eq!(
            *running_thread.borrow(),
            Some((
                sender_thread,
                crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE
            ))
        );
        assert!(blocked_waits.borrow().is_empty());
        assert_eq!(kernel.blocked_waiters().count(), 0);
        assert_eq!(kernel.scheduler_stats(), scheduler_before);
        assert!(pending.borrow().is_empty());
        assert!(cross_process_send_yield.borrow().is_none());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);
        assert!(!kernel.gwe.in_send_message(receiver_thread));
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            queued_before
        );
        assert!(kernel.gwe.sent_message(unrelated_send_id).is_some());
        assert!(kernel.gwe.sent_message(unrelated_send_id + 1).is_none());
        for &(register, value) in &original_regs {
            assert_eq!(uc.reg_read(register).unwrap(), value, "{register:?}");
        }
    }

    #[test]
    fn send_message_callout_blocks_sender_when_yielding_to_parked_process() -> crate::Result<()> {
        let config = RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let sender_thread = 1;
        let sender_process = 1;
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("boot sender birth");
        let sender_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let receiver_thread = 3;
        let receiver_process = 67;
        let wndproc: u32 = 0x0001_3570;
        let return_pc: u32 = 0x0040_1000;

        kernel.set_current_process_id(receiver_process);
        let hwnd =
            kernel.create_window_ex_w(receiver_thread, "CROSS_PROCESS_SEND", "", None, 0, 0, 0);
        kernel.gwe.set_window_long(hwnd, GWL_WNDPROC, wndproc);
        kernel.set_current_process_id(sender_process);

        let child = super::UnicornMips::new()?;
        let parked = Rc::new(RefCell::new(VecDeque::from([super::ParkedProcess {
            application: Some("\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned()),
            process_handle: Some(0x220),
            thread_handle: Some(0x224),
            process_state: crate::ce::kernel::CurrentProcessState {
                process_id: receiver_process,
                exit_code: crate::ce::kernel::STILL_ACTIVE,
                signaled: false,
            },
            thread_id: receiver_thread,
            cpu: Box::new(child),
            blocked_send_id: None,
            module_base: 0x0040_0000,
            module_path: "\\SDMMC Disk\\INavi\\happyway_win.exe".to_owned(),
            module_host_path: std::path::PathBuf::from(
                r"D:\INAVI_Emulator\INAVI\INavi\happyway_win.exe",
            ),
            command_line: "child".to_owned(),
            current_directory: None,
        }])));
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
        let blocked_waits = Rc::new(RefCell::new(Vec::new()));
        let pending = Rc::new(RefCell::new(Vec::new()));
        let cross_process_send_yield = Rc::new(RefCell::new(None));
        uc.reg_write(RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x7777_0002).unwrap();

        assert!(super::try_enter_send_message_callout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_W),
            &[hwnd, crate::ce::gwe::WM_USER + 89, 0x55, 0x66],
            sender_thread,
            &[],
            &current_thread_id,
            &running_thread,
            &blocked_waits,
            &pending,
            &parked,
            &cross_process_send_yield,
            &std::cell::RefCell::new(None),
        ));

        let yielded = cross_process_send_yield
            .borrow()
            .clone()
            .expect("cross-process send yield");
        assert_eq!(yielded.send_id, 1);
        assert_eq!(yielded.sender_thread_id, sender_thread);
        assert_eq!(yielded.target_process_id, receiver_process);
        assert!(pending.borrow().is_empty());
        let blocked_waits = blocked_waits.borrow();
        assert_eq!(blocked_waits.len(), 1);
        let blocked = &blocked_waits[0];
        assert_eq!(blocked.thread_id, sender_thread);
        assert_eq!(blocked.thread_handle, sender_handle);
        assert_eq!(blocked.return_pc, return_pc);
        assert_eq!(blocked.regs.regs[16], 0x7777_0002);
        let super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id,
            previous_running_thread,
            ..
        } = blocked.kind
        else {
            panic!("sender should be blocked on SendMessage");
        };
        assert_eq!(send_id, yielded.send_id);
        assert_eq!(receiver_thread_id, receiver_thread);
        assert_eq!(
            previous_running_thread,
            Some((sender_thread, sender_handle))
        );
        assert_eq!(
            kernel
                .blocked_waiter(blocked.wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(sender_birth),
        );
        assert_eq!(current_thread_id.get(), (sender_thread, Some(sender_birth)));
        assert!(kernel.gwe.sent_message(yielded.send_id).is_some());
        assert_eq!(kernel.gwe.active_sent_message_id(receiver_thread), None);

        Ok(())
    }

    #[test]
    fn import_callout_return_pc_maps_stub_ra_to_guest_continuation() {
        let return_pc: u32 = 0x0040_1000;
        let raw_return_pc: u32 = 0x008c_c9b0;
        let trampoline_jumps = [super::MipsTrampolineJump {
            origin: return_pc,
            stub: 0x008c_c9a0,
            byte_len: 0x20,
        }];

        assert_eq!(
            super::import_callout_return_pc(raw_return_pc, &trampoline_jumps),
            return_pc
        );
        assert_eq!(super::import_callout_return_pc(return_pc, &[]), return_pc);
    }

    fn native_payload_fixture() -> (
        super::NativeMappingPins,
        CeKernel,
        Unicorn<'static, ()>,
        RefCell<super::KernelMemoryMappings>,
        Vec<super::MappedBlob>,
        u32,
    ) {
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default().unwrap());
        let owner = kernel.current_process_birth_key().expect("fixture birth");
        kernel
            .memory
            .reserve_fixed_private_range(
                owner,
                crate::ce::memory::VirtualAllocationSource::ProcessHeapArena,
                super::GUEST_HEAP_ARENA_BASE,
                super::GUEST_HEAP_ARENA_SIZE,
                0x04,
            )
            .expect("fixture heap reservation");
        kernel
            .memory
            .heap_alloc(owner, kernel.memory.get_process_heap(), 0, 0xff0)
            .unwrap();
        let hwnd = kernel.create_window_ex_w(1, "NATIVE_PAYLOAD", "", None, 0, 0, 0);
        kernel.gwe.set_window_long(hwnd, GWL_WNDPROC, 0x0001_0000);
        for _ in 0..32 {
            if kernel.gwe.get_message_filtered(1, None, 0, 0).is_none() {
                break;
            }
        }
        let _ = kernel.gwe.validate_window(hwnd);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x10000, 0x1000, Prot::ALL).unwrap();
        uc.mem_map(0x20000, 0x1000, Prot::ALL).unwrap();
        uc.reg_write(RegisterMIPS::SP, 0x20800).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x10c00).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x10000).unwrap();
        let mut mapping = super::KernelMemoryMappings::new(&[]);
        mapping.system_slab_owner = Some(owner);
        mapping.system_slab_ranges =
            vec![(super::GUEST_HEAP_ARENA_BASE, super::GUEST_HEAP_ARENA_SIZE)];
        let mapped = RefCell::new(mapping);
        let blobs = vec![super::MappedBlob {
            name: "ram:msg".to_owned(),
            base: 0x20000,
            bytes: vec![0; 0x1000].into(),
        }];
        (
            super::NativeMappingPins::default(),
            kernel,
            uc,
            mapped,
            blobs,
            hwnd,
        )
    }

    fn native_payload_message(kernel: &mut CeKernel, hwnd: u32) -> crate::ce::gwe::Message {
        kernel
            .gwe
            .peek_message_filtered(
                1,
                Some(hwnd),
                crate::ce::gwe::WM_WINDOWPOSCHANGED,
                crate::ce::gwe::WM_WINDOWPOSCHANGED,
                crate::ce::gwe::PeekFlags::empty(),
            )
            .unwrap()
    }

    fn native_payload_mips_fields(
        kernel: &CeKernel,
        uc: &mut Unicorn<'_, ()>,
        mapped: &RefCell<super::KernelMemoryMappings>,
        native_pins: &super::NativeMappingPins,
        pointer: u32,
    ) -> (u32, u32, u32) {
        let owner = kernel.current_process_birth_key().expect("fixture birth");
        super::map_private_slab_pages(
            uc,
            kernel,
            &mut mapped.borrow_mut(),
            owner,
            native_pins,
            None,
        )
        .expect("map canonical payload pages");
        // Actual MIPS loads of WINDOWPOS x, y and width through the pointer.
        let code = [0x8c82_0008u32, 0x8c83_000c, 0x8c88_0010];
        uc.mem_write(
            0x10000,
            &code
                .into_iter()
                .flat_map(u32::to_le_bytes)
                .collect::<Vec<_>>(),
        )
        .unwrap();
        uc.reg_write(RegisterMIPS::A0, u64::from(pointer)).unwrap();
        uc.emu_start(0x10000, 0x1000c, 0, 0).unwrap();
        (
            uc.reg_read(RegisterMIPS::V0).unwrap() as u32,
            uc.reg_read(RegisterMIPS::V1).unwrap() as u32,
            uc.reg_read(RegisterMIPS::T0).unwrap() as u32,
        )
    }

    fn native_payload_restored_fields(kernel: &CeKernel, pointer: u32) -> (u32, u32, u32) {
        let native_pins = super::NativeMappingPins::default();
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let owner = kernel.current_process_birth_key().expect("fixture birth");
        let mut mapped = super::KernelMemoryMappings::new(&[]);
        mapped.system_slab_owner = Some(owner);
        mapped.system_slab_ranges =
            vec![(super::GUEST_HEAP_ARENA_BASE, super::GUEST_HEAP_ARENA_SIZE)];
        super::map_private_slab_pages(&mut uc, kernel, &mut mapped, owner, &native_pins, None)
            .expect("restore canonical payload pages");
        uc.mem_map(0x10000, 0x1000, Prot::ALL).unwrap();
        let fields = native_payload_mips_fields(
            kernel,
            &mut uc,
            &RefCell::new(mapped),
            &native_pins,
            pointer,
        );
        drop(uc); // Close the native owner before its raw-pointer pin registry.
        fields
    }

    fn native_payload_canonical_snapshot(
        kernel: &CeKernel,
        pointer: u32,
    ) -> Vec<(u32, Option<Vec<u8>>)> {
        let owner = kernel.current_process_birth_key().expect("fixture birth");
        let first = pointer & !0xfff;
        let last = pointer.checked_add(27).expect("WINDOWPOS range") & !0xfff;
        let pages = if first == last {
            vec![first]
        } else {
            vec![first, last]
        };
        pages
            .into_iter()
            .map(|page| {
                let bytes = kernel.memory.private_page_pin(owner, page).map(|pin| {
                    let mut bytes = vec![0; super::STABLE_PRIVATE_PAGE_SIZE];
                    pin.read_bytes(0, &mut bytes).expect("read canonical page");
                    bytes
                });
                (page, bytes)
            })
            .collect()
    }

    fn native_payload_msg_fault(
        uc: &mut Unicorn<'_, ()>,
        blobs: &mut Vec<super::MappedBlob>,
        fault: &str,
    ) -> u32 {
        if fault == "readonly_msg" {
            uc.mem_write(0x20000, &[0xa5; 28]).unwrap();
            uc.mem_protect(0x20000, 0x1000, Prot::READ).unwrap();
            0x20000
        } else if fault == "cross_readonly_msg" {
            uc.mem_map(0x21000, 0x1000, Prot::READ).unwrap();
            blobs.push(super::MappedBlob {
                name: "ram:msg-tail".to_owned(),
                base: 0x21000,
                bytes: vec![0; 0x1000].into(),
            });
            uc.mem_write(0x20ff0, &[0xa5; 28]).unwrap();
            0x20ff0
        } else {
            0x20000
        }
    }

    fn native_payload_clear_msg_fault(uc: &mut Unicorn<'_, ()>, fault: &str) {
        if fault == "readonly_msg" {
            uc.mem_protect(0x20000, 0x1000, Prot::ALL).unwrap();
        } else if fault == "cross_readonly_msg" {
            uc.mem_protect(0x21000, 0x1000, Prot::ALL).unwrap();
        }
    }

