    fn send_message_blocked_wait_resume_fixture(bound_directory: bool) {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let receiver_thread = 12;
        let result_ptr = 0x0001_0040;
        let return_pc = 0x0040_2200;
        uc.mem_map(
            u64::from(super::USER_KDATA_PAGE_BASE),
            u64::from(super::USER_KDATA_PAGE_SIZE),
            Prot::ALL,
        )
        .unwrap();
        uc.mem_map(0x0001_0000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0xaaaa_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_0002).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_1200).unwrap();

        let hwnd = kernel
            .gwe
            .create_window(receiver_thread, "SendResume", "send");
        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 212,
                0,
                0,
                Some(1000),
            )
            .expect("queued send");
        // An expired scheduler-only Send must not mask the exact native
        // sender, even though timeout is a second independent ready reason.
        let (orphan_handle, orphan_thread) = kernel.create_guest_thread(0x0040_3100, 0, false);
        let orphan_wait_id = kernel.register_blocked_waiter(
            orphan_thread,
            orphan_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::SendMessage { send_id: u64::MAX },
            kernel.timers.tick_count(),
            0,
        );
        let wait_started_ms = kernel.timers.tick_count();
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[16] = 0x7777_0011;
        let kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id: receiver_thread,
            result_ptr: Some(result_ptr),
            previous_running_thread: Some((sender_thread, sender_handle)),
        };
        let wait_id = kernel.register_blocked_waiter(
            sender_thread,
            sender_handle,
            Vec::new(),
            super::scheduler_blocked_wait_kind(kind),
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        assert_eq!(
            kernel
                .blocked_waiter(wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(sender_birth)
        );
        let blocked_waits = Rc::new(RefCell::new(vec![super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: sender_thread,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: sender_regs,
            return_pc,
        }]));
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, send_id)
        );
        assert_eq!(
            kernel.complete_active_sent_message(receiver_thread, 0x2468_ace0),
            Some(send_id)
        );

        let current_thread_id = Rc::new(super::NativeCurrentThread::new(receiver_thread, None));
        let suspended = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(None));
        let selected = std::cell::Cell::new(None);
        if bound_directory {
            let directory = super::CpuCustody::new().expect("machine directory");
            kernel
                .bind_cpu_machine_lineage(directory.machine_lineage())
                .expect("bind Kernel to directory");
            let send_before = kernel.gwe.sent_message(send_id).cloned();
            let wait_before = kernel.blocked_waiter(wait_id).cloned();
            let orphan_before = kernel.blocked_waiter(orphan_wait_id).cloned();
            let native_wait_before = blocked_waits.borrow().clone();
            let regs_before = (
                uc.reg_read(RegisterMIPS::S0).unwrap(),
                uc.reg_read(RegisterMIPS::V0).unwrap(),
                uc.reg_read(RegisterMIPS::RA).unwrap(),
                uc.reg_read(RegisterMIPS::PC).unwrap(),
            );
            assert!(super::try_resume_blocked_wait_with_active_pc_mode(
                &mut kernel,
                &mut uc,
                &super::SealedHostWriteGuard::default(),
                None,
                receiver_thread,
                &current_thread_id,
                &blocked_waits,
                &suspended,
                None,
                &running_thread,
                None,
                false,
                super::SendResumePhase::PreEntryProbe(&selected),
            ));
            assert!(matches!(
                current_thread_id.terminal_error.borrow().as_ref(),
                Some(Error::Backend(reason)) if reason.contains("CPU-directory Send handoff")
            ));
            assert_eq!(selected.get(), None);
            assert_eq!(kernel.gwe.sent_message(send_id), send_before.as_ref());
            assert_eq!(kernel.blocked_waiter(wait_id), wait_before.as_ref());
            assert_eq!(
                kernel.blocked_waiter(orphan_wait_id),
                orphan_before.as_ref()
            );
            assert_eq!(*blocked_waits.borrow(), native_wait_before);
            assert!(kernel.sent_message_result_ready(send_id));
            assert_eq!(*running_thread.borrow(), None);
            assert!(suspended.borrow().is_none());
            assert_eq!(
                (
                    uc.reg_read(RegisterMIPS::S0).unwrap(),
                    uc.reg_read(RegisterMIPS::V0).unwrap(),
                    uc.reg_read(RegisterMIPS::RA).unwrap(),
                    uc.reg_read(RegisterMIPS::PC).unwrap(),
                ),
                regs_before,
            );
            let mut result_bytes = [0; 4];
            uc.mem_read(u64::from(result_ptr), &mut result_bytes)
                .unwrap();
            assert_eq!(u32::from_le_bytes(result_bytes), 0);
            return;
        }
        assert!(!super::try_resume_blocked_wait_with_active_pc_mode(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            receiver_thread,
            &current_thread_id,
            &blocked_waits,
            &suspended,
            None,
            &running_thread,
            None,
            false,
            super::SendResumePhase::PreEntryProbe(&selected),
        ));
        assert_eq!(selected.get(), Some(wait_id));
        assert!(kernel.blocked_waiter(orphan_wait_id).is_some());
        assert!(kernel.sent_message_result_ready(send_id));
        assert!(super::try_resume_blocked_wait_with_active_pc_mode(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            receiver_thread,
            &current_thread_id,
            &blocked_waits,
            &suspended,
            None,
            &running_thread,
            None,
            false,
            super::SendResumePhase::Prepared(wait_id),
        ));

        assert_eq!(current_thread_id.get(), (sender_thread, Some(sender_birth)));
        assert_eq!(
            *running_thread.borrow(),
            Some((sender_thread, sender_handle))
        );
        assert!(blocked_waits.borrow().is_empty());
        assert!(kernel.blocked_waiter(wait_id).is_none());
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7777_0011);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0x2468_ace0);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, return_pc);
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0x2468_ace0);
        assert!(kernel.take_completed_send_message_result(send_id).is_none());
    }

    #[test]
    fn send_message_sender_restore_failure_does_not_consume_reply_or_resume_sender() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let sender_birth = kernel
            .live_thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let (_receiver_handle, receiver_thread) = kernel.create_guest_thread(0x0040_4000, 0, false);
        let receiver_birth = kernel
            .live_thread_birth_key_by_id(receiver_thread)
            .expect("receiver birth");
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "SendRestoreFault",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned receiver HWND");
        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 213,
                0,
                0,
                Some(1000),
            )
            .expect("queued send");
        let result_ptr = 0x0001_0040;
        let result_sentinel = 0xfeed_beefu32;
        let active_pc = 0x0040_1100u32;
        let sender_return_pc = 0x0040_2200u32;
        uc.mem_map(
            u64::from(super::USER_KDATA_PAGE_BASE),
            u64::from(super::USER_KDATA_PAGE_SIZE),
            Prot::ALL,
        )
        .unwrap();
        uc.mem_map(0x0001_0000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &result_sentinel.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::PC, u64::from(active_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::FCSR, 0).unwrap();

        // A pending FP cause with its enable set is a real Unicorn register
        // write failure (also covered by cpu_mips's checked-restore test).
        let unrestorable_fcsr = (1 << 12) | (1 << 7);
        assert!(
            uc.reg_write(RegisterMIPS::FCSR, u64::from(unrestorable_fcsr))
                .is_err()
        );
        uc.reg_write(RegisterMIPS::FCSR, 0).unwrap();
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[16] = 0x7777_0011;
        sender_regs.fcsr = unrestorable_fcsr;
        let wait_started_ms = kernel.timers.tick_count();
        let kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id: receiver_thread,
            result_ptr: Some(result_ptr),
            previous_running_thread: Some((sender_thread, sender_handle)),
        };
        let wait_id = kernel.register_blocked_waiter(
            sender_thread,
            sender_handle,
            Vec::new(),
            super::scheduler_blocked_wait_kind(kind),
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        assert_eq!(
            kernel.blocked_waiter(wait_id).unwrap().owner_birth,
            Some(sender_birth)
        );
        let blocked_waits = Rc::new(RefCell::new(vec![super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: sender_thread,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: sender_regs,
            return_pc: sender_return_pc,
        }]));
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver_birth(receiver_birth, send_id)
        );
        assert_eq!(
            kernel.complete_sent_message_for_birth(receiver_birth, send_id, 0x2468_ace0),
            Some(send_id)
        );
        assert!(kernel.sent_message_result_ready(send_id));

        let terminal_error = Rc::new(RefCell::new(None));
        let current_thread_id = Rc::new(super::NativeCurrentThread::with_terminal_error(
            receiver_thread,
            Some(receiver_birth),
            terminal_error.clone(),
        ));
        let suspended = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(None));
        let _ = super::try_resume_blocked_wait_with_active_pc_mode(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            receiver_thread,
            &current_thread_id,
            &blocked_waits,
            &suspended,
            None,
            &running_thread,
            None,
            false,
            super::SendResumePhase::Prepared(wait_id),
        );

        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        let result_after = u32::from_le_bytes(result_bytes);
        let current_after = current_thread_id.get();
        let running_after = *running_thread.borrow();
        let native_wait_preserved = blocked_waits
            .borrow()
            .iter()
            .any(|wait| wait.wait_id == wait_id);
        let scheduler_wait_preserved = kernel.blocked_waiter(wait_id).is_some();
        let reply_preserved = kernel.sent_message_result_ready(send_id);
        let pc_after = uc.reg_read(RegisterMIPS::PC).unwrap() as u32;
        let failed_closed = terminal_error.borrow().is_some()
            && current_after != (sender_thread, Some(sender_birth))
            && running_after != Some((sender_thread, sender_handle))
            && pc_after != sender_return_pc;
        assert!(
            failed_closed
                && native_wait_preserved
                && scheduler_wait_preserved
                && reply_preserved
                && result_after == result_sentinel,
            "faulted A restore: terminal_error={:?}, current={current_after:?}, running={running_after:?}, pc=0x{pc_after:08x}, native_wait={native_wait_preserved}, scheduler_wait={scheduler_wait_preserved}, reply_ready={reply_preserved}, result=0x{result_after:08x}",
            terminal_error.borrow().as_ref(),
        );
    }

    #[test]
    fn ready_send_message_hook_parks_receiver_without_consuming_sender_reply() {
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default().unwrap());
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let sender_birth = kernel
            .live_thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let (receiver_handle, receiver_thread) = kernel.create_guest_thread(0x0040_4000, 0, false);
        let receiver_birth = kernel.live_thread_birth_key_by_id(receiver_thread).unwrap();
        let hwnd = kernel
            .create_window_ex_w_with_parent_owner_and_rect_for_birth(
                receiver_birth,
                "SendHookPark",
                "",
                None,
                None,
                0,
                0,
                0,
                crate::ce::gwe::Rect::default(),
            )
            .expect("birth-owned receiver HWND");
        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 214,
                0,
                0,
                Some(1000),
            )
            .unwrap();
        let result_ptr = 0x0001_0040;
        let sentinel = 0xfeed_beefu32;
        uc.mem_map(0x0001_0000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &sentinel.to_le_bytes())
            .unwrap();
        let active_pc = 0x0040_4010;
        uc.reg_write(RegisterMIPS::PC, u64::from(active_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0xbbbb_0011).unwrap();
        uc.reg_write(RegisterMIPS::FCSR, 0).unwrap();
        let kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id: receiver_thread,
            result_ptr: Some(result_ptr),
            previous_running_thread: Some((sender_thread, sender_handle)),
        };
        let wait_started_ms = kernel.timers.tick_count();
        let wait_id = kernel.register_blocked_waiter(
            sender_thread,
            sender_handle,
            Vec::new(),
            super::scheduler_blocked_wait_kind(kind),
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        let blocked_waits = Rc::new(RefCell::new(vec![super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: sender_thread,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0x0040_2200,
        }]));
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver_birth(receiver_birth, send_id)
        );
        assert_eq!(
            kernel.complete_sent_message_for_birth(receiver_birth, send_id, 0x2468_ace0),
            Some(send_id)
        );
        let terminal_error = Rc::new(RefCell::new(None));
        let current_thread_id = Rc::new(super::NativeCurrentThread::with_terminal_error(
            receiver_thread,
            Some(receiver_birth),
            terminal_error.clone(),
        ));
        let suspended = Rc::new(RefCell::new(None));
        let suspended_queue = Rc::new(RefCell::new(std::collections::VecDeque::new()));
        let running_thread = Rc::new(RefCell::new(Some((receiver_thread, receiver_handle))));
        assert!(super::try_resume_blocked_wait_with_active_pc(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            receiver_thread,
            &current_thread_id,
            &blocked_waits,
            &suspended,
            Some(&suspended_queue),
            &running_thread,
            Some(active_pc),
            true,
        ));
        assert!(terminal_error.borrow().is_none());
        assert_eq!(
            current_thread_id.get(),
            (receiver_thread, Some(receiver_birth))
        );
        assert_eq!(*running_thread.borrow(), None);
        let parked = suspended.borrow();
        let parked = parked.as_ref().expect("receiver parked once");
        assert_eq!(parked.thread_id, receiver_thread);
        assert_eq!(parked.thread_birth, Some(receiver_birth));
        assert_eq!(parked.pc, active_pc);
        assert_eq!(parked.regs.regs[16], 0xbbbb_0011);
        assert!(suspended_queue.borrow().is_empty());
        assert_eq!(blocked_waits.borrow()[0].wait_id, wait_id);
        assert!(kernel.blocked_waiter(wait_id).is_some());
        assert!(kernel.sent_message_result_ready(send_id));
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), sentinel);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, active_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0xbbbb_0011);
        assert_eq!(uc.reg_read(RegisterMIPS::FCSR).unwrap() as u32, 0);
    }

    #[test]
    fn occupied_send_message_timeout_import_hook_reports_backend_error() -> crate::Result<()> {
        let mut kernel = CeKernel::boot(RuntimeConfig::load_default()?);
        let (a_handle, a_thread) = kernel.create_guest_thread(0x0040_a000, 0, false);
        let (b_handle, b_thread) = kernel.create_guest_thread(0x0040_a100, 0, false);
        let a_birth = kernel.handles.thread_birth_key_by_id(a_thread).unwrap();
        let hwnd = kernel
            .gwe
            .create_window(1, "SMT_NATIVE_OCCUPIED", "receiver");
        let blocked_smt = Rc::new(RefCell::new(None));
        let a_current = Rc::new(super::NativeCurrentThread::new(a_thread, Some(a_birth)));
        let a_running = Rc::new(RefCell::new(Some((a_thread, a_handle))));
        let mut a_uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        a_uc.reg_write(RegisterMIPS::PC, 0x7fff_a000).unwrap();
        a_uc.reg_write(RegisterMIPS::RA, 0x0040_a008).unwrap();
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut a_uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &[hwnd, crate::ce::gwe::WM_USER + 284, 0, 0, 0, 100, 0],
            a_thread,
            &a_current,
            &blocked_smt,
            &a_running,
        ));
        let a_blocked = blocked_smt.borrow().as_ref().expect("A blocked").clone();
        let a_sent = kernel
            .gwe
            .sent_message(a_blocked.block_state.send_id)
            .unwrap()
            .clone();

        let trap = super::IMPORT_TRAP_BASE + 0x400;
        let mut image_bytes = tiny_mips_spinner_pe();
        for (index, word) in [
            0x3c19_0000 | (trap >> 16),
            0x3739_0000 | (trap & 0xffff),
            0x0320_f809, // jalr t9: native SMT import hook
            0,
            0x1000_ffff, // bounded safety spinner if the hook falls through
            0,
        ]
        .into_iter()
        .enumerate()
        {
            write_vec_u32(&mut image_bytes, 0x200 + index * 4, word);
        }
        let image = crate::pe::PeImage::parse_bytes("smt-occupied-native.exe", &image_bytes)?;
        let mut cpu = super::UnicornMips::new()?;
        cpu.load_pe_image(&image)?;
        cpu.set_initial_thread_id(b_thread);
        cpu.import_traps
            .insert(crate::emulator::imports::ImportTrap {
                address: trap,
                module_kind: crate::emulator::imports::ImportModuleKind::Coredll,
                module_name: "COREDLL.dll".to_owned(),
                ordinal: Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                name: Some("SendMessageTimeout".to_owned()),
                iat_va: 0,
            });
        super::refresh_import_trap_page_blob(&mut cpu.mapped_blobs, &cpu.import_traps);
        cpu.blocked_send_message_timeout = blocked_smt.borrow_mut().take();
        let stack_pointer = cpu.stack_top.expect("fixture stack") - 0x100;
        let mut stack_args = [0u8; 12];
        stack_args[4..8].copy_from_slice(&100u32.to_le_bytes()); // dwTimeout
        write_guest_fixture_stack_bytes(&cpu, &mut kernel, stack_pointer + 16, &stack_args);
        let mut regs = super::MipsGuestContext::zero();
        regs.regs[4] = hwnd;
        regs.regs[5] = crate::ce::gwe::WM_USER + 285;
        regs.regs[29] = stack_pointer;
        cpu.saved_context = Some(super::SavedCpuContext {
            pc: cpu.entry.expect("fixture entry"),
            regs,
        });
        stamp_synthetic_saved_context(&mut cpu, &kernel);
        cpu.running_guest_thread = Some((b_thread, b_handle));
        kernel.threads.set_last_error(b_thread, 0xa100_1234);

        let mut framebuffer = VirtualFramebuffer::default_primary()?;
        let attempt = cpu.run_until_import_trap_with_framebuffer_limits_report(
            &mut kernel,
            &mut framebuffer,
            super::UnicornRunLimits {
                instruction_limit: 32,
                wall_clock_limit_ms: 500,
                stop_pc: None,
                live_pump: false,
            },
        );
        match attempt.result {
            Err(Error::Backend(message)) => assert!(message.contains("slot occupied"), "{message}"),
            other => panic!("occupied native import did not report Backend: {other:?}"),
        }
        assert_eq!(
            attempt.report.final_outcome(),
            super::NativeSliceOutcome::BackendError
        );
        assert_eq!(kernel.threads.get_last_error(b_thread), 0xa100_1234);
        assert_eq!(kernel.blocked_waiters().count(), 1);
        assert_eq!(
            kernel.gwe.sent_message(a_blocked.block_state.send_id),
            Some(&a_sent)
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![a_blocked.block_state.send_id]
        );
        Ok(())
    }

    #[test]
    fn occupied_send_message_timeout_slot_fails_closed_for_second_sender() -> crate::Result<()> {
        let config = RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let (a_handle, a_thread) = kernel.create_guest_thread(0x0040_9000, 0, false);
        let (b_handle, b_thread) = kernel.create_guest_thread(0x0040_9100, 0, false);
        let a_birth = kernel
            .handles
            .thread_birth_key_by_id(a_thread)
            .expect("live sender A");
        let b_birth = kernel
            .handles
            .thread_birth_key_by_id(b_thread)
            .expect("live sender B");
        assert_ne!(a_birth, b_birth);
        let hwnd = kernel.gwe.create_window(1, "SMT_OCCUPIED", "receiver");
        let a_result_ptr = 0x0001_a040;
        let b_result_ptr = 0x0001_a044;
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.mem_map(0x0001_a000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(a_result_ptr), &0xface_aaaa_u32.to_le_bytes())
            .unwrap();
        uc.mem_write(u64::from(b_result_ptr), &0xface_9090_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_9000).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_9008).unwrap();
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(a_thread, Some(a_birth)));
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((a_thread, a_handle))));
        let a_args = [
            hwnd,
            crate::ce::gwe::WM_USER + 280,
            0,
            0,
            0,
            100,
            a_result_ptr,
        ];
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &a_args,
            a_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let a_blocked = blocked_smt.borrow().as_ref().expect("A owns slot").clone();
        let a_send_id = a_blocked.block_state.send_id;
        let a_sent = kernel
            .gwe
            .sent_message(a_send_id)
            .expect("A queued send")
            .clone();
        assert_eq!(a_sent.result_ptr, Some(a_result_ptr));
        assert_eq!(a_sent.timeout_ms, Some(100));
        assert!(kernel.blocked_waiter(a_blocked.wait_id).is_some());

        current_thread_id.set_verified(b_birth);
        *running_thread.borrow_mut() = Some((b_thread, b_handle));
        kernel.threads.set_last_error(b_thread, 0x9090_1234);
        uc.reg_write(RegisterMIPS::PC, 0x7fff_9100).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_9108).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0x9090_5678).unwrap();
        let b_args = [
            hwnd,
            crate::ce::gwe::WM_USER + 281,
            0,
            0,
            0,
            100,
            b_result_ptr,
        ];
        let terminal_error = RefCell::new(None);
        assert!(super::try_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &b_args,
            b_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
            &terminal_error,
        ));
        assert!(
            terminal_error
                .borrow()
                .as_ref()
                .is_some_and(|error| { error.to_string().contains("slot occupied") })
        );
        assert_eq!(
            blocked_smt.borrow().as_ref().unwrap().wait_id,
            a_blocked.wait_id
        );
        assert_eq!(kernel.blocked_waiters().count(), 1);
        assert!(kernel.blocked_waiter(a_blocked.wait_id).is_some());
        assert_eq!(kernel.gwe.sent_message(a_send_id), Some(&a_sent));
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![a_send_id]
        );
        assert_eq!(kernel.threads.get_last_error(b_thread), 0x9090_1234);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x7fff_9100);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, 0x0040_9108);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0x9090_5678);
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(a_result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0xface_aaaa);
        uc.mem_read(u64::from(b_result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0xface_9090);

        *terminal_error.borrow_mut() = Some(Error::Backend("prior terminal error".to_owned()));
        assert!(super::try_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &b_args,
            b_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
            &terminal_error,
        ));
        assert!(
            terminal_error
                .borrow()
                .as_ref()
                .is_some_and(|error| { error.to_string().contains("prior terminal error") })
        );
        assert_eq!(kernel.gwe.sent_message(a_send_id), Some(&a_sent));
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![a_send_id]
        );
        uc.mem_read(u64::from(a_result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0xface_aaaa);
        Ok(())
    }

    #[test]
    fn occupied_send_message_timeout_slot_preserves_raw_compatibility() -> crate::Result<()> {
        let config = RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let (a_handle, a_thread) = kernel.create_guest_thread(0x0040_9200, 0, false);
        let (b_handle, b_thread) = kernel.create_guest_thread(0x0040_9300, 0, false);
        let a_birth = kernel.handles.thread_birth_key_by_id(a_thread).unwrap();
        let b_birth = kernel.handles.thread_birth_key_by_id(b_thread).unwrap();
        let hwnd = kernel.gwe.create_window(1, "SMT_OCCUPIED_RAW", "receiver");
        let self_hwnd = kernel.gwe.create_window(b_thread, "SMT_SELF_RAW", "sender");
        let destroyed_hwnd = kernel.gwe.create_window(1, "SMT_DESTROYED_RAW", "gone");
        assert!(kernel.gwe.destroy_window(destroyed_hwnd, 0));
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_9200).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_9208).unwrap();
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(a_thread, Some(a_birth)));
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((a_thread, a_handle))));
        let a_args = [hwnd, crate::ce::gwe::WM_USER + 282, 0, 0, 0, 100, 0];
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &a_args,
            a_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let a_blocked = blocked_smt.borrow().as_ref().unwrap().clone();
        let a_send_id = a_blocked.block_state.send_id;
        current_thread_id.set_verified(b_birth);
        *running_thread.borrow_mut() = Some((b_thread, b_handle));
        kernel.threads.set_last_error(b_thread, 0x9292_1234);
        uc.reg_write(RegisterMIPS::PC, 0x7fff_9300).unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_9308).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0x9292_5678).unwrap();
        let b_args = [hwnd, crate::ce::gwe::WM_USER + 283, 0, 0, 0, 100, 0];
        assert_eq!(
            crate::ce::coredll::send_message_timeout_parkable_target_thread(
                &kernel, b_thread, &b_args,
            ),
            Some(1)
        );
        let mut cases = Vec::new();
        let mut zero = b_args;
        zero[5] = 0;
        cases.push(("zero timeout", zero));
        let mut same_thread = b_args;
        same_thread[0] = self_hwnd;
        cases.push(("same thread", same_thread));
        let mut unsupported = b_args;
        unsupported[4] = 0x8000_0000;
        cases.push(("unsupported flags", unsupported));
        let mut invalid = b_args;
        invalid[0] = 0xdead_cafe;
        cases.push(("invalid window", invalid));
        let mut destroyed = b_args;
        destroyed[0] = destroyed_hwnd;
        cases.push(("destroyed window", destroyed));
        let mut broadcast = b_args;
        broadcast[0] = crate::ce::gwe::HWND_BROADCAST;
        cases.push(("broadcast", broadcast));
        for (case, args) in cases {
            assert_eq!(
                crate::ce::coredll::send_message_timeout_parkable_target_thread(
                    &kernel, b_thread, &args,
                ),
                None,
                "{case}"
            );
            let terminal_error = RefCell::new(None);
            assert!(
                !super::try_block_for_send_message_timeout_wait(
                    &mut kernel,
                    &mut uc,
                    &super::SealedHostWriteGuard::default(),
                    crate::emulator::imports::ImportModuleKind::Coredll,
                    Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                    &args,
                    b_thread,
                    &current_thread_id,
                    &blocked_smt,
                    &running_thread,
                    &terminal_error,
                ),
                "{case}"
            );
            assert!(terminal_error.borrow().is_none(), "{case}");
            assert_eq!(
                blocked_smt.borrow().as_ref().unwrap().wait_id,
                a_blocked.wait_id,
                "{case}"
            );
            assert_eq!(
                kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
                vec![a_send_id],
                "{case}"
            );
            assert_eq!(
                kernel.threads.get_last_error(b_thread),
                0x9292_1234,
                "{case}"
            );
        }

        let hung_threshold = crate::ce::coredll::CE_HUNG_THRESHOLD_MS;
        kernel.timers.sleep_ms(hung_threshold + 1);
        kernel
            .gwe
            .record_thread_dispatched(1, kernel.timers.tick_count() - (hung_threshold + 1));
        assert!(
            kernel
                .gwe
                .is_thread_hung(1, kernel.timers.tick_count(), hung_threshold)
        );
        let mut hung_abort = b_args;
        hung_abort[4] = 0x0000_0002;
        assert_eq!(
            crate::ce::coredll::send_message_timeout_parkable_target_thread(
                &kernel,
                b_thread,
                &hung_abort,
            ),
            None
        );
        let terminal_error = RefCell::new(None);
        assert!(!super::try_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &hung_abort,
            b_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
            &terminal_error,
        ));
        assert!(terminal_error.borrow().is_none());
        assert_eq!(
            blocked_smt.borrow().as_ref().unwrap().wait_id,
            a_blocked.wait_id
        );
        assert_eq!(
            kernel.gwe.sent_message_ids_for_windows(&[hwnd]),
            vec![a_send_id]
        );
        assert_eq!(kernel.threads.get_last_error(b_thread), 0x9292_1234);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x7fff_9300);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0x9292_5678);
        Ok(())
    }

    #[test]
    fn send_message_timeout_block_reentry_expires_without_receiver_delivery() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_6100, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let receiver_thread = 62;
        let result_ptr = 0x0001_0040;
        let return_pc = 0x0040_6100;
        uc.mem_map(0x0001_0000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0xfeed_cafe_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x6161_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6100).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6100).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();

        let hwnd = kernel
            .gwe
            .create_window(receiver_thread, "SendTimeoutBlock", "timeout");
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
        let args = [
            hwnd,
            crate::ce::gwe::WM_USER + 214,
            0x61,
            0x62,
            0,
            25,
            result_ptr,
        ];

        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let blocked = blocked_smt
            .borrow()
            .as_ref()
            .expect("blocked send timeout")
            .clone();
        assert_eq!(blocked.thread_id, sender_thread);
        assert_eq!(blocked.thread_handle, sender_handle);
        assert!(kernel.blocked_waiter(blocked.wait_id).is_some());
        assert!(
            kernel
                .gwe
                .sent_message(blocked.block_state.send_id)
                .is_some()
        );
        assert!(kernel.thread_has_pending_sent_message(receiver_thread));

        kernel.timers.sleep_ms(25);
        uc.reg_write(RegisterMIPS::S0, 0x9999_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6101).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6104).unwrap();
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));

        assert!(blocked_smt.borrow().is_none());
        assert!(kernel.blocked_waiter(blocked.wait_id).is_none());
        assert_eq!(
            kernel.take_completed_send_message_result(blocked.block_state.send_id),
            None
        );
        assert_eq!(kernel.gwe.stats().send_transaction_timeout_count, 1);
        assert_eq!(kernel.gwe.get_message(receiver_thread), None);
        assert_eq!(
            kernel.threads.get_last_error(sender_thread),
            crate::ce::coredll::ERROR_TIMEOUT_LOCAL
        );
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x6161_0001);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, return_pc);
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0xfeed_cafe);
    }

    #[test]
    fn send_message_timeout_block_reentry_writes_ready_result_without_timeout() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_6900, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let receiver_thread = 70;
        let result_ptr = 0x0001_3040;
        let return_pc = 0x0040_6900;
        uc.mem_map(0x0001_3000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0xfeed_babe_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x6969_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6900).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6900).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(return_pc))
            .unwrap();

        let hwnd = kernel
            .gwe
            .create_window(receiver_thread, "SendTimeoutBlockReady", "ready");
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
        let args = [
            hwnd,
            crate::ce::gwe::WM_USER + 217,
            0x69,
            0x70,
            0,
            1000,
            result_ptr,
        ];

        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let blocked = blocked_smt
            .borrow()
            .as_ref()
            .expect("blocked send timeout")
            .clone();
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, blocked.block_state.send_id)
        );
        assert_eq!(
            kernel.complete_active_sent_message(receiver_thread, 0x1122_3344),
            Some(blocked.block_state.send_id)
        );
        assert!(kernel.sent_message_result_ready(blocked.block_state.send_id));

        uc.reg_write(RegisterMIPS::S0, 0x9999_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6901).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6904).unwrap();
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));

        assert!(blocked_smt.borrow().is_none());
        assert!(kernel.blocked_waiter(blocked.wait_id).is_none());
        assert_eq!(
            kernel.take_completed_send_message_result(blocked.block_state.send_id),
            None
        );
        assert_eq!(kernel.gwe.stats().send_transaction_timeout_count, 0);
        assert_eq!(kernel.gwe.get_message(receiver_thread), None);
        assert_eq!(kernel.threads.get_last_error(sender_thread), 0);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x6969_0001);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 1);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        assert_eq!(uc.reg_read(RegisterMIPS::RA).unwrap() as u32, return_pc);
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0x1122_3344);
    }

    #[test]
    fn send_message_timeout_scheduler_resume_expires_and_suspends_active_thread() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_6300, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let receiver_thread = 64;
        let (active_handle, active_thread) = kernel.create_guest_thread(0x0040_6500, 0, false);
        let active_birth = kernel
            .handles
            .thread_birth_key_by_id(active_thread)
            .expect("active birth");
        let result_ptr = 0x0001_1040;
        let sender_return_pc = 0x0040_6300;
        let active_pc = 0x0040_6500;
        uc.mem_map(0x0000_5000, 0x1000, Prot::ALL).unwrap();
        uc.mem_map(0x0001_1000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0xabcd_ef01_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x6363_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6300).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6300).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(sender_return_pc))
            .unwrap();

        let hwnd =
            kernel
                .gwe
                .create_window(receiver_thread, "SendTimeoutSchedulerBlock", "timeout");
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
        let args = [
            hwnd,
            crate::ce::gwe::WM_USER + 215,
            0x63,
            0x64,
            0,
            30,
            result_ptr,
        ];

        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let blocked = blocked_smt
            .borrow()
            .as_ref()
            .expect("blocked send timeout")
            .clone();
        kernel.timers.sleep_ms(30);
        *running_thread.borrow_mut() = Some((active_thread, active_handle));
        uc.reg_write(RegisterMIPS::S0, 0x6565_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6500).unwrap();
        uc.reg_write(RegisterMIPS::PC, u64::from(active_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_6510).unwrap();

        current_thread_id.set_verified(active_birth);
        let suspended_thread = Rc::new(RefCell::new(None));
        assert!(super::try_resume_blocked_send_message_timeout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            active_thread,
            &current_thread_id,
            &blocked_smt,
            &suspended_thread,
            None,
            &running_thread,
            Some(active_pc),
            true,
        ));

        assert!(blocked_smt.borrow().is_none());
        assert!(kernel.blocked_waiter(blocked.wait_id).is_none());
        assert_eq!(current_thread_id.get().0, sender_thread);
        assert_eq!(current_thread_id.get().1, Some(sender_birth));
        assert_eq!(
            *running_thread.borrow(),
            Some((sender_thread, sender_handle))
        );
        let suspended = suspended_thread
            .borrow()
            .as_ref()
            .expect("active thread suspended")
            .clone();
        assert_eq!(suspended.thread_id, active_thread);
        assert_eq!(suspended.thread_handle, Some(active_handle));
        assert_eq!(suspended.pc, active_pc);
        assert_eq!(suspended.regs.regs[16], 0x6565_0001);
        assert_eq!(
            kernel.take_completed_send_message_result(blocked.block_state.send_id),
            None
        );
        assert_eq!(kernel.gwe.get_message(receiver_thread), None);
        assert_eq!(
            kernel.threads.get_last_error(sender_thread),
            crate::ce::coredll::ERROR_TIMEOUT_LOCAL
        );
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x6363_0001);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0);
        assert_eq!(
            uc.reg_read(RegisterMIPS::PC).unwrap() as u32,
            sender_return_pc
        );
        assert_eq!(
            uc.reg_read(RegisterMIPS::RA).unwrap() as u32,
            sender_return_pc
        );
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0xabcd_ef01);
    }

    #[test]
    fn send_message_timeout_scheduler_resume_writes_ready_result_and_suspends_active_thread() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_6600, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            sender_thread,
            Some(sender_birth),
        ));
        let receiver_thread = 67;
        let (active_handle, active_thread) = kernel.create_guest_thread(0x0040_6800, 0, false);
        let active_birth = kernel
            .handles
            .thread_birth_key_by_id(active_thread)
            .expect("active birth");
        let result_ptr = 0x0001_2040;
        let sender_return_pc = 0x0040_6600;
        let active_pc = 0x0040_6800;
        uc.mem_map(0x0000_5000, 0x1000, Prot::ALL).unwrap();
        uc.mem_map(0x0001_2000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0xface_b00c_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::S0, 0x6666_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6600).unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x7fff_6600).unwrap();
        uc.reg_write(RegisterMIPS::RA, u64::from(sender_return_pc))
            .unwrap();

        let hwnd = kernel
            .gwe
            .create_window(receiver_thread, "SendTimeoutSchedulerReady", "ready");
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
        let args = [
            hwnd,
            crate::ce::gwe::WM_USER + 216,
            0x66,
            0x67,
            0,
            1000,
            result_ptr,
        ];

        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            sender_thread,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let blocked = blocked_smt
            .borrow()
            .as_ref()
            .expect("blocked send timeout")
            .clone();
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, blocked.block_state.send_id)
        );
        assert_eq!(
            kernel.complete_active_sent_message(receiver_thread, 0x2468_ace0),
            Some(blocked.block_state.send_id)
        );
        assert!(kernel.sent_message_result_ready(blocked.block_state.send_id));

        *running_thread.borrow_mut() = Some((active_thread, active_handle));
        uc.reg_write(RegisterMIPS::S0, 0x6868_0001).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xeeee_6800).unwrap();
        uc.reg_write(RegisterMIPS::PC, u64::from(active_pc))
            .unwrap();
        uc.reg_write(RegisterMIPS::RA, 0x0040_6810).unwrap();

        current_thread_id.set_verified(active_birth);
        let suspended_thread = Rc::new(RefCell::new(None));
        assert!(super::try_resume_blocked_send_message_timeout(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            active_thread,
            &current_thread_id,
            &blocked_smt,
            &suspended_thread,
            None,
            &running_thread,
            Some(active_pc),
            true,
        ));

        assert!(blocked_smt.borrow().is_none());
        assert!(kernel.blocked_waiter(blocked.wait_id).is_none());
        assert_eq!(current_thread_id.get().0, sender_thread);
        assert_eq!(current_thread_id.get().1, Some(sender_birth));
        assert_eq!(
            *running_thread.borrow(),
            Some((sender_thread, sender_handle))
        );
        let suspended = suspended_thread
            .borrow()
            .as_ref()
            .expect("active thread suspended")
            .clone();
        assert_eq!(suspended.thread_id, active_thread);
        assert_eq!(suspended.thread_handle, Some(active_handle));
        assert_eq!(suspended.pc, active_pc);
        assert_eq!(suspended.regs.regs[16], 0x6868_0001);
        assert_eq!(
            kernel.take_completed_send_message_result(blocked.block_state.send_id),
            None
        );
        assert_eq!(kernel.gwe.stats().send_transaction_timeout_count, 0);
        assert_eq!(kernel.gwe.get_message(receiver_thread), None);
        assert_eq!(kernel.threads.get_last_error(sender_thread), 0);
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x6666_0001);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 1);
        assert_eq!(
            uc.reg_read(RegisterMIPS::PC).unwrap() as u32,
            sender_return_pc
        );
        assert_eq!(
            uc.reg_read(RegisterMIPS::RA).unwrap() as u32,
            sender_return_pc
        );
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0x2468_ace0);
    }

    #[test]
    fn send_message_timeout_rejects_stale_or_contradictory_producer_before_queue()
    -> crate::Result<()> {
        let config = RuntimeConfig::load_default()?;
        let mut kernel = CeKernel::boot(config);
        let owner = kernel
            .current_process_birth_key()
            .expect("boot process birth");
        let (old_handle, thread_id) = kernel.create_guest_thread(0x0040_7000, 0, false);
        let old_birth = kernel
            .handles
            .thread_birth_key_by_id(thread_id)
            .expect("sender A birth");
        assert!(kernel.mark_guest_thread_exited_by_id(thread_id, 0x11));
        assert!(kernel.close_handle(old_handle)?);
        let new_handle =
            kernel
                .handles
                .try_create_thread_in_birth(owner, thread_id, 0x0040_7100, 0, false)?;
        let new_birth = kernel
            .handles
            .thread_birth_key_by_id(thread_id)
            .expect("sender B birth");
        assert_ne!(old_birth, new_birth);

        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let result_ptr = 0x0001_7040;
        uc.mem_map(0x0001_7000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0xfeed_7070_u32.to_le_bytes())
            .unwrap();
        uc.reg_write(RegisterMIPS::PC, 0x0040_7100).unwrap();
        uc.reg_write(RegisterMIPS::V0, 0xbbee_7070).unwrap();
        let hwnd = kernel.gwe.create_window(1, "SMT_STALE_PRODUCER", "stale");
        let args = [
            hwnd,
            crate::ce::gwe::WM_USER + 270,
            0,
            0,
            0,
            100,
            result_ptr,
        ];
        let blocked_smt = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((thread_id, new_handle))));
        let current_thread_id =
            Rc::new(super::NativeCurrentThread::new(thread_id, Some(old_birth)));
        kernel.threads.set_last_error(thread_id, 0x1234_5678);

        let stale_terminal = RefCell::new(None);
        assert!(super::try_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
            &stale_terminal,
        ));
        assert!(matches!(
            stale_terminal.borrow().as_ref(),
            Some(Error::Backend(_))
        ));
        assert_eq!(current_thread_id.get(), (thread_id, None));
        assert!(blocked_smt.borrow().is_none());
        assert_eq!(kernel.blocked_waiters().count(), 0);
        assert!(kernel.gwe.sent_message(1).is_none());
        assert_eq!(kernel.threads.get_last_error(thread_id), 0x1234_5678);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_7100);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0xbbee_7070);
        let mut bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut bytes).unwrap();
        assert_eq!(u32::from_le_bytes(bytes), 0xfeed_7070);

        // Eligibility remains read-only: zero timeout belongs to the raw API.
        let mut zero_args = args;
        zero_args[5] = 0;
        assert!(!super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &zero_args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        assert!(kernel.gwe.sent_message(1).is_none());

        let mut same_thread_args = args;
        same_thread_args[0] = kernel.gwe.create_window(thread_id, "SMT_SELF", "self");
        assert!(!super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &same_thread_args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let mut unsupported_args = args;
        unsupported_args[4] = 0x8000_0000;
        assert!(!super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &unsupported_args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        assert!(kernel.gwe.sent_message(1).is_none());

        current_thread_id.set_verified(new_birth);
        *running_thread.borrow_mut() = Some((thread_id + 100, new_handle));
        let mismatch_terminal = RefCell::new(None);
        assert!(super::try_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
            &mismatch_terminal,
        ));
        assert!(matches!(
            mismatch_terminal.borrow().as_ref(),
            Some(Error::Backend(_))
        ));
        assert_eq!(current_thread_id.get(), (thread_id, None));
        assert!(blocked_smt.borrow().is_none());
        assert!(kernel.gwe.sent_message(1).is_none());

        // A terminal native attempt cannot be reused. This next fixture is a
        // separately staged B attempt after the rejected running metadata.
        current_thread_id.set_verified(new_birth);
        assert!(kernel.close_handle(new_handle)?);
        assert!(kernel.handles.thread_execution_live_by_id(thread_id));
        *running_thread.borrow_mut() = Some((thread_id, new_handle));
        assert!(super::test_block_for_send_message_timeout_wait(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
            &args,
            thread_id,
            &current_thread_id,
            &blocked_smt,
            &running_thread,
        ));
        let blocked = blocked_smt.borrow();
        let blocked = blocked.as_ref().expect("closed-alias sender still blocks");
        assert_eq!(
            blocked.thread_handle,
            crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE
        );
        assert_eq!(blocked.owner_birth, new_birth);
        assert_eq!(
            kernel
                .blocked_waiter(blocked.wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(new_birth)
        );
        Ok(())
    }

    #[test]
    fn send_message_timeout_live_birth_rejects_false_wait_or_transaction_pair() {
        for scenario in ["missing_wait", "wrong_result_ptr"] {
            let config = RuntimeConfig::load_default().unwrap();
            let mut kernel = CeKernel::boot(config);
            let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_8400, 0, false);
            let sender_birth = kernel
                .handles
                .thread_birth_key_by_id(sender_thread)
                .expect("live sender birth");
            let current_thread_id = Rc::new(super::NativeCurrentThread::new(
                sender_thread,
                Some(sender_birth),
            ));
            let running_thread = Rc::new(RefCell::new(Some((sender_thread, sender_handle))));
            let blocked_smt = Rc::new(RefCell::new(None));
            let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
            let result_ptr = 0x0001_9040;
            uc.mem_map(0x0001_9000, 0x1000, Prot::ALL).unwrap();
            uc.mem_write(u64::from(result_ptr), &0xcafe_8484_u32.to_le_bytes())
                .unwrap();
            uc.reg_write(RegisterMIPS::RA, 0x0040_8408).unwrap();
            let hwnd = kernel.gwe.create_window(1, "SMT_FALSE_PAIR", "pair");
            let args = [
                hwnd,
                crate::ce::gwe::WM_USER + 272,
                0,
                0,
                0,
                100,
                result_ptr,
            ];
            assert!(super::test_block_for_send_message_timeout_wait(
                &mut kernel,
                &mut uc,
                &super::SealedHostWriteGuard::default(),
                crate::emulator::imports::ImportModuleKind::Coredll,
                Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                &args,
                sender_thread,
                &current_thread_id,
                &blocked_smt,
                &running_thread,
            ));
            let blocked = blocked_smt.borrow().as_ref().expect("blocked send").clone();
            let send_id = blocked.block_state.send_id;
            if scenario == "missing_wait" {
                assert!(kernel.remove_blocked_waiter(blocked.wait_id).is_some());
            } else {
                assert!(
                    kernel
                        .gwe
                        .set_sent_message_result_ptr(send_id, result_ptr + 4)
                );
            }
            assert!(kernel.gwe.activate_sent_message_for_receiver(1, send_id));
            assert_eq!(
                kernel.complete_active_sent_message(1, 0x1122_3344),
                Some(send_id)
            );
            kernel.threads.set_last_error(sender_thread, 0x8888_9999);
            uc.reg_write(RegisterMIPS::PC, 0x0040_8440).unwrap();
            uc.reg_write(RegisterMIPS::V0, 0x1234_8484).unwrap();

            assert!(
                super::test_block_for_send_message_timeout_wait(
                    &mut kernel,
                    &mut uc,
                    &super::SealedHostWriteGuard::default(),
                    crate::emulator::imports::ImportModuleKind::Coredll,
                    Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                    &args,
                    sender_thread,
                    &current_thread_id,
                    &blocked_smt,
                    &running_thread,
                ),
                "{scenario}"
            );
            assert!(blocked_smt.borrow().is_none(), "{scenario}");
            assert!(
                kernel.blocked_waiter(blocked.wait_id).is_none(),
                "{scenario}"
            );
            assert_eq!(
                kernel.gwe.sent_message(send_id).is_some(),
                scenario == "wrong_result_ptr"
            );
            assert_eq!(kernel.threads.get_last_error(sender_thread), 0x8888_9999);
            assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, 0x0040_8440);
            assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0x1234_8484);
            let mut bytes = [0; 4];
            uc.mem_read(u64::from(result_ptr), &mut bytes).unwrap();
            assert_eq!(u32::from_le_bytes(bytes), 0xcafe_8484);
            assert_eq!(current_thread_id.get(), (sender_thread, Some(sender_birth)));
        }
    }

    #[test]
    fn stale_send_message_timeout_slot_never_consumes_reply_or_deadline_for_reused_tid()
    -> crate::Result<()> {
        for scenario in [
            "reentry_ready",
            "reentry_deadline",
            "resume_ready",
            "resume_deadline",
            "resume_same_tid",
        ] {
            let config = RuntimeConfig::load_default()?;
            let mut kernel = CeKernel::boot(config);
            let owner = kernel
                .current_process_birth_key()
                .expect("boot process birth");
            let (old_handle, thread_id) = kernel.create_guest_thread(0x0040_8100, 0, false);
            let old_birth = kernel
                .handles
                .thread_birth_key_by_id(thread_id)
                .expect("sender A birth");
            let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
            let result_ptr = 0x0001_8040;
            uc.mem_map(0x0001_8000, 0x1000, Prot::ALL).unwrap();
            uc.mem_write(u64::from(result_ptr), &0xface_8080_u32.to_le_bytes())
                .unwrap();
            uc.reg_write(RegisterMIPS::PC, 0x7fff_8100).unwrap();
            uc.reg_write(RegisterMIPS::RA, 0x0040_8108).unwrap();
            let hwnd = kernel.gwe.create_window(1, "SMT_STALE_RESUME", "stale");
            let args = [hwnd, crate::ce::gwe::WM_USER + 271, 0, 0, 0, 25, result_ptr];
            let current_thread_id =
                Rc::new(super::NativeCurrentThread::new(thread_id, Some(old_birth)));
            let running_thread = Rc::new(RefCell::new(Some((thread_id, old_handle))));
            let blocked_smt = Rc::new(RefCell::new(None));
            assert!(super::test_block_for_send_message_timeout_wait(
                &mut kernel,
                &mut uc,
                &super::SealedHostWriteGuard::default(),
                crate::emulator::imports::ImportModuleKind::Coredll,
                Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                &args,
                thread_id,
                &current_thread_id,
                &blocked_smt,
                &running_thread,
            ));
            let blocked = blocked_smt
                .borrow()
                .as_ref()
                .expect("A blocked send")
                .clone();
            let send_id = blocked.block_state.send_id;
            assert_eq!(
                kernel
                    .blocked_waiter(blocked.wait_id)
                    .and_then(|wait| wait.owner_birth),
                Some(old_birth)
            );

            if matches!(
                scenario,
                "reentry_ready" | "resume_ready" | "resume_same_tid"
            ) {
                assert!(kernel.gwe.activate_sent_message_for_receiver(1, send_id));
                assert_eq!(
                    kernel.complete_active_sent_message(1, 0x1122_3344),
                    Some(send_id)
                );
                assert!(kernel.sent_message_result_ready(send_id));
            }

            // Deliberately emulate a torn old native frame: the ordinary Kernel
            // exit path would already remove this exact wait and queued send.
            assert!(kernel.handles.mark_thread_exited_by_birth(old_birth, 0x11));
            assert!(kernel.close_handle(old_handle)?);
            let new_handle = kernel.handles.try_create_thread_in_birth(
                owner,
                thread_id,
                0x0040_8200,
                0,
                false,
            )?;
            let new_birth = kernel
                .handles
                .thread_birth_key_by_id(thread_id)
                .expect("sender B birth");
            assert_ne!(new_birth, old_birth);
            if matches!(scenario, "reentry_deadline" | "resume_deadline") {
                kernel.timers.sleep_ms(25);
            }
            let (active_handle, active_thread_id, active_birth) =
                if matches!(scenario, "resume_ready" | "resume_deadline") {
                    let (handle, id) = kernel.create_guest_thread(0x0040_8300, 0, false);
                    let birth = kernel
                        .handles
                        .thread_birth_key_by_id(id)
                        .expect("active birth");
                    (handle, id, birth)
                } else {
                    (new_handle, thread_id, new_birth)
                };
            current_thread_id.set_verified(active_birth);
            *running_thread.borrow_mut() = Some((active_thread_id, active_handle));
            kernel.threads.set_last_error(thread_id, 0x7777_8888);
            uc.reg_write(RegisterMIPS::PC, 0x0040_8220).unwrap();
            uc.reg_write(RegisterMIPS::RA, 0x0040_8228).unwrap();
            uc.reg_write(RegisterMIPS::V0, 0x1234_5678).unwrap();
            uc.reg_write(RegisterMIPS::S0, 0xabcd_8080).unwrap();
            let timeout_count_before = kernel.gwe.stats().send_transaction_timeout_count;

            if scenario.starts_with("reentry") {
                assert!(
                    super::test_block_for_send_message_timeout_wait(
                        &mut kernel,
                        &mut uc,
                        &super::SealedHostWriteGuard::default(),
                        crate::emulator::imports::ImportModuleKind::Coredll,
                        Some(crate::ce::coredll_ordinals::ORD_SEND_MESSAGE_TIMEOUT),
                        &args,
                        thread_id,
                        &current_thread_id,
                        &blocked_smt,
                        &running_thread,
                    ),
                    "{scenario}"
                );
            } else {
                let suspended_thread = Rc::new(RefCell::new(None));
                assert!(
                    super::try_resume_blocked_send_message_timeout(
                        &mut kernel,
                        &mut uc,
                        &super::SealedHostWriteGuard::default(),
                        active_thread_id,
                        &current_thread_id,
                        &blocked_smt,
                        &suspended_thread,
                        None,
                        &running_thread,
                        Some(0x0040_8220),
                        true,
                    ),
                    "{scenario}"
                );
                assert!(suspended_thread.borrow().is_none(), "{scenario}");
            }

            assert!(blocked_smt.borrow().is_none(), "{scenario}");
            assert!(
                kernel.blocked_waiter(blocked.wait_id).is_none(),
                "{scenario}"
            );
            assert!(kernel.gwe.sent_message(send_id).is_none(), "{scenario}");
            assert_eq!(
                kernel.gwe.stats().send_transaction_timeout_count,
                timeout_count_before,
                "{scenario}"
            );
            assert_eq!(
                kernel.threads.get_last_error(thread_id),
                0x7777_8888,
                "{scenario}"
            );
            assert_eq!(
                uc.reg_read(RegisterMIPS::PC).unwrap() as u32,
                0x0040_8220,
                "{scenario}"
            );
            assert_eq!(
                uc.reg_read(RegisterMIPS::RA).unwrap() as u32,
                0x0040_8228,
                "{scenario}"
            );
            assert_eq!(
                uc.reg_read(RegisterMIPS::V0).unwrap() as u32,
                0x1234_5678,
                "{scenario}"
            );
            assert_eq!(
                uc.reg_read(RegisterMIPS::S0).unwrap() as u32,
                0xabcd_8080,
                "{scenario}"
            );
            assert_eq!(
                current_thread_id.get(),
                (active_thread_id, Some(active_birth)),
                "{scenario}"
            );
            assert_eq!(
                *running_thread.borrow(),
                Some((active_thread_id, active_handle)),
                "{scenario}"
            );
            let mut bytes = [0; 4];
            uc.mem_read(u64::from(result_ptr), &mut bytes).unwrap();
            assert_eq!(u32::from_le_bytes(bytes), 0xface_8080, "{scenario}");
        }
        Ok(())
    }

    #[test]
    fn send_message_blocked_wait_resume_recovers_missing_running_metadata() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let (sender_handle, sender_thread) = kernel.create_guest_thread(0x0040_3000, 0, false);
        let sender_birth = kernel
            .handles
            .thread_birth_key_by_id(sender_thread)
            .expect("sender birth");
        let receiver_thread = 1;
        let result_ptr = 0x0001_0040;
        let return_pc = 0x0040_2200;
        uc.mem_map(
            u64::from(super::USER_KDATA_PAGE_BASE),
            u64::from(super::USER_KDATA_PAGE_SIZE),
            Prot::ALL,
        )
        .unwrap();
        uc.mem_map(0x0001_0000, 0x1000, Prot::ALL).unwrap();
        uc.mem_write(u64::from(result_ptr), &0u32.to_le_bytes())
            .unwrap();

        let hwnd = kernel
            .gwe
            .create_window(receiver_thread, "SendResumeFallback", "send");
        let send_id = kernel
            .begin_cross_thread_send_message_w_for_birth(
                sender_birth,
                hwnd,
                crate::ce::gwe::WM_USER + 213,
                0,
                0,
                Some(1000),
            )
            .expect("queued send");
        let wait_started_ms = kernel.timers.tick_count();
        let mut sender_regs = super::MipsGuestContext::zero();
        sender_regs.regs[16] = 0x7777_0012;
        let kind = super::BlockedWaitKind::SendMessage {
            send_id,
            receiver_thread_id: receiver_thread,
            result_ptr: Some(result_ptr),
            previous_running_thread: None,
        };
        let wait_id = kernel.register_blocked_waiter(
            sender_thread,
            sender_handle,
            Vec::new(),
            super::scheduler_blocked_wait_kind(kind),
            wait_started_ms,
            crate::ce::timer::INFINITE,
        );
        assert_eq!(
            kernel
                .blocked_waiter(wait_id)
                .and_then(|wait| wait.owner_birth),
            Some(sender_birth)
        );
        let blocked_waits = Rc::new(RefCell::new(vec![super::BlockedWaitThread {
            frame_ref: None,
            wait_id,
            thread_id: sender_thread,
            thread_handle: sender_handle,
            wait_handles: Vec::new(),
            kind,
            wait_started_ms,
            timeout_ms: crate::ce::timer::INFINITE,
            regs: sender_regs,
            return_pc,
        }]));
        assert!(
            kernel
                .gwe
                .activate_sent_message_for_receiver(receiver_thread, send_id)
        );
        assert_eq!(
            kernel.complete_active_sent_message(receiver_thread, 0x1357_2468),
            Some(send_id)
        );

        let current_thread_id = Rc::new(super::NativeCurrentThread::new(receiver_thread, None));
        let suspended = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(None));
        assert!(super::try_resume_blocked_wait_with_active_pc_mode(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            None,
            receiver_thread,
            &current_thread_id,
            &blocked_waits,
            &suspended,
            None,
            &running_thread,
            None,
            false,
            super::SendResumePhase::Prepared(wait_id),
        ));

        assert_eq!(current_thread_id.get(), (sender_thread, Some(sender_birth)));
        assert_eq!(
            *running_thread.borrow(),
            Some((sender_thread, sender_handle))
        );
        assert!(blocked_waits.borrow().is_empty());
        assert!(kernel.blocked_waiter(wait_id).is_none());
        assert_eq!(uc.reg_read(RegisterMIPS::S0).unwrap() as u32, 0x7777_0012);
        assert_eq!(uc.reg_read(RegisterMIPS::V0).unwrap() as u32, 0x1357_2468);
        assert_eq!(uc.reg_read(RegisterMIPS::PC).unwrap() as u32, return_pc);
        let mut result_bytes = [0; 4];
        uc.mem_read(u64::from(result_ptr), &mut result_bytes)
            .unwrap();
        assert_eq!(u32::from_le_bytes(result_bytes), 0x1357_2468);
    }

    #[test]
    fn get_message_block_registration_clears_stale_sleep_wait() {
        let config = RuntimeConfig::load_default().unwrap();
        let mut kernel = CeKernel::boot(config);
        let mut uc = Unicorn::new(Arch::MIPS, Mode::MIPS32 | Mode::LITTLE_ENDIAN).unwrap();
        let thread_id = super::MAIN_GUEST_THREAD_ID;
        let thread_handle = crate::ce::kernel::CE_CURRENT_THREAD_PSEUDO_HANDLE;
        let thread_birth = kernel
            .handles
            .thread_birth_key_by_id(thread_id)
            .expect("boot thread birth");
        let wait_started_ms = kernel.timers.tick_count();
        let stale_wait_id = kernel.register_blocked_waiter(
            thread_id,
            thread_handle,
            Vec::new(),
            crate::ce::scheduler::SchedulerBlockedWaitKind::Sleep,
            wait_started_ms,
            101,
        );
        let blocked_waits = Rc::new(RefCell::new(vec![super::BlockedWaitThread {
            frame_ref: None,
            wait_id: stale_wait_id,
            thread_id,
            thread_handle,
            wait_handles: Vec::new(),
            kind: super::BlockedWaitKind::Sleep,
            wait_started_ms,
            timeout_ms: 101,
            regs: super::MipsGuestContext::zero(),
            return_pc: 0x0040_1000,
        }]));
        let blocked_get_message = Rc::new(RefCell::new(None));
        let blocked_guest_thread = Rc::new(RefCell::new(None));
        let displaced_blocked_get_messages = Rc::new(RefCell::new(Vec::new()));
        let pending_returns = Rc::new(RefCell::new(Vec::new()));
        let current_thread_id = Rc::new(super::NativeCurrentThread::new(
            thread_id,
            Some(thread_birth),
        ));
        let suspended_thread = Rc::new(RefCell::new(None));
        let running_thread = Rc::new(RefCell::new(Some((thread_id, thread_handle))));
        let last_messages = Rc::new(RefCell::new(Vec::new()));
        uc.reg_write(RegisterMIPS::RA, 0x0040_2000).unwrap();

        let pending_com = Rc::new(RefCell::new(Vec::new()));
        assert!(super::try_block_empty_get_message(
            &mut kernel,
            &mut uc,
            &super::SealedHostWriteGuard::default(),
            &RefCell::new(super::KernelMemoryMappings::new(&[])),
            &mut Vec::new(),
            None,
            crate::emulator::imports::ImportModuleKind::Coredll,
            Some(crate::ce::coredll_ordinals::ORD_GET_MESSAGE_W),
            &[0x3000_0100, 0, 0, 0],
            0,
            thread_id,
            &blocked_get_message,
            &blocked_guest_thread,
            &displaced_blocked_get_messages,
            &blocked_waits,
            &pending_returns,
            &Rc::new(RefCell::new(Vec::new())),
            &current_thread_id,
            &suspended_thread,
            &running_thread,
            &last_messages,
            std::time::Instant::now(),
            Some(std::time::Duration::from_secs(1)),
            &pending_com,
            false,
            &std::cell::RefCell::new(None),
        ));

        assert!(blocked_waits.borrow().is_empty());
        assert!(kernel.blocked_waiter(stale_wait_id).is_none());
        assert!(blocked_guest_thread.borrow().is_some());
        let remaining: Vec<_> = kernel
            .blocked_waiters()
            .filter(|wait| wait.thread_id == thread_id)
            .collect();
        assert_eq!(remaining.len(), 1);
        assert!(matches!(
            remaining[0].kind,
            crate::ce::scheduler::SchedulerBlockedWaitKind::GetMessage { .. }
        ));
        assert_eq!(*running_thread.borrow(), None);
    }

